-- supabase/migrations/20260827134553_tenant_integrity_auditor_v1.sql:62; fixed literal control rows, existing keys preserved
INSERT INTO public.tenant_integrity_rule_registry (rule_key, category, severity, enforcement_mode, title, description, remediation_hint, is_enabled) VALUES (''TENANT-001'', ''tenant'', ''high'', ''release_gate'', ''Tenant lifecycle flags disagree'', ''Canonical tenant status, is_active and is_paused must not contradict each other.'', ''Use the canonical tenant lifecycle command; do not patch status flags independently.'', TRUE), (''ACCESS-001'', ''access'', ''critical'', ''release_gate'', ''Active membership has inactive profile'', ''An active tenant membership must resolve to an active user profile.'', ''Repair the user lifecycle through the canonical access command and verify Auth/profile state.'', TRUE), (''ACCESS-002'', ''access'', ''high'', ''release_gate'', ''Membership role mapping drift'', ''Active membership_role must match the canonical mapping for role_key.'', ''Reconcile through canonical_change_tenant_user_access; do not edit only one role field.'', TRUE), (''ACCESS-003'', ''access'', ''critical'', ''release_gate'', ''Active membership lacks matching RBAC role'', ''Every active tenant membership must have one matching active company-scoped RBAC role.'', ''Re-run canonical access provisioning and verify company-scoped user_roles.'', TRUE), (''ACCESS-004'', ''access'', ''high'', ''audit'', ''Active company selection is not accessible'', ''A user profile active_company_id must point to a tenant where the user has an active membership.'', ''Clear or change active_company_id through the canonical tenant selection flow.'', TRUE), (''ACCESS-005'', ''access'', ''high'', ''audit'', ''Accepted invitation lacks membership'', ''An accepted invitation with an invited user must have a membership row for the same tenant and user.'', ''Reconcile the invitation through canonical acceptance/provisioning; preserve invitation history.'', TRUE), (''OPS-001'', ''operations'', ''critical'', ''release_gate'', ''Core customer graph crosses tenant boundary'', ''Customer, site, metering point, contract and supplier switch references must resolve to one tenant.'', ''Stop the workflow and repair the parent relation using tenant-qualified canonical IDs.'', TRUE), (''OUTBOUND-001'', ''operations'', ''critical'', ''release_gate'', ''Outbound request crosses tenant boundary'', ''Outbound request tenant must match its customer, site, metering point, switch and contract relations.'', ''Block dispatch and rebuild the outbound request from the canonical customer operation.'', TRUE), (''EDIEL-001'', ''ediel'', ''critical'', ''release_gate'', ''Outbound Ediel graph crosses tenant boundary'', ''A non-draft outbound Ediel message must use one tenant across all linked business entities.'', ''Block sending and rebuild message/routing context from the canonical tenant operation.'', TRUE), (''EDIEL-002'', ''ediel'', ''high'', ''release_gate'', ''Resolved Ediel tenant disagrees with message tenant'', ''resolved_company_id and company_id may not disagree once both are known.'', ''Quarantine the message and rerun canonical tenant resolution before business processing.'', TRUE), (''EDIEL-003'', ''ediel'', ''critical'', ''release_gate'', ''Ediel outbox tenant disagrees with message tenant'', ''Sendable Ediel outbox rows must have the same tenant as their Ediel message.'', ''Block the outbox row and rematerialize it from the canonical message.'', TRUE), (''EDIEL-004'', ''ediel'', ''critical'', ''release_gate'', ''Blocked tenant still has sendable production Ediel'', ''Paused, suspended, frozen or Ediel-blocked tenants must not retain prepared/queued/sending production outbox work.'', ''Move work to blocked_tenant_state and require explicit canonical resume/re-evaluation.'', TRUE), (''EDIEL-005'', ''ediel'', ''high'', ''release_gate'', ''Live Ediel tenant lacks active production actor'', ''A tenant with production Ediel enabled must have an active, currently valid production actor setting.'', ''Complete/activate the production actor profile before enabling production Ediel.'', TRUE), (''EDIEL-006'', ''ediel'', ''high'', ''audit'', ''Overlapping active tenant Ediel profiles'', ''A tenant/environment/market must not have more than one currently active tenant Ediel profile.'', ''Close the superseded validity interval and keep one effective profile.'', TRUE) ON CONFLICT DO NOTHING;
