DO $permission_complete_post$ BEGIN IF EXISTS(SELECT FROM ops_api_complete_permission_before b LEFT JOIN public.permissions p USING(key) WHERE to_jsonb(p) IS DISTINCT FROM b.row_value) THEN RAISE EXCEPTION ''ops_complete_permission_rows_changed''; END IF; IF (SELECT count(*) FROM public.permissions WHERE key IN (''communication.write'',''ediel.source.review'',''ediel.ai_purpose.review'',''ediel.bilateral_profile.review'',''ediel.network_registry.review'',''ediel.regulated_supply.review'',''ediel.supply_rescission.review''))<>7 THEN RAISE EXCEPTION ''ops_complete_source_permissions_required''; END IF; END $permission_complete_post$;';
  IF (SELECT count(*) FROM public.ediel_message_profiles p WHERE p.profile_key IN ('PRODAT:Z03:H:26.A:r3','PRODAT:Z04:H:26.A:r3','PRODAT:Z05:H:26.A:r3','PRODAT:Z08:LK:26.A:r3') AND p.profile->>'bilateralCarrierOnly'='true')<>4 THEN RAISE EXCEPTION 'ops_portable_bilateral_carrier_metadata_required'; END IF;
  IF (SELECT count(*) FROM public.ediel_runtime_capabilities c JOIN public.ediel_message_profiles p ON p.rule_pack_id=c.rule_pack_id AND p.message_code=c.message_code AND p.transaction_subtype=c.transaction_subtype AND p.direction=c.direction WHERE p.profile->>'bilateralCarrierOnly'='true' AND p.profile_key IN ('PRODAT:Z03:H:26.A:r3','PRODAT:Z04:H:26.A:r3','PRODAT:Z05:H:26.A:r3','PRODAT:Z08:LK:26.A:r3'))<>4 THEN RAISE EXCEPTION 'ops_portable_bilateral_capabilities_required'; END IF;
  RAISE NOTICE 'ops_api_delivery_complete_source_state';
 ELSE
