-- Serialize exact source metadata registration; permission reads remain available
LOCK TABLE public.permissions IN SHARE ROW EXCLUSIVE MODE;

-- Fresh pre-existing catalogue fingerprint with explicit stable collation; seven independently registered exact source keys may already exist and their flags are preserved
DO $permission_catalog_pre$ BEGIN IF (SELECT md5(coalesce(jsonb_agg(to_jsonb(p) ORDER BY p.key COLLATE "C")::text,'[]')) FROM public.permissions p WHERE p.key NOT IN ('communication.write','ediel.source.review','ediel.ai_purpose.review','ediel.bilateral_profile.review','ediel.network_registry.review','ediel.regulated_supply.review','ediel.supply_rescission.review')) IS DISTINCT FROM '4f1cdf127508b28e7a07fa0c5f218bcf' THEN RAISE EXCEPTION 'ops_permission_catalog_stale'; END IF; END $permission_catalog_pre$;

-- Only fixed global metadata, no company/user/role data
CREATE TEMP TABLE ops_api_permission_catalog_before ON COMMIT DROP AS SELECT p.key,to_jsonb(p) AS row_value FROM public.permissions p;

-- Exact source field comparison; preserves existing is_active controls and row identity
