-- canonical:350
--
-- Name: identity_v1(jsonb); Type: FUNCTION; Schema: gridex_customer_masterdata; Owner: -
--

CREATE FUNCTION gridex_customer_masterdata.identity_v1(d jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$SELECT jsonb_typeof(d)='object' AND (d->>'qualifier' IN('SE1','SE2')) IS TRUE AND d->>'agency'='260' AND length(d->>'id') BETWEEN 1 AND 35 AND d->>'id'=btrim(d->>'id') AND (d->>'id')!~'[[:cntrl:]]'$$;

REVOKE ALL ON FUNCTION gridex_customer_masterdata.identity_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:351
--
-- Name: literal_masterdata_v1(jsonb); Type: FUNCTION; Schema: gridex_customer_masterdata; Owner: -
--

CREATE FUNCTION gridex_customer_masterdata.literal_masterdata_v1(d jsonb) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT jsonb_typeof(d)='object' AND NOT EXISTS(SELECT FROM jsonb_object_keys(d) k WHERE k NOT IN('nameParts','streetParts','postalCode','city','country'))
 AND jsonb_typeof(d->'nameParts')='array' AND jsonb_array_length(d->'nameParts') BETWEEN 1 AND 2 AND NOT EXISTS(SELECT FROM jsonb_array_elements(d->'nameParts') item WHERE jsonb_typeof(item)<>'string' OR length(item#>>'{}') NOT BETWEEN 1 AND 35 OR (item#>>'{}')~'[[:cntrl:]]')
 AND jsonb_typeof(d->'streetParts')='array' AND jsonb_array_length(d->'streetParts') BETWEEN 1 AND 3 AND NOT EXISTS(SELECT FROM jsonb_array_elements(d->'streetParts') item WHERE jsonb_typeof(item)<>'string' OR length(item#>>'{}') NOT BETWEEN 0 AND 35 OR (item#>>'{}')~'[[:cntrl:]]')
 AND EXISTS(SELECT FROM jsonb_array_elements(d->'streetParts')item WHERE item#>>'{}' NOT IN('','.'))
 AND length(d->>'postalCode') BETWEEN 1 AND 9 AND length(d->>'city') BETWEEN 1 AND 35 AND length(d->>'country')=2 AND (d->>'country')~'^[A-Z]{2}$' AND (d->>'postalCode')!~'[[:cntrl:]]' AND (d->>'city')!~'[[:cntrl:]]'
$_$;

REVOKE ALL ON FUNCTION gridex_customer_masterdata.literal_masterdata_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:548
--
-- Name: contract_copy_prepared_metadata_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.contract_copy_prepared_metadata_v1(b jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF b#>>'{sourceProof,rowProof,contract_id}' IS NOT NULL THEN RETURN jsonb_set(b,'{sourceProof,rowProof}',(b#>'{sourceProof,rowProof}')-ARRAY['agreement_original','source_original']);
 ELSIF b#>>'{sourceProof,rowProof,base,contract_id}' IS NOT NULL THEN RETURN jsonb_set(b,'{sourceProof,rowProof,base}',(b#>'{sourceProof,rowProof,base}')-ARRAY['agreement_original','source_original']);END IF;RETURN b;END$$;

REVOKE ALL ON FUNCTION gridex_ediel_retention.contract_copy_prepared_metadata_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:549
--
-- Name: contract_copy_prepared_proof_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.contract_copy_prepared_proof_v1(b jsonb) RETURNS jsonb
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$SELECT CASE WHEN b#>>'{sourceProof,rowProof,contract_id}' IS NOT NULL AND b#>>'{sourceProof,rowProof,id}' IS NOT NULL THEN b#>'{sourceProof,rowProof}' WHEN b#>>'{sourceProof,rowProof,base,contract_id}' IS NOT NULL AND b#>>'{sourceProof,rowProof,base,id}' IS NOT NULL THEN b#>'{sourceProof,rowProof,base}' END$$;

REVOKE ALL ON FUNCTION gridex_ediel_retention.contract_copy_prepared_proof_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;

