-- canonical:2887
--
-- Name: dsn_matchable_attempts_v1; Type: VIEW; Schema: gridex_ediel_transport; Owner: -
--

CREATE VIEW gridex_ediel_transport.dsn_matchable_attempts_v1 AS
 SELECT a.id,
    a.message_id,
    a.company_id,
    a.environment,
    a.binding,
    a.created_at,
    a.entered_at,
    a.observed_at,
    a.classification,
    'generic_journal'::text AS lane
   FROM gridex_ediel_transport.attempts a
  WHERE (a.entered_at IS NOT NULL)
UNION ALL
 SELECT a.id,
    a.message_id,
    a.company_id,
    a.environment,
    a.binding,
    a.created_at,
    e.observed_at AS entered_at,
    result.observed_at,
    (result.facts ->> 'classification'::text) AS classification,
    'sealed_z08'::text AS lane
   FROM (((gridex_outbound_dispatch.attempts a
     JOIN gridex_outbound_dispatch.events e ON (((e.attempt_id = a.id) AND (e.company_id = a.company_id) AND (e.environment = a.environment) AND (e.kind = 'provider_call_entered'::text))))
     JOIN gridex_outbound_dispatch.witnesses w ON (((w.event_id = e.id) AND (w.company_id = e.company_id) AND (w.environment = e.environment))))
     LEFT JOIN gridex_outbound_dispatch.events result ON (((result.attempt_id = a.id) AND (result.kind = 'provider_result'::text))));

