-- canonical:216
--
-- Name: outbound_capability_v1(uuid, uuid, text, text); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.outbound_capability_v1(c uuid, actor uuid, env text, raw text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE wire jsonb;own jsonb;ids uuid[];g gridex_bilateral_prodat.profile_versions%rowtype;a gridex_bilateral_prodat.artifacts%rowtype;
 point public.metering_points%rowtype;customer public.customers%rowtype;site public.customer_sites%rowtype;contract public.customer_contracts%rowtype;
 sw public.supplier_switch_requests%rowtype;period public.customer_supply_periods%rowtype;doc public.customer_contract_documents%rowtype;
 objects jsonb:='[]';kind text;event_at timestamptz;profile_id uuid;basis jsonb;sig text;identity text;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 IF gridex_bilateral_prodat.actor_v1(c,actor,'archive') IS NOT TRUE OR env NOT IN('test','production') OR octet_length(raw) NOT BETWEEN 1 AND 8388608 OR gridex_bilateral_prodat.outbound_required_v1(raw) IS NOT TRUE THEN RETURN NULL;END IF;
 wire:=gridex_bilateral_prodat.draft_wire_v1(raw);IF wire IS NULL THEN RETURN NULL;END IF;
 kind:=CASE wire->>'code' WHEN 'Z03' THEN 'normal_start_h' ELSE 'closure_request_lk' END;
 IF (SELECT count(*) FROM jsonb_array_elements(gridex_received_sources.wire_tokens_bounded_v1(raw,10000)) t WHERE t->>'tag'='UNH')<>1
 OR (SELECT count(DISTINCT o->>'point') FROM jsonb_array_elements(wire->'objects')o)<>jsonb_array_length(wire->'objects') THEN RETURN NULL;END IF;
 FOR own IN SELECT o FROM jsonb_array_elements(wire->'objects')o LOOP
  IF nullif(own->>'li','') IS NULL OR nullif(own->>'point','') IS NULL OR own->>'reason' IS DISTINCT FROM (CASE kind WHEN 'normal_start_h' THEN 'Z25' ELSE 'Z23' END) THEN RETURN NULL;END IF;
  SELECT array_agg(mp.id) INTO ids FROM public.metering_points mp WHERE mp.company_id=c AND mp.ediel_metering_point_id=own->>'point' AND mp.grid_owner_ediel_id=wire->>'receiver' AND mp.grid_area_code=own->>'gridArea';
  IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;SELECT * INTO point FROM public.metering_points WHERE id=ids[1] AND company_id=c;
  SELECT * INTO customer FROM public.customers WHERE id=point.customer_id AND company_id=c;SELECT * INTO site FROM public.customer_sites WHERE id=coalesce(point.customer_site_id,point.site_id) AND company_id=c AND customer_id=point.customer_id;
  identity:=coalesce(nullif(btrim(customer.org_number),''),nullif(btrim(customer.personal_number),''));
  IF customer.id IS NULL OR site.id IS NULL OR own->>'customerIdentity' IS DISTINCT FROM identity THEN RETURN NULL;END IF;
  own:=own||jsonb_build_object('identityAgency',(SELECT t#>>'{elements,3,3}' FROM jsonb_array_elements(gridex_received_sources.wire_tokens_bounded_v1(raw,10000))t WHERE t->>'tag'='LIN' AND t#>>'{elements,3,0}'=own->>'point' LIMIT 1));
  IF (own->>'identityAgency' IN('9','89')) IS NOT TRUE THEN RETURN NULL;END IF;
  event_at:=gridex_received_sources.permission_time_v1(own->>CASE kind WHEN 'normal_start_h' THEN 'start' ELSE 'end' END);IF event_at IS NULL THEN RETURN NULL;END IF;
  SELECT array_agg(v.id ORDER BY v.id) INTO ids FROM gridex_bilateral_prodat.profile_versions v JOIN gridex_bilateral_prodat.origins origin ON origin.ground_id=v.id AND origin.company_id=v.company_id JOIN gridex_bilateral_prodat.artifacts archived ON archived.id=origin.artifact_id AND archived.company_id=v.company_id
   WHERE v.company_id=c AND v.environment=env AND v.process=kind AND v.grid_area_code=own->>'gridArea' AND archived.scope->>'legalSenderId'=wire->>'sender' AND archived.scope->>'legalReceiverId'=wire->>'receiver'
   AND EXISTS(SELECT FROM jsonb_array_elements(archived.scope#>'{sourceGrammar,profiles}') p WHERE p->>'message_code'=wire->>'code' AND p->>'direction' IN('outbound','both')) AND gridex_bilateral_prodat.ground_current_v1(v.id,c,event_at) IS TRUE;
  IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;SELECT * INTO g FROM gridex_bilateral_prodat.profile_versions WHERE id=ids[1];SELECT archived.* INTO a FROM gridex_bilateral_prodat.origins o JOIN gridex_bilateral_prodat.artifacts archived ON archived.id=o.artifact_id AND archived.company_id=o.company_id WHERE o.ground_id=g.id;
  SELECT (p->>'id')::uuid INTO profile_id FROM jsonb_array_elements(a.scope#>'{sourceGrammar,profiles}')p WHERE p->>'message_code'=wire->>'code' AND p->>'direction' IN('outbound','both');
  SELECT array_agg(cc.id) INTO ids FROM public.customer_contracts cc WHERE cc.company_id=c AND cc.customer_id=customer.id AND cc.metering_point_id=point.id AND cc.status IN('signed','active') AND cc.signed_at IS NOT NULL AND cc.signed_version=cc.contract_version;
  IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;SELECT * INTO contract FROM public.customer_contracts WHERE id=ids[1] AND company_id=c;
  sig:=encode(sha256(convert_to(contract.signature_snapshot::text,'UTF8')),'hex');SELECT * INTO doc FROM public.customer_contract_documents WHERE company_id=c AND customer_contract_id=contract.id AND document_type='signed_contract_pdf' AND document_sha256=contract.document_sha256 AND verified_at IS NOT NULL ORDER BY id LIMIT 1;
  IF doc.id IS NULL OR contract.signature_snapshot_sha256 IS DISTINCT FROM sig OR contract.signature_snapshot->>'company_id' IS DISTINCT FROM c::text OR contract.signature_snapshot->>'customer_id' IS DISTINCT FROM customer.id::text OR contract.signature_snapshot->>'contract_id' IS DISTINCT FROM contract.id::text THEN RETURN NULL;END IF;
  IF kind='normal_start_h' THEN
   SELECT array_agg(s.id) INTO ids FROM public.supplier_switch_requests s WHERE s.company_id=c AND s.customer_id=customer.id AND s.metering_point_id=point.id AND coalesce(s.contract_id,s.customer_contract_id)=contract.id AND coalesce(s.site_id,s.customer_site_id)=site.id AND (s.rff_li_reference=own->>'li' OR s.rff_li_reference IS NULL) AND s.prodat_variant='H' AND s.prodat_reason='Z25' AND (s.outbound_z03_message_id IS NULL OR EXISTS(SELECT FROM gridex_bilateral_prodat.outbound_operations original WHERE original.message_id=s.outbound_z03_message_id AND original.company_id=c AND original.capability->>'messageCode'='Z03')) AND s.status IN('draft','ready','ready_for_switch','ready_for_z03','z03_ready','validated','prepared','queued','submitted','sent','waiting','waiting_response','waiting_for_z04','awaiting_confirmation') AND NOT s.lifecycle_blocked;
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;SELECT * INTO sw FROM public.supplier_switch_requests WHERE id=ids[1] AND company_id=c;
   IF sw.requested_start_date IS DISTINCT FROM gridex_received_sources.permission_date_v1(own->>'start') THEN RETURN NULL;END IF;
  ELSE
   SELECT array_agg(p.id) INTO ids FROM public.customer_supply_periods p WHERE p.company_id=c AND p.customer_id=customer.id AND p.metering_point_id=point.id AND coalesce(p.contract_id,p.customer_contract_id)=contract.id AND p.status IN('active','confirmed_by_grid_owner') AND p.market_start_at<event_at AND (p.market_end_at IS NULL OR p.market_end_at=event_at);
   IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;SELECT * INTO period FROM public.customer_supply_periods WHERE id=ids[1] AND company_id=c;
   basis:=gridex_received_sources.supply_period_source_basis_v1(c,period.id,event_at-interval '1 minute',event_at);IF basis IS NULL THEN RETURN NULL;END IF;
  END IF;
  objects:=objects||jsonb_build_array(jsonb_build_object('objectId',own->>'point','identityAgency',(SELECT t#>>'{elements,3,3}' FROM jsonb_array_elements(gridex_received_sources.wire_tokens_bounded_v1(raw,10000))t WHERE t->>'tag'='LIN' AND t#>>'{elements,3,0}'=own->>'point' LIMIT 1),'firstLineIndex',gridex_bilateral_prodat.first_line_index_v1(raw,own||jsonb_build_object('identityAgency',(SELECT t#>>'{elements,3,3}' FROM jsonb_array_elements(gridex_received_sources.wire_tokens_bounded_v1(raw,10000))t WHERE t->>'tag'='LIN' AND t#>>'{elements,3,0}'=own->>'point' LIMIT 1))),'lineItemReference',own->>'li','profileVersionId',g.id,'process',kind,'sourceHash',a.source_hash,'sourceGrammarHash',a.scope->>'sourceGrammarHash','rulePackId',a.scope->>'rulePackId','messageProfileId',profile_id,'pointId',point.id,'customerId',customer.id,'siteId',site.id,'contractId',contract.id,'contractHash',gridex_received_sources.production_contract_hash_v1(contract),'eventAt',event_at,'switchId',CASE kind WHEN 'normal_start_h' THEN sw.id ELSE NULL END,'supplyPeriodId',CASE kind WHEN 'closure_request_lk' THEN period.id ELSE NULL END,'marketStateVersion',CASE kind WHEN 'closure_request_lk' THEN period.market_state_version ELSE NULL END));
 END LOOP;
 IF jsonb_array_length(objects)=0 OR EXISTS(SELECT FROM jsonb_array_elements(objects)o WHERE o->>'identityAgency' NOT IN('9','89')) THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('version',1,'owner','immutable-bilateral-prodat-outbound-profile-v1','companyId',c,'environment',env,'actorUserId',actor,'payloadHash',encode(sha256(convert_to(raw,'UTF8')),'hex'),'messageCode',wire->>'code','objects',objects);
END$$;

REVOKE ALL ON FUNCTION gridex_bilateral_prodat.outbound_capability_v1(uuid, uuid, text, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:217
--
-- Name: outbound_required_v1(text); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.outbound_required_v1(raw text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.wire_tokens_bounded_v1(raw,10000);family text;code text;characteristic text;t jsonb;
BEGIN
 SELECT x#>>'{elements,2,0}' INTO family FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNH';SELECT x#>>'{elements,1,0}' INTO code FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='BGM';
 IF family IS DISTINCT FROM 'PRODAT' OR code NOT IN('Z03','Z08') THEN RETURN false;END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x LOOP
 IF t->>'tag'='CCI' THEN characteristic:=t#>>'{elements,2,0}';ELSIF t->>'tag'='CAV' AND characteristic='Z13' AND t#>>'{elements,1,0}'=(CASE code WHEN 'Z03' THEN 'Z25' ELSE 'Z23' END) THEN RETURN true;END IF;END LOOP;RETURN false;
END$$;

REVOKE ALL ON FUNCTION gridex_bilateral_prodat.outbound_required_v1(text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:221
--
-- Name: receipt_current_v1(gridex_bilateral_prodat.artifacts); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.receipt_current_v1(a gridex_bilateral_prodat.artifacts) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE k gridex_bilateral_prodat.issuer_keys%rowtype;r gridex_bilateral_prodat.issuer_representations%rowtype;p jsonb;raw bytea;issued timestamptz;expires timestamptz;receipt jsonb:=a.issuer_receipt;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_graph_v1();
 IF receipt IS NULL OR jsonb_typeof(receipt) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(receipt) key WHERE key NOT IN('keyId','representationId','payloadBase64','signatureHex')) OR coalesce(receipt->>'signatureHex','')!~'^[a-f0-9]{64}$' OR length(coalesce(receipt->>'payloadBase64','')) NOT BETWEEN 1 AND 1048576
 OR a.source_hash IS DISTINCT FROM encode(sha256(a.source_bytes),'hex') OR a.scope_hash IS DISTINCT FROM encode(sha256(convert_to(a.scope::text,'UTF8')),'hex') THEN RETURN false;END IF;
 SELECT * INTO k FROM gridex_bilateral_prodat.issuer_keys WHERE id=(receipt->>'keyId')::uuid AND company_id=a.company_id AND environment=a.environment;
 SELECT * INTO r FROM gridex_bilateral_prodat.issuer_representations WHERE id=(receipt->>'representationId')::uuid AND issuer_key_id=k.id AND company_id=a.company_id AND environment=a.environment
 AND legal_actor_id::text=a.scope->>'legalActorId' AND dso_actor_id::text=a.scope->>'dsoActorId' AND grid_area_code=a.scope->>'gridArea' AND permitted_kind=a.scope->>'kind' AND bilateral_agreement_id::text=a.scope->>'bilateralAgreementId';
 IF k.id IS NULL OR r.id IS NULL OR now()<k.valid_from OR now()>=k.valid_to OR now()<r.valid_from OR now()>=r.valid_to OR EXISTS(SELECT FROM gridex_bilateral_prodat.issuer_revocations v WHERE v.target_kind='key' AND v.target_id=k.id OR v.target_kind='representation' AND v.target_id=r.id) THEN RETURN false;END IF;
 raw:=decode(receipt->>'payloadBase64','base64');IF sha256(gridex_requested_changes.receipt_hmac_sha256_v1(raw,k.receipt_signing_key)) IS DISTINCT FROM sha256(decode(receipt->>'signatureHex','hex')) THEN RETURN false;END IF;
 p:=convert_from(raw,'UTF8')::jsonb;issued:=(p->>'issuedAt')::timestamptz;expires:=(p->>'expiresAt')::timestamptz;
 RETURN (p->>'format'='ediel_bilateral_prodat_ground_receipt_v1' AND p->>'issuerCode'=k.issuer_code AND nullif(p->>'receiptId','') IS NOT NULL AND p->>'companyId'=a.company_id::text AND p->>'environment'=a.environment AND p->'scope'=a.scope
 AND p->>'sourceHash'=a.source_hash AND p->>'sourceReference'=a.source_reference AND p->>'sourceVersion'=a.source_version AND nullif(p->>'legalDecisionReference','') IS NOT NULL AND length(p->>'legalDecisionReference')<=2000
 AND isfinite(issued) AND isfinite(expires) AND issued<=now() AND expires>(a.scope->>'validTo')::timestamptz AND (a.scope->>'validFrom')::timestamptz>=r.valid_from AND (a.scope->>'validTo')::timestamptz>=r.valid_from AND issued>=greatest(k.valid_from,r.valid_from) AND expires<=least(k.valid_to,r.valid_to)) IS TRUE;
EXCEPTION WHEN invalid_text_representation OR invalid_parameter_value OR invalid_datetime_format OR datetime_field_overflow OR character_not_in_repertoire THEN RETURN false;
END$_$;

REVOKE ALL ON FUNCTION gridex_bilateral_prodat.receipt_current_v1(gridex_bilateral_prodat.artifacts) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:224
--
-- Name: recorded_closure_end_current_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.recorded_closure_end_current_v1(c uuid, s uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE r gridex_bilateral_prodat.closure_end_receipts%rowtype;z public.ediel_messages%rowtype;t gridex_received_sources.supply_source_transitions%rowtype;m public.ediel_messages%rowtype;own_count int;BEGIN
 PERFORM gridex_bilateral_prodat.lock_closure_v1();SELECT * INTO m FROM public.ediel_messages WHERE id=s AND company_id=c;
 SELECT * INTO t FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=s AND company_id=c;
 IF m.id IS NULL OR t.source_message_id IS NULL OR t.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RETURN false;END IF;
 SELECT count(*) INTO own_count FROM jsonb_array_elements(t.source_objects) own WHERE own->>'reason'='Z23';
 IF own_count=0 OR own_count<>(SELECT count(*) FROM gridex_bilateral_prodat.closure_end_receipts WHERE company_id=c AND source_message_id=s) THEN RETURN false;END IF;
 FOR r IN SELECT receipt.* FROM gridex_bilateral_prodat.closure_end_receipts receipt WHERE receipt.company_id=c AND receipt.source_message_id=s LOOP
  IF r.environment IS DISTINCT FROM m.environment OR r.source_payload_hash IS DISTINCT FROM t.payload_hash OR r.transition_hash IS DISTINCT FROM encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex') OR gridex_bilateral_prodat.recorded_profile_authority_v1(r.profile_id,c) IS NOT TRUE OR NOT EXISTS(SELECT FROM jsonb_array_elements(t.source_objects) own WHERE own=r.source_object) THEN RETURN false;END IF;
  SELECT * INTO z FROM public.ediel_messages WHERE id=r.original_message_id AND company_id=c AND environment=m.environment;
  IF z.id IS NULL OR z.immutable_payload_hash IS DISTINCT FROM r.original_payload_hash OR gridex_received_sources.sent_source_is_current_v1(z) IS NOT TRUE THEN RETURN false;END IF;
  PERFORM gridex_bilateral_prodat.require_recorded_outbound_v1(z,z.created_by);
 END LOOP;RETURN true;
END$$;

REVOKE ALL ON FUNCTION gridex_bilateral_prodat.recorded_closure_end_current_v1(uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:225
--
-- Name: recorded_profile_authority_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.recorded_profile_authority_v1(profile uuid, company uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE o gridex_bilateral_prodat.origins%rowtype;a gridex_bilateral_prodat.artifacts%rowtype;r gridex_bilateral_prodat.reviews%rowtype;g gridex_bilateral_prodat.profile_versions%rowtype;agreement public.tenant_bilateral_agreements%rowtype;binding jsonb;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_graph_v1();
 SELECT * INTO o FROM gridex_bilateral_prodat.origins WHERE ground_id=profile AND company_id=company;
 SELECT * INTO a FROM gridex_bilateral_prodat.artifacts WHERE id=o.artifact_id AND company_id=company;
 SELECT * INTO r FROM gridex_bilateral_prodat.reviews WHERE id=o.review_id AND artifact_id=a.id AND company_id=company;
 SELECT * INTO g FROM gridex_bilateral_prodat.profile_versions WHERE id=profile AND company_id=company;
 IF o.ground_id IS NULL OR a.id IS NULL OR r.id IS NULL OR g.id IS NULL OR r.decision IS DISTINCT FROM 'approved' OR r.reviewer_user_id=a.submitted_by
  OR g.revoked_at IS NOT NULL OR now()<g.valid_from OR now()>=g.valid_to OR o.ground_binding IS DISTINCT FROM to_jsonb(g)-'revoked_at'
  OR gridex_bilateral_prodat.actor_v1(company,r.reviewer_user_id,'review') IS NOT TRUE OR gridex_bilateral_prodat.receipt_current_v1(a) IS NOT TRUE THEN RETURN false;END IF;
 SELECT * INTO agreement FROM public.tenant_bilateral_agreements WHERE id=g.bilateral_agreement_id AND company_id=company AND environment=g.environment AND is_enabled AND valid_from<=now() AND(valid_to IS NULL OR now()<valid_to);
 IF agreement.id IS NULL OR to_jsonb(agreement) IS DISTINCT FROM a.scope->'agreementBinding' THEN RETURN false;END IF;
 SELECT jsonb_build_object('profiles',(SELECT jsonb_agg(to_jsonb(p) ORDER BY p.id) FROM public.tenant_ediel_profiles p WHERE company_id=company AND environment=g.environment AND market='electricity' AND is_enabled),
 'identifiers',(SELECT jsonb_agg(to_jsonb(i) ORDER BY i.id) FROM public.tenant_actor_identifiers i WHERE company_id=company AND environment=g.environment AND actor_id=g.legal_actor_id),
 'roles',(SELECT jsonb_agg(to_jsonb(role) ORDER BY role.id) FROM public.tenant_actor_roles role WHERE company_id=company AND environment=g.environment AND actor_id=g.legal_actor_id),
 'counterparty',(SELECT jsonb_agg(to_jsonb(i) ORDER BY i.id) FROM public.platform_actor_identifiers i WHERE actor_id=g.dso_actor_id AND is_verified)) INTO binding;
 RETURN binding=a.scope->'legalBinding'
  AND (SELECT count(DISTINCT (company_id,actor_id)) FROM public.tenant_actor_identifiers WHERE environment=g.environment AND identifier_type='EdielId' AND identifier_value=a.scope->>'legalSenderId' AND valid_from<=now() AND(valid_to IS NULL OR now()<valid_to))=1
  AND EXISTS(SELECT FROM public.tenant_actor_roles WHERE company_id=company AND environment=g.environment AND actor_id=g.legal_actor_id AND role_code='electricity_supplier' AND valid_from<=now() AND(valid_to IS NULL OR now()<valid_to))
  AND EXISTS(SELECT FROM public.tenant_ediel_profiles WHERE company_id=company AND environment=g.environment AND market='electricity' AND is_enabled AND valid_from<=now() AND(valid_to IS NULL OR now()<valid_to))
  AND (SELECT count(DISTINCT actor_id) FROM public.platform_actor_identifiers WHERE identifier_value=a.scope->>'legalReceiverId' AND lower(identifier_type) IN('edielid','ediel_id') AND is_verified AND(valid_from IS NULL OR valid_from<=current_date) AND(valid_to IS NULL OR current_date<=valid_to))=1
  AND EXISTS(SELECT FROM public.platform_actor_identifiers WHERE actor_id=g.dso_actor_id AND identifier_value=a.scope->>'legalReceiverId' AND lower(identifier_type) IN('edielid','ediel_id') AND is_verified AND(valid_from IS NULL OR valid_from<=current_date) AND(valid_to IS NULL OR current_date<=valid_to))
  AND EXISTS(SELECT FROM public.tenant_actor_identifiers WHERE company_id=company AND environment=g.environment AND actor_id=g.legal_actor_id AND identifier_value=a.scope->>'legalSenderId' AND identifier_type='EdielId' AND valid_from<=now() AND(valid_to IS NULL OR now()<valid_to));
END$$;

