-- canonical:226
--
-- Name: recorded_supply_current_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.recorded_supply_current_v1(c uuid, s uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;r gridex_bilateral_prodat.supply_effect_receipts%rowtype;
 t gridex_received_sources.supply_source_transitions%rowtype;w jsonb;cap jsonb;own jsonb;seen text[]:=ARRAY[]::text[];key text;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_supply_v1();
 SELECT * INTO m FROM public.ediel_messages WHERE company_id=c AND id=s;
 SELECT * INTO t FROM gridex_received_sources.supply_source_transitions WHERE company_id=c AND source_message_id=s;
 IF m.id IS NULL OR t.source_message_id IS NULL OR m.raw_payload IS NULL OR t.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RETURN false;END IF;
 PERFORM public.ediel_require_source_bytes_available_v1(c,s);
 SELECT * INTO r FROM gridex_bilateral_prodat.supply_effect_receipts WHERE company_id=c AND source_message_id=s;
 IF m.message_code='Z05' AND EXISTS(SELECT FROM jsonb_array_elements(t.source_objects) o WHERE o->>'reason'='Z23') THEN RETURN gridex_bilateral_prodat.recorded_closure_end_current_v1(c,s);END IF;
 IF gridex_supply_rescission.recorded_end_current_v1(c,s) IS NOT TRUE THEN RETURN false;END IF;
 IF r.source_message_id IS NULL THEN RETURN NOT EXISTS(SELECT FROM jsonb_array_elements(t.source_objects) o WHERE o->>'reason'='Z25');END IF;
 IF r.environment IS DISTINCT FROM m.environment OR r.payload_hash IS DISTINCT FROM t.payload_hash
  OR r.transition_hash IS DISTINCT FROM encode(sha256(convert_to(to_jsonb(t)::text,'UTF8')),'hex') THEN RETURN false;END IF;
 w:=gridex_received_sources.normal_switch_wire_v1(m.raw_payload);
 IF w IS NULL OR (w->>'code' IN('Z04','Z05')) IS NOT TRUE OR t.source_code IS DISTINCT FROM w->>'code'
  OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT'
  OR jsonb_array_length(r.profiles) IS DISTINCT FROM (SELECT count(*) FROM jsonb_array_elements(t.source_objects) o WHERE o->>'reason'='Z25') THEN RETURN false;END IF;
 FOR cap IN SELECT p FROM jsonb_array_elements(r.profiles) p LOOP
  key:=jsonb_build_array(cap->>'objectId',cap->>'lineItemReference')::text;
  IF key=ANY(seen) OR cap->>'owner' IS DISTINCT FROM 'immutable-bilateral-prodat-profile-v1'
   OR cap->>'process' IS DISTINCT FROM (CASE w->>'code' WHEN 'Z04' THEN 'normal_start_h' WHEN 'Z05' THEN 'own_end_h' END)
   OR gridex_bilateral_prodat.recorded_profile_authority_v1((cap->>'profileVersionId')::uuid,c) IS NOT TRUE THEN RETURN false;END IF;
  seen:=array_append(seen,key);
  SELECT o INTO own FROM jsonb_array_elements(t.source_objects) o WHERE o->>'reason'='Z25' AND o->>'point'=cap->>'objectId' AND o->>'li'=cap->>'lineItemReference';
  IF own IS NULL OR (SELECT count(*) FROM jsonb_array_elements(w->'objects') o WHERE o=own)<>1 THEN RETURN false;END IF;
 END LOOP;
 RETURN true;
END$$;

REVOKE ALL ON FUNCTION gridex_bilateral_prodat.recorded_supply_current_v1(uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:227
--
-- Name: require_closure_draft_v1(uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.require_closure_draft_v1(c uuid, actor uuid, d jsonb, cap jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE scope jsonb;w jsonb;own jsonb;i public.ediel_message_intents%rowtype;r public.outbound_requests%rowtype;BEGIN
 scope:=gridex_bilateral_prodat.closure_operation_current_v1(c,actor,(d->>'sourceOperationId')::uuid);
 w:=gridex_bilateral_prodat.draft_wire_v1(d->>'rawPayload');own:=w#>'{objects,0}';
 IF scope IS NULL OR cap->>'messageCode' IS DISTINCT FROM 'Z08' OR jsonb_array_length(cap->'objects')<>1 OR jsonb_array_length(w->'objects')<>1 OR w->>'bgmId' IS DISTINCT FROM scope->>'documentReference'
  OR own->>'li' IS DISTINCT FROM scope->>'lineItemReference' OR own->>'reason' IS DISTINCT FROM 'Z23' OR own->>'point' IS DISTINCT FROM scope->>'externalPoint' OR gridex_received_sources.permission_time_v1(own->>'end') IS DISTINCT FROM (scope->>'effectiveAt')::timestamptz
  OR cap#>>'{objects,0,supplyPeriodId}' IS DISTINCT FROM scope->>'periodId' OR cap#>>'{objects,0,profileVersionId}' IS DISTINCT FROM scope->>'profileId'
  OR d->>'customerId' IS DISTINCT FROM scope->>'customerId' OR d->>'siteId' IS DISTINCT FROM scope->>'siteId' OR d->>'meteringPointId' IS DISTINCT FROM scope->>'pointId'
  OR nullif(d->>'switchRequestId','') IS NOT NULL THEN RAISE EXCEPTION 'bilateral_closure_actual_operation_required';END IF;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=(d->>'intentId')::uuid AND company_id=c FOR UPDATE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=(d->>'outboundRequestId')::uuid AND company_id=c FOR SHARE;
 IF i.id IS NULL OR i.ediel_message_id IS NOT NULL OR i.created_by IS DISTINCT FROM actor OR i.environment IS DISTINCT FROM scope->>'environment' OR i.direction IS DISTINCT FROM 'outbound' OR i.message_family IS DISTINCT FROM 'PRODAT' OR i.message_code IS DISTINCT FROM 'Z08' OR i.operation_id::text IS DISTINCT FROM scope->>'operationId'
  OR i.customer_id::text IS DISTINCT FROM scope->>'customerId' OR i.customer_site_id::text IS DISTINCT FROM scope->>'siteId' OR i.metering_point_id IS DISTINCT FROM scope->>'pointId' OR i.payload->>'transactionSubtype' IS DISTINCT FROM 'LK'
  OR r.id IS NULL OR r.request_type IS DISTINCT FROM 'supplier_switch_cancellation' OR r.source_type IS DISTINCT FROM 'manual' OR r.source_id IS DISTINCT FROM i.id OR r.operation_id IS DISTINCT FROM i.operation_id OR r.customer_id IS DISTINCT FROM i.customer_id OR r.site_id IS DISTINCT FROM i.customer_site_id OR r.metering_point_id::text IS DISTINCT FROM scope->>'pointId' OR r.payload->>'environment' IS DISTINCT FROM scope->>'environment'
 THEN RAISE EXCEPTION 'bilateral_closure_validated_own_intent_request_required';END IF;
END$$;

REVOKE ALL ON FUNCTION gridex_bilateral_prodat.require_closure_draft_v1(uuid, uuid, jsonb, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:229
--
-- Name: require_outbound_original_v1(public.ediel_messages, boolean); Type: FUNCTION; Schema: gridex_bilateral_prodat; Owner: -
--

CREATE FUNCTION gridex_bilateral_prodat.require_outbound_original_v1(m public.ediel_messages, p_creating boolean DEFAULT false) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o gridex_bilateral_prodat.outbound_operations%rowtype;r gridex_bilateral_prodat.outbound_receipts%rowtype;cap jsonb;
BEGIN
 IF m.direction IS DISTINCT FROM 'outbound' OR m.raw_payload IS NULL OR gridex_bilateral_prodat.outbound_required_v1(m.raw_payload) IS NOT TRUE THEN RETURN;END IF;
 PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 SELECT * INTO o FROM gridex_bilateral_prodat.outbound_operations WHERE message_id=m.id AND company_id=m.company_id;
 SELECT * INTO r FROM gridex_bilateral_prodat.outbound_receipts WHERE message_id=m.id AND company_id=m.company_id;
 IF o.message_id IS NULL OR r.message_id IS NULL OR o.environment IS DISTINCT FROM m.environment OR o.actor_user_id IS DISTINCT FROM m.created_by
  OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR r.payload_hash IS DISTINCT FROM o.payload_hash
  OR r.witness_id::text IS DISTINCT FROM m.execution_context_snapshot->>'outboundOwnerWitnessId'
  OR p_creating AND o.creation_txid IS DISTINCT FROM txid_current()
  OR NOT EXISTS(SELECT FROM gridex_ediel_outbound_owner.witnesses w WHERE w.id=r.witness_id AND w.company_id=m.company_id AND w.actor_user_id=o.actor_user_id AND w.environment=m.environment AND w.payload_sha256=o.payload_hash) THEN RAISE EXCEPTION 'bilateral_prodat_outbound_atomic_original_required';END IF;
 cap:=gridex_bilateral_prodat.outbound_capability_v1(m.company_id,o.actor_user_id,m.environment,m.raw_payload);
 IF cap IS NULL OR cap IS DISTINCT FROM o.capability THEN RAISE EXCEPTION 'bilateral_prodat_outbound_current_profile_required';END IF;
END$$;

REVOKE ALL ON FUNCTION gridex_bilateral_prodat.require_outbound_original_v1(public.ediel_messages, boolean) FROM PUBLIC,anon,authenticated,service_role;

