-- canonical:363
--
-- Name: bound_prodat_response_before_domain_effects_v1(public.ediel_messages, public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.bound_prodat_response_before_domain_effects_v1(m public.ediel_messages, s public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b gridex_ediel_ack_guide.prodat_structural_response_bindings%rowtype;facet jsonb;actual jsonb;positive_indices integer[];BEGIN
 SELECT binding.* INTO b FROM gridex_ediel_ack_guide.prodat_structural_response_bindings binding JOIN gridex_ediel_outbound_owner.consumptions c ON c.witness_id=binding.witness_id WHERE c.source_message_id=m.id;
 IF b.witness_id IS NULL AND m.execution_context_snapshot->>'outboundOwnerWitnessId' IS NOT NULL THEN SELECT * INTO b FROM gridex_ediel_ack_guide.prodat_structural_response_bindings WHERE witness_id=(m.execution_context_snapshot->>'outboundOwnerWitnessId')::uuid;END IF;
 IF b.witness_id IS NULL THEN
  -- The real owner invokes the national checker before the new seal exists.
  -- A draft can read committed primary receipts, but cannot provide a final
  -- verdict. Persisted ACKs require their original immutable binding instead.
  IF m.id IS NULL AND s.message_code IN('Z06','Z10') AND (EXISTS(SELECT FROM gridex_received_sources.structural_object_apply_receipts r WHERE r.source_message_id=s.id) OR EXISTS(SELECT FROM gridex_received_sources.customer_primary_response_receipts r WHERE r.source_message_id=s.id) OR EXISTS(SELECT FROM gridex_requested_changes.confirmed_customer_versions v WHERE v.source_message_id=s.id AND v.company_id=s.company_id AND v.environment=s.environment AND v.event_id IS NOT NULL AND v.bilateral_artifact_id IS NULL)) THEN
   facet:=gridex_received_sources.prodat_structural_response_v1(m.company_id,s.id,NULL);
   actual:=gridex_ediel_ack_guide.prodat_wire_responses_v1(m.raw_payload,facet->'objects');
   SELECT array_agg((x->>'lineIndex')::integer ORDER BY(x->>'lineIndex')::integer) INTO positive_indices FROM jsonb_array_elements(actual)x WHERE x->>'ercCode'='100';
   IF positive_indices IS NOT NULL AND (EXISTS(SELECT FROM gridex_received_sources.structural_object_apply_receipts r WHERE r.source_message_id=s.id AND r.first_line_index=ANY(positive_indices)) OR EXISTS(SELECT FROM gridex_received_sources.customer_primary_response_receipts r WHERE r.source_message_id=s.id AND r.first_line_index=ANY(positive_indices)) OR EXISTS(SELECT FROM gridex_requested_changes.confirmed_customer_versions v WHERE v.source_message_id=s.id AND v.company_id=s.company_id AND v.environment=s.environment AND v.event_id IS NOT NULL AND v.bilateral_artifact_id IS NULL)) THEN
    RETURN gridex_received_sources.prodat_structural_response_v1(m.company_id,s.id,positive_indices);
   END IF;
  END IF;
  RETURN gridex_ediel_ack_guide.bound_prodat_response_before_structural_v1(m,s);
 END IF;
 IF b.source_message_id IS DISTINCT FROM s.id OR b.company_id IS DISTINCT FROM m.company_id OR b.environment IS DISTINCT FROM m.environment OR b.ack_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR b.facet_hash IS DISTINCT FROM encode(sha256(convert_to(b.facet_text,'UTF8')),'hex') OR b.facet_text::jsonb->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_structural_response_frozen_binding_changed';END IF;
 RETURN b.facet_text::jsonb;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_guide.bound_prodat_response_before_domain_effects_v1(public.ediel_messages, public.ediel_messages) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:364
--
-- Name: bound_prodat_response_before_structural_v1(public.ediel_messages, public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.bound_prodat_response_before_structural_v1(m public.ediel_messages, s public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b gridex_ediel_ack_guide.prodat_response_owner_bindings%rowtype;facet jsonb;f gridex_received_sources.prodat_response_facets%rowtype;
BEGIN
 SELECT binding.* INTO b FROM gridex_ediel_ack_guide.prodat_response_owner_bindings binding JOIN gridex_ediel_outbound_owner.consumptions c ON c.witness_id=binding.witness_id WHERE c.source_message_id=m.id;
 IF b.witness_id IS NULL AND m.execution_context_snapshot->>'outboundOwnerWitnessId' IS NOT NULL THEN SELECT * INTO b FROM gridex_ediel_ack_guide.prodat_response_owner_bindings WHERE witness_id=(m.execution_context_snapshot->>'outboundOwnerWitnessId')::uuid;END IF;
 IF b.witness_id IS NULL THEN
  IF m.id IS NOT NULL THEN RAISE EXCEPTION 'prodat_response_frozen_owner_binding_unavailable';END IF;
  RETURN gridex_received_sources.require_prodat_responses_v1(m.company_id,s.id);
 END IF;
 IF b.company_id IS DISTINCT FROM m.company_id OR b.environment IS DISTINCT FROM m.environment OR b.source_message_id IS DISTINCT FROM s.id OR b.ack_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_response_frozen_owner_binding_changed';END IF;
 SELECT * INTO f FROM gridex_received_sources.prodat_response_facets WHERE assessment_id=b.assessment_id;
 IF f.response_facts_hash IS DISTINCT FROM b.facet_hash THEN RAISE EXCEPTION 'prodat_response_frozen_owner_binding_changed';END IF;
 RETURN gridex_received_sources.read_prodat_response_assessment_v1(m.company_id,s.id,b.assessment_id);
END $$;

