CREATE FUNCTION gridex_ediel_ack_guide.date_time_v1(v text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN IF v!~'^[0-9]{12}$' THEN RETURN false;END IF;RETURN to_char(make_timestamp(substr(v,1,4)::int,substr(v,5,2)::int,substr(v,7,2)::int,substr(v,9,2)::int,substr(v,11,2)::int,0),'YYYYMMDDHH24MI')=v;EXCEPTION WHEN OTHERS THEN RETURN false;END $_$;

