-- canonical:375
--
-- Name: prodat_wire_responses_v1(text, jsonb); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.prodat_wire_responses_v1(raw text, objects jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_utilts_binding.wire_tokens_v1(raw);a jsonb:=gridex_ack_authority.wire_v1(raw);t jsonb;ftx jsonb;own_li text;own_id text;object jsonb;result jsonb:='[]';finish integer;n integer;scope text;
BEGIN
 IF a IS NULL OR a->>'family' IS DISTINCT FROM 'APERAK' OR a#>>'{type,2}' IS DISTINCT FROM '96A' OR a#>>'{type,4}' IS DISTINCT FROM 'E2SE6A' OR a->>'function' NOT IN('27','34') THEN RAISE EXCEPTION 'prodat_response_native_scope_invalid';END IF;
 scope:=CASE a->>'function' WHEN '27' THEN 'message' ELSE 'object' END;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='ERC' ORDER BY(x->>'index')::integer LOOP
  SELECT min((x->>'index')::integer) INTO finish FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::integer>(t->>'index')::integer AND x->>'tag' IN('ERC','UNT','UNZ');
  SELECT x INTO ftx FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='FTX' AND(x->>'index')::integer=(t->>'index')::integer+1;
  IF ftx IS NULL THEN RAISE EXCEPTION 'prodat_response_native_scope_invalid';END IF;
  SELECT count(*),min(x#>>'{elements,1,1}') INTO n,own_li FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI' AND(x->>'index')::integer>(t->>'index')::integer AND(x->>'index')::integer<finish;
  IF n>1 THEN RAISE EXCEPTION 'prodat_response_native_scope_invalid';END IF;
  SELECT count(*),min(x#>>'{elements,1,1}') INTO n,own_id FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='Z07' AND(x->>'index')::integer>(t->>'index')::integer AND(x->>'index')::integer<finish;
  IF n>1 THEN RAISE EXCEPTION 'prodat_response_native_scope_invalid';END IF;object:=NULL;
  IF scope='object' THEN
   SELECT count(*) INTO n FROM jsonb_array_elements(objects)x WHERE CASE WHEN own_li IS NOT NULL THEN x->>'li'=own_li ELSE x->>'id'=own_id END AND(own_id IS NULL OR x->>'id'=own_id);
   SELECT x INTO object FROM jsonb_array_elements(objects)x WHERE CASE WHEN own_li IS NOT NULL THEN x->>'li'=own_li ELSE x->>'id'=own_id END AND(own_id IS NULL OR x->>'id'=own_id);
   IF n<>1 THEN RAISE EXCEPTION 'prodat_response_native_scope_invalid';END IF;
  END IF;
  result:=result||jsonb_build_array(jsonb_build_object('scope',scope,'lineIndex',CASE WHEN scope='object' THEN object->'lineIndex' ELSE 'null'::jsonb END,
   'ercCode',t#>>'{elements,1,0}','fieldCode',nullif(ftx#>>'{elements,3,0}',''),'text',ftx#>>'{elements,4,0}','id',own_id,'li',own_li));
 END LOOP;
 RETURN result;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_guide.prodat_wire_responses_v1(text, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:376
--
-- Name: projection_before_err_reason_scopes_v1(text); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.projection_before_err_reason_scopes_v1(p_source_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE original jsonb;extended jsonb;
BEGIN
 SELECT projection INTO STRICT original FROM gridex_ediel_ack_guide.editions WHERE source_version=p_source_version;
 IF original ? 'registeredGuideScopes' THEN RETURN original;END IF;
 SELECT e.projection INTO extended FROM gridex_ediel_ack_guide.edition_extensions x JOIN gridex_ediel_ack_guide.editions e ON e.source_version=x.extended_source_version WHERE x.original_source_version=p_source_version;
 IF extended IS NULL OR extended->'constraints' IS DISTINCT FROM original->'constraints' OR extended->'originalSources' IS DISTINCT FROM original->'originalSources' THEN RAISE EXCEPTION 'ediel_registered_original_guide_unavailable';END IF;
 RETURN extended;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_guide.projection_before_err_reason_scopes_v1(text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:377
--
-- Name: projection_for_original_v1(text); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.projection_for_original_v1(p_source_version text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE original jsonb;known jsonb;n integer;
BEGIN
 original:=gridex_ediel_ack_guide.projection_before_err_reason_scopes_v1(p_source_version);
 IF original ? 'utiltsErrReasonGuideScopes' THEN RETURN original;END IF;
 SELECT count(*) INTO n FROM gridex_ediel_ack_guide.err_reason_source_editions x JOIN gridex_ediel_ack_guide.editions e ON e.source_version=x.source_version
  WHERE e.projection->'constraints'=original->'constraints' AND e.projection->'utiltsErr'=original->'utiltsErr'
   AND e.projection->'registeredGuideScopes'=original->'registeredGuideScopes' AND e.projection->'originalSources'=original->'originalSources';
 SELECT e.projection INTO known FROM gridex_ediel_ack_guide.err_reason_source_editions x JOIN gridex_ediel_ack_guide.editions e ON e.source_version=x.source_version
  WHERE e.projection->'constraints'=original->'constraints' AND e.projection->'utiltsErr'=original->'utiltsErr'
   AND e.projection->'registeredGuideScopes'=original->'registeredGuideScopes' AND e.projection->'originalSources'=original->'originalSources';
 IF n<>1 OR known IS NULL THEN RAISE EXCEPTION 'ediel_original_err_reason_scope_unavailable';END IF;
 -- Supplemental source knowledge only: no new reception/version/acceptance.
 RETURN original||jsonb_build_object('utiltsErrReasonGuideScopes',known->'utiltsErrReasonGuideScopes');
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_guide.projection_for_original_v1(text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:378
--
-- Name: qualify_err_reason_projection_v1(jsonb, jsonb); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.qualify_err_reason_projection_v1(p_projection jsonb, p_basis jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r jsonb:=p_basis#>'{snapshot,rulePack}';reasons jsonb;n integer;
BEGIN
 IF r->>'family' IS DISTINCT FROM 'UTILTS' THEN RETURN p_projection;END IF;
 SELECT count(*) INTO n FROM jsonb_array_elements(p_projection->'utiltsErrReasonGuideScopes')s
  WHERE s->>'family'=r->>'family' AND s->>'guideVersion'=r->>'guide_version' AND s->>'guideRevision'=r->>'guide_revision';
 SELECT s->'allowedReasons' INTO reasons FROM jsonb_array_elements(p_projection->'utiltsErrReasonGuideScopes')s
  WHERE s->>'family'=r->>'family' AND s->>'guideVersion'=r->>'guide_version' AND s->>'guideRevision'=r->>'guide_revision';
 IF n<>1 OR jsonb_typeof(reasons) IS DISTINCT FROM 'array' OR jsonb_array_length(reasons)=0 THEN RAISE EXCEPTION 'ediel_original_err_reason_scope_unavailable';END IF;
 RETURN jsonb_set(p_projection,'{utiltsErr,allowedReasons}',reasons,false);
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_guide.qualify_err_reason_projection_v1(jsonb, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:379
--
-- Name: require_before_mixed_object_results_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.require_before_mixed_object_results_v1(m public.ediel_messages) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;b gridex_ediel_ack_guide.source_bindings%rowtype;projection jsonb;basis jsonb;binding_kind text;observed timestamptz:=clock_timestamp();stamp text;document_at timestamptz;
BEGIN
 IF m.message_family NOT IN('APERAK','CONTRL','UTILTS_ERR') THEN RETURN;END IF;
 binding_kind:=CASE WHEN m.message_family='CONTRL' THEN 'technical' WHEN m.execution_context_snapshot->>'prodatCommonHeaderNegativeWitnessId' IS NOT NULL THEN 'common' ELSE 'national' END;
 SELECT * INTO source FROM public.ediel_messages WHERE id=m.related_message_id AND (company_id=m.company_id OR (binding_kind IN('technical','common') AND company_id IS NULL)) AND environment=m.environment AND direction='inbound' FOR SHARE;IF source.id IS NULL THEN RAISE EXCEPTION 'ediel_native_ack_guide_source_required';END IF;
 basis:=CASE binding_kind WHEN 'technical' THEN gridex_ediel_technical_ack.require_source_v1(m.company_id,source.id) WHEN 'common' THEN gridex_ediel_common_header.require_ack_v1(m) ELSE gridex_ediel_source_rules.require_v1(m.company_id,source.id) END;
 SELECT * INTO b FROM gridex_ediel_ack_guide.source_bindings WHERE source_message_id=source.id AND kind=binding_kind FOR SHARE;IF b.source_message_id IS NULL THEN RAISE EXCEPTION 'ediel_historical_ack_guide_basis_unavailable';END IF;
 IF b.company_id IS DISTINCT FROM m.company_id OR b.environment IS DISTINCT FROM m.environment OR b.payload_sha256 IS DISTINCT FROM encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex') OR b.original_basis IS DISTINCT FROM basis THEN RAISE EXCEPTION 'ediel_ack_guide_original_basis_changed';END IF;
 projection:=gridex_ediel_ack_guide.projection_for_original_v1(b.source_version);projection:=gridex_ediel_ack_guide.qualify_err_reason_projection_v1(projection,basis);PERFORM gridex_ediel_ack_guide.require_registered_basis_v1(source,binding_kind,basis,projection);
 IF NOT coalesce(gridex_ediel_ack_guide.validate_response_for_message_v1(m,source,projection),false) THEN RAISE EXCEPTION 'ediel_native_ack_guide_invalid';END IF;
 IF m.message_family='UTILTS_ERR' AND projection#>>'{utiltsErr,documentDate,noFuture}'='true' THEN
  SELECT x#>>'{elements,1,1}' INTO stamp FROM jsonb_array_elements(gridex_utilts_binding.wire_tokens_v1(m.raw_payload))x WHERE x->>'tag'='DTM' AND x#>>'{elements,1,0}'=projection#>>'{utiltsErr,documentDate,qualifier}';
  document_at:=(make_timestamp(substr(stamp,1,4)::int,substr(stamp,5,2)::int,substr(stamp,7,2)::int,substr(stamp,9,2)::int,substr(stamp,11,2)::int,0) AT TIME ZONE 'UTC')-interval '1 hour';IF document_at>observed THEN RAISE EXCEPTION 'ediel_native_err_document_date_future';END IF;
 END IF;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_guide.require_before_mixed_object_results_v1(public.ediel_messages) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:380
--
-- Name: require_before_prodat_scope_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.require_before_prodat_scope_v1(m public.ediel_messages) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;tokens jsonb;t jsonb;group_tokens jsonb;next_group integer;li text;point text;r gridex_received_sources.prodat_mixed_object_receipts%rowtype;
BEGIN
 PERFORM gridex_ediel_ack_guide.require_before_mixed_object_results_v1(m);
 IF m.message_family IS DISTINCT FROM 'APERAK' THEN RETURN;END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=m.related_message_id AND company_id=m.company_id AND environment=m.environment FOR SHARE;
 IF source.message_family IS DISTINCT FROM 'PRODAT' THEN RETURN;END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(m.raw_payload);
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='ERC' AND x#>>'{elements,1,0}'='100') THEN RETURN;END IF;
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='ERC' AND x#>>'{elements,1,0}'<>'100') THEN
  IF EXISTS(SELECT FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=source.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex') AND a.facts_text::jsonb->>'applicationDecision'='rejected' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id)) THEN RAISE EXCEPTION 'prodat_mixed_ack_whole_source_success_forbidden';END IF;
  RETURN;
 END IF;
 SELECT * INTO r FROM gridex_received_sources.prodat_mixed_object_receipts WHERE source_message_id=source.id AND company_id=m.company_id AND environment=m.environment AND source_payload_hash=encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex') FOR SHARE;
 IF NOT FOUND AND EXISTS(SELECT FROM gridex_received_sources.supply_object_partitions p WHERE p.source_message_id=source.id AND p.company_id=m.company_id
   AND p.environment=m.environment AND p.payload_hash=encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex'))
  AND EXISTS(SELECT FROM pg_trigger WHERE tgrelid='public.ediel_messages'::regclass AND tgname='domain_response_birth' AND tgenabled<>'D'
   AND tgfoid='gridex_received_sources.require_domain_response_at_birth_v1()'::regprocedure) THEN RETURN;END IF;
 IF NOT FOUND OR NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments a JOIN gridex_received_sources.prodat_object_validation_facets f ON f.assessment_id=a.id AND f.facts_hash=r.object_facts_hash AND f.source_payload_hash=r.source_payload_hash WHERE a.facts_hash=(SELECT initial.facts_hash FROM gridex_received_sources.validation_assessments initial WHERE initial.id=r.assessment_id) AND a.source_message_id=source.id AND a.company_id=m.company_id AND a.environment=m.environment AND a.source_payload_hash=r.source_payload_hash AND a.facts_text::jsonb->>'syntaxDecision'='accepted' AND a.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id))
 OR NOT EXISTS(SELECT FROM gridex_received_sources.prodat_mixed_reply_outbox o WHERE o.source_message_id=source.id AND o.company_id=m.company_id AND o.environment=m.environment AND o.source_payload_hash=r.source_payload_hash AND o.object_facts_hash=r.object_facts_hash) THEN RAISE EXCEPTION 'prodat_mixed_ack_committed_own_results_required';END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='ERC' AND x#>>'{elements,1,0}'='100' LOOP
  SELECT min((x->>'index')::integer) INTO next_group FROM jsonb_array_elements(tokens) x WHERE (x->>'index')::integer>(t->>'index')::integer AND x->>'tag' IN('ERC','UNT');
  SELECT jsonb_agg(x) INTO group_tokens FROM jsonb_array_elements(tokens) x WHERE (x->>'index')::integer>(t->>'index')::integer AND (x->>'index')::integer<next_group;
  SELECT x#>>'{elements,1,1}' INTO li FROM jsonb_array_elements(group_tokens) x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI';
  SELECT x#>>'{elements,1,1}' INTO point FROM jsonb_array_elements(group_tokens) x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='Z07';
  IF li IS NULL OR point IS NULL OR NOT EXISTS(SELECT FROM jsonb_array_elements(r.processed_objects) o WHERE o->>'objectId'=point AND o->>'lineItemReference'=li AND o->>'disposition'='accepted')
   OR NOT EXISTS(SELECT FROM gridex_received_sources.normal_switch_confirmations c WHERE c.company_id=m.company_id AND c.source_message_id=source.id AND c.source_object->>'point'=point AND c.source_object->>'li'=li) THEN RAISE EXCEPTION 'prodat_mixed_ack_own_commit_mismatch';END IF;
 END LOOP;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_guide.require_before_prodat_scope_v1(public.ediel_messages) FROM PUBLIC,anon,authenticated,service_role;

