 IF is_utilts AND (SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='DTM' AND x#>>'{elements,1,0}'=cfg#>>'{fixedOffset,0}' AND x#>'{elements,1}'=cfg->'fixedOffset')<>1 THEN RETURN false;END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='NAD' AND (x->>'index')::int<first_erc LOOP
  e:=t->'elements';reference:=e#>>'{1,0}';
  IF reference IN(CASE WHEN is_utilts THEN 'MS' ELSE 'FR' END,CASE WHEN is_utilts THEN 'MR' ELSE 'DO' END) THEN
   part:=e->2;IF nullif(part->>0,'') IS NULL OR length(part->>0)>35 THEN RETURN false;END IF;
   IF is_utilts THEN IF NOT cfg->'legalAgencies' ? (part->>2) OR (part->>2=cfg->>'svkAgency' AND part->>1 IS DISTINCT FROM cfg->>'svkQualifier') THEN RETURN false;END IF;
   ELSE IF part->>1 IS DISTINCT FROM cfg->>'legalQualifier' OR part->>2 IS DISTINCT FROM cfg->>'legalAgency' OR NOT coalesce(e#>>'{9,0}'~(cfg->>'countryPattern'),false) THEN RETURN false;END IF;END IF;
   SELECT count(*) INTO party_count FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='NAD' AND (x->>'index')::int<first_erc AND x#>>'{elements,1,0}'=reference;IF party_count<>1 THEN RETURN false;END IF;
   SELECT x->'elements' INTO opposite FROM jsonb_array_elements(original)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'=CASE reference WHEN 'MS' THEN 'MR' WHEN 'MR' THEN 'MS' WHEN 'FR' THEN 'DO' ELSE 'FR' END ORDER BY(x->>'index')::int LIMIT 1;
   IF opposite->2 IS DISTINCT FROM part OR (NOT is_utilts AND opposite#>>'{9,0}' IS DISTINCT FROM e#>>'{9,0}') THEN RETURN false;END IF;
  END IF;
 END LOOP;
 IF NOT is_utilts THEN
  source_objects:=p_source_objects;
 END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='ERC' ORDER BY(x->>'index')::int LOOP
  group_start:=(t->>'index')::int;SELECT min((x->>'index')::int) INTO group_end FROM jsonb_array_elements(tokens)x WHERE (x->>'index')::int>group_start AND x->>'tag' IN('ERC','UNT','UNZ');
  e:=t->'elements';erc:=e#>>'{1,0}';
  IF NOT cfg->'allowedErc' ? erc OR nullif(e#>>'{1,1}','') IS NOT NULL OR e#>>'{1,2}' IS DISTINCT FROM cfg->>'agency' OR gridex_ediel_ack_guide.tail_populated_v1(e->1,3) THEN RETURN false;END IF;
  IF (is_utilts AND ((a->>'code'='312' AND erc<>'100') OR (a->>'code'='313' AND erc='100'))) OR (NOT is_utilts AND a->>'function'='27' AND erc='100') THEN RETURN false;END IF;
  SELECT count(*) INTO party_count FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='FTX' AND (x->>'index')::int>group_start AND (x->>'index')::int<group_end;IF party_count<>1 THEN RETURN false;END IF;
  SELECT x->'elements' INTO e FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='FTX' AND (x->>'index')::int=group_start+1;IF e IS NULL OR e#>>'{1,0}' IS DISTINCT FROM cfg->>'textQualifier' OR gridex_ediel_ack_guide.tail_populated_v1(e->2,0) OR gridex_ediel_ack_guide.tail_populated_v1(e->4,1) OR gridex_ediel_ack_guide.tail_populated_v1(e->5,0) OR gridex_ediel_ack_guide.tail_populated_v1(e->6,0) THEN RETURN false;END IF;
  literal:=e#>>'{4,0}';reference:=e#>>'{3,0}';IF nullif(literal,'') IS NULL OR length(literal)>(cfg->>'textMax')::int THEN RETURN false;END IF;
  IF erc='100' THEN IF literal IS DISTINCT FROM common->>'positiveText' OR gridex_ediel_ack_guide.tail_populated_v1(e->3,0) THEN RETURN false;END IF;
  ELSE
   IF nullif(reference,'') IS NULL OR length(reference)>(cfg->>'fieldReferenceMax')::int OR nullif(e#>>'{3,1}','') IS NOT NULL OR e#>>'{3,2}' IS DISTINCT FROM cfg->>'agency' OR gridex_ediel_ack_guide.tail_populated_v1(e->3,3) THEN RETURN false;END IF;
   IF is_utilts THEN IF (erc='41' AND literal IS DISTINCT FROM cfg->>'missingText') OR (erc='42' AND literal!~(cfg->>'invalidTextPattern')) THEN RETURN false;END IF;
   ELSE
    label:=cfg#>>ARRAY['fieldLabels',reference];
    IF erc IN('41','42') AND label IS NULL THEN RETURN false;END IF;
    IF erc='40' AND (cfg#>>ARRAY['applicationTexts',reference] IS NULL OR literal IS DISTINCT FROM cfg#>>ARRAY['applicationTexts',reference]) THEN RETURN false;END IF;
    IF erc='41' AND literal<>label||(cfg->>'missingSuffix') AND left(literal,length(label||(cfg->>'missingCustomerPrefix')))<>label||(cfg->>'missingCustomerPrefix') THEN RETURN false;END IF;
    IF erc='42' AND (left(literal,length((cfg->>'invalidPrefix')||label||' '))<>(cfg->>'invalidPrefix')||label||' ' OR length(literal)<=length((cfg->>'invalidPrefix')||label||' ')) THEN RETURN false;END IF;
   END IF;
  END IF;
  IF is_utilts THEN
   SELECT count(*),min(x#>>'{elements,1,1}') INTO ref_count,reference FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='DM' AND (x->>'index')::int>group_start AND (x->>'index')::int<group_end;
   IF ref_count<>1 OR nullif(reference,'') IS NULL OR length(reference)>(cfg->>'ownDmMax')::int OR reference=ANY(dm) THEN RETURN false;END IF;dm:=array_append(dm,reference);
   SELECT count(*),min(x#>>'{elements,1,1}') INTO ref_count,reference FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='ACW' AND (x->>'index')::int>group_start AND (x->>'index')::int<group_end;
   IF ref_count>1 OR (ref_count=1 AND (nullif(reference,'') IS NULL OR length(reference)>(cfg->>'originalAcwMax')::int)) OR (erc='100' AND ref_count<>1) THEN RETURN false;END IF;
  ELSE
   SELECT count(*),min(x#>>'{elements,1,1}') INTO ref_count,own_li FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI' AND (x->>'index')::int>group_start AND (x->>'index')::int<group_end;
   IF ref_count>1 OR (erc='100' AND ref_count<>1) OR (ref_count=1 AND (nullif(own_li,'') IS NULL OR length(own_li)>35)) THEN RETURN false;END IF;
   SELECT count(*),min(x#>>'{elements,1,1}') INTO ref_count,own_object FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='Z07' AND (x->>'index')::int>group_start AND (x->>'index')::int<group_end;
   IF ref_count>1 OR (ref_count=1 AND (nullif(own_object,'') IS NULL OR length(own_object)>25)) THEN RETURN false;END IF;
   IF NOT (a->>'function'='27' AND own_li IS NULL AND own_object IS NULL) THEN
    SELECT jsonb_agg(x) INTO matches FROM jsonb_array_elements(source_objects)x WHERE CASE WHEN own_li IS NOT NULL THEN x->>'li'=own_li ELSE x->>'id'=own_object END;
    IF jsonb_array_length(coalesce(matches,'[]'))<>1 OR matches#>>'{0,li}' IS DISTINCT FROM own_li OR (nullif(matches#>>'{0,id}','') IS NOT NULL AND matches#>>'{0,id}' IS DISTINCT FROM own_object AND NOT(erc='100' AND s->>'code'='Z13')) THEN RETURN false;END IF;
    answered:=array_append(answered,coalesce(matches#>>'{0,id}','')||'|'||coalesce(matches#>>'{0,li}',''));
   END IF;
  END IF;
 END LOOP;
 -- P original pp85-87 allows several APERAKs for one multi-object source. Own tuple completeness is checked by the protected response owner.
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_guide.validate_prodat_planned_v1(text, text, jsonb, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:399
--
-- Name: validate_response_for_message_v1(public.ediel_messages, public.ediel_messages, jsonb); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.validate_response_for_message_v1(m public.ediel_messages, s public.ediel_messages, projection jsonb) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE facet jsonb;actual jsonb;expected jsonb;w gridex_ediel_outbound_owner.witnesses%rowtype;row_established gridex_ediel_ack_guide.established_prodat_acks%rowtype;
BEGIN
 IF m.execution_context_snapshot->>'prodatCommonHeaderNegativeWitnessId' IS NOT NULL AND gridex_ediel_header_negative_birth.evidence_v1(s) IS NOT NULL THEN
  PERFORM gridex_ediel_header_negative_birth.assert_ack_v1(m,gridex_ediel_common_header.require_ack_v1(m));RETURN true;
 END IF;
 IF gridex_ediel_duplicate_responses.allows_message_v1(m) THEN PERFORM gridex_ediel_duplicate_responses.require_wire_v1(m.raw_payload,s.raw_payload,projection);RETURN true;END IF;
 IF m.message_family IS DISTINCT FROM 'APERAK' OR s.message_family IS DISTINCT FROM 'PRODAT' OR m.execution_context_snapshot->>'prodatCommonHeaderNegativeWitnessId' IS NOT NULL THEN RETURN gridex_ediel_ack_guide.validate_v1(m.raw_payload,s.raw_payload,projection);END IF;
 SELECT * INTO row_established FROM gridex_ediel_ack_guide.established_prodat_acks WHERE ack_message_id=m.id;
 IF row_established.ack_message_id IS NOT NULL THEN
  IF row_established.source_message_id IS DISTINCT FROM s.id OR row_established.company_id IS DISTINCT FROM m.company_id OR row_established.environment IS DISTINCT FROM m.environment
   OR row_established.ack_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR row_established.source_hash IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_response_established_original_changed';END IF;
  SELECT witness.* INTO w FROM gridex_ediel_outbound_owner.consumptions c JOIN gridex_ediel_outbound_owner.witnesses witness ON witness.id=c.witness_id WHERE c.source_message_id=m.id AND c.company_id=m.company_id AND c.environment=m.environment AND c.payload_sha256=row_established.ack_hash;
  IF w.id IS NULL THEN RAISE EXCEPTION 'prodat_response_established_original_changed';END IF;PERFORM gridex_ediel_outbound_owner.assert_message_before_native_ack_guide_v1(m,w);RETURN true;
 END IF;
 facet:=gridex_ediel_ack_guide.bound_prodat_response_v1(m,s);
 IF NOT coalesce(gridex_ediel_ack_guide.validate_prodat_planned_v1(m.raw_payload,s.raw_payload,projection,facet->'objects'),false) THEN RETURN false;END IF;
 actual:=gridex_ediel_ack_guide.prodat_wire_responses_v1(m.raw_payload,facet->'objects');
 -- A per-object ACK must carry its actual planned own errors/confirmation;
 -- another object's response and an invented subset cannot supply its result.
 SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') INTO expected FROM jsonb_array_elements(facet->'responses')x WHERE EXISTS(SELECT FROM jsonb_array_elements(actual)a WHERE a->'scope'=x->'scope' AND a->'lineIndex'=x->'lineIndex');
 SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') INTO actual FROM jsonb_array_elements(actual)x;
 RETURN jsonb_array_length(actual)>0 AND actual=expected;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_guide.validate_response_for_message_v1(public.ediel_messages, public.ediel_messages, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:400
--
-- Name: validate_utilts_err_v1(text, text, jsonb); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.validate_utilts_err_v1(p_raw text, p_source_raw text, p_projection jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_utilts_binding.wire_tokens_v1(p_raw);original jsonb:=gridex_utilts_binding.wire_tokens_v1(p_source_raw);a jsonb:=gridex_ack_authority.wire_v1(p_raw);s jsonb:=gridex_ack_authority.wire_v1(p_source_raw);cfg jsonb:=p_projection->'utiltsErr';t jsonb;source_token jsonb;field jsonb;e jsonb;actual jsonb;expected jsonb;header_end integer;source_header_end integer;group_start integer;group_end integer;source_start integer;source_end integer;seq integer;n integer;tx text;own_id text;reason text;ids text[]:='{}';answered text[]:='{}';opposite text;qualifier text;
BEGIN
 IF tokens IS NULL OR original IS NULL OR a IS NULL OR s IS NULL OR cfg IS NULL OR cfg->>'version'<>'1' OR a->>'family'<>'UTILTS' OR a->>'code'<>'ERR' OR s->>'family'<>'UTILTS' OR NOT coalesce(cfg->'originalMessageCodes' ? (s->>'code'),false) OR NOT coalesce(gridex_ack_authority.source_match_v1(a,s),false) THEN RETURN false;END IF;
 IF a->'type' IS DISTINCT FROM cfg->'technicalProfile' OR a->'type' IS DISTINCT FROM s->'type' OR EXISTS(SELECT FROM jsonb_array_elements(tokens)x WHERE cfg->'forbiddenSegments' ? (x->>'tag')) THEN RETURN false;END IF;
 SELECT count(*),min((x->>'index')::int) INTO n,header_end FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='IDE';IF n=0 THEN RETURN false;END IF;
 SELECT min((x->>'index')::int) INTO source_header_end FROM jsonb_array_elements(original)x WHERE x->>'tag'='IDE';IF source_header_end IS NULL THEN RETURN false;END IF;
 SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='BGM';IF n<>1 THEN RETURN false;END IF;
 SELECT x->'elements' INTO e FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='BGM';
 IF e#>>'{1,0}' IS DISTINCT FROM cfg->>'documentCode' OR e#>>'{1,2}' IS DISTINCT FROM cfg->>'documentAgency' OR NOT coalesce(cfg->'optionalDocumentCodeLists' ? coalesce(e#>>'{1,1}',''),false) OR gridex_ediel_ack_guide.tail_populated_v1(e->1,3) OR nullif(e#>>'{2,0}','') IS NULL OR length(e#>>'{2,0}')>(cfg->>'documentIdMax')::int OR jsonb_array_length(e->2)<>1 OR NOT coalesce(cfg->'allowedFunctions' ? (e#>>'{3,0}'),false) OR NOT coalesce(cfg->'allowedAcknowledgementRequests' ? (e#>>'{4,0}'),false) OR jsonb_array_length(e->3)<>1 OR jsonb_array_length(e->4)<>1 OR jsonb_array_length(e)>5 THEN RETURN false;END IF;
 SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='DTM' AND x#>>'{elements,1,0}'=cfg#>>'{documentDate,qualifier}' AND(x->>'index')::int<header_end;IF n<>1 THEN RETURN false;END IF;
 SELECT x#>'{elements,1}' INTO e FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='DTM' AND x#>>'{elements,1,0}'=cfg#>>'{documentDate,qualifier}' AND(x->>'index')::int<header_end;
 IF jsonb_array_length(e)<>3 OR e->>2 IS DISTINCT FROM cfg#>>'{documentDate,format}' OR NOT coalesce(gridex_ediel_ack_guide.date_time_v1(e->>1),false) THEN RETURN false;END IF;
 SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='DTM' AND x#>>'{elements,1,0}'='735' AND(x->>'index')::int<header_end;IF n<>1 THEN RETURN false;END IF;
 SELECT x#>'{elements,1}' INTO e FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='DTM' AND x#>>'{elements,1,0}'='735' AND(x->>'index')::int<header_end;IF e IS DISTINCT FROM cfg->'fixedOffset' THEN RETURN false;END IF;
 SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='MKS' AND(x->>'index')::int<header_end;IF n<>1 THEN RETURN false;END IF;
 SELECT x->'elements' INTO actual FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='MKS' AND(x->>'index')::int<header_end;
 SELECT count(*) INTO n FROM jsonb_array_elements(original)x WHERE x->>'tag'='MKS' AND(x->>'index')::int<source_header_end;IF n<>1 THEN RETURN false;END IF;
 SELECT x->'elements' INTO expected FROM jsonb_array_elements(original)x WHERE x->>'tag'='MKS' AND(x->>'index')::int<source_header_end;
 IF actual IS DISTINCT FROM expected OR NOT coalesce(cfg->'marketCodes' ? (actual#>>'{1,0}'),false) OR NOT coalesce(cfg->'phaseCodes' ? (actual#>>'{2,0}'),false) OR actual#>>'{2,2}' IS DISTINCT FROM cfg->>'agency' THEN RETURN false;END IF;
 FOREACH qualifier IN ARRAY ARRAY['MS','MR'] LOOP
  SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'=qualifier AND(x->>'index')::int<header_end;IF n<>1 THEN RETURN false;END IF;
  SELECT x#>'{elements,2}' INTO e FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'=qualifier AND(x->>'index')::int<header_end;
  IF nullif(e->>0,'') IS NULL OR length(e->>0)>35 OR NOT coalesce(cfg->'legalAgencies' ? (e->>2),false) OR (e->>2=cfg->>'svkAgency' AND e->>1 IS DISTINCT FROM cfg->>'svkQualifier') THEN RETURN false;END IF;
  IF e->>1=cfg#>>'{identity,edielQualifier}' AND (e->>0)!~(cfg#>>'{identity,edielIdPattern}') THEN RETURN false;END IF;
  IF cfg#>'{identity,gs1Agencies}' ? (e->>2) THEN
   IF (e->>0)!~(cfg#>>'{identity,glnPattern}') OR (SELECT sum(substr(e->>0,i,1)::int*(cfg#>'{identity,glnCheckWeights}'->>((i-1)%jsonb_array_length(cfg#>'{identity,glnCheckWeights}')))::int)%10 FROM generate_series(1,length(e->>0))i)<>0 THEN RETURN false;END IF;
  END IF;
 END LOOP;
 SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}' NOT IN('MS','MR') AND(x->>'index')::int<header_end;IF n<>1 THEN RETURN false;END IF;
 SELECT x->'elements' INTO actual FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}' NOT IN('MS','MR') AND(x->>'index')::int<header_end;
 SELECT count(*) INTO n FROM jsonb_array_elements(original)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}' NOT IN('MS','MR') AND(x->>'index')::int<source_header_end;IF n<>1 THEN RETURN false;END IF;
 SELECT x->'elements' INTO expected FROM jsonb_array_elements(original)x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}' NOT IN('MS','MR') AND(x->>'index')::int<source_header_end;
 IF actual IS DISTINCT FROM expected OR NOT coalesce(cfg->'subordinateRoles' ? (actual#>>'{1,0}'),false) OR EXISTS(SELECT FROM jsonb_array_elements(actual)WITH ORDINALITY z(e,n) WHERE z.n>2 AND gridex_ediel_ack_guide.tail_populated_v1(z.e,0)) THEN RETURN false;END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='IDE' ORDER BY(x->>'index')::int LOOP
  group_start:=(t->>'index')::int;SELECT min((x->>'index')::int) INTO group_end FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::int>group_start AND x->>'tag' IN('IDE','UNT','UNZ');IF group_end IS NULL THEN RETURN false;END IF;
  own_id:=t#>>'{elements,2,0}';IF t#>'{elements,1}' IS DISTINCT FROM jsonb_build_array(cfg->>'transactionQualifier') OR t#>'{elements,2}' IS DISTINCT FROM jsonb_build_array(own_id) OR nullif(own_id,'') IS NULL OR length(own_id)>(cfg->>'ownTransactionIdMax')::int OR own_id=ANY(ids) THEN RETURN false;END IF;ids:=array_append(ids,own_id);
  SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='STS' AND x#>>'{elements,1,0}'=cfg->>'responseQualifier' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;IF n<>1 THEN RETURN false;END IF;
  SELECT x->'elements' INTO e FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='STS' AND x#>>'{elements,1,0}'=cfg->>'responseQualifier' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;reason:=e#>>'{3,0}';
  IF e->1 IS DISTINCT FROM jsonb_build_array(cfg->>'responseQualifier','',cfg->>'agency') OR e->2 IS DISTINCT FROM jsonb_build_array(cfg->>'responseStatus') OR e->3 IS DISTINCT FROM jsonb_build_array(reason,'',cfg->>'agency') OR NOT coalesce(cfg->'allowedReasons' ? reason,false) OR jsonb_array_length(e)>4 THEN RETURN false;END IF;
  SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'=cfg->>'referenceQualifier' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;IF n<>1 THEN RETURN false;END IF;
  SELECT x#>'{elements,1}' INTO e FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'=cfg->>'referenceQualifier' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;tx:=e->>1;
  IF e IS DISTINCT FROM jsonb_build_array(cfg->>'referenceQualifier',tx) OR nullif(tx,'') IS NULL OR length(tx)>(cfg->>'originalTransactionIdMax')::int OR (tx||'|'||reason)=ANY(answered) THEN RETURN false;END IF;answered:=array_append(answered,tx||'|'||reason);
  IF EXISTS(SELECT FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}' NOT IN(cfg->>'referenceQualifier',s->>'code') AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end) THEN RETURN false;END IF;
  SELECT count(*) INTO n FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'=s->>'code' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;IF n<>1 THEN RETURN false;END IF;
  SELECT x#>'{elements,1}' INTO e FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'=s->>'code' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;IF e IS DISTINCT FROM jsonb_build_array(s->>'code',s->>'document') THEN RETURN false;END IF;
  SELECT count(*) INTO n FROM jsonb_array_elements(original)x WHERE x->>'tag'='IDE' AND x#>>'{elements,1,0}'=cfg->>'transactionQualifier' AND x#>>'{elements,2,0}'=tx;IF n<>1 THEN RETURN false;END IF;
  SELECT(x->>'index')::int INTO source_start FROM jsonb_array_elements(original)x WHERE x->>'tag'='IDE' AND x#>>'{elements,1,0}'=cfg->>'transactionQualifier' AND x#>>'{elements,2,0}'=tx;
  SELECT min((x->>'index')::int) INTO source_end FROM jsonb_array_elements(original)x WHERE(x->>'index')::int>source_start AND x->>'tag' IN('IDE','UNT','UNZ');SELECT min((x->>'index')::int) INTO seq FROM jsonb_array_elements(original)x WHERE x->>'tag'='SEQ' AND(x->>'index')::int>source_start AND(x->>'index')::int<source_end;source_end:=coalesce(seq,source_end);
  FOR field IN SELECT x FROM jsonb_array_elements(p_projection->'utiltsErrSourceCopyFields')x LOOP
   SELECT jsonb_agg(x->'elements' ORDER BY(x->>'index')::int) INTO expected FROM jsonb_array_elements(original)x WHERE x->>'tag'=field->>'tag' AND x#>>'{elements,1,0}'=field->>'qualifier' AND(x->>'index')::int>source_start AND(x->>'index')::int<source_end;
   SELECT jsonb_agg(x->'elements' ORDER BY(x->>'index')::int) INTO actual FROM jsonb_array_elements(tokens)x WHERE x->>'tag'=field->>'tag' AND x#>>'{elements,1,0}'=field->>'qualifier' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;
   IF coalesce(actual,'[]') IS DISTINCT FROM coalesce(expected,'[]') THEN RETURN false;END IF;
  END LOOP;
 END LOOP;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_guide.validate_utilts_err_v1(text, text, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:401
--
-- Name: validate_v1(text, text, jsonb); Type: FUNCTION; Schema: gridex_ediel_ack_guide; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_guide.validate_v1(p_raw text, p_source_raw text, p_projection jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a jsonb:=gridex_ack_authority.wire_v1(p_raw);
BEGIN IF a->>'family'='UTILTS' AND a->>'code'='ERR' THEN RETURN gridex_ediel_ack_guide.validate_utilts_err_v1(p_raw,p_source_raw,p_projection);END IF;RETURN gridex_ediel_ack_guide.validate_before_registered_responses_v1(p_raw,p_source_raw,p_projection);END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_guide.validate_v1(text, text, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:402
--
-- Name: beneficiary_series_page_filtered_v2(uuid, uuid, uuid, bigint, text, uuid, text[], timestamp with time zone, timestamp with time zone, integer, timestamp with time zone, uuid); Type: FUNCTION; Schema: gridex_ediel_ack_replay; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_replay.beneficiary_series_page_filtered_v2(p_beneficiary_company_id uuid, p_actor_user_id uuid, p_grant_id uuid, p_expected_grant_version bigint, p_purpose text, p_series_id uuid, p_fields text[], p_start timestamp with time zone, p_end timestamp with time zone, p_limit integer DEFAULT 100, p_after_at timestamp with time zone DEFAULT NULL::timestamp with time zone, p_after_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
declare g public.ediel_data_access_grants%rowtype; a public.ediel_service_assignments%rowtype; l public.ediel_assignment_permission_links%rowtype; p public.metering_permissions%rowtype; s public.meter_reading_series%rowtype; payload jsonb; next_cursor jsonb; source_id uuid; source_context jsonb; source_row public.ediel_messages%rowtype; bound_contract jsonb; selected_contract jsonb; source_transaction text; source_sender text; dso_id text;
begin
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM m.user_id FROM public.company_memberships m WHERE m.company_id=p_beneficiary_company_id AND m.user_id=p_actor_user_id FOR SHARE;
 if not exists(select 1 from public.company_memberships m where m.company_id=p_beneficiary_company_id and m.user_id=p_actor_user_id and m.status='active' and m.is_active and m.accepted_at is not null) or not exists(select 1 from public.user_profiles u where u.id=p_actor_user_id and u.user_status='active') or not coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_beneficiary_company_id,'metering.read'),false) then raise exception 'ediel_beneficiary_forbidden' using errcode='42501'; end if;
 if p_start is null or p_end is null or p_end<=p_start or p_limit is null or p_limit<1 or p_limit>500 or (p_after_at is null)<>(p_after_id is null) or p_fields is null or cardinality(p_fields)=0 or array_position(p_fields,null) is not null then raise exception 'ediel_projection_request_invalid'; end if;
 -- Match the command's assignment-before-grant lock order. Identity is immutable.
 select * into strict g from public.ediel_data_access_grants where id=p_grant_id and beneficiary_company_id=p_beneficiary_company_id;
 -- Discover the owned immutable source first, then lock it before assignment/grant:
 -- the shared legal-context authority takes the same source FOR UPDATE lock.
 SELECT source_ediel_message_id INTO STRICT source_id FROM public.meter_reading_series WHERE company_id=g.company_id AND id=p_series_id;
 source_context:=gridex_ediel_inbound_context.require_v1(g.company_id,source_id);
 SELECT * INTO STRICT source_row FROM public.ediel_messages WHERE company_id=g.company_id AND id=source_id;
 source_context:=gridex_ediel_ack_replay.require_current_source_role_v2(g.company_id,source_row.environment,source_id);
 select * into strict a from public.ediel_service_assignments where company_id=g.company_id and id=g.assignment_id for share;
 select * into strict g from public.ediel_data_access_grants where id=p_grant_id and beneficiary_company_id=p_beneficiary_company_id for share;
 if p_expected_grant_version is null or p_expected_grant_version<1 or g.version is distinct from p_expected_grant_version or g.status<>'active' or g.revoked_at is not null or g.valid_from>now() or (g.valid_to is not null and g.valid_to<=now()) then raise exception 'ediel_grant_not_current'; end if;
 if g.beneficiary_company_id is distinct from a.beneficiary_company_id or g.purpose is distinct from a.purpose or not(g.object_ids <@ a.object_ids and g.product_ids <@ a.product_ids and g.fields <@ a.field_sets) or g.data_start<a.data_start or (a.data_end is not null and (g.data_end is null or g.data_end>a.data_end)) or g.valid_from<a.valid_from or (a.valid_to is not null and (g.valid_to is null or g.valid_to>a.valid_to)) then raise exception 'ediel_grant_basis_changed'; end if;
 if public.ediel_service_assignment_assessment_v1(a.company_id,a.id)->>'status' is distinct from 'authorized' then raise exception 'ediel_assignment_not_authorized'; end if;
 if p_purpose is null or p_purpose<>g.purpose or not(p_fields <@ g.fields) or p_start<g.data_start or (g.data_end is not null and p_end>g.data_end) then raise exception 'ediel_projection_outside_grant'; end if;
 select * into strict l from public.ediel_assignment_permission_links where company_id=g.company_id and id=g.permission_link_id and assignment_id=g.assignment_id for share;
 select * into strict p from public.metering_permissions where company_id=g.company_id and id=l.permission_id for share;
 if (p.status in ('active','approved','partially_approved')) is not true or p.customer_id is distinct from a.customer_id or p.source_z14_message_id is null and p.inbound_z14_message_id is null then raise exception 'ediel_market_permission_not_approved'; end if;
 PERFORM x.id FROM public.metering_permission_sites x WHERE x.company_id=g.company_id AND x.metering_permission_id=p.id ORDER BY x.id FOR SHARE;
 if public.ediel_permission_source_is_current_v1(g.company_id,p.id,coalesce(p.inbound_z14_message_id,p.source_z14_message_id)) is not true then raise exception 'ediel_permission_source_not_current'; end if;
 if gridex_service_administration.permission_matches_assignment_v1(a,p) is not true then raise exception 'ediel_permission_legal_actor_mismatch';end if;
 select * into strict s from public.meter_reading_series where company_id=g.company_id and id=p_series_id for share;
 if s.message_code is distinct from 'E66' or s.series_kind is distinct from 'actual' or (s.external_metering_point_id=any(g.object_ids)) is not true or (s.product_id=any(g.product_ids)) is not true or s.period_start is null or s.period_end is null or p_start<s.period_start or p_end>s.period_end then raise exception 'ediel_series_outside_grant'; end if;
 if s.source_ediel_message_id IS DISTINCT FROM source_id OR source_row.environment IS DISTINCT FROM a.environment OR source_row.direction IS DISTINCT FROM 'inbound' OR source_row.message_family IS DISTINCT FROM 'UTILTS' OR source_row.message_code IS DISTINCT FROM 'E66' OR source_context->>'legalActorId' IS DISTINCT FROM a.provider_actor_id::text OR source_context->>'actorRole' IS DISTINCT FROM 'energy_service_company' OR source_context->>'environment' IS DISTINCT FROM a.environment OR source_context->>'direction' IS DISTINCT FROM 'inbound' OR source_context->>'family' IS DISTINCT FROM 'UTILTS' OR source_context->>'code' IS DISTINCT FROM 'E66' THEN RAISE EXCEPTION 'ediel_series_source_actor_not_qualified'; END IF;
 -- Bind the series to its private accepted transaction, never parsed metadata.
 SELECT c.transaction_id,c.contract INTO STRICT source_transaction,selected_contract FROM gridex_utilts_binding.contracts c WHERE c.company_id=g.company_id AND c.series_id=s.id AND c.source_message_id=source_id;
 bound_contract:=gridex_utilts_binding.stored_contract_v1(g.company_id,source_id,source_transaction);
 IF bound_contract IS DISTINCT FROM selected_contract OR bound_contract->>'seriesKind' IS DISTINCT FROM 'actual' OR bound_contract->>'messageCode' IS DISTINCT FROM 'E66' OR EXISTS(SELECT FROM jsonb_array_elements(bound_contract->'observations') o WHERE o->>'externalPoint' IS DISTINCT FROM s.external_metering_point_id OR o->>'productCode' IS DISTINCT FROM s.product_id) THEN RAISE EXCEPTION 'ediel_series_source_contract_mismatch';END IF;
 SELECT min(t#>>'{elements,2,0}') INTO source_sender FROM jsonb_array_elements(gridex_utilts_binding.wire_tokens_v1(source_row.raw_payload)) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='MS';
 SELECT min(i.identifier_value) INTO dso_id FROM public.platform_actor_identifiers i WHERE i.actor_id=a.dso_actor_id AND lower(i.identifier_type) IN ('edielid','ediel_id') AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date);
 IF source_sender IS NULL OR source_sender IS DISTINCT FROM dso_id OR (SELECT count(*) FROM jsonb_array_elements(gridex_utilts_binding.wire_tokens_v1(source_row.raw_payload)) t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='MS')<>1 THEN RAISE EXCEPTION 'ediel_series_source_dso_not_qualified';END IF;
 if not exists(select 1 from public.ediel_messages z14 where z14.id=coalesce(p.inbound_z14_message_id,p.source_z14_message_id) and z14.company_id=g.company_id and z14.environment=a.environment and z14.direction='inbound' and z14.message_family='PRODAT' and z14.message_code='Z14') then raise exception 'ediel_permission_source_not_qualified'; end if;
 if not exists(select 1 from public.metering_permission_sites x where x.company_id=g.company_id and x.metering_permission_id=p.id and x.customer_id=a.customer_id and x.facility_id=s.external_metering_point_id and x.status in ('approved','active') and x.metadata->>'source'='inbound_prodat_z14' and x.metadata->>'edielMessageId'=coalesce(p.inbound_z14_message_id,p.source_z14_message_id)::text and x.metadata->>'mode'=case a.mode when 'V' then 'S17' else 'S18' end and x.metadata->>'product'=s.product_id and x.start_at is not null and p_start>=x.start_at and (x.end_at is null or p_end<=x.end_at)) then raise exception 'ediel_permission_object_not_approved'; end if;
 -- Field whitelist is the full projection: raw_transaction/metadata/raw EML are never returned.
 with page as (
  select v.id,v.reading_at,(select jsonb_object_agg(k,value) from jsonb_each(jsonb_build_object('reading_at',v.reading_at,'quantity',v.quantity::text,'unit',v.unit,'quality',v.quality,'qualifier',v.qualifier,'registration_date',s.registration_date,'resolution',s.resolution,'product_id',s.product_id)) as allowed(k,value) where k=any(p_fields)) as projected
  from public.meter_reading_values v where v.company_id=g.company_id and v.series_id=s.id and v.reading_at>=p_start and v.reading_at<p_end and (p_after_at is null or (v.reading_at,v.id)>(p_after_at,p_after_id)) order by v.reading_at,v.id limit p_limit
 ) select coalesce(jsonb_agg(projected order by reading_at,id),'[]'::jsonb),(select jsonb_build_object('readingAt',reading_at,'valueId',id) from page order by reading_at desc,id desc limit 1) into payload,next_cursor from page;
 return jsonb_build_object('grantId',g.id,'grantVersion',g.version,'seriesId',s.id,'rows',payload,'next',case when jsonb_array_length(payload)=p_limit then next_cursor else null end);
end;
$$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_replay.beneficiary_series_page_filtered_v2(uuid, uuid, uuid, bigint, text, uuid, text[], timestamp with time zone, timestamp with time zone, integer, timestamp with time zone, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:406
--
-- Name: current_service_grant_set_v2(uuid, text, jsonb, text, text, text, timestamp with time zone, timestamp with time zone, jsonb, uuid[]); Type: FUNCTION; Schema: gridex_ediel_ack_replay; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_replay.current_service_grant_set_v2(c uuid, env text, ctx jsonb, sender text, point text, product text, v_period_start timestamp with time zone, v_period_end timestamp with time zone, contract jsonb, only_grant_ids uuid[] DEFAULT NULL::uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE candidate uuid;candidates uuid[]:=ARRAY[]::uuid[];proofs jsonb:='[]';evidence jsonb;assessment jsonb;dso_ids text[];
 a public.ediel_service_assignments%rowtype;g public.ediel_data_access_grants%rowtype;l public.ediel_assignment_permission_links%rowtype;p public.metering_permissions%rowtype;site public.metering_permission_sites%rowtype;
BEGIN
 IF c IS NULL OR (env IN('test','production')) IS NOT TRUE OR ctx->>'companyId' IS DISTINCT FROM c::text OR ctx->>'environment' IS DISTINCT FROM env
 OR (ctx->>'actorRole' IN('energy_service_company','esco')) IS NOT TRUE OR ctx->>'family' IS DISTINCT FROM 'UTILTS' OR ctx->>'code' IS DISTINCT FROM 'E66'
 OR nullif(sender,'') IS NULL OR nullif(point,'') IS NULL OR nullif(product,'') IS NULL OR v_period_start IS NULL OR v_period_end IS NULL OR v_period_end<=v_period_start THEN RAISE EXCEPTION 'ediel_ack_service_scope_source_unqualified';END IF;
 IF only_grant_ids IS NOT NULL AND (cardinality(only_grant_ids)=0 OR array_position(only_grant_ids,NULL) IS NOT NULL OR cardinality(only_grant_ids)<>(SELECT count(DISTINCT x) FROM unnest(only_grant_ids)x)) THEN RAISE EXCEPTION 'ediel_ack_service_scope_captured_set_invalid';END IF;

  FOR candidate IN SELECT x.id FROM public.ediel_data_access_grants x JOIN public.ediel_service_assignments y ON y.company_id=x.company_id AND y.id=x.assignment_id
   WHERE x.company_id=c AND x.status='active' AND x.revoked_at IS NULL AND x.valid_from<=now() AND (x.valid_to IS NULL OR now()<x.valid_to)
   AND y.provider_actor_id::text=ctx->>'legalActorId' AND y.actor_profile_id::text=ctx#>>'{facts,profile,id}' AND y.environment=env
   AND (only_grant_ids IS NULL OR x.id=ANY(only_grant_ids)) AND point=ANY(x.object_ids) AND product=ANY(x.product_ids) AND v_period_start>=x.data_start AND (x.data_end IS NULL OR v_period_end<=x.data_end) ORDER BY x.id LOOP
   SELECT * INTO STRICT g FROM public.ediel_data_access_grants WHERE company_id=c AND id=candidate FOR SHARE;
   SELECT * INTO STRICT a FROM public.ediel_service_assignments WHERE company_id=c AND id=g.assignment_id FOR SHARE;
   IF g.beneficiary_company_id IS DISTINCT FROM a.beneficiary_company_id OR g.purpose IS DISTINCT FROM a.purpose OR NOT(g.object_ids <@ a.object_ids AND g.product_ids <@ a.product_ids AND g.fields <@ a.field_sets)
   OR g.data_start<a.data_start OR (a.data_end IS NOT NULL AND (g.data_end IS NULL OR g.data_end>a.data_end)) OR g.valid_from<a.valid_from OR (a.valid_to IS NOT NULL AND (g.valid_to IS NULL OR g.valid_to>a.valid_to))
   OR public.ediel_service_assignment_assessment_v1(c,a.id)->>'status' IS DISTINCT FROM 'authorized' THEN CONTINUE;END IF;
   IF contract#>>'{metering,capability}'='write' AND (contract#>>'{metering,customerId}' IS DISTINCT FROM a.customer_id::text
    OR NOT EXISTS(SELECT mp.id FROM public.metering_points mp WHERE mp.company_id=c AND mp.id::text=contract#>>'{metering,meteringPointId}' AND mp.customer_id=a.customer_id
      AND coalesce(nullif(mp.ediel_metering_point_id,''),nullif(mp.meter_point_id,''),mp.metering_point_id)=point
      AND (contract#>>'{metering,siteId}' IS NULL OR coalesce(mp.customer_site_id,mp.site_id)::text=contract#>>'{metering,siteId}') FOR SHARE)) THEN CONTINUE;END IF;
   IF contract#>>'{billing,capability}'='write' AND contract#>>'{billing,customerId}' IS DISTINCT FROM a.customer_id::text THEN CONTINUE;END IF;
   SELECT * INTO l FROM public.ediel_assignment_permission_links WHERE company_id=c AND id=g.permission_link_id AND assignment_id=a.id;IF NOT FOUND THEN CONTINUE;END IF;
   SELECT * INTO p FROM public.metering_permissions WHERE company_id=c AND id=l.permission_id;
   IF NOT FOUND OR (p.status IN('active','approved','partially_approved')) IS NOT TRUE OR p.customer_id IS DISTINCT FROM a.customer_id OR gridex_service_administration.permission_matches_assignment_v1(a,p) IS NOT TRUE THEN CONTINUE;END IF;
   SELECT array_agg(DISTINCT i.identifier_value ORDER BY i.identifier_value) INTO dso_ids FROM public.platform_actor_identifiers i WHERE i.actor_id=a.dso_actor_id AND lower(i.identifier_type) IN('edielid','ediel_id') AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date);
   IF cardinality(dso_ids) IS DISTINCT FROM 1 OR dso_ids[1] IS DISTINCT FROM sender THEN CONTINUE;END IF;
   IF public.ediel_permission_source_is_current_v1(c,p.id,coalesce(p.inbound_z14_message_id,p.source_z14_message_id)) IS NOT TRUE THEN CONTINUE;END IF;
   IF NOT EXISTS(SELECT FROM public.ediel_messages z WHERE z.company_id=c AND z.id=coalesce(p.inbound_z14_message_id,p.source_z14_message_id) AND z.environment=env AND z.direction='inbound' AND z.message_family='PRODAT' AND z.message_code='Z14') THEN CONTINUE;END IF;
   IF (SELECT count(*) FROM public.metering_permission_sites x WHERE x.company_id=c AND x.metering_permission_id=p.id AND x.customer_id=a.customer_id AND x.facility_id=point AND x.status IN('approved','active')
    AND x.metadata->>'source'='inbound_prodat_z14' AND x.metadata->>'edielMessageId'=coalesce(p.inbound_z14_message_id,p.source_z14_message_id)::text AND x.metadata->>'mode'=CASE a.mode WHEN 'V' THEN 'S17' ELSE 'S18' END AND x.metadata->>'product'=product AND x.start_at IS NOT NULL AND v_period_start>=x.start_at AND (x.end_at IS NULL OR v_period_end<=x.end_at))<>1 THEN CONTINUE;END IF;
   candidates:=array_append(candidates,candidate);
   SELECT * INTO STRICT site FROM public.metering_permission_sites x WHERE x.company_id=c AND x.metering_permission_id=p.id AND x.customer_id=a.customer_id AND x.facility_id=point AND x.status IN('approved','active') AND x.metadata->>'source'='inbound_prodat_z14' AND x.metadata->>'edielMessageId'=coalesce(p.inbound_z14_message_id,p.source_z14_message_id)::text AND x.metadata->>'mode'=CASE a.mode WHEN 'V' THEN 'S17' ELSE 'S18' END AND x.metadata->>'product'=product AND x.start_at IS NOT NULL AND v_period_start>=x.start_at AND (x.end_at IS NULL OR v_period_end<=x.end_at);
   SELECT coalesce(jsonb_agg(gridex_ediel_services.evidence_receipt_row_v1(e) ORDER BY e.id),'[]'::jsonb) INTO evidence FROM public.ediel_service_evidence e WHERE e.company_id=c AND e.assignment_id=a.id AND e.status='verified' AND e.approved_assignment_version=a.scope_basis_version AND e.valid_from<=now() AND (e.valid_to IS NULL OR now()<e.valid_to) AND e.approved_at<=now();
   proofs:=proofs||jsonb_build_array(jsonb_build_object('assignment',to_jsonb(a),'grant',to_jsonb(g),'permissionLink',to_jsonb(l),'permission',to_jsonb(p),'site',to_jsonb(site),'evidence',evidence));
  END LOOP;

 IF cardinality(candidates)=0 THEN RAISE EXCEPTION 'ediel_ack_service_scope_current_grant_required' USING ERRCODE='42501';END IF;
 IF only_grant_ids IS NOT NULL AND cardinality(candidates)<>cardinality(only_grant_ids) THEN RAISE EXCEPTION 'ediel_ack_service_scope_captured_grant_not_current' USING ERRCODE='42501';END IF;
 -- Different beneficiaries/field sets/purposes are separate internal missions.
 -- Conflicting upstream customer or DSO relations cannot be guessed from GSRN.
 IF (SELECT count(DISTINCT jsonb_build_array(x#>>'{assignment,customer_id}',x#>>'{assignment,provider_actor_id}',x#>>'{assignment,dso_actor_id}',x#>>'{assignment,actor_profile_id}')) FROM jsonb_array_elements(proofs)x)<>1 THEN RAISE EXCEPTION 'ediel_ack_service_scope_upstream_relation_ambiguous' USING ERRCODE='42501';END IF;
 RETURN proofs;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_replay.current_service_grant_set_v2(uuid, text, jsonb, text, text, text, timestamp with time zone, timestamp with time zone, jsonb, uuid[]) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:407
--
-- Name: lock_current_graph_v2(); Type: FUNCTION; Schema: gridex_ediel_ack_replay; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_replay.lock_current_graph_v2() RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 LOCK TABLE auth.users,public.user_profiles,public.companies,public.company_memberships,public.admin_users,
  public.user_roles,public.roles,public.role_permissions,public.permissions,public.user_permissions,public.user_permission_overrides,
  public.tenant_actor_identifiers,public.tenant_actor_roles,public.tenant_ediel_profiles,public.tenant_counterparty_relations,public.platform_actor_identifiers,
  public.ediel_service_assignments,public.ediel_service_evidence,public.ediel_data_access_grants,public.ediel_assignment_permission_links,
  public.metering_permissions,public.metering_permission_sites,public.ediel_ack_transaction_results,public.meter_reading_series,
  gridex_utilts_binding.receipts,gridex_utilts_binding.contracts,gridex_service_administration.scope_versions,
  gridex_received_sources.permission_transitions,gridex_received_sources.validation_assessments IN SHARE MODE;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_replay.lock_current_graph_v2() FROM PUBLIC,anon,authenticated,service_role;

-- canonical:409
--
-- Name: positive_service_scope_projection_v2(uuid, text, uuid, text, jsonb); Type: FUNCTION; Schema: gridex_ediel_ack_replay; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_replay.positive_service_scope_projection_v2(c uuid, env text, sourceid uuid, ackraw text, sealed jsonb DEFAULT NULL::jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE ctx jsonb; origin_ctx jsonb; source public.ediel_messages%rowtype; origin public.ediel_messages%rowtype;
 tokens jsonb; t jsonb; current_erc text; positive_refs text[]:=ARRAY[]::text[]; tx text;
 reservation public.ediel_ack_transaction_results%rowtype; series public.meter_reading_series%rowtype;
 contract jsonb; stored gridex_utilts_binding.contracts%rowtype;
 a public.ediel_service_assignments%rowtype; g public.ediel_data_access_grants%rowtype;
 l public.ediel_assignment_permission_links%rowtype; p public.metering_permissions%rowtype;
 site public.metering_permission_sites%rowtype; candidate uuid; candidates uuid[];
 dso_ids text[]; sender text; origin_sender text; assessment jsonb; proofs jsonb:='[]'::jsonb; evidence jsonb;scopes jsonb;chosen jsonb;ids uuid[];base jsonb;sealed_version int;
BEGIN
 IF c IS NULL OR (env IN ('test','production')) IS NOT TRUE OR sourceid IS NULL OR ackraw IS NULL THEN RAISE EXCEPTION 'ediel_ack_service_scope_unavailable';END IF;
 -- Same graph locks as the atomic ACK owner; table locks prevent a newly
 -- inserted alternative grant or identity from racing unique-scope discovery.
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 ctx:=gridex_ediel_ack_replay.require_current_source_role_v2(c,env,sourceid);
 SELECT * INTO STRICT source FROM public.ediel_messages WHERE company_id=c AND id=sourceid AND environment=env FOR SHARE;
 IF (ctx->>'actorRole' IN ('energy_service_company','esco')) IS NOT TRUE OR ctx->>'family' IS DISTINCT FROM 'UTILTS'
 OR source.direction IS DISTINCT FROM 'inbound' OR source.message_family IS DISTINCT FROM 'UTILTS' OR source.message_code IS DISTINCT FROM 'E66'
 OR ctx->>'code' IS DISTINCT FROM 'E66' OR ctx->>'applicationReference' IS DISTINCT FROM source.application_reference
 OR (ctx->>'applicationReference' ~ '^23-(DDQ|DGI)-E66-(S|T)$') IS NOT TRUE THEN RAISE EXCEPTION 'ediel_ack_service_scope_source_unqualified';END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(ackraw);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='UNH' AND x#>>'{elements,2,0}'='APERAK')<>1
 OR (SELECT count(*) FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='BGM' AND x#>>'{elements,1,0}'='312')<>1 THEN RAISE EXCEPTION 'ediel_ack_service_scope_ack_unqualified';END IF;
 -- ERC scopes its following ACW, rather than treating any ACW in a mixed
 -- positive/negative response as a positive transaction.
 FOR t IN SELECT value FROM jsonb_array_elements(tokens) WITH ORDINALITY x(value,n) ORDER BY n LOOP
  IF t->>'tag'='ERC' THEN current_erc:=t#>>'{elements,1,0}';
  ELSIF t->>'tag'='RFF' AND t#>>'{elements,1,0}'='ACW' AND current_erc='100' THEN
   tx:=t#>>'{elements,1,1}';IF nullif(tx,'') IS NULL OR tx=ANY(positive_refs) THEN RAISE EXCEPTION 'ediel_ack_service_scope_positive_reference_invalid';END IF;
   positive_refs:=array_append(positive_refs,tx);
  END IF;
 END LOOP;
 IF sealed IS NOT NULL AND (jsonb_typeof(sealed->'transactions') IS DISTINCT FROM 'array' OR jsonb_array_length(sealed->'transactions')<>cardinality(positive_refs)) THEN RAISE EXCEPTION 'ediel_ack_service_scope_captured_set_invalid';END IF;
 IF cardinality(positive_refs)=0 THEN RAISE EXCEPTION 'ediel_ack_service_scope_positive_reference_unavailable';END IF;
 SELECT min(x#>>'{elements,2,0}') INTO sender FROM jsonb_array_elements(gridex_utilts_binding.wire_tokens_v1(source.raw_payload)) x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='MS';
 IF sender IS NULL OR (SELECT count(*) FROM jsonb_array_elements(gridex_utilts_binding.wire_tokens_v1(source.raw_payload)) x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='MS')<>1 THEN RAISE EXCEPTION 'ediel_ack_service_scope_dso_unqualified';END IF;
 FOREACH tx IN ARRAY positive_refs LOOP
  PERFORM public.gridex_require_utilts_positive_ack_authority_v1(c,env,sourceid,tx,NULL,NULL);
  SELECT * INTO STRICT reservation FROM public.ediel_ack_transaction_results WHERE company_id=c AND environment=env AND source_message_id=sourceid AND source_transaction_id=tx FOR SHARE;
  SELECT * INTO STRICT series FROM public.meter_reading_series WHERE company_id=c AND id=reservation.persisted_series_id FOR SHARE;
  SELECT * INTO STRICT stored FROM gridex_utilts_binding.contracts WHERE company_id=c AND series_id=series.id;
  contract:=gridex_utilts_binding.stored_contract_v1(c,series.source_ediel_message_id,stored.transaction_id);
  origin_ctx:=gridex_ediel_inbound_context.require_v1(c,series.source_ediel_message_id);
  SELECT * INTO STRICT origin FROM public.ediel_messages WHERE company_id=c AND id=series.source_ediel_message_id;
  -- Earlier genuine accepted origin reuse remains valid. The private contract
  -- and both original/current DSO identities still have to agree.
  IF contract IS DISTINCT FROM stored.contract OR contract->>'seriesKind' IS DISTINCT FROM 'actual' OR contract->>'messageCode' IS DISTINCT FROM 'E66'
  OR series.series_kind IS DISTINCT FROM 'actual' OR series.message_code IS DISTINCT FROM 'E66' OR series.period_start IS NULL OR series.period_end IS NULL OR series.period_end<=series.period_start
  OR origin.environment IS DISTINCT FROM env OR origin_ctx->>'legalActorId' IS DISTINCT FROM ctx->>'legalActorId' OR origin_ctx->>'legalEdielId' IS DISTINCT FROM ctx->>'legalEdielId'
  OR (origin_ctx->>'actorRole' IN ('energy_service_company','esco')) IS NOT TRUE OR origin_ctx->>'family' IS DISTINCT FROM 'UTILTS' OR origin_ctx->>'code' IS DISTINCT FROM 'E66'
  OR EXISTS(SELECT FROM jsonb_array_elements(contract->'observations') o WHERE o->>'externalPoint' IS DISTINCT FROM series.external_metering_point_id OR o->>'productCode' IS DISTINCT FROM series.product_id) THEN RAISE EXCEPTION 'ediel_ack_service_scope_contract_unqualified';END IF;
  SELECT min(x#>>'{elements,2,0}') INTO origin_sender FROM jsonb_array_elements(gridex_utilts_binding.wire_tokens_v1(origin.raw_payload)) x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='MS';
  IF origin_sender IS DISTINCT FROM sender OR (SELECT count(*) FROM jsonb_array_elements(gridex_utilts_binding.wire_tokens_v1(origin.raw_payload)) x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='MS')<>1 THEN RAISE EXCEPTION 'ediel_ack_service_scope_dso_unqualified';END IF;
  ids:=NULL;chosen:=NULL;
  IF sealed IS NOT NULL THEN
   SELECT x INTO STRICT chosen FROM jsonb_array_elements(sealed->'transactions')x WHERE x->>'transactionId'=tx;
   sealed_version:=(sealed->>'version')::int;
   IF sealed_version=1 THEN ids:=ARRAY[(chosen#>>'{grant,id}')::uuid];
   ELSIF sealed_version=2 THEN SELECT array_agg((x#>>'{grant,id}')::uuid ORDER BY x#>>'{grant,id}') INTO ids FROM jsonb_array_elements(chosen->'scopes')x;
   ELSE RAISE EXCEPTION 'ediel_ack_service_scope_captured_set_invalid';END IF;
  END IF;
  scopes:=gridex_ediel_ack_replay.current_service_grant_set_v2(c,env,ctx,sender,series.external_metering_point_id,series.product_id,series.period_start,series.period_end,contract,ids);
  base:=jsonb_build_object('transactionId',tx,'seriesId',series.id,'originMessageId',origin.id,'originRawHash',encode(sha256(convert_to(origin.raw_payload,'UTF8')),'hex'),'contractHash',stored.contract_hash,'originContext',origin_ctx);
  IF sealed IS NOT NULL AND sealed_version=1 THEN
   IF jsonb_array_length(scopes)<>1 THEN RAISE EXCEPTION 'ediel_ack_service_scope_captured_set_invalid';END IF;
   proofs:=proofs||jsonb_build_array(base||(scopes->0));
  ELSE proofs:=proofs||jsonb_build_array(base||jsonb_build_object('scopes',scopes));END IF;

 END LOOP;
 RETURN jsonb_build_object('version',CASE WHEN sealed IS NULL THEN 2 ELSE (sealed->>'version')::int END,'companyId',c,'environment',env,'sourceMessageId',sourceid,'sourceRawHash',encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex'),'ackRawHash',encode(sha256(convert_to(ackraw,'UTF8')),'hex'),'sourceContext',ctx,'transactions',proofs);
END $_$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_replay.positive_service_scope_projection_v2(uuid, text, uuid, text, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:410
--
-- Name: prodat_permission_scope_projection_v2(uuid, text, uuid, text); Type: FUNCTION; Schema: gridex_ediel_ack_replay; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_replay.prodat_permission_scope_projection_v2(c uuid, env text, sourceid uuid, ackraw text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE ctx jsonb;s public.ediel_messages%rowtype;outcomes jsonb;transitions jsonb;source_rules jsonb;h text;committed jsonb;positive_indices integer[];own jsonb;source_wire jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 ctx:=gridex_ediel_ack_replay.require_current_source_role_v2(c,env,sourceid);
 SELECT * INTO STRICT s FROM public.ediel_messages WHERE company_id=c AND id=sourceid AND environment=env AND direction='inbound' FOR SHARE;
 IF (ctx->>'actorRole' IN('energy_service_company','esco')) IS NOT TRUE OR ctx->>'family' IS DISTINCT FROM 'PRODAT' OR s.message_family IS DISTINCT FROM 'PRODAT' OR s.message_code NOT IN('Z14','Z15') OR ctx->>'code' IS DISTINCT FROM s.message_code THEN RAISE EXCEPTION 'ediel_ack_service_scope_source_unqualified';END IF;
 source_rules:=gridex_ediel_source_rules.require_v1(c,sourceid);
 outcomes:=gridex_ediel_ack_guide.prodat_outcomes_v1(ackraw,s.raw_payload);
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(outcomes)x WHERE x->>'outcome'='positive') THEN RAISE EXCEPTION 'ediel_ack_service_scope_positive_reference_unavailable';END IF;
 h:=encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex');
 SELECT jsonb_agg(to_jsonb(t) ORDER BY t.permission_id) INTO transitions FROM gridex_received_sources.permission_transitions t WHERE t.company_id=c AND t.source_message_id=sourceid AND t.payload_hash=h AND t.qualified_expected_message_code=s.message_code AND t.qualified_original_message_id IS NOT NULL;
 -- Historical projections stay byte-identical. A new producer must prove
 -- every positive physical object using its committed own canonical receipt.
 IF transitions IS NULL THEN
  IF EXISTS(SELECT FROM jsonb_array_elements(outcomes)x WHERE x->>'outcome'='positive' AND(x->>'scope' IS DISTINCT FROM 'object' OR x#>>'{physicalReference,lineIndex}' IS NULL)) THEN
   RAISE EXCEPTION 'ediel_ack_service_scope_prodat_own_commit_required';
  END IF;
  SELECT array_agg(DISTINCT (x#>>'{physicalReference,lineIndex}')::integer ORDER BY (x#>>'{physicalReference,lineIndex}')::integer)
   INTO positive_indices FROM jsonb_array_elements(outcomes)x WHERE x->>'outcome'='positive';
  committed:=gridex_received_sources.committed_permission_effects_v1(c,sourceid,positive_indices);
  source_wire:=gridex_received_sources.permission_partition_wire_v1(s.raw_payload);
  FOR own IN SELECT value FROM jsonb_array_elements(outcomes) WHERE value->>'outcome'='positive' LOOP
   IF NOT EXISTS(SELECT FROM jsonb_array_elements(committed)e
    WHERE e#>>'{objectScope,registers,0,segmentIndex}'=own#>>'{physicalReference,lineIndex}'
     AND e#>>'{objectScope,objectId}' IS NOT DISTINCT FROM own#>>'{physicalReference,id}'
     AND e->>'sourcePayloadHash'=h
     AND EXISTS(SELECT FROM jsonb_array_elements(source_wire->'objects')o
      WHERE o->>'firstLineIndex'=own#>>'{physicalReference,lineIndex}'
       AND o->>'point' IS NOT DISTINCT FROM own#>>'{physicalReference,id}'
       AND o->>'li' IS NOT DISTINCT FROM own#>>'{physicalReference,li}')) THEN
    RAISE EXCEPTION 'ediel_ack_service_scope_prodat_own_commit_required';
   END IF;
  END LOOP;
  SELECT jsonb_agg(to_jsonb(t) ORDER BY t.permission_id) INTO transitions
   FROM gridex_received_sources.permission_effect_transitions_v1 t
   WHERE t.company_id=c AND t.source_message_id=sourceid AND t.payload_hash=h
    AND t.qualified_expected_message_code=s.message_code AND t.qualified_original_message_id IS NOT NULL
    AND EXISTS(SELECT FROM gridex_received_sources.permission_effect_receipts r,jsonb_array_elements(committed)e
     WHERE r.id::text=e->>'receiptId' AND r.company_id=c AND r.source_message_id=sourceid
      AND r.permission_id=t.permission_id AND r.payload_hash=h);
 END IF;
 IF transitions IS NULL THEN RAISE EXCEPTION 'ediel_ack_service_scope_prodat_own_commit_required';END IF;
 RETURN jsonb_build_object('version',2,'scopeKind','prescribed_prodat_permission_ack','companyId',c,'environment',env,'sourceMessageId',sourceid,'sourceRawHash',h,'ackRawHash',encode(sha256(convert_to(ackraw,'UTF8')),'hex'),'sourceContext',ctx,'sourceRuleEvidence',source_rules,'outcomes',outcomes,'permissionTransitions',transitions,'dataAccessGranted',false);
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_replay.prodat_permission_scope_projection_v2(uuid, text, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:414
--
-- Name: require_common_guide_v2(public.ediel_messages, jsonb); Type: FUNCTION; Schema: gridex_ediel_ack_replay; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_replay.require_common_guide_v2(m public.ediel_messages, basis jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE s public.ediel_messages%rowtype;b gridex_ediel_ack_guide.source_bindings%rowtype;e gridex_ediel_ack_guide.editions%rowtype;BEGIN
 SELECT * INTO s FROM public.ediel_messages WHERE id=m.related_message_id AND (company_id=m.company_id OR company_id IS NULL) AND environment=m.environment AND direction='inbound' FOR SHARE;
 SELECT * INTO b FROM gridex_ediel_ack_guide.source_bindings WHERE source_message_id=s.id AND kind='common' FOR SHARE;
 IF s.id IS NULL OR b.source_message_id IS NULL OR b.company_id IS DISTINCT FROM m.company_id OR b.environment IS DISTINCT FROM m.environment
  OR b.payload_sha256 IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') OR b.original_basis IS DISTINCT FROM basis THEN RAISE EXCEPTION 'ediel_ack_guide_original_basis_changed';END IF;
 SELECT * INTO STRICT e FROM gridex_ediel_ack_guide.editions WHERE source_version=b.source_version;
 IF basis->>'assignedNegativeBirthReceiptId' IS NOT NULL THEN
  IF gridex_ediel_ack_replay.require_common_own_v2(m) IS DISTINCT FROM basis THEN RAISE EXCEPTION 'ediel_ack_guide_original_basis_changed';END IF;
  PERFORM gridex_ediel_header_negative_birth.assert_ack_v1(m,basis);RETURN;
 END IF;
 IF NOT coalesce(gridex_ediel_ack_guide.validate_v1(m.raw_payload,s.raw_payload,e.projection),false) THEN RAISE EXCEPTION 'ediel_native_ack_guide_invalid';END IF;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_replay.require_common_guide_v2(public.ediel_messages, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:415
--
-- Name: require_common_own_v2(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_ack_replay; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_replay.require_common_own_v2(m public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE w gridex_ediel_common_header.negative_witnesses%rowtype;r jsonb;BEGIN
 w:=gridex_ediel_common_header.witness_before_route_v1(m);
 SELECT route INTO r FROM gridex_ediel_common_header.negative_route_bindings WHERE witness_id=w.id;
 IF r IS NULL OR m.communication_route_id::text IS DISTINCT FROM r#>>'{route,id}' OR m.route_profile_id::text IS DISTINCT FROM r#>>'{routeRuntime,route_profile_id}'
  OR m.sender_email IS DISTINCT FROM r->>'senderEmail' OR m.receiver_email IS DISTINCT FROM r->>'receiverEmail' OR m.mailbox IS DISTINCT FROM r->>'mailbox'
  OR m.sender_ediel_id IS DISTINCT FROM r->>'senderEdielId' OR m.receiver_ediel_id IS DISTINCT FROM r->>'receiverEdielId'
  OR coalesce(m.sender_sub_address,'') IS DISTINCT FROM coalesce(r->>'senderSubAddress','') OR coalesce(m.receiver_sub_address,'') IS DISTINCT FROM coalesce(r->>'receiverSubAddress','')
  OR m.application_reference IS DISTINCT FROM r->>'applicationReference' THEN RAISE EXCEPTION 'ediel_common_header_negative_route_binding_required';END IF;
 PERFORM gridex_ediel_common_header.require_current_scope_v1(w.evidence);
 IF NOT EXISTS(SELECT FROM gridex_ediel_common_header.negative_consumptions p WHERE p.witness_id=w.id AND p.ack_message_id=m.id AND p.company_id=m.company_id AND p.environment=m.environment AND p.payload_sha256=w.payload_sha256) THEN RAISE EXCEPTION 'ediel_common_header_negative_witness_required';END IF;
 RETURN w.evidence;END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_replay.require_common_own_v2(public.ediel_messages) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:416
--
-- Name: require_current_service_actor_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_ack_replay; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_replay.require_current_service_actor_v1(c uuid, actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF c IS NULL OR actor IS NULL OR NOT EXISTS(SELECT FROM public.companies co WHERE co.id=c AND co.status='active')
 OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active')
 OR NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=c AND m.user_id=actor AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL)
 OR public.gridex_actor_has_company_permission(actor,c,'communication.write') IS NOT TRUE THEN RAISE EXCEPTION 'ediel_ack_service_actor_not_authorized' USING ERRCODE='42501';END IF;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_replay.require_current_service_actor_v1(uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:417
--
-- Name: require_current_source_role_v2(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_ack_replay; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_replay.require_current_source_role_v2(c uuid, env text, source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE ctx jsonb;s public.ediel_messages%rowtype;n bigint;role text;observed timestamptz:=clock_timestamp();BEGIN
 SELECT * INTO s FROM public.ediel_messages WHERE id=source_id AND company_id=c AND environment=env AND direction='inbound' FOR SHARE;
 ctx:=gridex_ediel_inbound_context.require_v1(c,source_id);
 IF s.id IS NULL OR ctx->>'basisKind' IS DISTINCT FROM 'observed_source_persistence' OR ctx->>'companyId' IS DISTINCT FROM c::text
  OR ctx->>'environment' IS DISTINCT FROM env OR ctx->>'family' IS DISTINCT FROM s.message_family OR ctx->>'code' IS DISTINCT FROM s.message_code
  OR NOT coalesce(ctx#>'{canonicalProjection,applicationReferences}' ? (ctx->>'applicationReference'),false)
  OR NOT EXISTS(SELECT FROM public.tenant_ediel_profiles p WHERE p.id::text=ctx#>>'{facts,profile,id}' AND p.company_id=c AND p.environment=env
    AND p.market='electricity' AND p.is_enabled AND p.valid_from<=observed AND (p.valid_to IS NULL OR observed<p.valid_to))
  OR (SELECT count(*) FROM public.tenant_ediel_profiles p WHERE p.company_id=c AND p.environment=env AND p.market='electricity' AND p.is_enabled AND p.valid_from<=observed AND (p.valid_to IS NULL OR observed<p.valid_to))<>1 THEN
  RAISE EXCEPTION 'ediel_ack_current_captured_role_unavailable' USING ERRCODE='42501';END IF;
 SELECT count(DISTINCT r.role_code),min(r.role_code) INTO n,role FROM public.tenant_actor_roles r WHERE r.company_id=c AND r.environment=env
  AND r.actor_id::text=ctx->>'legalActorId' AND r.valid_from<=observed AND (r.valid_to IS NULL OR observed<r.valid_to)
  AND (ctx#>'{canonicalProjection,receiverRoles}' ? r.role_code OR ctx#>'{canonicalProjection,receiverRoles}' ? CASE r.role_code WHEN 'electricity_supplier' THEN 'supplier' WHEN 'energy_service_company' THEN 'esco' ELSE r.role_code END);
 IF n<>1 OR role IS DISTINCT FROM ctx->>'actorRole' THEN RAISE EXCEPTION 'ediel_ack_current_captured_role_unavailable' USING ERRCODE='42501';END IF;
 PERFORM gridex_ediel_technical_ack.require_current_endpoint_v1(ctx);
 RETURN ctx;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_replay.require_current_source_role_v2(uuid, text, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:418
--
-- Name: require_positive_service_scope_v1(uuid, text, uuid, text); Type: FUNCTION; Schema: gridex_ediel_ack_replay; Owner: -
--

CREATE FUNCTION gridex_ediel_ack_replay.require_positive_service_scope_v1(c uuid, env text, sourceid uuid, ackraw text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE existing gridex_ediel_ack_replay.positive_service_scope_receipts%rowtype;projection jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT * INTO existing FROM gridex_ediel_ack_replay.positive_service_scope_receipts r WHERE r.company_id=c AND r.environment=env AND r.source_message_id=sourceid AND r.ack_raw_hash=encode(sha256(convert_to(ackraw,'UTF8')),'hex');
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_ack_service_scope_receipt_unavailable';END IF;
 PERFORM gridex_ediel_ack_replay.require_current_service_actor_v1(c,existing.actor_user_id);
 IF existing.projection->>'scopeKind'='prescribed_prodat_permission_ack' THEN projection:=gridex_ediel_ack_replay.prodat_permission_scope_projection_v2(c,env,sourceid,ackraw);
 ELSE projection:=gridex_ediel_ack_replay.positive_service_scope_projection_v2(c,env,sourceid,ackraw,existing.projection);END IF;
 IF projection IS DISTINCT FROM existing.projection THEN RAISE EXCEPTION 'ediel_ack_service_scope_receipt_changed';END IF;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_ack_replay.require_positive_service_scope_v1(uuid, text, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

