    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_guide.require_before_prodat_scope_v1(m);PERFORM gridex_ediel_ack_replay.require_readonly_prodat_ledger_v2(m);END $$;

