-- canonical:422
--
-- Name: actor_v2(uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_business_incidents; Owner: -
--

CREATE FUNCTION gridex_ediel_business_incidents.actor_v2(c uuid, actor uuid, mode text) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF mode IS NULL OR mode NOT IN('read','report') THEN RETURN false;END IF;
 PERFORM gridex_ediel_duplicate_responses.require_business_read_actor_v1(c,actor,CASE mode WHEN 'read' THEN 'read' ELSE 'prepare' END);
 RETURN true;EXCEPTION WHEN insufficient_privilege THEN RETURN false;END$$;

REVOKE ALL ON FUNCTION gridex_ediel_business_incidents.actor_v2(uuid, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

