-- canonical:448
--
-- Name: is_duplicate_ack_v1(uuid); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.is_duplicate_ack_v1(ack_id uuid) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$SELECT EXISTS(SELECT FROM gridex_ediel_duplicate_responses.consumptions c WHERE c.acknowledgement_id=ack_id)$$;

REVOKE ALL ON FUNCTION gridex_ediel_duplicate_responses.is_duplicate_ack_v1(uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:450
--
-- Name: read_business_original_v1(uuid, text, uuid, uuid, text, uuid, text); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.read_business_original_v1(c uuid, env text, source_id uuid, actor uuid, family text, ack_id uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE source public.ediel_messages%rowtype;ack public.ediel_messages%rowtype;ids uuid[];context jsonb;ack_context jsonb;basis jsonb;own_basis jsonb;
 a jsonb;s jsonb;tokens jsonb;sequence_field text:=NULL;sequence_value text:=NULL;common_source boolean;observed timestamptz:=clock_timestamp();companies uuid[];wire_outcome text;
BEGIN
 IF c IS NULL OR actor IS NULL OR source_id IS NULL OR env IS NULL OR env NOT IN('test','production') OR family IS NULL OR family NOT IN('CONTRL','APERAK','UTILTS_ERR')
  OR (sequence_field IS NULL)<>(sequence_value IS NULL) OR sequence_field IS NOT NULL AND (sequence_field NOT IN('relatedTransactionReference','utiltsErrSequenceToken') OR nullif(btrim(sequence_value),'') IS NULL)
  OR family='CONTRL' AND sequence_field IS NOT NULL OR sequence_field='utiltsErrSequenceToken' AND family<>'UTILTS_ERR' THEN
  RAISE EXCEPTION 'ediel_ack_replay_scope_required' USING ERRCODE='22023';END IF;
 -- A permission decision must remain true through source/ACK qualification.
 -- SHARE prevents UPDATE/DELETE and phantom INSERT grants/namespace collisions;
 -- all permission sources used by the current native resolver are included.
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=c AND m.user_id=actor AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL)
  OR NOT EXISTS(SELECT FROM public.companies co WHERE co.id=c AND co.status='active') THEN
  RAISE EXCEPTION 'ediel_ack_replay_actor_not_authorized' USING ERRCODE='42501';END IF;
 -- Stabilize the entire own-source candidate set, including opposite outcomes.
 -- A later concurrent INSERT is re-read through this same command after 23505.
 LOCK TABLE public.ediel_messages IN SHARE MODE;
 SELECT * INTO source FROM public.ediel_messages WHERE id=source_id AND environment=env AND direction='inbound'
  AND message_standard='edifact' AND (company_id=c OR company_id IS NULL) FOR SHARE;
 IF source.id IS NULL OR nullif(source.raw_payload,'') IS NULL THEN RAISE EXCEPTION 'ediel_ack_replay_actual_source_unavailable';END IF;
 common_source:=family='APERAK' AND source.message_family='PRODAT' AND EXISTS(SELECT FROM gridex_ediel_common_header.sources p WHERE p.source_message_id=source.id AND p.company_id=c AND p.environment=env AND p.status='ready');
 PERFORM gridex_ediel_duplicate_responses.require_business_read_actor_v1(c,actor,phase);
 IF family='CONTRL' THEN
  basis:=gridex_ediel_technical_ack.require_source_v1(c,source.id);
  PERFORM gridex_ediel_technical_ack.require_current_endpoint_v1(basis);
 ELSIF common_source THEN
  basis:=gridex_ediel_common_header.require_v1(c,env,source.id);
  PERFORM gridex_ediel_common_header.require_current_scope_v1(basis);
 ELSE
  IF source.company_id IS DISTINCT FROM c THEN RAISE EXCEPTION 'ediel_ack_replay_actual_source_unavailable';END IF;
  basis:=gridex_ediel_source_rules.require_v1(c,source.id);
  context:=gridex_ediel_ack_replay.require_current_source_role_v2(c,env,source.id);
  -- The immutable local legal recipient becomes the ACK issuer. Both wire
  -- legal parties and full transport components are matched below; only the
  -- current local namespace is resolved here, without profile/role re-selection.
  IF context->>'basisKind' IS DISTINCT FROM 'observed_source_persistence' OR context->>'companyId' IS DISTINCT FROM c::text OR context->>'environment' IS DISTINCT FROM env THEN RAISE EXCEPTION 'ediel_ack_replay_legal_scope_invalid';END IF;
  SELECT array_agg(DISTINCT i.company_id) INTO companies FROM public.tenant_actor_identifiers i WHERE i.environment=env AND i.identifier_type='EdielId'
   AND i.identifier_value=context->>'legalEdielId' AND i.valid_from<=observed AND (i.valid_to IS NULL OR observed<i.valid_to);
  IF cardinality(companies) IS DISTINCT FROM 1 OR companies[1] IS DISTINCT FROM c OR NOT EXISTS(SELECT FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=env
   AND i.actor_id::text=context->>'legalActorId' AND i.identifier_type='EdielId' AND i.identifier_value=context->>'legalEdielId'
   AND i.valid_from<=observed AND (i.valid_to IS NULL OR observed<i.valid_to)) THEN RAISE EXCEPTION 'ediel_ack_replay_legal_scope_invalid';END IF;
  PERFORM gridex_ediel_technical_ack.require_current_endpoint_v1(context);
 END IF;
 IF ack_id IS NULL THEN PERFORM gridex_ediel_duplicate_responses.require_business_read_actor_v1(c,actor,phase);RETURN jsonb_build_object('version',1,'sourceMessage',to_jsonb(source));END IF;
 SELECT array_agg(m.id) INTO ids FROM public.ediel_messages m WHERE m.id=ack_id AND m.company_id=c AND m.environment=env AND m.direction='outbound' AND m.message_family=family;
 IF coalesce(cardinality(ids),0)=0 THEN PERFORM gridex_ediel_duplicate_responses.require_business_read_actor_v1(c,actor,phase);RETURN NULL;END IF;
 IF cardinality(ids)<>1 THEN RAISE EXCEPTION 'ediel_ack_replay_own_response_ambiguous';END IF;
 SELECT * INTO STRICT ack FROM public.ediel_messages WHERE id=ids[1] AND company_id=c AND environment=env AND direction='outbound' AND message_family=family FOR SHARE;
 PERFORM gridex_ediel_duplicate_responses.require_business_binding_v1(c,env,source.id,ack.id,family); ack.related_message_id:=source.id;
 IF NOT EXISTS(SELECT FROM gridex_ediel_wire_namespace.coverage w WHERE w.source_message_id=ack.id AND w.company_id=c AND w.environment=env
  AND w.payload_sha256=encode(sha256(convert_to(ack.raw_payload,'UTF8')),'hex')) THEN RAISE EXCEPTION 'ediel_ack_replay_private_own_wire_unavailable';END IF;
 IF family='CONTRL' THEN
  own_basis:=gridex_ediel_technical_ack.require_contrl_v1(ack);
  IF own_basis IS DISTINCT FROM basis THEN RAISE EXCEPTION 'ediel_ack_replay_original_basis_mismatch';END IF;
  wire_outcome:=CASE own_basis->>'syntaxDecision' WHEN 'accepted' THEN 'positive' WHEN 'rejected' THEN 'negative' END;
 ELSIF common_source THEN
  own_basis:=gridex_ediel_ack_replay.require_common_own_v2(ack);
  IF own_basis IS DISTINCT FROM basis THEN RAISE EXCEPTION 'ediel_ack_replay_original_basis_mismatch';END IF;
  wire_outcome:='negative';
 ELSE
  own_basis:=gridex_ediel_duplicate_responses.require_business_owner_v1(c,ack.id,source.id);
  IF own_basis IS DISTINCT FROM basis OR gridex_ediel_source_rules.require_v1(c,ack.id) IS DISTINCT FROM basis
   OR NOT EXISTS(SELECT FROM gridex_ediel_source_rules.receipts r WHERE r.source_message_id=ack.id AND r.original_source_message_id=source.id) THEN RAISE EXCEPTION 'ediel_ack_replay_original_basis_mismatch';END IF;
  ack_context:=gridex_ediel_inbound_context.require_v1(c,ack.id);
  IF ack_context->>'basisKind' IS DISTINCT FROM 'prescribed_outbound_ack' OR ack_context->>'originalSourceMessageId' IS DISTINCT FROM source.id::text
   OR ack_context->>'originalSourceHash' IS DISTINCT FROM encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex')
   OR ack_context->>'legalActorId' IS DISTINCT FROM context->>'legalActorId' OR ack_context->>'legalEdielId' IS DISTINCT FROM context->>'legalEdielId'
   OR ack_context->>'transportActorId' IS DISTINCT FROM context->>'transportActorId' THEN RAISE EXCEPTION 'ediel_ack_replay_legal_scope_invalid';END IF;
  a:=gridex_ack_authority.wire_v1(ack.raw_payload);s:=gridex_ack_authority.wire_v1(source.raw_payload);
  IF NOT coalesce(gridex_ack_authority.source_match_v1(a,s),false) THEN RAISE EXCEPTION 'ediel_ack_replay_physical_source_mismatch';END IF;
  IF sequence_field='relatedTransactionReference' AND (NOT coalesce(s->'ide','[]') ? sequence_value
   OR NOT (CASE family WHEN 'APERAK' THEN coalesce(a#>'{refs,ACW}','[]') ELSE coalesce(a#>'{refs,TN}','[]') END) ? sequence_value
   OR ack.parsed_payload->>'ackScope' IS DISTINCT FROM 'transaction') THEN RAISE EXCEPTION 'ediel_ack_replay_sequence_mismatch';END IF;
  IF sequence_field='utiltsErrSequenceToken' THEN
   tokens:=gridex_utilts_binding.wire_tokens_v1(ack.raw_payload);
   IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='STS' AND t#>>'{elements,1,0}'='E01' AND t#>>'{elements,2,0}'='41' AND t#>>'{elements,3,0}'=sequence_value) THEN RAISE EXCEPTION 'ediel_ack_replay_sequence_mismatch';END IF;
  END IF;
  wire_outcome:=CASE WHEN family='UTILTS_ERR' THEN 'negative' WHEN jsonb_array_length(coalesce(a->'erc','[]'))>0 AND NOT EXISTS(SELECT FROM jsonb_array_elements_text(a->'erc') x WHERE x<>'100') THEN 'positive' ELSE 'negative' END;
 END IF;
 IF common_source THEN PERFORM gridex_ediel_ack_replay.require_common_guide_v2(ack,own_basis);ELSE PERFORM gridex_ediel_ack_replay.require_readonly_guide_v2(ack);END IF;
 IF family='APERAK' AND source.message_family='PRODAT' THEN PERFORM gridex_ediel_ack_replay.require_readonly_prodat_ledger_v2(ack);END IF;
 IF family='APERAK' AND source.message_family='PRODAT' AND EXISTS(SELECT FROM jsonb_array_elements(gridex_utilts_binding.wire_tokens_v1(ack.raw_payload))t WHERE t->>'tag'='ERC' AND t#>>'{elements,1,0}'='100') THEN
  PERFORM public.ediel_require_recorded_prodat_bilateral_ack_source_v1(c,source.id,encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex'));END IF;
 IF NOT common_source AND family<>'CONTRL' AND context->>'actorRole' IN('energy_service_company','esco') AND wire_outcome='positive' THEN
  PERFORM gridex_ediel_ack_replay.require_positive_service_scope_v1(c,env,source.id,ack.raw_payload);END IF;
 IF wire_outcome IS NULL THEN RAISE EXCEPTION 'ediel_ack_replay_own_outcome_mismatch';END IF;
 PERFORM gridex_ediel_duplicate_responses.require_business_creation_outcome_v1(c,env,source.id,ack,wire_outcome);
 PERFORM gridex_ediel_duplicate_responses.read_business_original_v1(c,env,source.id,actor,family,NULL,phase);
 PERFORM gridex_ediel_duplicate_responses.require_business_read_actor_v1(c,actor,phase);
 RETURN jsonb_build_object('version',1,'sourceMessage',to_jsonb(source),'ackMessage',to_jsonb(ack)||jsonb_build_object('ack_outcome',wire_outcome));
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_duplicate_responses.read_business_original_v1(uuid, text, uuid, uuid, text, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:453
--
-- Name: read_result_v1(gridex_ediel_duplicate_responses.intents); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.read_result_v1(i gridex_ediel_duplicate_responses.intents) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c gridex_ediel_duplicate_responses.consumptions%rowtype;m public.ediel_messages%rowtype;o public.ediel_outbox%rowtype;BEGIN
 SELECT * INTO c FROM gridex_ediel_duplicate_responses.consumptions WHERE intent_id=i.id;
 IF c.intent_id IS NULL THEN RETURN NULL;END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=c.acknowledgement_id AND company_id=i.company_id AND environment=i.environment AND related_message_id=i.source_message_id FOR SHARE;
 SELECT * INTO o FROM public.ediel_outbox WHERE id=c.outbox_id AND company_id=i.company_id AND environment=i.environment AND ediel_message_id=m.id AND source_message_id=i.source_message_id FOR SHARE;
 IF m.id IS NULL OR o.id IS NULL OR m.message_family IS DISTINCT FROM 'APERAK' OR m.direction IS DISTINCT FROM 'outbound' OR m.ack_outcome IS DISTINCT FROM 'negative' OR encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') IS DISTINCT FROM i.ack_hash OR gridex_ediel_duplicate_responses.allows_message_v1(m) IS NOT TRUE OR NOT EXISTS(SELECT FROM public.ediel_message_events e WHERE e.id=c.event_id AND e.company_id=i.company_id AND e.ediel_message_id=m.id) THEN RAISE EXCEPTION 'ediel_duplicate_established_receipt_changed';END IF;
 RETURN jsonb_build_object('status','protocol_response_prepared','ackMessage',to_jsonb(m),'outboxId',o.id,'receptionId',i.reception_id,'responseRequestId',i.response_request_id,'businessEffectAuthorized',false);
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_duplicate_responses.read_result_v1(gridex_ediel_duplicate_responses.intents) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:454
--
-- Name: require_actor_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.require_actor_v1(c uuid, actor uuid, phase text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF c IS NULL OR actor IS NULL OR NOT EXISTS(SELECT FROM public.companies WHERE id=c AND status='active' AND is_active)
  OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
  OR (phase IN('prepare','send')) IS NOT TRUE
  OR (CASE phase WHEN 'prepare' THEN public.gridex_actor_has_company_permission(actor,c,'communication.write') IS TRUE
      WHEN 'send' THEN public.gridex_actor_has_company_permission(actor,c,'communication.send') IS TRUE OR public.gridex_actor_has_company_permission(actor,c,'ediel.send') IS TRUE END) IS NOT TRUE
  THEN RAISE EXCEPTION 'ediel_duplicate_current_actor_required' USING ERRCODE='42501';END IF;
END$$;

REVOKE ALL ON FUNCTION gridex_ediel_duplicate_responses.require_actor_v1(uuid, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:455
--
-- Name: require_business_binding_v1(uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.require_business_binding_v1(c uuid, env text, source_id uuid, ack_id uuid, family text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE basis jsonb;entry jsonb;BEGIN
 basis:=gridex_ack_authority.read_outbound_originals_v1(source_id,family);
 IF basis->>'sourceMessageId' IS DISTINCT FROM source_id::text OR basis->>'companyId' IS DISTINCT FROM c::text OR basis->>'environment' IS DISTINCT FROM env THEN RAISE EXCEPTION 'ediel_business_ack_own_original_required';END IF;
 SELECT x INTO entry FROM jsonb_array_elements(basis->'originals')x WHERE x#>>'{message,id}'=ack_id::text;
 IF entry->>'status' IS DISTINCT FROM 'qualified' THEN RAISE EXCEPTION 'ediel_business_ack_own_original_required';END IF;
END$$;

REVOKE ALL ON FUNCTION gridex_ediel_duplicate_responses.require_business_binding_v1(uuid, text, uuid, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:456
--
-- Name: require_business_creation_outcome_v1(uuid, text, uuid, public.ediel_messages, text); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.require_business_creation_outcome_v1(c uuid, env text, source_id uuid, ack public.ediel_messages, outcome text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE receipt gridex_ediel_ack_replay.creation_receipts%rowtype;source public.ediel_messages%rowtype;BEGIN
 SELECT * INTO receipt FROM gridex_ediel_ack_replay.creation_receipts WHERE ack_message_id=ack.id FOR SHARE;
 IF receipt.ack_message_id IS NULL THEN RETURN;END IF;
 SELECT * INTO STRICT source FROM public.ediel_messages WHERE id=source_id FOR SHARE;
 IF receipt.company_id IS DISTINCT FROM c OR receipt.environment IS DISTINCT FROM env OR receipt.source_message_id IS DISTINCT FROM source_id
  OR receipt.family IS DISTINCT FROM ack.message_family OR receipt.ack_payload_hash IS DISTINCT FROM encode(sha256(convert_to(ack.raw_payload,'UTF8')),'hex')
  OR receipt.source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex') OR receipt.outcome IS DISTINCT FROM outcome
 THEN RAISE EXCEPTION 'ediel_business_ack_creation_outcome_changed';END IF;
END$$;

REVOKE ALL ON FUNCTION gridex_ediel_duplicate_responses.require_business_creation_outcome_v1(uuid, text, uuid, public.ediel_messages, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:457
--
-- Name: require_business_owner_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.require_business_owner_v1(p_company_id uuid, p_message_id uuid, p_source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;w gridex_ediel_outbound_owner.witnesses%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id AND direction='outbound' FOR SHARE;
 SELECT witness.* INTO w FROM gridex_ediel_outbound_owner.consumptions c JOIN gridex_ediel_outbound_owner.witnesses witness ON witness.id=c.witness_id
  WHERE c.source_message_id=m.id AND c.company_id=m.company_id AND c.environment=m.environment AND c.payload_sha256=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') FOR SHARE OF witness;
 IF w.id IS NULL THEN RAISE EXCEPTION 'ediel_historical_outbound_owner_witness_unavailable';END IF;
 IF w.related_message_id IS DISTINCT FROM p_source_id THEN RAISE EXCEPTION 'ediel_business_ack_private_relation_changed';END IF; m.related_message_id:=p_source_id; PERFORM gridex_ediel_outbound_owner.assert_message_v1(m,w);RETURN w.evidence;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_duplicate_responses.require_business_owner_v1(uuid, uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:458
--
-- Name: require_business_read_actor_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.require_business_read_actor_v1(c uuid, actor uuid, phase text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF phase NOT IN('prepare','read','send') OR phase IS NULL OR c IS NULL OR actor IS NULL
  OR NOT EXISTS(SELECT FROM public.companies WHERE id=c AND status='active' AND is_active)
  OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
  OR (CASE phase WHEN 'prepare' THEN public.gridex_actor_has_company_permission(actor,c,'communication.write') IS TRUE
 WHEN 'read' THEN public.gridex_actor_has_company_permission(actor,c,'communication.read') IS TRUE
 WHEN 'send' THEN public.gridex_actor_has_company_permission(actor,c,'communication.send') IS TRUE OR public.gridex_actor_has_company_permission(actor,c,'ediel.send') IS TRUE ELSE false END) IS NOT TRUE
 THEN RAISE EXCEPTION 'ediel_business_ack_current_actor_required' USING ERRCODE='42501';END IF;
END$$;

REVOKE ALL ON FUNCTION gridex_ediel_duplicate_responses.require_business_read_actor_v1(uuid, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:459
--
-- Name: require_namespace_v1(uuid, text, jsonb); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.require_namespace_v1(c uuid, env text, ctx jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE companies uuid[];observed timestamptz;BEGIN
 IF ctx->>'basisKind' IS DISTINCT FROM 'observed_source_persistence' OR ctx->>'companyId' IS DISTINCT FROM c::text OR ctx->>'environment' IS DISTINCT FROM env THEN RAISE EXCEPTION 'ediel_duplicate_legal_scope_invalid';END IF;
 observed:=clock_timestamp();
 SELECT array_agg(DISTINCT i.company_id) INTO companies FROM public.tenant_actor_identifiers i WHERE i.environment=env AND i.identifier_type='EdielId'
  AND i.identifier_value=ctx->>'legalEdielId' AND i.valid_from<=observed AND(i.valid_to IS NULL OR observed<i.valid_to);
 IF cardinality(companies) IS DISTINCT FROM 1 OR companies[1] IS DISTINCT FROM c OR NOT EXISTS(SELECT FROM public.tenant_actor_identifiers i WHERE i.company_id=c AND i.environment=env
  AND i.actor_id::text=ctx->>'legalActorId' AND i.identifier_type='EdielId' AND i.identifier_value=ctx->>'legalEdielId'
  AND i.valid_from<=observed AND(i.valid_to IS NULL OR observed<i.valid_to)) THEN RAISE EXCEPTION 'ediel_duplicate_legal_scope_invalid';END IF;
 PERFORM gridex_ediel_technical_ack.require_current_endpoint_v1(ctx);
END$$;

REVOKE ALL ON FUNCTION gridex_ediel_duplicate_responses.require_namespace_v1(uuid, text, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:460
--
-- Name: require_transport_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.require_transport_v1(c uuid, ack_id uuid, actor uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE i gridex_ediel_duplicate_responses.intents%rowtype;r gridex_ediel_inbound_receptions.receptions%rowtype;source jsonb;BEGIN
 SELECT intent.* INTO i FROM gridex_ediel_duplicate_responses.consumptions co JOIN gridex_ediel_duplicate_responses.intents intent ON intent.id=co.intent_id WHERE co.acknowledgement_id=ack_id;
 IF i.id IS NULL THEN RETURN;END IF;
 IF i.company_id IS DISTINCT FROM c THEN RAISE EXCEPTION 'ediel_duplicate_transport_company_changed';END IF;
 SELECT * INTO STRICT r FROM gridex_ediel_inbound_receptions.receptions WHERE id=i.reception_id;
 source:=gridex_ediel_duplicate_responses.source_for_execution_v1(c,i.source_message_id,r.inbound_email_message_id,actor,'send');
 IF source->>'sourceHash' IS DISTINCT FROM i.source_hash OR encode(sha256(convert_to((source->'currentContext')::text,'UTF8')),'hex') IS DISTINCT FROM i.source_role_hash OR gridex_ediel_duplicate_responses.read_result_v1(i) IS NULL THEN RAISE EXCEPTION 'ediel_duplicate_current_capability_changed';END IF;
 PERFORM public.ediel_require_source_bytes_available_v1(c,i.source_message_id);
 IF gridex_ediel_duplicate_responses.source_for_execution_v1(c,i.source_message_id,r.inbound_email_message_id,actor,'send') IS DISTINCT FROM source THEN RAISE EXCEPTION 'ediel_duplicate_current_capability_changed';END IF;
END$$;

REVOKE ALL ON FUNCTION gridex_ediel_duplicate_responses.require_transport_v1(uuid, uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:461
--
-- Name: require_wire_v1(text, text, jsonb); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.require_wire_v1(raw text, source_raw text, projection jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(raw);t jsonb;tags text[];ref_count int;BEGIN
 IF gridex_ediel_ack_guide.validate_v1(raw,source_raw,projection) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_duplicate_native_103_wire_required';END IF;
 PERFORM gridex_ediel_ack_guide.require_fresh_ack_envelope_v1(raw,'APERAK');
 SELECT array_agg(x->>'tag' ORDER BY(x->>'index')::int) INTO tags FROM jsonb_array_elements(tokens)x;
 -- Strict complete D96A producer subset: SG1 ACW before SG2 legal NAD;
 -- SG3 ERC+FTX; at most one SG4 RFF. No directory relaxation for known Z07+LI.
 IF tags IS DISTINCT FROM ARRAY['UNB','UNH','BGM','DTM','DTM','RFF','NAD','NAD','ERC','FTX','UNT','UNZ']::text[] AND tags IS DISTINCT FROM ARRAY['UNB','UNH','BGM','DTM','DTM','RFF','NAD','NAD','ERC','FTX','RFF','UNT','UNZ']::text[] THEN RAISE EXCEPTION 'ediel_duplicate_strict_96a_scope_held';END IF;
 IF tokens#>>'{2,elements,3,0}' IS DISTINCT FROM '27' OR tokens#>>'{3,elements,1,0}' IS DISTINCT FROM '137' OR tokens#>>'{4,elements,1,0}' IS DISTINCT FROM '178' OR tokens#>>'{5,elements,1,0}' IS DISTINCT FROM 'ACW'
  OR tokens#>>'{6,elements,1,0}' IS DISTINCT FROM 'FR' OR tokens#>>'{7,elements,1,0}' IS DISTINCT FROM 'DO' OR tokens#>>'{8,elements,1,0}' IS DISTINCT FROM '40' OR tokens#>>'{9,elements,3,0}' IS DISTINCT FROM '103' OR tokens#>>'{9,elements,4,0}' IS DISTINCT FROM 'Dubblett av meddelandet' THEN RAISE EXCEPTION 'ediel_duplicate_exact_103_required';END IF;
 -- Mandatory own known reference facts are retained, including when that
 -- requires a truthful strict-directory hold. Never drop one to make wire green.
 SELECT count(DISTINCT jsonb_build_array(x#>>'{elements,1,0}',x#>>'{elements,1,1}')) INTO ref_count FROM jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(source_raw))x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI' AND nullif(x#>>'{elements,1,1}','') IS NOT NULL;
 IF ref_count>1 THEN RAISE EXCEPTION 'ediel_duplicate_multiple_own_reference_scope_held';END IF;
 IF ref_count=1 AND NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)a JOIN jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(source_raw))s ON s->>'tag'='RFF' AND s#>>'{elements,1,0}'='LI' AND a#>>'{elements,1,1}'=s#>>'{elements,1,1}' WHERE a->>'tag'='RFF' AND a#>>'{elements,1,0}'='LI') THEN RAISE EXCEPTION 'ediel_duplicate_known_own_reference_required';END IF;
 SELECT count(DISTINCT x#>>'{elements,3,0}') INTO ref_count FROM jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(source_raw))x WHERE x->>'tag'='LIN' AND nullif(x#>>'{elements,3,0}','') IS NOT NULL;
 IF ref_count>1 THEN RAISE EXCEPTION 'ediel_duplicate_multiple_own_reference_scope_held';END IF;
 IF ref_count=1 AND NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)a JOIN jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(source_raw))s ON s->>'tag'='LIN' AND a#>>'{elements,1,1}'=s#>>'{elements,3,0}' WHERE a->>'tag'='RFF' AND a#>>'{elements,1,0}'='Z07') THEN RAISE EXCEPTION 'ediel_duplicate_known_own_reference_required';END IF;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_duplicate_responses.require_wire_v1(text, text, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:462
--
-- Name: source_for_execution_v1(uuid, uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.source_for_execution_v1(c uuid, source_id uuid, mail_id uuid, actor uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;r gridex_ediel_inbound_receptions.receptions%rowtype;q gridex_ediel_inbound_receptions.response_requests%rowtype;
 first gridex_ediel_inbound_receptions.receptions%rowtype;ctx jsonb;basis jsonb;t jsonb;original_hash text;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 PERFORM gridex_ediel_duplicate_responses.require_actor_v1(c,actor,phase);
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c AND direction='inbound' AND message_standard='edifact' AND message_family='PRODAT' FOR SHARE;
 IF m.id IS NULL OR nullif(m.raw_payload,'') IS NULL OR m.message_received_at IS NULL THEN RAISE EXCEPTION 'ediel_duplicate_actual_original_required';END IF;
 original_hash:=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex');
 -- Same protected source-only legal namespace/endpoint as read_exact_v2,
 -- with the actual execution purpose kept independent of that prepare port.
 ctx:=gridex_ediel_ack_replay.require_current_source_role_v2(c,m.environment,m.id);
 basis:=gridex_ediel_source_rules.require_v1(c,m.id);
 PERFORM gridex_ediel_duplicate_responses.require_namespace_v1(c,m.environment,ctx);
 IF ctx->>'actorRole' IS DISTINCT FROM 'electricity_supplier' OR ctx->>'applicationReference' IS DISTINCT FROM '23-DDQ-PRODAT' THEN RAISE EXCEPTION 'ediel_duplicate_captured_legal_ddq_required';END IF;
 SELECT * INTO r FROM gridex_ediel_inbound_receptions.receptions WHERE company_id=c AND source_message_id=m.id AND inbound_email_message_id=mail_id FOR SHARE;
 SELECT * INTO q FROM gridex_ediel_inbound_receptions.response_requests WHERE reception_id=r.id AND company_id=c AND source_message_id=m.id FOR SHARE;
 SELECT * INTO first FROM gridex_ediel_inbound_receptions.receptions WHERE company_id=c AND source_message_id=m.id AND classification='first_reception' FOR SHARE;
 IF r.id IS NULL OR q.id IS NULL OR first.id IS NULL OR r.classification IS DISTINCT FROM 'protocol_duplicate' OR q.reason IS DISTINCT FROM 'authentic_duplicate_transport_response_policy_required'
  OR r.inbound_email_message_id=first.inbound_email_message_id OR r.environment IS DISTINCT FROM m.environment OR r.canonical_payload_hash IS DISTINCT FROM original_hash OR r.received_payload_hash IS DISTINCT FROM original_hash
  OR first.canonical_payload_hash IS DISTINCT FROM original_hash OR first.received_payload_hash IS DISTINCT FROM original_hash OR r.scope IS DISTINCT FROM first.scope
  OR r.received_at IS NULL OR r.received_at<first.received_at THEN RAISE EXCEPTION 'ediel_duplicate_genuine_same_original_reception_required';END IF;
 -- P26.A p99 field A901 / DTM178 is the actual arrival. This response
 -- belongs to this NEW native reception, never the worker or first-reception
 -- clock. The canonical original timestamp and its earlier ACK remain fixed.
 -- Native source syntax/family and inherited edition/source binding are fixed.
 t:=gridex_ediel_technical_ack.require_source_v1(c,m.id);
 IF t->>'sourceHash' IS DISTINCT FROM original_hash OR t->>'environment' IS DISTINCT FROM m.environment THEN RAISE EXCEPTION 'ediel_duplicate_source_syntax_required';END IF;
 IF NOT EXISTS(SELECT FROM gridex_ediel_ack_guide.source_bindings b JOIN gridex_ediel_ack_guide.editions e ON e.source_version=b.source_version WHERE b.source_message_id=m.id AND b.kind='national' AND b.company_id=c AND b.environment=m.environment AND b.payload_sha256=original_hash AND b.original_basis=basis AND e.projection#>>'{constraints,PRODAT,applicationTexts,103}'='Dubblett av meddelandet') THEN RAISE EXCEPTION 'ediel_duplicate_inherited_103_guide_required';END IF;
 -- Source/guide/reception reads may wait; current clocks are independent of
 -- table-lock stability. Repeat purpose, role and namespace at the final edge.
 IF gridex_ediel_ack_replay.require_current_source_role_v2(c,m.environment,m.id) IS DISTINCT FROM ctx THEN RAISE EXCEPTION 'ediel_duplicate_current_source_changed';END IF;
 PERFORM gridex_ediel_duplicate_responses.require_namespace_v1(c,m.environment,ctx);
 PERFORM gridex_ediel_duplicate_responses.require_actor_v1(c,actor,phase);
 RETURN jsonb_build_object('sourceMessage',to_jsonb(m),'receptionId',r.id,'responseRequestId',q.id,'sourceHash',original_hash,'currentContext',ctx,'technicalBasis',t,'sourceReceivedDate203',to_char(r.received_at AT TIME ZONE 'Etc/GMT-1','YYYYMMDDHH24MI'),'sourceRulePackEvidence',basis,'businessEffectAuthorized',false);
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_duplicate_responses.source_for_execution_v1(uuid, uuid, uuid, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:463
--
-- Name: source_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_duplicate_responses; Owner: -
--

CREATE FUNCTION gridex_ediel_duplicate_responses.source_v1(c uuid, source_id uuid, mail_id uuid, actor uuid) RETURNS jsonb
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$SELECT gridex_ediel_duplicate_responses.source_for_execution_v1(c,source_id,mail_id,actor,'prepare')$$;

