    AS $$
DECLARE e jsonb;
BEGIN
 IF NOT(gridex_ediel_header_negative_birth.is_bound_v1(m,true) OR gridex_ediel_header_negative_birth.is_bound_v1(m,false)) THEN RETURN NULL;END IF;
