--

CREATE FUNCTION gridex_ediel_inbound_context.capture() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE observed timestamptz:=clock_timestamp(); context jsonb:='{}'; status text:='ready'; reason text;
BEGIN IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
 IF nullif(NEW.raw_payload,'') IS NULL OR left(NEW.raw_payload,3) NOT IN('UNA','UNB') OR EXISTS(SELECT FROM gridex_ediel_inbound_context.receipts WHERE source_message_id=NEW.id) THEN RETURN NEW; END IF;
 BEGIN context:=gridex_ediel_inbound_context.derive(NEW,observed);
 EXCEPTION WHEN OTHERS THEN status:='held';reason:=CASE WHEN SQLERRM IN('ediel_inbound_legal_context_required','ediel_historical_identity_basis_unavailable') THEN SQLERRM ELSE 'ediel_original_identity_capture_failed' END; END;
 INSERT INTO gridex_ediel_inbound_context.receipts VALUES(NEW.id,NEW.company_id,NEW.environment,NEW.direction,encode(digest(convert_to(NEW.raw_payload,'UTF8'),'sha256'),'hex'),NEW.message_received_at,observed,status,reason,context);
 RETURN NEW;
END $$;

