-- canonical:485
--
-- Name: require_ack_v1(public.ediel_messages, public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_inbound_context; Owner: -
--

CREATE FUNCTION gridex_ediel_inbound_context.require_ack_v1(ack public.ediel_messages, source public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE context jsonb; tokens jsonb; receiver text;
BEGIN
 IF ack.direction IS DISTINCT FROM 'inbound' OR source.direction IS DISTINCT FROM 'outbound' OR ack.company_id IS DISTINCT FROM source.company_id OR ack.environment IS DISTINCT FROM source.environment THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 context:=gridex_ediel_inbound_context.require_v1(source.company_id,source.id);
 -- Complete physical ACK family/party/reference/global uniqueness qualification
 -- is owned by gridex_ack_authority; this guard adds genuine original rolebasis.
 tokens:=gridex_utilts_binding.wire_tokens_v1(ack.raw_payload);
 SELECT x#>>'{elements,3,0}' INTO receiver FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='UNB';
 IF receiver IS DISTINCT FROM context->>'transportEdielId' THEN RAISE EXCEPTION 'ediel_inbound_legal_context_required'; END IF;
 RETURN context||jsonb_build_object('basisKind','qualified_outbound_original_ack','ackMessageId',ack.id,'originalSourceMessageId',source.id);
END $$;

