-- canonical:500
--
-- Name: assert_preparation_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.assert_preparation_v1(i jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c uuid:=(i->>'companyId')::uuid;actor uuid:=(i->>'actorUserId')::uuid;
 env text:=i->>'environment';raw text:=i->>'rawPayload';positive uuid:=(i->>'sourceQualifiedPositiveFixtureWitnessId')::uuid;
 negative uuid:=(i->>'sourceQualifiedNegativeFixtureWitnessId')::uuid;q jsonb;
BEGIN
 PERFORM u.id FROM public.user_profiles u WHERE u.id=actor FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor FOR SHARE;
 IF c IS NULL OR actor IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=c AND cm.user_id=actor AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
 THEN RAISE EXCEPTION 'ediel_outbound_owner_actor_scope_required' USING ERRCODE='42501';END IF;
 IF public.gridex_actor_has_company_permission(actor,c,'communication.write') IS TRUE THEN RETURN;END IF;
 IF env IS DISTINCT FROM 'test' OR public.gridex_actor_has_company_permission(actor,c,'ediel_testing.write') IS NOT TRUE
  OR (positive IS NULL)=(negative IS NULL) THEN RAISE EXCEPTION 'ediel_outbound_owner_preparation_permission_required' USING ERRCODE='42501';END IF;
 -- Caller IDs are selectors only. The source owner rechecks actual registered
 -- original, run/role/case/revision/step/bytes, exact preparer and current scope.
 IF positive IS NOT NULL THEN q:=gridex_negative_fixtures.prepared_positive_fixture_v1(c,positive,raw,actor);
 ELSE q:=gridex_negative_fixtures.prepared_negative_fixture_v1(c,negative,raw,actor);END IF;
 IF q IS NULL OR q->>'companyId' IS DISTINCT FROM c::text OR q->'authorizesBusinessEffect' IS DISTINCT FROM 'false'::jsonb
 THEN RAISE EXCEPTION 'ediel_outbound_owner_preparation_fixture_required';END IF;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_outbound_owner.assert_preparation_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:501
--
-- Name: consume(); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.consume() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE w gridex_ediel_outbound_owner.witnesses%rowtype;prior gridex_ediel_outbound_owner.consumptions%rowtype;token uuid;
BEGIN IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
 IF NEW.direction='outbound' AND NEW.message_family='APERAK' AND NEW.execution_context_snapshot ? 'prodatCommonHeaderNegativeWitnessId' THEN
  PERFORM gridex_ediel_common_header.consume_v1(NEW);PERFORM gridex_ediel_ack_guide.require_v1(NEW);RETURN NEW;
 END IF;
 IF NEW.direction IS DISTINCT FROM 'outbound' OR NEW.message_family NOT IN('PRODAT','UTILTS','APERAK','UTILTS_ERR') OR nullif(NEW.raw_payload,'') IS NULL THEN RETURN NEW;END IF;
 token:=(NEW.execution_context_snapshot->>'outboundOwnerWitnessId')::uuid;
 SELECT * INTO w FROM gridex_ediel_outbound_owner.witnesses WHERE id=token FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_historical_outbound_owner_witness_unavailable';END IF;
 PERFORM gridex_ediel_outbound_owner.assert_message_v1(NEW,w);
 PERFORM gridex_ediel_outbound_owner.require_positive_utilts_ack_v1(NEW,false);
 SELECT * INTO prior FROM gridex_ediel_outbound_owner.consumptions WHERE witness_id=w.id;
 IF FOUND THEN
  IF prior.source_message_id IS DISTINCT FROM NEW.id THEN RAISE EXCEPTION 'ediel_outbound_owner_witness_already_consumed';END IF;
  RETURN NEW;
 END IF;
 -- The same INSERT transaction owns both actual immutable physical message
 -- scope and one-use protected witness consumption. Failure rolls back both.
 INSERT INTO gridex_ediel_outbound_owner.consumptions VALUES(w.id,NEW.id,w.company_id,w.environment,w.payload_sha256);
 RETURN NEW;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_outbound_owner.consume() FROM PUBLIC,anon,authenticated,service_role;

