-- canonical:515
--
-- Name: require_positive_before_received_err_v1(public.ediel_messages, boolean); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.require_positive_before_received_err_v1(m public.ediel_messages, p_sending boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;a jsonb;s jsonb;groups jsonb;g jsonb;code text;transaction_id text;header_scope boolean;expected_header jsonb;actual_header jsonb;reservation public.ediel_ack_transaction_results%rowtype;
BEGIN
 IF m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'APERAK' THEN RETURN;END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=m.related_message_id AND company_id=m.company_id AND environment=m.environment AND direction='inbound' FOR SHARE;
 IF source.message_family IS DISTINCT FROM 'UTILTS' THEN RETURN;END IF;
 -- Reuse the one native physical ACK lexical/scope projector. The added own
 -- ERC groups never select policy, decide business acceptance or invent codes.
 a:=gridex_ack_authority.wire_v1(m.raw_payload);s:=gridex_ack_authority.wire_v1(source.raw_payload);
 IF a IS NULL OR a->>'family' IS DISTINCT FROM 'APERAK' OR a#>>'{type,1}' IS DISTINCT FROM 'D' OR a#>>'{type,2}' IS DISTINCT FROM '04A' OR a#>>'{type,3}' IS DISTINCT FROM 'UN' OR a#>>'{type,4}' IS DISTINCT FROM 'E5SE5A'
  OR NOT coalesce(gridex_ack_authority.source_match_v1(a,s),false) THEN RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable';END IF;
 code:=a->>'code';groups:=a->'ercGroups';
 IF code IS NULL OR code NOT IN('312','313') OR jsonb_typeof(groups) IS DISTINCT FROM 'array' OR jsonb_array_length(groups)=0
  OR (jsonb_array_length(groups)<>jsonb_array_length(coalesce(a#>'{refs,ACW}','[]')) AND NOT(code='313' AND jsonb_array_length(coalesce(a#>'{refs,ACW}','[]'))=0)) OR jsonb_array_length(groups)<>jsonb_array_length(coalesce(a#>'{refs,DM}','[]'))
  OR EXISTS(SELECT x FROM jsonb_array_elements_text(coalesce(a#>'{refs,DM}','[]'))x GROUP BY x HAVING count(*)>1)
  OR (code='312' AND EXISTS(SELECT x FROM jsonb_array_elements_text(coalesce(a#>'{refs,ACW}','[]'))x GROUP BY x HAVING count(*)>1)) THEN RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable';END IF;
 header_scope:=code='313' AND jsonb_array_length(coalesce(a#>'{refs,ACW}','[]'))=0;
 IF header_scope THEN
  expected_header:=gridex_received_sources.require_utilts_header_v1(m.company_id,source.id);
  IF EXISTS(SELECT FROM jsonb_array_elements(groups)x WHERE jsonb_array_length(coalesce(x->'texts','[]'))<>1) THEN RAISE EXCEPTION 'utilts_header_ack_owner_unavailable';END IF;
  SELECT jsonb_agg(row ORDER BY row::text) INTO actual_header FROM (SELECT jsonb_build_object('ercCode',x->>'code','fieldCode',x#>>'{texts,0,3,0}','text',x#>>'{texts,0,4,0}') row FROM jsonb_array_elements(groups)x) own_errors;
  SELECT jsonb_agg(x ORDER BY x::text) INTO expected_header FROM jsonb_array_elements(expected_header->'applicationErrors')x;
  IF actual_header IS DISTINCT FROM expected_header THEN RAISE EXCEPTION 'utilts_header_ack_owner_unavailable';END IF;
 END IF;
 FOR g IN SELECT x FROM jsonb_array_elements(groups)x LOOP
  IF nullif(g->>'code','') IS NULL OR (code='312' AND g->>'code' IS DISTINCT FROM '100') OR (code='313' AND g->>'code'='100')
   OR jsonb_array_length(g->'acw')<>(CASE WHEN header_scope THEN 0 ELSE 1 END) OR jsonb_array_length(g->'dm')<>1 OR (NOT header_scope AND nullif(g#>>'{acw,0}','') IS NULL) OR nullif(g#>>'{dm,0}','') IS NULL OR length(g#>>'{dm,0}')>(gridex_ediel_ack_guide.utilts_reference_constraints_v1()->>'ownDmMax')::integer OR btrim(g#>>'{dm,0}') IS DISTINCT FROM g#>>'{dm,0}' THEN RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable';END IF;
  IF header_scope THEN CONTINUE;END IF;
  transaction_id:=g#>>'{acw,0}';
  IF code='312' THEN
   PERFORM public.gridex_require_utilts_positive_ack_authority_v1(m.company_id,m.environment,source.id,transaction_id,
    CASE WHEN p_sending THEN m.id ELSE NULL END,CASE WHEN p_sending THEN m.raw_payload ELSE NULL END);
  ELSE
   -- A negative own-IDE response cannot replace an already established positive
   -- storage/ACK result or bypass its own immutable planned/final reservation.
   SELECT * INTO reservation FROM public.ediel_ack_transaction_results WHERE company_id=m.company_id AND environment=m.environment AND source_message_id=source.id AND source_transaction_id=transaction_id FOR SHARE;
   IF NOT FOUND OR reservation.planned_response_type IS DISTINCT FROM 'negative_aperak' OR reservation.disposition='accepted'
    OR (reservation.final_response_type IS NOT NULL AND reservation.final_response_type<>'negative_aperak')
    OR (p_sending AND (reservation.final_response_type IS DISTINCT FROM 'negative_aperak' OR reservation.response_message_id IS DISTINCT FROM m.id OR reservation.finalized_at IS NULL)) THEN RAISE EXCEPTION 'utilts_negative_ack_reservation_unavailable';END IF;
  END IF;
 END LOOP;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_outbound_owner.require_positive_before_received_err_v1(public.ediel_messages, boolean) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:516
--
-- Name: require_positive_utilts_ack_v1(public.ediel_messages, boolean); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.require_positive_utilts_ack_v1(m public.ediel_messages, p_sending boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;a jsonb;s jsonb;groups jsonb;g jsonb;ids text[]:='{}';dms text[]:='{}';tx text;dm text;
BEGIN
 IF m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'APERAK' THEN RETURN;END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=m.related_message_id AND company_id=m.company_id AND environment=m.environment AND direction='inbound' FOR SHARE;
 IF source.message_family IS DISTINCT FROM 'UTILTS_ERR' THEN PERFORM gridex_ediel_outbound_owner.require_positive_before_received_err_v1(m,p_sending);RETURN;END IF;
 a:=gridex_ack_authority.wire_v1(m.raw_payload);s:=gridex_ack_authority.wire_v1(source.raw_payload);groups:=a->'ercGroups';
 IF a IS NULL OR a->>'family' IS DISTINCT FROM 'APERAK' OR a->>'code' IS DISTINCT FROM '312' OR a#>>'{type,2}' IS DISTINCT FROM '04A' OR a#>>'{type,4}' IS DISTINCT FROM 'E5SE5A'
  OR NOT coalesce(gridex_ack_authority.source_match_v1(a,s),false) OR jsonb_typeof(groups) IS DISTINCT FROM 'array' OR jsonb_array_length(groups)=0 THEN RAISE EXCEPTION 'utilts_err_application_response_authority_unavailable';END IF;
 FOR g IN SELECT x FROM jsonb_array_elements(groups)x LOOP
  tx:=g#>>'{acw,0}';dm:=g#>>'{dm,0}';
  IF g->>'code' IS DISTINCT FROM '100' OR jsonb_array_length(g->'acw')<>1 OR jsonb_array_length(g->'dm')<>1 OR nullif(tx,'') IS NULL OR nullif(dm,'') IS NULL OR length(dm)>(gridex_ediel_ack_guide.utilts_reference_constraints_v1()->>'ownDmMax')::integer OR tx=ANY(ids) OR dm=ANY(dms) THEN RAISE EXCEPTION 'utilts_err_application_response_authority_unavailable';END IF;
  ids:=array_append(ids,tx);dms:=array_append(dms,dm);
  PERFORM public.gridex_require_utilts_positive_ack_authority_v1(m.company_id,m.environment,source.id,tx,CASE WHEN p_sending THEN m.id ELSE NULL END,CASE WHEN p_sending THEN m.raw_payload ELSE NULL END);
 END LOOP;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_outbound_owner.require_positive_utilts_ack_v1(public.ediel_messages, boolean) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:517
--
-- Name: require_utilts_err_source_v1(public.ediel_messages, boolean); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.require_utilts_err_source_v1(m public.ediel_messages, p_sending boolean) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;tokens jsonb;a jsonb;s jsonb;facet jsonb;own_facet jsonb;
 t jsonb;sts jsonb;reference jsonb;original_reference jsonb;group_start integer;group_end integer;
 transaction_id text;national_code text;own_id text;count_refs integer;seen text[]:='{}';own_ids text[]:='{}';
 reservation public.ediel_ack_transaction_results%rowtype;
BEGIN
 IF m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'UTILTS_ERR' THEN RETURN;END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=m.related_message_id AND company_id=m.company_id AND environment=m.environment AND direction='inbound' FOR SHARE;
 IF source.id IS NULL OR source.message_family IS DISTINCT FROM 'UTILTS' THEN RAISE EXCEPTION 'utilts_err_own_source_unavailable';END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(m.raw_payload);a:=gridex_ack_authority.wire_v1(m.raw_payload);s:=gridex_ack_authority.wire_v1(source.raw_payload);
 IF tokens IS NULL OR a IS NULL OR s IS NULL OR a->>'family' IS DISTINCT FROM 'UTILTS' OR a->>'code' IS DISTINCT FROM 'ERR'
  OR NOT coalesce(gridex_ack_authority.source_match_v1(a,s),false) THEN RAISE EXCEPTION 'utilts_err_own_source_unavailable';END IF;
 facet:=gridex_received_sources.require_utilts_functional_responses_v1(m.company_id,source.id);
 IF NOT coalesce(facet->>'version' IN('1','2'),false) OR facet->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex') OR jsonb_typeof(facet->'transactions') IS DISTINCT FROM 'array'
  OR (SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='IDE')=0 THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='IDE' ORDER BY(x->>'index')::int LOOP
  group_start:=(t->>'index')::int;SELECT min((x->>'index')::int) INTO group_end FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::int>group_start AND x->>'tag' IN('IDE','UNT','UNZ');
  own_id:=t#>>'{elements,2,0}';
  IF t#>>'{elements,1,0}' IS DISTINCT FROM '24' OR nullif(own_id,'') IS NULL OR own_id=ANY(own_ids) THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;own_ids:=array_append(own_ids,own_id);
  SELECT count(*) INTO count_refs FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='STS' AND x#>>'{elements,1,0}'='E01' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;
  IF count_refs<>1 THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;
  SELECT x->'elements' INTO sts FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='STS' AND x#>>'{elements,1,0}'='E01' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;
  national_code:=sts#>>'{3,0}';
  IF sts->1 IS DISTINCT FROM '["E01","","260"]'::jsonb OR sts->2 IS DISTINCT FROM '["41"]'::jsonb OR sts->3 IS DISTINCT FROM jsonb_build_array(national_code,'','260') OR jsonb_array_length(sts)>4 OR nullif(national_code,'') IS NULL THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;
  SELECT count(*) INTO count_refs FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='TN' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;
  IF count_refs<>1 THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;
  SELECT x#>'{elements,1}' INTO reference FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='TN' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;
  transaction_id:=reference->>1;
  IF reference IS DISTINCT FROM jsonb_build_array('TN',transaction_id) OR nullif(transaction_id,'') IS NULL OR NOT coalesce(s->'ide','[]') ? transaction_id OR (transaction_id||'|'||national_code)=ANY(seen) THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;seen:=array_append(seen,transaction_id||'|'||national_code);
  SELECT count(*) INTO count_refs FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'=s->>'code' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;
  IF count_refs<>1 THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;
  SELECT x#>'{elements,1}' INTO original_reference FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'=s->>'code' AND(x->>'index')::int>group_start AND(x->>'index')::int<group_end;
  IF original_reference IS DISTINCT FROM jsonb_build_array(s->>'code',s->>'document') THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;
  SELECT count(*) INTO count_refs FROM jsonb_array_elements(facet->'transactions')x WHERE x->>'transactionId'=transaction_id;IF count_refs<>1 THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;
  SELECT x INTO own_facet FROM jsonb_array_elements(facet->'transactions')x WHERE x->>'transactionId'=transaction_id;
  IF NOT EXISTS(SELECT FROM jsonb_array_elements(own_facet->'errors')x WHERE x->>'code'=national_code AND (
    (facet->>'version'='1' AND x->>'referenceQualifier'='TN' AND x->>'referenceNumber'=transaction_id)
    OR (facet->>'version'='2' AND x->'responseReference'=jsonb_build_object('qualifier','TN','number',transaction_id) AND (
      (x->>'originalScope'='transaction' AND x->>'referenceQualifier'='TN' AND x->>'referenceNumber'=transaction_id)
      OR (x->>'originalScope'='message' AND x->'referenceNumber'='null'::jsonb)
    ))
  )) THEN RAISE EXCEPTION 'utilts_err_own_functional_facet_required';END IF;
  SELECT * INTO reservation FROM public.ediel_ack_transaction_results WHERE company_id=m.company_id AND environment=m.environment AND source_message_id=source.id AND source_transaction_id=transaction_id FOR SHARE;
  IF NOT FOUND OR reservation.planned_response_type IS DISTINCT FROM 'utilts_err' OR reservation.disposition IS DISTINCT FROM 'processability_rejected'
   OR (reservation.final_response_type IS NOT NULL AND reservation.final_response_type<>'utilts_err') OR (p_sending AND (reservation.final_response_type IS DISTINCT FROM 'utilts_err' OR reservation.response_message_id IS DISTINCT FROM m.id OR reservation.finalized_at IS NULL)) THEN RAISE EXCEPTION 'utilts_err_own_reservation_unavailable';END IF;
 END LOOP;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_outbound_owner.require_utilts_err_source_v1(public.ediel_messages, boolean) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:518
--
-- Name: require_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_outbound_owner; Owner: -
--

CREATE FUNCTION gridex_ediel_outbound_owner.require_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;w gridex_ediel_outbound_owner.witnesses%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id AND direction='outbound' FOR SHARE;
 SELECT witness.* INTO w FROM gridex_ediel_outbound_owner.consumptions c JOIN gridex_ediel_outbound_owner.witnesses witness ON witness.id=c.witness_id
  WHERE c.source_message_id=m.id AND c.company_id=m.company_id AND c.environment=m.environment AND c.payload_sha256=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') FOR SHARE OF witness;
 IF w.id IS NULL THEN RAISE EXCEPTION 'ediel_historical_outbound_owner_witness_unavailable';END IF;
 PERFORM gridex_ediel_outbound_owner.assert_message_v1(m,w);RETURN w.evidence;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_outbound_owner.require_v1(uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:519
--
-- Name: capture(uuid, uuid, uuid, text, text, text, text, uuid, text, text); Type: FUNCTION; Schema: gridex_ediel_readiness; Owner: -
--

CREATE FUNCTION gridex_ediel_readiness.capture(p_company_id uuid, p_message_id uuid, p_legal_actor_id uuid, p_actor_role text, p_family text, p_code text, p_subtype text, p_assignment_id uuid, p_release_sha text, p_rulepack_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE result jsonb;q jsonb;deps jsonb;BEGIN
 result:=gridex_ediel_readiness.capture_before_registry_markets_v1(p_company_id,p_message_id,p_legal_actor_id,p_actor_role,p_family,p_code,p_subtype,p_assignment_id,p_release_sha,p_rulepack_hash);
 q:=gridex_registry_import.require_message_market_v1(p_company_id,p_message_id);
 IF q IS NULL THEN RETURN result;END IF;
 deps:=(result->'dependencies')||jsonb_build_object('sourceQualifiedRegistryMarket',q);
 RETURN result||jsonb_build_object('dependencies',deps,'dependencyHash',encode(sha256(convert_to(jsonb_build_object('scope',result->'scope','dependencies',deps)::text,'UTF8')),'hex'));
END$$;

REVOKE ALL ON FUNCTION gridex_ediel_readiness.capture(uuid, uuid, uuid, text, text, text, text, uuid, text, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:520
--
-- Name: capture_before_registry_markets_v1(uuid, uuid, uuid, text, text, text, text, uuid, text, text); Type: FUNCTION; Schema: gridex_ediel_readiness; Owner: -
--

CREATE FUNCTION gridex_ediel_readiness.capture_before_registry_markets_v1(p_company_id uuid, p_message_id uuid, p_legal_actor_id uuid, p_actor_role text, p_family text, p_code text, p_subtype text, p_assignment_id uuid, p_release_sha text, p_rulepack_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE current_scope jsonb; deps jsonb; m public.ediel_messages%rowtype; r public.ediel_route_profiles%rowtype; communication public.communication_routes%rowtype; registry_route public.platform_actor_routes%rowtype; registry_id uuid; route_dependency jsonb;
BEGIN
 current_scope:=gridex_ediel_readiness.capture_before_route_dependencies_v1(p_company_id,p_message_id,p_legal_actor_id,p_actor_role,p_family,p_code,p_subtype,p_assignment_id,p_release_sha,p_rulepack_hash);
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO r FROM public.ediel_route_profiles WHERE id=m.route_profile_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO communication FROM public.communication_routes WHERE id=r.communication_route_id AND company_id=p_company_id FOR SHARE;
 IF NOT FOUND OR communication.is_active IS DISTINCT FROM true OR to_jsonb(communication)->>'environment_type' IS DISTINCT FROM 'production' THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 BEGIN registry_id:=nullif(r.metadata->>'platform_actor_route_id','')::uuid; EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END;
 IF registry_id IS NOT NULL THEN
  SELECT * INTO registry_route FROM public.platform_actor_routes WHERE id=registry_id AND environment='production' FOR SHARE;
  IF NOT FOUND OR registry_route.is_verified IS DISTINCT FROM true OR registry_route.status IS DISTINCT FROM 'active' OR to_jsonb(registry_route)->'auto_send_allowed'='false'::jsonb THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  IF nullif(btrim(registry_route.communication_address),'') IS NULL OR lower(btrim(registry_route.communication_address)) IS DISTINCT FROM lower(btrim(communication.target_email)) THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  IF coalesce(nullif(btrim(registry_route.party_id),''),nullif(btrim(registry_route.interchange_party_id),'')) IS DISTINCT FROM nullif(btrim(r.receiver_ediel_id),'')
   OR upper(registry_route.message_family) IS DISTINCT FROM upper(m.message_family) THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 END IF;
 -- Only selected actual fields. No global routes hash or secret auth_config.
 route_dependency:=jsonb_build_object('communicationRoute',jsonb_build_object('id',communication.id,'companyId',communication.company_id,'active',communication.is_active,'environment',to_jsonb(communication)->'environment_type','targetEmail',communication.target_email,'endpoint',to_jsonb(communication)->'endpoint','counterpartyEdielId',to_jsonb(communication)->'counterparty_ediel_id','payloadVersion',to_jsonb(communication)->'supported_payload_version','messageFamilies',to_jsonb(communication)->'supported_message_families','messageCodes',to_jsonb(communication)->'supported_message_codes'),
  'registryRoute',CASE WHEN registry_id IS NULL THEN NULL ELSE jsonb_build_object('id',registry_route.id,'actorId',registry_route.actor_id,'environment',registry_route.environment,'messageFamily',registry_route.message_family,'applicationReference',registry_route.application_reference,'subaddress',registry_route.subaddress,'communicationType',registry_route.communication_type,'communicationAddress',registry_route.communication_address,'partyId',registry_route.party_id,'interchangePartyId',registry_route.interchange_party_id,'verified',registry_route.is_verified,'status',registry_route.status,'source',registry_route.source,'sourceVersion',registry_route.metadata->'source_version') END);
 deps:=(current_scope->'dependencies')||jsonb_build_object('selectedRouteSecurity',route_dependency);
 RETURN current_scope||jsonb_build_object('dependencies',deps,'dependencyHash',encode(digest(convert_to(jsonb_build_object('scope',current_scope->'scope','dependencies',deps)::text,'UTF8'),'sha256'),'hex'));
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_readiness.capture_before_registry_markets_v1(uuid, uuid, uuid, text, text, text, text, uuid, text, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:521
--
-- Name: capture_before_route_dependencies_v1(uuid, uuid, uuid, text, text, text, text, uuid, text, text); Type: FUNCTION; Schema: gridex_ediel_readiness; Owner: -
--

CREATE FUNCTION gridex_ediel_readiness.capture_before_route_dependencies_v1(p_company_id uuid, p_message_id uuid, p_legal_actor_id uuid, p_actor_role text, p_family text, p_code text, p_subtype text, p_assignment_id uuid, p_release_sha text, p_rulepack_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE m public.ediel_messages%rowtype; r public.ediel_route_profiles%rowtype; scope jsonb; deps jsonb; profile_rows jsonb; role_rows jsonb;
 identifier_rows jsonb; capability_rows jsonb; permission_rows jsonb:='[]'; assignment_rows jsonb:='[]'; certificate_rows jsonb;
 schema_parts jsonb; schema_hash text; schema_ready boolean; release_row public.platform_release_receipts%rowtype; source_tokens jsonb; family text; code text; wire_subtype text; derived jsonb; selected_profile public.ediel_message_profiles%rowtype; selected_pack public.ediel_rule_packs%rowtype;
BEGIN
 IF p_company_id IS NULL OR p_message_id IS NULL OR p_legal_actor_id IS NULL OR nullif(p_actor_role,'') IS NULL
  OR p_family IS NULL OR p_family NOT IN ('PRODAT','UTILTS','AI_LIST') OR nullif(p_code,'') IS NULL OR p_code='ERR'
  OR p_release_sha IS NULL OR p_release_sha !~ '^[0-9a-f]{40}$' OR p_rulepack_hash IS NULL OR p_rulepack_hash !~ '^[0-9a-f]{64}$' THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 SELECT * INTO release_row FROM public.platform_release_receipts WHERE environment='production' AND status='verified'
  AND verified_at IS NOT NULL AND nullif(ci_run_id,'') IS NOT NULL AND nullif(deployment_id,'') IS NOT NULL
  ORDER BY verified_at DESC,recorded_at DESC,id LIMIT 1 FOR SHARE;
 IF NOT FOUND OR release_row.release_sha IS DISTINCT FROM p_release_sha THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id AND environment='production' FOR SHARE;
 IF NOT FOUND OR m.direction<>'outbound' OR m.message_family IS DISTINCT FROM p_family OR m.message_code IS DISTINCT FROM p_code
  OR (p_family<>'AI_LIST' AND m.rule_pack_checksum IS DISTINCT FROM p_rulepack_hash) OR m.raw_payload IS NULL THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 derived:=gridex_ediel_readiness.source_scope(m);
 IF derived->>'actorId' IS DISTINCT FROM p_legal_actor_id::text OR derived->>'actorRole' IS DISTINCT FROM p_actor_role
  OR derived->>'family' IS DISTINCT FROM p_family OR derived->>'code' IS DISTINCT FROM p_code OR derived->>'subtype' IS DISTINCT FROM p_subtype
  OR derived->>'assignmentId' IS DISTINCT FROM p_assignment_id::text THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 wire_subtype:=derived#>>'{canonicalProjection,transactionReasonCode}';
 IF p_family<>'AI_LIST' THEN
  SELECT * INTO selected_profile FROM public.ediel_message_profiles mp WHERE mp.id=m.rule_profile_version_id AND mp.rule_pack_id=m.canonical_rule_pack_id AND mp.message_code=p_code
   AND mp.transaction_subtype=coalesce(p_subtype,'') AND mp.is_enabled AND mp.direction IN ('outbound','both') FOR SHARE;
  IF NOT FOUND OR (p_family='PRODAT' AND selected_profile.profile->>'reasonForTransaction' IS DISTINCT FROM wire_subtype) THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  SELECT * INTO selected_pack FROM public.ediel_rule_packs rp WHERE rp.id=selected_profile.rule_pack_id AND rp.family=p_family AND rp.market='electricity' AND rp.status='active'
   AND rp.source_hash=p_rulepack_hash AND rp.valid_from<=current_date AND (rp.valid_to IS NULL OR rp.valid_to>=current_date) FOR SHARE;
  IF NOT FOUND THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',a.id,'companyId',a.company_id,'environment',a.environment,'market',a.market,'enabled',a.is_enabled,'validFrom',a.valid_from,'validTo',a.valid_to) ORDER BY a.id),'[]') INTO profile_rows FROM public.tenant_ediel_profiles a
  WHERE a.company_id=p_company_id AND a.environment='production' AND a.market='electricity' AND a.is_enabled AND a.valid_from<=now() AND (a.valid_to IS NULL OR a.valid_to>now());
 SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]') INTO identifier_rows FROM public.tenant_actor_identifiers a
  WHERE a.company_id=p_company_id AND a.environment='production' AND a.actor_id=p_legal_actor_id AND a.identifier_type='EdielId' AND a.valid_from<=now() AND (a.valid_to IS NULL OR a.valid_to>now());
 SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]') INTO role_rows FROM public.tenant_actor_roles a
  WHERE a.company_id=p_company_id AND a.environment='production' AND a.actor_id=p_legal_actor_id AND a.role_code=p_actor_role AND a.valid_from<=now() AND (a.valid_to IS NULL OR a.valid_to>now());
 SELECT coalesce(jsonb_agg(to_jsonb(a) ORDER BY a.id),'[]') INTO capability_rows FROM public.tenant_message_capabilities a
  WHERE a.company_id=p_company_id AND a.environment='production' AND a.message_family=p_family AND a.message_code=p_code AND a.transaction_subtype IN ('*',coalesce(p_subtype,''))
   AND a.direction IN ('outbound','both') AND a.is_enabled AND a.valid_from<=now() AND (a.valid_to IS NULL OR a.valid_to>now());
 IF p_family='AI_LIST' AND NOT EXISTS(SELECT FROM jsonb_array_elements(identifier_rows) x WHERE x->>'identifier_value'=split_part(m.raw_payload,';',4)) THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 IF jsonb_array_length(profile_rows)=0 OR jsonb_array_length(identifier_rows)=0 OR jsonb_array_length(role_rows)=0 OR jsonb_array_length(capability_rows)=0 THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 SELECT * INTO r FROM public.ediel_route_profiles WHERE company_id=p_company_id AND id=m.route_profile_id AND environment='production' FOR SHARE;
 IF NOT FOUND OR NOT coalesce(r.is_enabled,false) OR r.is_active=false OR r.communication_route_id IS DISTINCT FROM m.communication_route_id THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 IF EXISTS(SELECT FROM public.ediel_certificates c WHERE c.company_id=p_company_id AND c.id IN (r.certificate_id,r.receiver_certificate_id)
   AND ((c.certificate_valid_from IS NOT NULL AND c.certificate_valid_from>now()) OR (c.certificate_valid_to IS NOT NULL AND c.certificate_valid_to<=now()))) THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',c.id,'fingerprint',c.certificate_fingerprint,'validFrom',c.certificate_valid_from,'validTo',c.certificate_valid_to,'status',c.status,'encryptionStatus',c.encryption_status) ORDER BY c.id),'[]') INTO certificate_rows
  FROM public.ediel_certificates c WHERE c.company_id=p_company_id AND c.id IN (r.certificate_id,r.receiver_certificate_id);
 IF p_actor_role IN ('energy_service_company','esco','service_provider') THEN
  IF p_assignment_id IS NULL OR public.ediel_service_assignment_assessment_v1(p_company_id,p_assignment_id)->>'status' IS DISTINCT FROM 'authorized' THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  SELECT jsonb_build_array(to_jsonb(a)) INTO assignment_rows FROM public.ediel_service_assignments a
   WHERE a.id=p_assignment_id AND a.company_id=p_company_id AND a.environment='production' AND a.provider_actor_id=p_legal_actor_id AND a.customer_id=m.customer_id;
  IF assignment_rows IS NULL THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  SELECT coalesce(jsonb_agg(jsonb_build_object('permission',to_jsonb(p),'link',to_jsonb(l),'grants',coalesce((SELECT jsonb_agg(to_jsonb(g) ORDER BY g.id) FROM public.ediel_data_access_grants g WHERE g.company_id=p_company_id AND g.permission_link_id=l.id),'[]')) ORDER BY l.id),'[]') INTO permission_rows
   FROM public.ediel_assignment_permission_links l JOIN public.metering_permissions p ON p.id=l.permission_id AND p.company_id=l.company_id WHERE l.company_id=p_company_id AND l.assignment_id=p_assignment_id;
 ELSE
  IF p_assignment_id IS NOT NULL THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 END IF;
 -- Live schema identity for this capability's own dependency relations/functions.
 -- Unrelated UI/schema additions do not invalidate a different dependency graph.
 SELECT coalesce(is_ready,false) INTO schema_ready FROM public.platform_runtime_readiness WHERE id=true;
 IF NOT coalesce(schema_ready,false) THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 SELECT jsonb_build_object('columns',(SELECT jsonb_agg(jsonb_build_array(n.nspname,c.relname,a.attname,format_type(a.atttypid,a.atttypmod),a.attnotnull) ORDER BY n.nspname,c.relname,a.attnum)
  FROM pg_attribute a JOIN pg_class c ON c.oid=a.attrelid JOIN pg_namespace n ON n.oid=c.relnamespace
  WHERE n.nspname='public' AND c.relname=ANY(ARRAY['ediel_messages','ediel_route_profiles','ediel_certificates','tenant_ediel_profiles','tenant_actor_identifiers','tenant_actor_roles','tenant_message_capabilities',CASE WHEN p_actor_role IN ('energy_service_company','esco','service_provider') THEN 'ediel_service_assignments' END,CASE WHEN p_actor_role IN ('energy_service_company','esco','service_provider') THEN 'metering_permissions' END,CASE WHEN p_actor_role IN ('energy_service_company','esco','service_provider') THEN 'ediel_data_access_grants' END]) AND a.attnum>0 AND NOT a.attisdropped),
  'functions',(SELECT jsonb_agg(jsonb_build_array(n.nspname,p.proname,pg_get_function_identity_arguments(p.oid),p.prosecdef,p.proconfig,pg_get_functiondef(p.oid)) ORDER BY n.nspname,p.proname,p.oid)
   FROM pg_proc p JOIN pg_namespace n ON n.oid=p.pronamespace WHERE n.nspname='gridex_ediel_readiness' AND p.proname IN ('capture','source_scope'))) INTO schema_parts;
 schema_hash:=encode(digest(convert_to(schema_parts::text,'UTF8'),'sha256'),'hex');
 scope:=jsonb_build_object('companyId',p_company_id,'actorId',p_legal_actor_id,'actorRole',p_actor_role,'market','electricity','environment','production','family',p_family,'code',p_code,'subtype',p_subtype,'assignmentId',p_assignment_id);
 deps:=jsonb_build_object('releaseSha',p_release_sha,'releaseReceipt',jsonb_build_object('id',release_row.id,'ciRunId',release_row.ci_run_id,'deploymentId',release_row.deployment_id,'schemaMigrationVersion',release_row.schema_migration_version,'databaseSchemaFingerprint',to_jsonb(release_row)->'database_schema_fingerprint','generatedTypesHash',to_jsonb(release_row)->'generated_types_hash','migrationManifestHash',to_jsonb(release_row)->'migration_manifest_hash'),'schemaFingerprint',schema_hash,'rulepackHash',p_rulepack_hash,'wireTransactionReason',wire_subtype,'technicalFormatVersion',CASE WHEN p_family='AI_LIST' THEN 'Ver20140401' ELSE NULL END,'rulepackId',m.canonical_rule_pack_id,'ruleProfileVersionId',m.rule_profile_version_id,
   'canonicalProjection',derived->'canonicalProjection','canonicalProjectionHash',derived->'canonicalProjectionHash','transportRelation',derived->'transportRelation','transportEdielId',derived->'transportEdielId','transportIdentifiers',derived->'transportIdentifiers',
   'normativeProjection',CASE WHEN p_family='AI_LIST' THEN '[]'::jsonb ELSE jsonb_build_array(jsonb_build_object('packId',selected_pack.id,'sourceHash',selected_pack.source_hash,'status',selected_pack.status,'guideVersion',selected_pack.guide_version,'guideRevision',selected_pack.guide_revision,'validFrom',selected_pack.valid_from,'validTo',selected_pack.valid_to,'profileId',selected_profile.id,'profileKey',selected_profile.profile_key,'subtype',selected_profile.transaction_subtype,'profile',selected_profile.profile)) END,
  'tenantRuleProfileVersion',coalesce((SELECT jsonb_build_object('id',rv.id,'version',rv.version,'status',rv.status,'checksum',rv.checksum,'sourceRevision',rv.source_revision)
    FROM public.ediel_rule_profile_versions rv WHERE rv.company_id=p_company_id AND rv.id=m.rule_profile_version_id), '{}'::jsonb),
  'profile',profile_rows,'legalIdentifiers' ,identifier_rows,'actorRole',role_rows,'capability',capability_rows,
  'route',jsonb_build_object('id',r.id,'communicationRouteId',r.communication_route_id,'routeVersion',to_jsonb(r)->'route_version','senderEdielId',r.sender_ediel_id,'receiverEdielId',r.receiver_ediel_id,'senderSubaddress',coalesce(r.sender_sub_address,r.sender_subaddress),'receiverSubaddress',coalesce(r.receiver_sub_address,r.receiver_subaddress),'mailboxId',r.mailbox_id,'transportProfileId',r.transport_profile_id,'certificateId',r.certificate_id,'receiverCertificateId',r.receiver_certificate_id,'enabled',r.is_enabled,'active',r.is_active),
  'certificates',certificate_rows,'assignments',assignment_rows,'permissions',permission_rows);
 RETURN jsonb_build_object('authorityVersion',1,'scope',scope,'dependencies',deps,'dependencyHash',encode(digest(convert_to(jsonb_build_object('scope',scope,'dependencies',deps)::text,'UTF8'),'sha256'),'hex'));
END $_$;

