-- canonical:523
--
-- Name: source_scope(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_readiness; Owner: -
--

CREATE FUNCTION gridex_ediel_readiness.source_scope(m public.ediel_messages) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE ai_parties jsonb;tokens jsonb; own_projection jsonb; family text; code text; reason text; wire_sender text; legal_actor uuid; legal_id text;
 transport_id text; transport_identifiers jsonb; relation public.tenant_counterparty_relations%rowtype; role text; role_count integer; reasons jsonb; assignment uuid;
BEGIN
 IF m.direction<>'outbound' OR m.environment<>'production' OR m.company_id IS NULL OR nullif(m.raw_payload,'') IS NULL THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 IF m.message_family='AI_LIST' THEN
  IF m.message_code<>'AI' OR split_part(m.raw_payload,';',1)<>'AI' OR rtrim(split_part(split_part(m.raw_payload,E'\n',1),';',10),E'\r')<>'Ver20140401' THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  family:='AI_LIST';code:='AI';wire_sender:=split_part(m.raw_payload,';',4);
  own_projection:=jsonb_build_object('family','AI_LIST','code','AI','subtype',NULL,'transactionReasonCode',NULL,'senderRoles',jsonb_build_array('supplier'),'direction','outbound');
 ELSE
  tokens:=gridex_utilts_binding.wire_tokens_v1(m.raw_payload);
  IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNB')<>1
   OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNH')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM')<>1 THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  SELECT t#>>'{elements,2,0}' INTO family FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNH';
  SELECT t#>>'{elements,1,0}' INTO code FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM';
  SELECT t#>>'{elements,2,0}' INTO wire_sender FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNB';
  IF family='PRODAT' THEN
   SELECT coalesce(jsonb_agg(DISTINCT cav.token#>>'{elements,1,0}'),'[]') INTO reasons FROM jsonb_array_elements(tokens) WITH ORDINALITY cci(token,n)
    JOIN jsonb_array_elements(tokens) WITH ORDINALITY cav(token,n) ON cav.n=cci.n+1 WHERE cci.token->>'tag'='CCI' AND cci.token#>>'{elements,2,0}'='Z13' AND cav.token->>'tag'='CAV';
   IF jsonb_array_length(reasons)<>1 OR nullif(reasons->>0,'') IS NULL THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
   reason:=reasons->>0;
  END IF;
  SELECT projection INTO own_projection FROM (SELECT catalog FROM gridex_ediel_readiness.source_editions ORDER BY recorded_at DESC,source_version LIMIT 1) edition CROSS JOIN LATERAL jsonb_array_elements(edition.catalog) projection
   WHERE projection->>'family'=family AND projection->>'code'=code AND projection->>'transactionReasonCode' IS NOT DISTINCT FROM reason;
  IF own_projection IS NULL OR own_projection->>'direction' NOT IN ('outbound','both') THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 END IF;
 IF family IS DISTINCT FROM m.message_family OR code IS DISTINCT FROM m.message_code THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 -- Count the entire current legal identity set: no stale proof can opt into a
 -- different valid actor of the same tenant or resolve an ambiguous identity.
 IF (SELECT count(DISTINCT (i.actor_id,btrim(i.identifier_value))) FROM public.tenant_actor_identifiers i WHERE i.company_id=m.company_id AND i.environment='production' AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR i.valid_to>now()))<>1 THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 SELECT i.actor_id,btrim(i.identifier_value) INTO legal_actor,legal_id FROM public.tenant_actor_identifiers i WHERE i.company_id=m.company_id AND i.environment='production' AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR i.valid_to>now()) LIMIT 1;
 IF legal_actor IS NULL OR nullif(legal_id,'') IS NULL THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 IF family='AI_LIST' THEN
  IF wire_sender IS DISTINCT FROM legal_id THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 ELSE
  IF (SELECT count(*) FROM public.tenant_counterparty_relations t WHERE t.company_id=m.company_id AND t.environment='production' AND t.relation_type='ediel_transport_agent' AND t.is_enabled AND t.valid_from<=now() AND (t.valid_to IS NULL OR t.valid_to>now()))>1 THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  SELECT * INTO relation FROM public.tenant_counterparty_relations t WHERE t.company_id=m.company_id AND t.environment='production' AND t.relation_type='ediel_transport_agent' AND t.is_enabled AND t.valid_from<=now() AND (t.valid_to IS NULL OR t.valid_to>now());
  transport_id:=legal_id;
  IF FOUND THEN
   IF relation.counterparty_actor_id=legal_actor OR (SELECT count(DISTINCT btrim(i.identifier_value)) FROM public.platform_actor_identifiers i WHERE i.actor_id=relation.counterparty_actor_id AND i.identifier_type='EdielId' AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date))<>1 THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
   SELECT btrim(i.identifier_value) INTO transport_id FROM public.platform_actor_identifiers i WHERE i.actor_id=relation.counterparty_actor_id AND i.identifier_type='EdielId' AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date) LIMIT 1;
   SELECT jsonb_agg(to_jsonb(i) ORDER BY i.id) INTO transport_identifiers FROM public.platform_actor_identifiers i WHERE i.actor_id=relation.counterparty_actor_id AND i.identifier_type='EdielId' AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date);
   IF transport_id=legal_id THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
  END IF;
  IF nullif(transport_id,'') IS NULL OR wire_sender IS DISTINCT FROM transport_id THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 END IF;
 SELECT count(DISTINCT a.role_code),min(a.role_code) INTO role_count,role FROM public.tenant_actor_roles a WHERE a.company_id=m.company_id AND a.environment='production' AND a.actor_id=legal_actor AND a.valid_from<=now() AND (a.valid_to IS NULL OR a.valid_to>now())
  AND own_projection->'senderRoles' ? CASE a.role_code WHEN 'electricity_supplier' THEN 'supplier' WHEN 'energy_service_company' THEN 'esco' ELSE a.role_code END;
 IF role_count<>1 THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 IF role IN ('energy_service_company','esco') THEN
  BEGIN assignment:=nullif(m.parsed_payload->>'serviceAssignmentId','')::uuid; EXCEPTION WHEN invalid_text_representation THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END;
  IF assignment IS NULL THEN RAISE EXCEPTION 'ediel_scoped_capability_evidence_required'; END IF;
 END IF;
 IF family='AI_LIST' THEN
  ai_parties:=gridex_ai_processing.party_source_v1(m.company_id,m.intent_id);PERFORM gridex_ai_processing.require_party_wire_v1(m.raw_payload,ai_parties);
  IF m.sender_ediel_id IS DISTINCT FROM ai_parties->>'technicalSender' OR m.receiver_ediel_id IS DISTINCT FROM ai_parties->>'technicalReceiver' THEN RAISE EXCEPTION 'ai_list_readiness_technical_party_source_mismatch';END IF;
  transport_id:=ai_parties->>'technicalSender';transport_identifiers:=ai_parties#>'{sourceBasis,transportIdentifiers}';
 END IF;
 RETURN jsonb_build_object('actorId',legal_actor,'actorRole',role,'family',family,'code',code,'subtype',own_projection->'subtype','assignmentId',assignment,'canonicalProjection',own_projection,'canonicalProjectionHash',encode(digest(convert_to(own_projection::text,'UTF8'),'sha256'),'hex'),'transportRelation',CASE WHEN family='AI_LIST' THEN ai_parties#>'{sourceBasis,transportRelation}' WHEN relation.id IS NULL THEN NULL ELSE to_jsonb(relation) END,'transportEdielId',transport_id,'transportIdentifiers',transport_identifiers);
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_readiness.source_scope(public.ediel_messages) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:524
--
-- Name: actor_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.actor_v1(c uuid, actor uuid, permission text) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 -- Hold the actual authorization registry, including insertion of new deny
 -- overrides, throughout this operation; a preceding server/UI check is not it.
 LOCK TABLE public.permissions,public.roles,public.user_roles,public.role_permissions,public.user_permissions,public.user_permission_overrides IN SHARE MODE;
 PERFORM public.ediel_retention_lock_auth_actor_v1(actor);PERFORM id FROM public.companies WHERE id=c FOR SHARE;PERFORM id FROM public.user_profiles WHERE id=actor FOR SHARE;
 PERFORM user_id FROM public.company_memberships WHERE company_id=c AND user_id=actor FOR SHARE;
 IF public.ediel_retention_session_actor_v1() IS DISTINCT FROM actor OR permission NOT IN('ediel.retention.submit','ediel.retention.review','ediel.retention.purge')
 OR NOT public.ediel_retention_lock_auth_actor_v1(actor)
 OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active')
 OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
 OR gridex_ediel_retention.permission_v1(c,actor,permission) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_retention_current_actor_forbidden' USING ERRCODE='42501';END IF;
END$$;

REVOKE ALL ON FUNCTION gridex_ediel_retention.actor_v1(uuid, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:525
--
-- Name: artifact_guard_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.artifact_guard_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF TG_OP<>'UPDATE' OR old.source_bytes IS NULL OR new.source_bytes IS NOT NULL OR new.purged_at IS NULL
 OR (to_jsonb(new)-ARRAY['source_bytes','purged_at']) IS DISTINCT FROM (to_jsonb(old)-ARRAY['source_bytes','purged_at'])
 OR NOT EXISTS(SELECT FROM gridex_ediel_retention.purges p WHERE p.artifact_id=old.id AND p.company_id=old.company_id AND p.source_hash=old.source_hash AND p.claims_hash=old.claims_hash AND p.byte_length=octet_length(old.source_bytes) AND p.created_at=new.purged_at)
 THEN RAISE EXCEPTION 'ediel_artifact_immutable_without_qualified_purge';END IF;RETURN new;
END$$;

REVOKE ALL ON FUNCTION gridex_ediel_retention.artifact_guard_v1() FROM PUBLIC,anon,authenticated,service_role;

-- canonical:526
--
-- Name: artifact_insert_length_v1(); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.artifact_insert_length_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF new.source_bytes IS NULL OR new.purged_at IS NOT NULL THEN RAISE EXCEPTION 'ediel_retention_new_source_bytes_required';END IF;
 new.source_byte_length:=octet_length(new.source_bytes);RETURN new;
END$$;

REVOKE ALL ON FUNCTION gridex_ediel_retention.artifact_insert_length_v1() FROM PUBLIC,anon,authenticated,service_role;

-- canonical:527
--
-- Name: blob_basis_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.blob_basis_v1(c uuid, k text, target uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE m public.ediel_messages%rowtype;s gridex_received_sources.sources%rowtype;p public.ediel_message_payloads%rowtype;facts jsonb;rawhash text;bytes bigint;path text;payloads jsonb;
BEGIN
 IF k='received_ediel_message_content' THEN
  SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=target AND company_id=c FOR SHARE;SELECT * INTO STRICT s FROM gridex_received_sources.sources WHERE source_message_id=m.id AND company_id=c FOR SHARE;
  IF m.direction IS DISTINCT FROM 'inbound' OR s.raw_payload IS NULL OR m.raw_payload IS DISTINCT FROM s.raw_payload OR s.payload_hash IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'retention_actual_received_original_required';END IF;
  PERFORM id FROM public.ediel_message_payloads WHERE company_id=c AND ediel_message_id=m.id ORDER BY id FOR SHARE;
  SELECT coalesce(jsonb_agg(jsonb_build_object('id',id,'raw',raw_payload,'encrypted',encrypted_payload,'hash',raw_payload_hash,'kind',payload_kind) ORDER BY id),'[]') INTO payloads FROM public.ediel_message_payloads WHERE company_id=c AND ediel_message_id=m.id;
  rawhash:=s.payload_hash;bytes:=octet_length(convert_to(s.raw_payload,'UTF8'));facts:=jsonb_build_object('source',to_jsonb(s),'publicContent',gridex_ediel_retention.public_content_v1(m),'payloadCopies',payloads);
 ELSIF k='transport_raw_mime_bytes' THEN
  SELECT * INTO STRICT p FROM public.ediel_message_payloads WHERE id=target AND company_id=c FOR SHARE;SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=p.ediel_message_id AND company_id=c FOR SHARE;
  rawhash:=p.metadata->>'archived_mime_sha256';bytes:=(p.metadata->>'archived_mime_bytes')::bigint;path:='transport/'||c::text||'/'||m.id::text||'/'||rawhash||'.eml';
  IF m.direction IS DISTINCT FROM 'outbound' OR p.payload_kind NOT IN('raw_mime','smime_enveloped') OR p.metadata->>'archive_verified' IS DISTINCT FROM 'true' OR rawhash!~'^[a-f0-9]{64}$' OR bytes NOT BETWEEN 1 AND 33554432 OR p.encrypted_payload_ref IS DISTINCT FROM 'storage://ediel-files/'||path
  OR NOT (EXISTS(SELECT FROM gridex_ediel_transport.attempts a WHERE a.company_id=c AND a.message_id=m.id AND a.entered_at IS NOT NULL AND a.binding->>'mimeSha256'=rawhash AND a.binding->>'mimeArchiveRef'=p.encrypted_payload_ref AND a.binding->>'mimeLength'=bytes::text AND a.binding->>'rfcMessageId'=p.metadata->>'archived_rfc_message_id')
   OR EXISTS(SELECT FROM gridex_outbound_dispatch.attempts a JOIN gridex_outbound_dispatch.events e ON e.attempt_id=a.id AND e.kind='provider_call_entered' WHERE a.company_id=c AND a.message_id=m.id AND a.binding->>'mimeSha256'=rawhash AND a.binding->>'mimeArchiveRef'=p.encrypted_payload_ref AND a.binding->>'mimeLength'=bytes::text AND a.binding->>'rfcMessageId'=p.metadata->>'archived_rfc_message_id')) THEN RAISE EXCEPTION 'retention_private_entered_mime_original_required';END IF;
  facts:=jsonb_build_object('snapshot',to_jsonb(p),'message',m.id,'company',c,'environment',m.environment);
 ELSE RAISE EXCEPTION 'retention_class_not_implemented';END IF;
 RETURN jsonb_build_object('companyId',c,'retentionClass',k,'targetId',target,'messageId',m.id,'sourceHash',rawhash,'targetHash',encode(sha256(convert_to(facts::text,'UTF8')),'hex'),'publicContentHash',encode(sha256(convert_to(gridex_ediel_retention.public_content_v1(m)::text,'UTF8')),'hex'),'byteLength',bytes,'storagePath',path);
END$_$;

REVOKE ALL ON FUNCTION gridex_ediel_retention.blob_basis_v1(uuid, text, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:530
--
-- Name: blob_current_v1(gridex_ediel_retention.blob_decisions); Type: FUNCTION; Schema: gridex_ediel_retention; Owner: -
--

CREATE FUNCTION gridex_ediel_retention.blob_current_v1(d gridex_ediel_retention.blob_decisions) RETURNS uuid
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r gridex_ediel_retention.blob_reviews%rowtype;claims jsonb;BEGIN
 SELECT * INTO r FROM gridex_ediel_retention.blob_reviews WHERE decision_id=d.id ORDER BY created_at DESC,id DESC LIMIT 1 FOR SHARE;
 PERFORM public.ediel_retention_lock_auth_actor_v1(r.actor_user_id);PERFORM id FROM public.user_profiles WHERE id=r.actor_user_id FOR SHARE;PERFORM user_id FROM public.company_memberships WHERE company_id=d.company_id AND user_id=r.actor_user_id FOR SHARE;
 IF r.outcome IS DISTINCT FROM 'approved' OR NOT public.ediel_retention_lock_auth_actor_v1(r.actor_user_id) OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=r.actor_user_id AND user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=d.company_id AND user_id=r.actor_user_id AND status='active' AND is_active AND accepted_at IS NOT NULL) OR gridex_ediel_retention.permission_v1(d.company_id,r.actor_user_id,'ediel.retention.review') IS NOT TRUE THEN RETURN NULL;END IF;
 IF gridex_ediel_retention.class_permission_v1(d.company_id,r.actor_user_id,d.retention_class) IS NOT TRUE THEN RETURN NULL;END IF;claims:=gridex_ediel_retention.blob_receipt_v1(d);IF claims IS NULL OR (claims->>'retainUntil')::timestamptz>now() THEN RETURN NULL;END IF;RETURN r.id;
END$$;

