 SELECT retention_class INTO STRICT k FROM gridex_ediel_retention.process_class_catalog WHERE source_table=TG_TABLE_NAME;target:=(CASE WHEN TG_OP='INSERT' THEN to_jsonb(NEW) ELSE to_jsonb(OLD) END)->>'id';
