    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF TG_OP<>'UPDATE' OR old.raw_payload IS NULL OR new.raw_payload IS NOT NULL OR new.retention_purged_at IS NULL OR (to_jsonb(new)-ARRAY['raw_payload','retention_purged_at','scope_point']) IS DISTINCT FROM (to_jsonb(old)-ARRAY['raw_payload','retention_purged_at','scope_point']) OR NOT EXISTS(SELECT FROM gridex_ediel_retention.blob_tombstones t WHERE t.retention_class='received_ediel_message_content' AND t.target_id=old.source_message_id AND t.company_id=old.company_id AND t.source_hash=old.payload_hash AND t.byte_length=octet_length(convert_to(old.raw_payload,'UTF8')) AND t.created_at=new.retention_purged_at) THEN RAISE EXCEPTION 'received_original_immutable_without_native_retention';END IF;RETURN new;END$$;

