-- canonical:781
--
-- Name: reconciliation_observed_v1(); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.reconciliation_observed_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF TG_TABLE_SCHEMA='gridex_ediel_transport' AND TG_TABLE_NAME='attempts' AND TG_OP='UPDATE' THEN
  IF OLD.observed_at IS NULL AND NEW.observed_at IS NOT NULL AND NEW.classification='unknown' AND NEW.entered_at IS NOT NULL THEN
   PERFORM gridex_ediel_transport.open_reconciliation_case_v1('generic_journal',NEW.id,'provider_outcome_unknown','generic_observation',NEW.id);
  END IF;
 ELSIF TG_TABLE_SCHEMA='gridex_outbound_dispatch' AND TG_TABLE_NAME='events' AND TG_OP='INSERT' THEN
  IF NEW.kind='provider_result' AND NEW.facts->>'classification'='uncertain' THEN
   -- Result witness can only be made after commit; require the committed ENTRY witness.
   PERFORM gridex_ediel_transport.open_reconciliation_case_v1('sealed_z08',NEW.attempt_id,'provider_outcome_unknown','sealed_result',NEW.id);
  END IF;
 ELSE RAISE EXCEPTION 'ediel_reconciliation_observation_origin_invalid'; END IF;
 RETURN NEW;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_transport.reconciliation_observed_v1() FROM PUBLIC,anon,authenticated,service_role;

-- canonical:782
--
-- Name: reconciliation_worker_uncertain_v1(); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.reconciliation_worker_uncertain_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a record;
BEGIN
 IF OLD.status IS DISTINCT FROM 'sending' OR NEW.status IS DISTINCT FROM 'delivery_uncertain' OR OLD.current_send_attempt_id IS NULL OR OLD.locked_at IS NULL OR nullif(OLD.locked_by,'') IS NULL
  OR NEW.company_id IS DISTINCT FROM OLD.company_id OR NEW.environment IS DISTINCT FROM OLD.environment OR NEW.ediel_message_id IS DISTINCT FROM OLD.ediel_message_id OR NEW.current_send_attempt_id IS DISTINCT FROM OLD.current_send_attempt_id
 THEN RETURN NEW; END IF;
 -- The prior real claim, not a caller boolean, must own an unresolved entry.
 FOR a IN
  SELECT x.id,'generic_journal'::text lane FROM gridex_ediel_transport.attempts x
   JOIN gridex_ediel_transport.reservations r ON r.message_id=x.message_id AND r.attempt_id=x.id AND r.state='entered'
   WHERE x.company_id=OLD.company_id AND x.environment=OLD.environment AND x.message_id=OLD.ediel_message_id AND x.entered_at IS NOT NULL AND x.observed_at IS NULL
    AND x.owner->>'kind'='worker' AND x.owner->>'outboxId'=OLD.id::text AND x.owner->>'sendAttemptId'=OLD.current_send_attempt_id::text AND x.owner->>'workerId'=OLD.locked_by
  UNION ALL
  SELECT x.id,'sealed_z08' FROM gridex_outbound_dispatch.attempts x
   JOIN gridex_outbound_dispatch.reservations r ON r.message_id=x.message_id AND r.attempt_id=x.id AND r.state='provider_call_entered'
   WHERE x.company_id=OLD.company_id AND x.environment=OLD.environment AND x.message_id=OLD.ediel_message_id
    AND x.owner->>'kind'='worker' AND x.owner->>'outboxId'=OLD.id::text AND x.owner->>'sendAttemptId'=OLD.current_send_attempt_id::text AND x.owner->>'workerId'=OLD.locked_by
    AND EXISTS(SELECT FROM gridex_outbound_dispatch.events e WHERE e.attempt_id=x.id AND e.message_id=x.message_id AND e.company_id=x.company_id AND e.environment=x.environment AND e.kind='provider_call_entered')
    AND NOT EXISTS(SELECT FROM gridex_outbound_dispatch.events e WHERE e.attempt_id=x.id AND e.message_id=x.message_id AND e.company_id=x.company_id AND e.environment=x.environment AND e.kind='provider_result')
 LOOP
  PERFORM gridex_ediel_transport.open_reconciliation_case_v1(a.lane,a.id,'entry_unresolved_after_lease','worker_claim_uncertain',OLD.id);
 END LOOP;
 RETURN NEW;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_transport.reconciliation_worker_uncertain_v1() FROM PUBLIC,anon,authenticated,service_role;

-- canonical:783
--
-- Name: record_dsn_v1(jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.record_dsn_v1(p_input jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE c uuid:=(p_input->>'companyId')::uuid;actor uuid:=(p_input->>'actorUserId')::uuid;mailid uuid:=(p_input->>'inboundEmailMessageId')::uuid;
 mail public.inbound_email_messages%rowtype;mb public.ediel_mailboxes%rowtype;body text;field text:=p_input->>'sourceField';attachment uuid:=(p_input->>'attachmentId')::uuid;
 report jsonb:=p_input->'report';recipient jsonb;sourcehash text;candidate jsonb;candidates jsonb;obs gridex_ediel_transport.dsn_observations%rowtype;
BEGIN
 PERFORM 1 FROM public.user_profiles u WHERE u.id=actor FOR SHARE;
 PERFORM 1 FROM public.company_memberships m WHERE m.company_id=c AND m.user_id=actor FOR SHARE;
 IF c IS NULL OR actor IS NULL OR mailid IS NULL OR field IS NULL OR field NOT IN('raw_email','body_text','attachment')
  OR NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=c AND m.user_id=actor AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL)
  OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=actor AND u.user_status='active') OR NOT coalesce(public.gridex_actor_has_company_permission(actor,c,'communication.read'),false) THEN RAISE EXCEPTION 'ediel_dsn_actor_scope_invalid' USING ERRCODE='42501';END IF;
 SELECT * INTO mail FROM public.inbound_email_messages WHERE id=mailid AND company_id=c FOR UPDATE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_dsn_mail_scope_invalid';END IF;
 SELECT * INTO mb FROM public.ediel_mailboxes WHERE id=coalesce(nullif(to_jsonb(mail)->>'ediel_mailbox_id','')::uuid,nullif(to_jsonb(mail)->>'mailbox_id','')::uuid) FOR SHARE;
 IF NOT FOUND OR NOT mb.is_active OR mb.environment NOT IN('test','production') OR mb.company_id IS DISTINCT FROM c AND NOT(mb.company_id IS NULL AND mb.is_shared_platform_mailbox)
  OR to_jsonb(mail)->>'environment' IS NOT NULL AND to_jsonb(mail)->>'environment' IS DISTINCT FROM mb.environment THEN RAISE EXCEPTION 'ediel_dsn_mailbox_scope_invalid';END IF;
 IF field='attachment' THEN
  SELECT a.raw_text INTO body FROM public.inbound_email_attachments a WHERE a.id=attachment AND a.inbound_email_message_id=mailid FOR SHARE;
 ELSE
  IF attachment IS NOT NULL THEN RAISE EXCEPTION 'ediel_dsn_source_invalid';END IF;
  body:=to_jsonb(mail)->>field;
 END IF;
 sourcehash:=encode(sha256(convert_to(body,'UTF8')),'hex');
 IF body IS NULL OR octet_length(body)>26214400 OR sourcehash IS DISTINCT FROM p_input->>'sourceHash' OR jsonb_typeof(report) IS DISTINCT FROM 'object' OR octet_length(report::text)>262144
  OR report->>'version' IS DISTINCT FROM '1' OR report->>'transportCorrelation' IS DISTINCT FROM 'unverified' OR report->'issues' IS DISTINCT FROM '[]'::jsonb
  OR jsonb_typeof(report->'originalMessageIds') IS DISTINCT FROM 'array' OR jsonb_array_length(report->'originalMessageIds')<>1
  OR jsonb_typeof(report->'recipients') IS DISTINCT FROM 'array' OR jsonb_array_length(report->'recipients')<>1 THEN RAISE EXCEPTION 'ediel_dsn_source_invalid';END IF;
 recipient:=report->'recipients'->0;
 IF recipient->>'action' IS NULL OR recipient->>'action' NOT IN('failed','delayed','delivered','relayed','expanded') OR coalesce(recipient->>'status','')!~'^[245]\.[0-9]{1,3}\.[0-9]{1,3}$'
  OR left(recipient->>'status',1) IS DISTINCT FROM (CASE recipient->>'action' WHEN 'failed' THEN '5' WHEN 'delayed' THEN '4' ELSE '2' END)
  OR recipient#>>'{finalRecipient,type}' IS NULL OR recipient#>>'{finalRecipient,type}' NOT IN('rfc822','utf-8')
  OR coalesce(recipient#>>'{finalRecipient,address}','')!~'^[^[:space:]<>@]+@[^[:space:]<>@]+$'
  OR NOT gridex_ediel_transport.dsn_source_identity_matches_v1(body,report) THEN RAISE EXCEPTION 'ediel_dsn_source_invalid';END IF;
 candidates:=gridex_ediel_transport.dsn_candidates_v1(c,mb.environment,report#>>'{originalMessageIds,0}',recipient#>>'{finalRecipient,address}',mb.id);
 IF jsonb_array_length(candidates)<>1 THEN RAISE EXCEPTION 'ediel_dsn_attempt_ambiguous_or_missing';END IF;
 candidate:=candidates->0;
 SELECT * INTO obs FROM gridex_ediel_transport.dsn_observations WHERE inbound_email_message_id=mailid AND source_field=field AND source_sha256=sourcehash AND attempt_id=(candidate->>'attemptId')::uuid AND lane=candidate->>'lane';
 IF FOUND THEN
  IF obs.company_id IS DISTINCT FROM c OR obs.environment IS DISTINCT FROM mb.environment OR obs.attachment_id IS DISTINCT FROM attachment OR obs.report IS DISTINCT FROM report THEN RAISE EXCEPTION 'ediel_dsn_observation_immutable';END IF;
 ELSE
  IF EXISTS(SELECT FROM gridex_ediel_transport.dsn_observations o WHERE o.inbound_email_message_id=mailid AND o.source_field=field AND o.attachment_id IS NOT DISTINCT FROM attachment AND o.source_sha256<>sourcehash) THEN RAISE EXCEPTION 'ediel_dsn_observation_source_changed';END IF;
  INSERT INTO gridex_ediel_transport.dsn_observations(inbound_email_message_id,company_id,environment,mailbox_id,message_id,attempt_id,lane,source_field,attachment_id,source_sha256,report,report_sha256)
   VALUES(mailid,c,mb.environment,mb.id,(candidate->>'messageId')::uuid,(candidate->>'attemptId')::uuid,candidate->>'lane',field,attachment,sourcehash,report,encode(sha256(convert_to(report::text,'UTF8')),'hex')) RETURNING * INTO obs;
 END IF;
 RETURN jsonb_build_object('version',1,'observationId',obs.id,'attemptId',obs.attempt_id,'messageId',obs.message_id,'sourceHash',obs.source_sha256,'observedAt',obs.observed_at,'transportCorrelation','source_matched_unverified','authorizesResend',false,'deliveryProven',false);
END $_$;

REVOKE ALL ON FUNCTION gridex_ediel_transport.record_dsn_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:784
--
-- Name: repair_before_method_watch_v1(uuid, text, uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.repair_before_method_watch_v1(p_company_id uuid, p_environment text, p_actor_user_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE projection jsonb; source_projection jsonb;
BEGIN
 projection:=gridex_ediel_transport.repair_message_projection_v1(p_company_id,p_environment,p_actor_user_id,p_message_id);
 IF projection IS NULL THEN RETURN NULL;END IF;
 source_projection:=public.ediel_project_accepted_source_state_v1(p_company_id,p_environment,p_actor_user_id,p_message_id,projection->>'originalHash');
 IF source_projection->>'status' IS DISTINCT FROM 'source_projection'
  OR source_projection->>'companyId' IS DISTINCT FROM projection->>'companyId'
  OR source_projection->>'environment' IS DISTINCT FROM projection->>'environment'
  OR source_projection->>'messageId' IS DISTINCT FROM projection->>'messageId'
  OR source_projection->>'originalHash' IS DISTINCT FROM projection->>'originalHash'
  OR (source_projection->>'observedAt')::timestamptz IS DISTINCT FROM (projection->>'observedAt')::timestamptz
  THEN RAISE EXCEPTION 'ediel_accepted_projection_source_changed';END IF;
 RETURN projection;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_transport.repair_before_method_watch_v1(uuid, text, uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:785
--
-- Name: repair_message_projection_v1(uuid, text, uuid, uuid); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.repair_message_projection_v1(p_company_id uuid, p_environment text, p_actor_user_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype; projection jsonb; resulting_status text;
BEGIN
 IF p_company_id IS NULL OR p_actor_user_id IS NULL OR p_message_id IS NULL OR (p_environment IN ('test','production')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_accepted_projection_scope_required';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL) OR (public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel.send') OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.send')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_accepted_projection_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE company_id=p_company_id AND environment=p_environment AND id=p_message_id AND direction='outbound' FOR UPDATE;
 projection:=public.gridex_ediel_accepted_transport_projection_v1(p_company_id,p_environment,p_actor_user_id,p_message_id);
 IF projection IS NULL THEN RETURN NULL;END IF;
 UPDATE public.ediel_messages SET
  status=CASE WHEN status IN ('draft','prepared','queued','dispatching','provider_accepted','sent') THEN 'sent' ELSE status END,
  processing_status=CASE WHEN processing_status IS NULL OR processing_status IN ('draft','prepared','queued','dispatching','provider_accepted','sent') THEN 'sent' ELSE processing_status END,
  message_sent_at=(projection->>'observedAt')::timestamptz,updated_by=p_actor_user_id,updated_at=now()
 WHERE id=p_message_id AND company_id=p_company_id AND environment=p_environment RETURNING status INTO resulting_status;
 RETURN projection||jsonb_build_object('projectionStatus',resulting_status);
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_transport.repair_message_projection_v1(uuid, text, uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:786
--
-- Name: require_message_intent_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.require_message_intent_v1(m public.ediel_messages) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE i public.ediel_message_intents%rowtype;p public.ediel_message_profiles%rowtype;r public.ediel_rule_packs%rowtype;
 route public.communication_routes%rowtype;profile public.ediel_route_profiles%rowtype;point public.metering_points%rowtype;
 tokens jsonb;unb jsonb;unh jsonb;bgm jsonb;physical_points text[];
BEGIN
 -- Prescribed technical/application ACKs keep their own exact source owner;
 -- ordinary P/U messages, including test fixtures, require their own intent.
 IF m.direction IS DISTINCT FROM 'outbound' OR (m.message_family IN('PRODAT','UTILTS')) IS NOT TRUE THEN RETURN;END IF;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=m.intent_id AND company_id=m.company_id FOR SHARE;
 SELECT * INTO p FROM public.ediel_message_profiles WHERE id=m.rule_profile_version_id FOR SHARE;
 SELECT * INTO r FROM public.ediel_rule_packs WHERE id=m.canonical_rule_pack_id FOR SHARE;
 SELECT * INTO route FROM public.communication_routes WHERE id=m.communication_route_id FOR SHARE;
 SELECT * INTO profile FROM public.ediel_route_profiles WHERE id=m.route_profile_id FOR SHARE;
 IF i.id IS NULL OR i.environment IS DISTINCT FROM m.environment OR i.market IS DISTINCT FROM 'electricity' OR i.message_family IS DISTINCT FROM m.message_family OR i.message_code IS DISTINCT FROM m.message_code
  OR (i.direction IN('outbound','inbound_response')) IS NOT TRUE OR i.validation_status IS DISTINCT FROM 'validated' OR i.validation_result->>'ok' IS DISTINCT FROM 'true' OR i.validation_result->>'status' IS DISTINCT FROM 'validated' OR i.blocking_reasons IS DISTINCT FROM '[]'::jsonb
  OR i.ediel_message_id IS DISTINCT FROM m.id OR i.outbound_request_id IS DISTINCT FROM m.outbound_request_id OR i.route_profile_id IS DISTINCT FROM m.route_profile_id OR i.communication_route_id IS DISTINCT FROM m.communication_route_id
  OR i.customer_id IS DISTINCT FROM m.customer_id OR i.customer_site_id IS DISTINCT FROM m.site_id OR i.supplier_switch_request_id IS DISTINCT FROM m.switch_request_id
  OR route.id IS NULL OR profile.id IS NULL OR (route.company_id IS NOT NULL AND route.company_id IS DISTINCT FROM m.company_id) OR (profile.company_id IS NOT NULL AND profile.company_id IS DISTINCT FROM m.company_id)
  OR route.is_active IS DISTINCT FROM true OR profile.is_enabled IS DISTINCT FROM true OR profile.environment IS DISTINCT FROM m.environment OR profile.communication_route_id IS DISTINCT FROM route.id
  OR p.id IS NULL OR p.is_enabled IS DISTINCT FROM true OR p.rule_pack_id IS DISTINCT FROM r.id OR p.message_code IS DISTINCT FROM m.message_code OR r.family IS DISTINCT FROM m.message_family
  OR (i.expected_rule_version IS NOT NULL AND i.expected_rule_version IS DISTINCT FROM m.rule_profile_version) OR (i.expected_field_matrix_version IS NOT NULL AND i.expected_field_matrix_version IS DISTINCT FROM r.field_matrix_version)
  OR (i.payload->>'transactionSubtype' IS NOT NULL AND i.payload->>'transactionSubtype' IS DISTINCT FROM p.transaction_subtype) THEN RAISE EXCEPTION 'ediel_native_validated_intent_required';END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(m.raw_payload);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNB')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM')<>1 THEN RAISE EXCEPTION 'ediel_native_intent_wire_required';END IF;
 SELECT t INTO unb FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNB';SELECT t INTO unh FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH';SELECT t INTO bgm FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='BGM';
 IF unh#>>'{elements,2,0}' IS DISTINCT FROM i.message_family OR bgm#>>'{elements,1,0}' IS DISTINCT FROM i.message_code
  OR unh#>>'{elements,1,0}' IS DISTINCT FROM i.message_reference OR unb#>>'{elements,5,0}' IS DISTINCT FROM i.interchange_reference OR unb#>>'{elements,7,0}' IS DISTINCT FROM i.application_reference
  OR unb#>>'{elements,2,0}' IS DISTINCT FROM i.sender_ediel_id OR unb#>>'{elements,3,0}' IS DISTINCT FROM i.receiver_ediel_id
  OR nullif(unb#>>'{elements,2,2}','') IS DISTINCT FROM nullif(i.sender_subaddress,'') OR nullif(unb#>>'{elements,3,2}','') IS DISTINCT FROM nullif(i.receiver_subaddress,'')
  OR (i.transaction_reference IS NOT NULL AND NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE (t->>'tag'='RFF' AND t#>>'{elements,1,0}'='LI' AND t#>>'{elements,1,1}'=i.transaction_reference) OR (t->>'tag'='IDE' AND t#>>'{elements,2,0}'=i.transaction_reference))) THEN RAISE EXCEPTION 'ediel_native_intent_wire_scope_changed';END IF;
 IF m.metering_point_id IS NOT NULL THEN
  SELECT * INTO point FROM public.metering_points WHERE id=m.metering_point_id AND company_id=m.company_id FOR SHARE;
  IF point.id IS NULL OR nullif(i.metering_point_id,'') IS NULL OR point.customer_id IS DISTINCT FROM m.customer_id OR point.site_id IS DISTINCT FROM m.site_id
   OR (i.metering_point_id IS DISTINCT FROM point.id::text AND i.metering_point_id IS DISTINCT FROM point.meter_point_id AND i.metering_point_id IS DISTINCT FROM point.ediel_metering_point_id)
   OR (i.grid_area_code IS NOT NULL AND i.grid_area_code IS DISTINCT FROM point.grid_area_code) THEN RAISE EXCEPTION 'ediel_native_intent_owned_point_required';END IF;
  SELECT array_agg(DISTINCT t#>>'{elements,3,0}') INTO physical_points FROM jsonb_array_elements(tokens)t WHERE t->>'tag' IN('LIN','LOC') AND t#>>'{elements,3,0}' IS NOT NULL;
  IF m.message_family='PRODAT' AND physical_points IS NOT NULL AND (cardinality(physical_points)<>1 OR (physical_points[1] IS DISTINCT FROM point.meter_point_id AND physical_points[1] IS DISTINCT FROM point.ediel_metering_point_id)) THEN RAISE EXCEPTION 'ediel_native_intent_physical_point_scope_changed';END IF;
 ELSIF i.metering_point_id IS NOT NULL THEN RAISE EXCEPTION 'ediel_native_intent_owned_point_required';END IF;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_transport.require_message_intent_v1(public.ediel_messages) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:787
--
-- Name: require_technical_expectation_binding_v1(public.ediel_messages, jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.require_technical_expectation_binding_v1(m public.ediel_messages, p_binding jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE plan jsonb;admission jsonb;
BEGIN
 plan:=gridex_ediel_transport.require_technical_expectation_plan_v1(m,p_binding->'technicalExpectationPlan');
 IF plan IS NULL THEN RETURN p_binding;END IF;admission:=p_binding->'admissionDecision';
 IF jsonb_typeof(admission) IS DISTINCT FROM 'object' OR admission->>'version' IS DISTINCT FROM '1' OR admission->>'family' IS DISTINCT FROM m.message_family OR admission->>'code' IS DISTINCT FROM gridex_ediel_transport.canonical_message_code_v1(m.message_family,m.message_code)
  OR plan->'policy' IS DISTINCT FROM jsonb_build_object('guideRevision',admission#>'{guide,guideRevision}','referenceDate',admission->'referenceDate','profileKey',admission->'profileKey','sourceTrace',admission->'sourceTrace') THEN RAISE EXCEPTION 'ediel_technical_expectation_same_admission_required';END IF;
 RETURN p_binding;
END $$;

REVOKE ALL ON FUNCTION gridex_ediel_transport.require_technical_expectation_binding_v1(public.ediel_messages, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:788
--
-- Name: require_technical_expectation_plan_v1(public.ediel_messages, jsonb); Type: FUNCTION; Schema: gridex_ediel_transport; Owner: -
--

CREATE FUNCTION gridex_ediel_transport.require_technical_expectation_plan_v1(m public.ediel_messages, p_plan jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE projection jsonb;cfg jsonb;rule jsonb;expected_profile jsonb;basis jsonb;r jsonb;scope jsonb;policy jsonb;v text;reference_date date;
BEGIN
 SELECT e.projection INTO STRICT projection FROM gridex_ediel_transport.technical_expectation_editions e WHERE source_version='05abbd87fb53e2a4e5e0583741e4dad6fed9f525010420e93c12e9b5c3dfda98';cfg:=projection->'constraints';
 IF m.direction IS DISTINCT FROM 'outbound' OR m.company_id IS NULL OR (m.environment IS NULL OR m.environment NOT IN('test','production')) THEN RAISE EXCEPTION 'ediel_technical_expectation_source_scope_required';END IF;
 IF m.message_family='AI_LIST' THEN IF p_plan IS NOT NULL AND p_plan<>'null'::jsonb THEN RAISE EXCEPTION 'ediel_technical_expectation_not_applicable';END IF;RETURN NULL;END IF;
 SELECT x INTO rule FROM jsonb_array_elements(projection->'ackMatrix')x WHERE x->>'family'=m.message_family AND x->>'code' IN(gridex_ediel_transport.canonical_message_code_v1(m.message_family,m.message_code),'*') ORDER BY(x->>'code'='*') LIMIT 1;
 IF rule IS NULL THEN RAISE EXCEPTION 'ediel_technical_expectation_unknown_family';END IF;
 IF rule->>'technicalAck'='none' THEN IF p_plan IS NOT NULL AND p_plan<>'null'::jsonb THEN RAISE EXCEPTION 'ediel_technical_expectation_not_applicable';END IF;RETURN NULL;END IF;
 IF jsonb_typeof(p_plan) IS DISTINCT FROM 'object' OR p_plan-'policy' IS DISTINCT FROM cfg OR jsonb_typeof(p_plan->'policy') IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'ediel_technical_expectation_source_plan_required';END IF;
 policy:=p_plan->'policy';
 IF (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(policy)k) IS DISTINCT FROM ARRAY['guideRevision','profileKey','referenceDate','sourceTrace']::text[] OR jsonb_typeof(policy->'guideRevision') IS DISTINCT FROM 'string' OR nullif(policy->>'guideRevision','') IS NULL OR jsonb_typeof(policy->'referenceDate') IS DISTINCT FROM 'string' OR coalesce(policy->>'referenceDate','')!~'^[0-9]{4}-[0-9]{2}-[0-9]{2}$' OR jsonb_typeof(policy->'sourceTrace') IS DISTINCT FROM 'array' OR jsonb_array_length(policy->'sourceTrace')=0 THEN RAISE EXCEPTION 'ediel_technical_expectation_policy_required';END IF;
 BEGIN reference_date:=(policy->>'referenceDate')::date;EXCEPTION WHEN OTHERS THEN RAISE EXCEPTION 'ediel_technical_expectation_reference_date_invalid';END;
 IF reference_date::text IS DISTINCT FROM policy->>'referenceDate' OR extract(year FROM reference_date)<=0 THEN RAISE EXCEPTION 'ediel_technical_expectation_reference_date_invalid';END IF;
 SELECT x INTO expected_profile FROM jsonb_array_elements(projection->'profiles')x WHERE x->>'family'=m.message_family AND x->>'code'=gridex_ediel_transport.canonical_message_code_v1(m.message_family,m.message_code);
 IF expected_profile IS NULL OR policy->'profileKey' IS DISTINCT FROM expected_profile->'profileKey' THEN RAISE EXCEPTION 'ediel_technical_expectation_canonical_profile_required';END IF;
 IF m.execution_context_snapshot->>'prodatCommonHeaderNegativeWitnessId' IS NOT NULL THEN basis:=gridex_ediel_common_header.require_ack_v1(m);r:=basis#>'{familyEdition,rulePack}';v:=basis#>>'{familyEdition,version}';
 ELSE basis:=gridex_ediel_source_rules.require_v1(m.company_id,m.id);r:=basis#>'{snapshot,rulePack}';v:=basis->>'version';END IF;
 SELECT x INTO scope FROM jsonb_array_elements(projection->'scopes')x WHERE x->>'family'=r->>'family' AND x->>'guideVersion'=r->>'guide_version' AND x->>'guideRevision'=r->>'guide_revision' ;
 IF nullif(v,'') IS NULL OR (basis->>'kind' IS DISTINCT FROM 'prodat_common_header_rejection' AND basis#>>'{snapshot,version}' IS DISTINCT FROM v) OR scope IS NULL OR policy->>'guideRevision' IS DISTINCT FROM scope->>'canonicalGuideRevision' THEN RAISE EXCEPTION 'ediel_technical_expectation_original_guide_required';END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(policy->'sourceTrace')x WHERE jsonb_typeof(x) IS DISTINCT FROM 'object' OR (SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(x)k) IS DISTINCT FROM ARRAY['authority','document','section']::text[] OR jsonb_typeof(x->'authority') IS DISTINCT FROM 'string' OR nullif(x->>'authority','') IS NULL OR jsonb_typeof(x->'document') IS DISTINCT FROM 'string' OR nullif(x->>'document','') IS NULL OR jsonb_typeof(x->'section') IS DISTINCT FROM 'string' OR nullif(x->>'section','') IS NULL)
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(policy->'sourceTrace')x WHERE x->>'authority'='guide' AND x->>'document'=scope->>'documentName')
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(policy->'sourceTrace')x WHERE x->>'authority'='acknowledgement' AND x->>'document'=scope->>'documentName') THEN RAISE EXCEPTION 'ediel_technical_expectation_source_trace_required';END IF;
 RETURN p_plan;
END $_$;

REVOKE ALL ON FUNCTION gridex_ediel_transport.require_technical_expectation_plan_v1(public.ediel_messages, jsonb) FROM PUBLIC,anon,authenticated,service_role;

