--
-- Name: require_service_v1(); Type: FUNCTION; Schema: gridex_prodat_object_batch; Owner: -
--

CREATE FUNCTION gridex_prodat_object_batch.require_service_v1() RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'prodat_object_batch_service_required' USING ERRCODE='42501';END IF;
END $$;

