-- canonical:887
--
-- Name: require_wire_projection_v1(text, jsonb, jsonb, text, uuid); Type: FUNCTION; Schema: gridex_prodat_object_batch; Owner: -
--

CREATE FUNCTION gridex_prodat_object_batch.require_wire_projection_v1(raw text, own jsonb, command jsonb, mode text, actor uuid) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(raw);raw_parts jsonb:=gridex_prodat_object_batch.raw_segments_v1(raw);t jsonb;e jsonb;first_index int:=(own#>>'{registers,0,segmentIndex}')::int;next_index int;
 ud jsonb;it jsonb;qty text;start_day text;frequency text;product text;reference text;area text;grid_id uuid;characteristic text;name text;personal text;org text;is_business bool;key text;expected jsonb;field_value jsonb;reg jsonb;wire_reg jsonb;reg_end int;reg_raw jsonb;reg_qty text;BEGIN
 IF tokens IS NULL THEN RAISE EXCEPTION 'prodat_object_batch_physical_projection_required';END IF;
 SELECT min((x->>'index')::int) INTO next_index FROM jsonb_array_elements(tokens)x WHERE x->>'tag' IN('LIN','UNT') AND (x->>'index')::int>first_index;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE (x->>'index')::int>first_index AND (x->>'index')::int<next_index ORDER BY(x->>'index')::int LOOP
  e:=t->'elements';
  IF t->>'tag'='NAD' AND e#>>'{1,0}'='UD' THEN ud:=e;ELSIF t->>'tag'='NAD' AND e#>>'{1,0}'='IT' THEN it:=e;
  ELSIF t->>'tag'='QTY' AND e#>>'{1,0}'='31' THEN qty:=e#>>'{1,1}';
  ELSIF t->>'tag'='DTM' AND e#>>'{1,0}'='92' THEN start_day:=e#>>'{1,1}';
  ELSIF t->>'tag'='RFF' AND e#>>'{1,0}'='Z07' THEN reference:=e#>>'{1,1}';
  ELSIF t->>'tag'='RFF' AND e#>>'{1,0}'='Z05' THEN area:=e#>>'{1,1}';
  ELSIF t->>'tag'='CCI' THEN characteristic:=e#>>'{2,0}';
  ELSIF t->>'tag'='CAV' AND characteristic='Z12' THEN frequency:=e#>>'{1,3}';
  ELSIF t->>'tag'='CAV' AND characteristic='Z14' THEN product:=e#>>'{1,3}';END IF;
 END LOOP;
 FOR reg IN SELECT value FROM jsonb_array_elements(command#>'{application,payload_snapshot,prodatRegisters}') LOOP
  SELECT x INTO wire_reg FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='LIN' AND x#>>'{elements,1,0}'=reg->>'lineSequenceNumber';
  SELECT min((x->>'index')::int) INTO reg_end FROM jsonb_array_elements(tokens)x WHERE x->>'tag' IN('LIN','UNT') AND (x->>'index')::int>(wire_reg->>'index')::int;
  SELECT jsonb_agg(raw_parts->((x->>'index')::int) ORDER BY(x->>'index')::int) INTO reg_raw FROM jsonb_array_elements(tokens)x WHERE (x->>'index')::int>=(wire_reg->>'index')::int AND(x->>'index')::int<reg_end;
  SELECT btrim(x#>>'{elements,1,1}') INTO reg_qty FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='QTY' AND x#>>'{elements,1,0}'='31' AND(x->>'index')::int>(wire_reg->>'index')::int AND(x->>'index')::int<reg_end;
  IF wire_reg IS NULL OR wire_reg#>>'{elements,3,0}' IS DISTINCT FROM own->>'objectId' OR wire_reg#>>'{elements,3,3}' IS DISTINCT FROM own->>'identityAgency'
   OR reg->>'meteringPointId' IS DISTINCT FROM own->>'objectId' OR reg->>'identityAgency' IS DISTINCT FROM own->>'identityAgency'
   OR reg->'rawSegments' IS DISTINCT FROM reg_raw OR reg->>'annualConsumption' IS DISTINCT FROM reg_qty OR reg->>'registerIndex' IS DISTINCT FROM nullif(wire_reg#>>'{elements,4,1}','')
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(own->'registers')r WHERE r->'lineIndex'=reg->'sourceOrder' AND r->>'lineNumber'=reg->>'lineSequenceNumber' AND r->'segmentIndex'=wire_reg->'index') THEN RAISE EXCEPTION 'prodat_object_batch_physical_register_required';END IF;
 END LOOP;
 IF mode='link_existing_only' THEN
  IF command->'customer'<>'{}'::jsonb OR command->'site' IS DISTINCT FROM jsonb_build_object('facility_id',own->>'objectId') OR command->'metering_point' IS DISTINCT FROM jsonb_build_object('meter_point_id',own->>'objectId') OR command->'update_existing' IS DISTINCT FROM 'false'::jsonb THEN RAISE EXCEPTION 'prodat_object_batch_link_identity_only_required';END IF;RETURN;
 END IF;
 IF area IS NOT NULL THEN SELECT id INTO grid_id FROM public.grid_owners WHERE company_id=(command->>'company_id')::uuid AND owner_code=area FOR SHARE;
  IF (SELECT count(*) FROM public.grid_owners WHERE company_id=(command->>'company_id')::uuid AND owner_code=area)>1 THEN RAISE EXCEPTION 'prodat_object_batch_grid_namespace_ambiguous';END IF;END IF;
 IF command#>'{site,grid_owner_id}' IS NOT NULL AND command#>'{site,grid_owner_id}' IS DISTINCT FROM coalesce(to_jsonb(grid_id::text),'null'::jsonb) OR command#>'{metering_point,grid_owner_id}' IS NOT NULL AND command#>'{metering_point,grid_owner_id}' IS DISTINCT FROM coalesce(to_jsonb(grid_id::text),'null'::jsonb) THEN RAISE EXCEPTION 'prodat_object_batch_wire_grid_owner_required';END IF;
 SELECT string_agg(btrim(v#>>'{}'),E'\n' ORDER BY ord) INTO name FROM jsonb_array_elements(coalesce(ud->4,'[]')) WITH ORDINALITY n(v,ord) WHERE ord<=2 AND btrim(v#>>'{}')<>'';
 is_business:=ud#>>'{2,1}'='SE1';
 IF ud#>>'{2,0}'~'^[0-9]+([-+][0-9]+)?$' THEN
  IF ud#>>'{2,1}'='SE1' THEN org:=regexp_replace(ud#>>'{2,0}','[^0-9]','','g');ELSIF ud#>>'{2,1}'='SE2' THEN personal:=regexp_replace(ud#>>'{2,0}','[^0-9]','','g');END IF;
 END IF;
 expected:=jsonb_build_object('customer_type',CASE WHEN is_business THEN 'business' ELSE 'private' END,'full_name',coalesce(name,'Ediel inbound-kund'),'company_name',CASE WHEN is_business THEN name END,
  'first_name',CASE WHEN NOT coalesce(is_business,false) THEN split_part(name,' ',1) END,'last_name',CASE WHEN NOT coalesce(is_business,false) THEN nullif(substr(name,strpos(name,' ')+1),name) END,'personal_number',personal,'org_number',org);
 FOR key,field_value IN SELECT * FROM jsonb_each(command->'customer') LOOP
  IF expected ? key AND field_value IS DISTINCT FROM expected->key THEN RAISE EXCEPTION 'prodat_object_batch_wire_customer_required';END IF;
  IF NOT(expected ? key) AND key NOT IN('status','source','metadata','created_by','updated_by') THEN RAISE EXCEPTION 'prodat_object_batch_customer_field_not_source_bound';END IF;
  IF key='status' AND field_value IS DISTINCT FROM '"draft"'::jsonb OR key='source' AND field_value IS DISTINCT FROM '"ediel_inbound"'::jsonb THEN RAISE EXCEPTION 'prodat_object_batch_customer_binding_required';END IF;
  IF key IN('created_by','updated_by') AND field_value IS DISTINCT FROM to_jsonb(actor::text) THEN RAISE EXCEPTION 'prodat_object_batch_actor_required';END IF;
 END LOOP;
 expected:=jsonb_build_object('site_name','Ediel '||(own->>'objectId'),'facility_id',own->>'objectId','site_type',CASE WHEN product='L641Q' THEN 'production' ELSE 'consumption' END,
  'street',CASE WHEN it IS NOT NULL THEN array_to_string(ARRAY(SELECT btrim(v#>>'{}') FROM jsonb_array_elements(it->5) WITH ORDINALITY a(v,ord) WHERE ord<=3 AND btrim(v#>>'{}')<>''),E'\n') END,
  'postal_code',nullif(it#>>'{8,0}',''),'city',nullif(it#>>'{6,0}',''),'country',coalesce(nullif(it#>>'{9,0}',''),'SE'),
  'annual_consumption_kwh',CASE WHEN qty IS NOT NULL THEN replace(qty,',','.')::numeric END,'move_in_date',CASE WHEN start_day IS NOT NULL THEN substr(start_day,1,4)||'-'||substr(start_day,5,2)||'-'||substr(start_day,7,2) END);
 FOR key,field_value IN SELECT * FROM jsonb_each(command->'site') LOOP
  IF expected ? key AND field_value IS DISTINCT FROM expected->key THEN RAISE EXCEPTION 'prodat_object_batch_wire_site_required';END IF;
  IF key='status' AND field_value IS DISTINCT FROM '"draft"'::jsonb OR key IN('created_by','updated_by') AND field_value IS DISTINCT FROM to_jsonb(actor::text) THEN RAISE EXCEPTION 'prodat_object_batch_actor_required';END IF;
  IF NOT(expected ? key) AND key NOT IN('status','grid_owner_id','internal_notes','created_by','updated_by') THEN RAISE EXCEPTION 'prodat_object_batch_site_field_not_source_bound';END IF;
 END LOOP;
 expected:=jsonb_build_object('meter_point_id',own->>'objectId','metering_point_id',own->>'objectId','site_facility_id',own->>'objectId','ediel_reference',reference,
  'measurement_type',CASE WHEN product='L641Q' THEN 'production' ELSE 'consumption' END,'reading_frequency',CASE frequency WHEN 'D' THEN 'daily' WHEN 'M' THEN 'monthly' ELSE 'hourly' END,
  'start_date',CASE WHEN start_day IS NOT NULL THEN substr(start_day,1,4)||'-'||substr(start_day,5,2)||'-'||substr(start_day,7,2) END,'is_settlement_relevant',true);
 FOR key,field_value IN SELECT * FROM jsonb_each(command->'metering_point') LOOP
  IF expected ? key AND field_value IS DISTINCT FROM expected->key THEN RAISE EXCEPTION 'prodat_object_batch_wire_meter_required';END IF;
  IF key='status' AND field_value IS DISTINCT FROM '"draft"'::jsonb OR key IN('created_by','updated_by') AND field_value IS DISTINCT FROM to_jsonb(actor::text) THEN RAISE EXCEPTION 'prodat_object_batch_actor_required';END IF;
  IF NOT(expected ? key) AND key NOT IN('status','grid_owner_id','created_by','updated_by') THEN RAISE EXCEPTION 'prodat_object_batch_meter_field_not_source_bound';END IF;
 END LOOP;
END $_$;

REVOKE ALL ON FUNCTION gridex_prodat_object_batch.require_wire_projection_v1(text, jsonb, jsonb, text, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:888
--
-- Name: source_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_prodat_object_batch; Owner: -
--

CREATE FUNCTION gridex_prodat_object_batch.source_v1(c uuid, source_id uuid, actor uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;s gridex_received_sources.sources%rowtype;a gridex_received_sources.validation_assessments%rowtype;
 f gridex_received_sources.prodat_object_validation_facets%rowtype;r gridex_received_sources.prodat_response_facets%rowtype;app jsonb;ctx jsonb;own jsonb;fullown jsonb;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 IF actor IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles WHERE id=actor AND user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships WHERE company_id=c AND user_id=actor AND status='active' AND is_active AND accepted_at IS NOT NULL)
  OR public.gridex_actor_has_company_permission(actor,c,'communication.write') IS NOT TRUE
  OR public.gridex_actor_has_company_permission(actor,c,'customers.write') IS NOT TRUE THEN RAISE EXCEPTION 'prodat_object_batch_current_actor_required' USING ERRCODE='42501';END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c FOR SHARE;
 SELECT * INTO s FROM gridex_received_sources.sources WHERE source_message_id=source_id AND company_id=c AND environment=m.environment FOR SHARE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.raw_payload IS NULL
  OR s.source_message_id IS NULL OR s.origin IS DISTINCT FROM 'database_insert' OR s.raw_payload IS DISTINCT FROM m.raw_payload
  OR s.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR s.message_code IS DISTINCT FROM m.message_code
  OR s.source_received_at IS NULL OR s.source_received_at IS DISTINCT FROM m.message_received_at
  OR s.received_context IS DISTINCT FROM m.execution_context_snapshot->'receivedProdatContext'
  OR s.received_context->>'contextOrigin' IS DISTINCT FROM 'database_insert' OR s.received_context->>'payloadHash' IS DISTINCT FROM s.payload_hash
  OR s.received_context->>'sourceMessageId' IS DISTINCT FROM m.id::text OR s.received_context->>'companyId' IS DISTINCT FROM c::text
  OR s.received_context->>'environment' IS DISTINCT FROM m.environment OR s.received_context->>'messageCode' IS DISTINCT FROM m.message_code
  OR (s.received_context->>'sourceReceivedAt')::timestamptz IS DISTINCT FROM s.source_received_at THEN RAISE EXCEPTION 'prodat_object_batch_immutable_original_required';END IF;
 ctx:=gridex_ediel_ack_replay.require_current_source_role_v2(c,m.environment,m.id);
 IF ctx->>'actorRole' IS DISTINCT FROM 'electricity_supplier' THEN RAISE EXCEPTION 'prodat_object_batch_current_receiver_role_required';END IF;
 app:=gridex_received_sources.require_prodat_application_objects_v1(c,m.id);
 SELECT * INTO a FROM gridex_received_sources.validation_assessments WHERE id=(app->>'assessmentId')::uuid AND company_id=c AND environment=m.environment AND source_message_id=m.id AND source_payload_hash=s.payload_hash FOR SHARE;
 SELECT * INTO f FROM gridex_received_sources.prodat_object_validation_facets WHERE assessment_id=a.id AND company_id=c AND environment=m.environment AND source_message_id=m.id AND source_payload_hash=s.payload_hash;
 SELECT * INTO r FROM gridex_received_sources.prodat_response_facets WHERE assessment_id=a.id AND company_id=c AND environment=m.environment AND source_message_id=m.id AND source_payload_hash=s.payload_hash;
 IF a.id IS NULL OR f.assessment_id IS NULL OR r.assessment_id IS NULL OR f.facts_hash IS DISTINCT FROM encode(sha256(convert_to(f.facts_text,'UTF8')),'hex')
  OR r.response_facts_hash IS DISTINCT FROM encode(sha256(convert_to(r.response_facts_text,'UTF8')),'hex') OR f.facts_text::jsonb->>'sharedAccepted' IS DISTINCT FROM 'true'
  OR a.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR a.facts_text::jsonb->>'functionalDecision' IS DISTINCT FROM 'accepted'
  OR app->>'headerDecision' IS DISTINCT FROM 'accepted' OR jsonb_array_length(app->'objects') NOT BETWEEN 2 AND 16
  OR jsonb_array_length(app->'objects') IS DISTINCT FROM jsonb_array_length(f.facts_text::jsonb->'objects') THEN RAISE EXCEPTION 'prodat_object_batch_complete_own_facets_required';END IF;
 FOR own IN SELECT value FROM jsonb_array_elements(app->'objects') LOOP
  SELECT value INTO fullown FROM jsonb_array_elements(f.facts_text::jsonb->'objects') WHERE value->>'objectId'=own->>'objectId' AND value->>'identityAgency'=own->>'identityAgency' AND value->>'messageReference'=own->>'messageReference' AND value->'firstLineIndex'=own#>'{registers,0,lineIndex}';
  IF own->>'applicationDecision' IS DISTINCT FROM 'accepted' OR fullown->>'disposition' IS DISTINCT FROM 'accepted'
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(r.response_facts_text::jsonb->'objects') o WHERE o->>'id'=own->>'objectId' AND o->>'li' IS NOT DISTINCT FROM fullown->>'lineItemReference' AND o->'lineIndex'=own#>'{registers,0,segmentIndex}' AND o->>'outcome'='positive')
   OR EXISTS(SELECT FROM jsonb_array_elements(r.response_facts_text::jsonb->'responses') o WHERE o->>'ercCode'<>'100' AND(o->>'scope'='message' OR o->'lineIndex'=own#>'{registers,0,segmentIndex}')) THEN RAISE EXCEPTION 'prodat_object_batch_own_accepted_partition_required';END IF;
 END LOOP;
 IF (SELECT count(DISTINCT o->>'objectId') FROM jsonb_array_elements(app->'objects')o)<>jsonb_array_length(app->'objects') THEN RAISE EXCEPTION 'prodat_object_batch_namespace_unsupported';END IF;
 RETURN jsonb_build_object('version',1,'sourceMessage',to_jsonb(m),'sourcePayloadHash',s.payload_hash,'assessmentId',a.id,'applicationValidation',app-'assessmentId');
END $$;

REVOKE ALL ON FUNCTION gridex_prodat_object_batch.source_v1(uuid, uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:889
--
-- Name: bind_final_v1(); Type: FUNCTION; Schema: gridex_received_err_response; Owner: -
--

CREATE FUNCTION gridex_received_err_response.bind_final_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;a jsonb;tx text;prior gridex_received_err_response.final_responses%rowtype;
BEGIN
 IF NEW.direction IS DISTINCT FROM 'outbound' OR NEW.message_family IS DISTINCT FROM 'APERAK' THEN RETURN NEW;END IF;
 SELECT * INTO source FROM public.ediel_messages WHERE id=NEW.related_message_id AND company_id=NEW.company_id AND environment=NEW.environment AND direction='inbound' FOR UPDATE;
 IF source.message_family IS DISTINCT FROM 'UTILTS_ERR' THEN RETURN NEW;END IF;
 PERFORM gridex_ediel_outbound_owner.require_positive_utilts_ack_v1(NEW,false);a:=gridex_ack_authority.wire_v1(NEW.raw_payload);
 FOR tx IN SELECT jsonb_array_elements_text(a#>'{refs,ACW}') LOOP
  SELECT * INTO prior FROM gridex_received_err_response.final_responses WHERE source_message_id=source.id AND transaction_id=tx;
  IF FOUND AND (prior.ack_message_id IS DISTINCT FROM NEW.id OR prior.ack_payload_hash IS DISTINCT FROM encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex')) THEN RAISE EXCEPTION 'utilts_err_application_response_final_scope_conflict' USING ERRCODE='23505';END IF;
  IF NOT FOUND THEN INSERT INTO gridex_received_err_response.final_responses(source_message_id,transaction_id,company_id,environment,ack_message_id,ack_payload_hash) VALUES(source.id,tx,NEW.company_id,NEW.environment,NEW.id,encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex'));END IF;
 END LOOP;
 RETURN NEW;
END $$;

REVOKE ALL ON FUNCTION gridex_received_err_response.bind_final_v1() FROM PUBLIC,anon,authenticated,service_role;

-- canonical:890
--
-- Name: capture_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_received_err_response; Owner: -
--

CREATE FUNCTION gridex_received_err_response.capture_v1(p_company uuid, p_environment text, p_source uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE c gridex_ack_authority.source_correlations%rowtype;m public.ediel_messages%rowtype;original public.ediel_messages%rowtype;
 captured gridex_received_sources.sources%rowtype;a gridex_received_sources.validation_assessments%rowtype;
 facts jsonb;evidence jsonb;expected jsonb;wire jsonb;source_wire jsonb;transactions jsonb;context jsonb;
BEGIN
 SELECT * INTO c FROM gridex_ack_authority.source_correlations WHERE ack_message_id=p_source;
 SELECT * INTO original FROM public.ediel_messages WHERE id=c.source_message_id FOR SHARE;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source AND company_id=p_company AND environment=p_environment AND direction='inbound' FOR UPDATE;
 IF EXISTS(SELECT FROM gridex_received_err_response.receipts WHERE source_message_id=p_source) THEN PERFORM gridex_received_err_response.require_v1(p_company,p_environment,p_source);RETURN;END IF;
 SELECT * INTO captured FROM gridex_received_sources.sources WHERE source_message_id=m.id;
 SELECT * INTO a FROM gridex_received_sources.validation_assessments WHERE id=c.canonical_assessment_id;
 wire:=gridex_ack_authority.wire_v1(m.raw_payload);source_wire:=gridex_ack_authority.wire_v1(original.raw_payload);
 IF m.id IS NULL OR m.message_family IS DISTINCT FROM 'UTILTS_ERR' OR m.message_standard IS DISTINCT FROM 'edifact' OR c.ack_family IS DISTINCT FROM 'UTILTS_ERR'
  OR c.company_id IS DISTINCT FROM p_company OR c.environment IS DISTINCT FROM p_environment OR c.ack_outcome IS DISTINCT FROM 'negative'
  OR original.id IS NULL OR original.company_id IS DISTINCT FROM p_company OR original.environment IS DISTINCT FROM p_environment OR original.direction IS DISTINCT FROM 'outbound'
  OR original.message_sent_at IS NULL OR original.immutable_rendered_at IS NULL OR c.source_payload_hash IS DISTINCT FROM original.immutable_payload_hash
  OR c.source_payload_hash IS DISTINCT FROM encode(sha256(convert_to(original.raw_payload,'UTF8')),'hex')
  OR c.ack_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR captured.raw_payload IS DISTINCT FROM m.raw_payload
  OR captured.company_id IS DISTINCT FROM p_company OR captured.environment IS DISTINCT FROM p_environment OR captured.payload_hash IS DISTINCT FROM c.ack_payload_hash OR captured.received_context IS NULL
  OR a.id IS NULL OR a.source_message_id IS DISTINCT FROM m.id OR a.company_id IS DISTINCT FROM p_company OR a.environment IS DISTINCT FROM p_environment OR a.source_payload_hash IS DISTINCT FROM c.ack_payload_hash
  OR a.owner IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR a.facts_hash IS DISTINCT FROM encode(sha256(convert_to(a.facts_text,'UTF8')),'hex')
  OR a.xmin::text::numeric=mod(pg_current_xact_id()::text::numeric,4294967296)
  OR wire IS NULL OR wire->>'family' IS DISTINCT FROM 'UTILTS' OR wire->>'code' IS DISTINCT FROM 'ERR' OR NOT coalesce(gridex_ack_authority.source_match_v1(wire,source_wire),false)
 THEN RAISE EXCEPTION 'utilts_err_application_response_authority_unavailable';END IF;
 facts:=a.facts_text::jsonb;evidence:=gridex_ediel_source_rules.require_v1(p_company,original.id);
 expected:=jsonb_build_object('profileKey',evidence->'profileKey','messageProfileId',evidence->'messageProfileId','rulePackId',evidence->'rulePackId','sourceHash',evidence->'sourceHash','version',evidence->'version',
  'snapshot',jsonb_build_object('rulePack',evidence#>'{snapshot,rulePack}','messageProfile',evidence#>'{snapshot,messageProfile}','guideSources',evidence#>'{snapshot,guideSources}'));
 IF facts->>'owner' IS DISTINCT FROM 'canonical-runtime-with-registry-v1' OR facts->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR facts->>'applicationDecision' IS DISTINCT FROM 'accepted'
  OR facts->>'functionalDecision' IS DISTINCT FROM 'accepted' OR facts->'rulePackEvidence' IS DISTINCT FROM expected
  OR jsonb_typeof(wire->'ide') IS DISTINCT FROM 'array' OR jsonb_array_length(wire->'ide')=0
  OR EXISTS(SELECT FROM jsonb_array_elements_text(wire->'ide')t WHERE nullif(t,'') IS NULL)
  OR (SELECT count(*) FROM jsonb_array_elements_text(wire->'ide'))<>(SELECT count(DISTINCT t) FROM jsonb_array_elements_text(wire->'ide')t)
 THEN RAISE EXCEPTION 'utilts_err_application_response_authority_unavailable';END IF;
 SELECT jsonb_agg(jsonb_build_object('transactionIndex',n-1,'transactionId',t) ORDER BY n) INTO transactions FROM jsonb_array_elements_text(wire->'ide') WITH ORDINALITY x(t,n);
 -- The source's actual local outbound endpoint already had an immutable legal
 -- authority. Full physical reversal was proved by the correlation owner;
 -- this does not choose a current role or change the held receipt at insertion.
 context:=gridex_ediel_inbound_context.require_v1(p_company,original.id);
 IF context->>'transportEdielId' IS DISTINCT FROM wire#>>'{receiver,0}' OR context->>'legalEdielId' IS DISTINCT FROM wire->>'legalReceiver'
  OR context->>'applicationReference' IS DISTINCT FROM wire->>'app' THEN RAISE EXCEPTION 'utilts_err_application_response_authority_unavailable';END IF;
 context:=context||jsonb_build_object('basisKind','accepted_received_err_application','companyId',p_company,'environment',p_environment,'direction','inbound',
  'family','UTILTS_ERR','code','ERR','wireFamily','UTILTS','wireCode','ERR','observedAt',c.correlated_at,'sourceReceivedAt',m.message_received_at,
  'correlatedOriginalMessageId',original.id,'canonicalAssessmentId',a.id,'sourceHash',c.ack_payload_hash,'authorizesBusinessEffect',false);
 INSERT INTO gridex_received_err_response.receipts VALUES(m.id,p_company,p_environment,c.ack_payload_hash,a.id,original.id,evidence,transactions,context,c.correlated_at);
 INSERT INTO gridex_ediel_source_rules.receipts(source_message_id,company_id,environment,direction,payload_sha256,canonical_assessment_id,original_source_message_id,evidence)
  VALUES(m.id,p_company,p_environment,'inbound',c.ack_payload_hash,a.id,original.id,evidence);
 PERFORM gridex_ediel_ack_guide.bind_source_v1(m,'national',evidence);
END $$;

REVOKE ALL ON FUNCTION gridex_received_err_response.capture_v1(uuid, text, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:892
--
-- Name: require_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_received_err_response; Owner: -
--

CREATE FUNCTION gridex_received_err_response.require_v1(p_company uuid, p_environment text, p_source uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r gridex_received_err_response.receipts%rowtype;c gridex_ack_authority.source_correlations%rowtype;m public.ediel_messages%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source AND company_id=p_company AND environment=p_environment AND direction='inbound' FOR SHARE;
 SELECT * INTO r FROM gridex_received_err_response.receipts WHERE source_message_id=p_source;
 SELECT * INTO c FROM gridex_ack_authority.source_correlations WHERE ack_message_id=p_source;
 IF m.id IS NULL OR m.message_family IS DISTINCT FROM 'UTILTS_ERR' OR r.source_message_id IS NULL OR c.ack_family IS DISTINCT FROM 'UTILTS_ERR'
  OR r.company_id IS DISTINCT FROM m.company_id OR r.environment IS DISTINCT FROM m.environment OR r.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR r.payload_hash IS DISTINCT FROM c.ack_payload_hash OR c.company_id IS DISTINCT FROM r.company_id OR c.environment IS DISTINCT FROM r.environment
  OR r.canonical_assessment_id IS DISTINCT FROM c.canonical_assessment_id OR r.correlated_original_message_id IS DISTINCT FROM c.source_message_id
  OR r.evidence IS DISTINCT FROM gridex_ediel_source_rules.require_v1(p_company,c.source_message_id)
 THEN RAISE EXCEPTION 'utilts_err_application_response_authority_unavailable';END IF;
 RETURN jsonb_build_object('version',1,'sourceMessage',to_jsonb(m),'sourceRulePackEvidence',r.evidence,'sourceHash',r.payload_hash,
  'canonicalAssessmentId',r.canonical_assessment_id,'correlatedOriginalMessageId',r.correlated_original_message_id,'transactions',r.transactions,
  'localContext',r.local_context,'observedAt',r.observed_at,'authorizesBusinessEffect',false);
END $$;

REVOKE ALL ON FUNCTION gridex_received_err_response.require_v1(uuid, text, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:893
--
-- Name: applied_source_v1(); Type: FUNCTION; Schema: gridex_received_reading_expectations; Owner: -
--

CREATE FUNCTION gridex_received_reading_expectations.applied_source_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE prior_source uuid;BEGIN
 PERFORM gridex_received_reading_expectations.capture_source_v1(NEW.company_id,NEW.environment,NEW.source_message_id);
 IF jsonb_array_length(gridex_received_reading_expectations.source_contracts_v1(NEW.company_id,NEW.environment,NEW.source_message_id))>0 THEN
  FOR prior_source IN SELECT r.source_message_id FROM gridex_utilts_binding.receipts r WHERE r.company_id=NEW.company_id AND r.environment=NEW.environment ORDER BY r.source_message_id LOOP
   PERFORM gridex_received_reading_expectations.consider_utilts_source_v1(NEW.company_id,NEW.environment,prior_source);
  END LOOP;
 END IF;RETURN NEW;END$$;

REVOKE ALL ON FUNCTION gridex_received_reading_expectations.applied_source_v1() FROM PUBLIC,anon,authenticated,service_role;

-- canonical:894
--
-- Name: apply_before_live_followup_v1(uuid, uuid, uuid, integer[]); Type: FUNCTION; Schema: gridex_received_reading_expectations; Owner: -
--

CREATE FUNCTION gridex_received_reading_expectations.apply_before_live_followup_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid, p_object_line_indices integer[] DEFAULT NULL::integer[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;src gridex_received_sources.sources%rowtype;
 canonical gridex_received_sources.validation_assessments%rowtype;assessment gridex_received_sources.object_assessments%rowtype;
 prior gridex_received_sources.structural_apply_receipts%rowtype;entry jsonb;business jsonb;wire jsonb;tokens jsonb;own_tokens jsonb;
 objects jsonb:='[]';counted integer;reg jsonb;lin jsonb;point public.metering_points%rowtype;site public.customer_sites%rowtype;
 line_start integer;line_end integer;physical_count integer;effective_at timestamptz;result jsonb;applied_count integer:=0;period_preflight jsonb;locked_periods jsonb;application jsonb;selected jsonb:='[]';manifest jsonb:='[]';own_effect jsonb;first_line integer;scope_key text;requested integer[];
 batch gridex_received_sources.structural_apply_batches%rowtype;own_prior gridex_received_sources.structural_object_apply_receipts%rowtype;skipped_count integer:=0;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'structural_apply_service_required' USING ERRCODE='42501'; END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact'
  OR m.message_family IS DISTINCT FROM 'PRODAT' OR (m.message_code IN ('Z06','Z10')) IS NOT TRUE THEN RAISE EXCEPTION 'structural_apply_source_required'; END IF;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'metering.write'),false) THEN RAISE EXCEPTION 'ediel_tenant_actor_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO prior FROM gridex_received_sources.structural_apply_receipts WHERE source_message_id=m.id;
 IF FOUND THEN
  IF prior.company_id IS DISTINCT FROM m.company_id OR prior.environment IS DISTINCT FROM m.environment OR prior.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'structural_apply_replay_conflict'; END IF;
  RETURN prior.result;
 END IF;
 IF p_object_line_indices IS NOT NULL AND (cardinality(p_object_line_indices) NOT BETWEEN 1 AND 8192 OR EXISTS(SELECT FROM unnest(p_object_line_indices) n WHERE n IS NULL OR n<0) OR cardinality(p_object_line_indices)<>(SELECT count(DISTINCT n) FROM unnest(p_object_line_indices)n)) THEN RAISE EXCEPTION 'structural_apply_requested_scope_invalid';END IF;
 SELECT array_agg(n ORDER BY n) INTO requested FROM unnest(p_object_line_indices)n;
 scope_key:=CASE WHEN p_object_line_indices IS NULL THEN 'all_source_objects' ELSE encode(sha256(convert_to(to_jsonb(requested)::text,'UTF8')),'hex') END;
 SELECT * INTO batch FROM gridex_received_sources.structural_apply_batches WHERE source_message_id=m.id AND requested_scope_key=scope_key;
 IF FOUND THEN
  IF batch.company_id IS DISTINCT FROM m.company_id OR batch.environment IS DISTINCT FROM m.environment OR batch.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'structural_apply_replay_conflict';END IF;
  RETURN batch.result;
 END IF;
 -- A differently requested read of already established own receipts is
 -- still replay. It must not acquire today's role/rule basis as new authority.
 IF requested IS NOT NULL AND cardinality(requested)=(SELECT count(*) FROM gridex_received_sources.structural_object_apply_receipts r WHERE r.source_message_id=m.id AND r.first_line_index=ANY(requested)) THEN
  IF EXISTS(SELECT FROM gridex_received_sources.structural_object_apply_receipts r WHERE r.source_message_id=m.id AND r.first_line_index=ANY(requested) AND(r.company_id IS DISTINCT FROM m.company_id OR r.environment IS DISTINCT FROM m.environment OR r.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'))) THEN RAISE EXCEPTION 'structural_apply_object_replay_conflict';END IF;
  SELECT jsonb_agg(r.effect ORDER BY r.first_line_index),sum(jsonb_array_length(r.object_scope->'registers')),jsonb_agg(jsonb_build_object('object',r.object_scope,'status','already_applied') ORDER BY r.first_line_index)
   INTO objects,applied_count,manifest FROM gridex_received_sources.structural_object_apply_receipts r WHERE r.source_message_id=m.id AND r.first_line_index=ANY(requested);
  RETURN jsonb_build_object('applied',true,'appliedCount',applied_count,'skippedCount',0,'objects',objects,'sourceMessageId',m.id,'manifest',manifest);
 END IF;
 -- Current admission cannot relabel an already committed source outcome.
 PERFORM gridex_ediel_inbound_context.require_v1(p_company_id,m.id);
 PERFORM gridex_ediel_source_rules.require_v1(p_company_id,m.id);
 SELECT * INTO src FROM gridex_received_sources.sources WHERE source_message_id=m.id AND company_id=p_company_id AND environment=m.environment FOR UPDATE;
 IF NOT FOUND OR src.raw_payload IS DISTINCT FROM m.raw_payload OR src.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR src.source_received_at IS NULL OR src.source_received_at IS DISTINCT FROM m.message_received_at THEN RAISE EXCEPTION 'structural_apply_immutable_source_required'; END IF;
 SELECT count(*) INTO counted FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=p_company_id AND a.environment=m.environment
  AND a.source_payload_hash=src.payload_hash AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id);
 IF counted<>1 THEN RETURN jsonb_build_object('applied',false,'reason','structural_apply_canonical_source_ambiguous'); END IF;
 SELECT * INTO canonical FROM gridex_received_sources.validation_assessments a WHERE a.source_message_id=m.id AND a.company_id=p_company_id AND a.environment=m.environment
  AND a.source_payload_hash=src.payload_hash AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=a.id) FOR SHARE;
 application:=gridex_received_sources.require_prodat_application_objects_v1(p_company_id,m.id);
 IF canonical.facts_text::jsonb->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR application->>'assessmentId' IS DISTINCT FROM canonical.id::text OR application->>'headerDecision' IS DISTINCT FROM 'accepted' THEN RETURN jsonb_build_object('applied',false,'reason','structural_apply_canonical_source_not_accepted');END IF;
 SELECT count(*) INTO counted FROM gridex_received_sources.object_assessments a WHERE a.source_message_id=m.id AND a.company_id=p_company_id AND a.environment=m.environment
  AND a.source_payload_hash=src.payload_hash AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=a.id);
 IF counted<>1 THEN RETURN jsonb_build_object('applied',false,'reason','structural_apply_original_review_required'); END IF;
 SELECT * INTO assessment FROM gridex_received_sources.object_assessments a WHERE a.source_message_id=m.id AND a.company_id=p_company_id AND a.environment=m.environment
  AND a.source_payload_hash=src.payload_hash AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments child WHERE child.previous_assessment_id=a.id) FOR SHARE;
 IF assessment.canonical_assessment_id IS DISTINCT FROM canonical.id OR jsonb_typeof(assessment.facts_text::jsonb->'objects') IS DISTINCT FROM 'array'
  OR jsonb_array_length(assessment.facts_text::jsonb->'objects')<1 THEN RETURN jsonb_build_object('applied',false,'reason','structural_apply_original_review_required'); END IF;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(src.raw_payload);
 IF tokens IS NULL THEN RAISE EXCEPTION 'structural_apply_whole_wire_required'; END IF;
 SELECT count(*) INTO physical_count FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN';
 -- The owner assessment must cover every physical object/register, with no
 -- caller-provided changes, entity IDs, field labels or partial object writes.
 IF (SELECT coalesce(sum(jsonb_array_length(e#>'{object,registers}')),0) FROM jsonb_array_elements(assessment.facts_text::jsonb->'objects') e)<>physical_count THEN RAISE EXCEPTION 'structural_apply_physical_scope_incomplete'; END IF;
 -- Keep the complete physical partition. Only SAME full application AND
 -- actual source-specific business/party owner can qualify a first effect.
 IF requested IS NOT NULL AND EXISTS(SELECT FROM unnest(requested)n WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(assessment.facts_text::jsonb->'objects')e WHERE (e#>>'{object,registers,0,segmentIndex}')::integer=n)) THEN RAISE EXCEPTION 'structural_apply_requested_scope_invalid';END IF;
 FOR entry IN SELECT e FROM jsonb_array_elements(assessment.facts_text::jsonb->'objects')e LOOP
  first_line:=(entry#>>'{object,registers,0,segmentIndex}')::integer;
  IF requested IS NOT NULL AND NOT first_line=ANY(requested) THEN
   manifest:=manifest||jsonb_build_array(jsonb_build_object('object',entry->'object','status','not_requested'));skipped_count:=skipped_count+jsonb_array_length(entry#>'{object,registers}');CONTINUE;
  END IF;
  SELECT * INTO own_prior FROM gridex_received_sources.structural_object_apply_receipts WHERE source_message_id=m.id AND first_line_index=first_line;
  IF FOUND THEN
   IF own_prior.company_id IS DISTINCT FROM m.company_id OR own_prior.environment IS DISTINCT FROM m.environment OR own_prior.payload_hash IS DISTINCT FROM src.payload_hash OR own_prior.object_scope IS DISTINCT FROM entry->'object' THEN RAISE EXCEPTION 'structural_apply_object_replay_conflict';END IF;
   objects:=objects||jsonb_build_array(own_prior.effect);applied_count:=applied_count+jsonb_array_length(entry#>'{object,registers}');
   manifest:=manifest||jsonb_build_array(jsonb_build_object('object',entry->'object','status','already_applied'));CONTINUE;
  END IF;
  IF entry->>'disposition'='accepted' AND coalesce(gridex_received_sources.prodat_application_object_accepted_v1(p_company_id,m.id,canonical.id,entry->'object'),false) THEN
   IF entry#>>'{business,owner}' IS DISTINCT FROM 'reviewed-received-structure-v1' OR(entry#>>'{business,wire,businessCase}' IN('change_with_reading','change_without_reading','meter_exchange')) IS NOT TRUE THEN RAISE EXCEPTION 'structural_apply_original_review_required';END IF;
   selected:=selected||jsonb_build_array(entry);
  ELSE
   IF requested IS NOT NULL THEN RAISE EXCEPTION 'structural_apply_requested_object_not_qualified';END IF;
   skipped_count:=skipped_count+jsonb_array_length(entry#>'{object,registers}');manifest:=manifest||jsonb_build_array(jsonb_build_object('object',entry->'object','status',CASE WHEN entry->>'disposition'='rejected' THEN 'rejected' ELSE 'held' END));
  END IF;
 END LOOP;
 IF jsonb_array_length(selected)=0 AND applied_count=0 THEN RETURN jsonb_build_object('applied',false,'reason','structural_apply_no_qualified_object','manifest',manifest);END IF;
 -- Follow the normal supply commit order: original inbound baselines first,
 -- then their originating outbound requests, switches, periods, points/sites.
 -- Acquire whole-message sets before proof evaluation to prevent a concurrent
 -- cancellation/activation from changing coverage halfway through an apply.
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',sp.id,'sourceId',sp.source_message_id,'version',sp.market_state_version) ORDER BY sp.id),'[]') INTO period_preflight
 FROM public.customer_supply_periods sp WHERE sp.company_id=p_company_id AND sp.id IN(SELECT (e#>>'{business,supplyPeriodId}')::uuid FROM jsonb_array_elements(selected) e);
 PERFORM original.id FROM public.ediel_messages original WHERE original.company_id=p_company_id AND original.environment=m.environment AND original.id IN(
  SELECT (e#>>'{business,coverageWindow,baselineSourceMessageId}')::uuid FROM jsonb_array_elements(selected) e UNION
  SELECT (e#>>'{business,coverageWindow,outboundSourceMessageId}')::uuid FROM jsonb_array_elements(selected) e UNION
  SELECT (p->>'sourceId')::uuid FROM jsonb_array_elements(period_preflight) p UNION
  SELECT tr.source_message_id FROM gridex_received_sources.supply_source_transitions tr,jsonb_array_elements(tr.resulting_states) own,jsonb_array_elements(period_preflight) p
   WHERE tr.company_id=p_company_id AND own->>'id'=p->>'id' AND own->>'market_state_version'=p->>'version'
 ) ORDER BY original.id FOR UPDATE;
 PERFORM sw.id FROM public.supplier_switch_requests sw WHERE sw.company_id=p_company_id
  AND sw.id IN(SELECT (e#>>'{business,switchRequestId}')::uuid FROM jsonb_array_elements(selected) e) ORDER BY sw.id FOR UPDATE;
 PERFORM sp.id FROM public.customer_supply_periods sp WHERE sp.company_id=p_company_id
  AND sp.id IN(SELECT (e#>>'{business,supplyPeriodId}')::uuid FROM jsonb_array_elements(selected) e) ORDER BY sp.id FOR UPDATE;
 SELECT coalesce(jsonb_agg(jsonb_build_object('id',sp.id,'sourceId',sp.source_message_id,'version',sp.market_state_version) ORDER BY sp.id),'[]') INTO locked_periods
 FROM public.customer_supply_periods sp WHERE sp.company_id=p_company_id AND sp.id IN(SELECT (e#>>'{business,supplyPeriodId}')::uuid FROM jsonb_array_elements(selected) e);
 IF locked_periods IS DISTINCT FROM period_preflight THEN RETURN jsonb_build_object('applied',false,'reason','structural_apply_supply_version_changed_retry'); END IF;
 PERFORM mp.id FROM public.metering_points mp WHERE mp.company_id=p_company_id
  AND mp.id IN(SELECT (e#>>'{business,meteringPointId}')::uuid FROM jsonb_array_elements(selected) e) ORDER BY mp.id FOR UPDATE;
 PERFORM cs.id FROM public.customer_sites cs WHERE cs.company_id=p_company_id
  AND cs.id IN(SELECT (e#>>'{business,siteId}')::uuid FROM jsonb_array_elements(selected) e) ORDER BY cs.id FOR UPDATE;
 FOR entry IN SELECT e FROM jsonb_array_elements(selected) e ORDER BY e#>>'{business,meteringPointId}' LOOP
  business:=entry->'business';wire:=business->'wire';
  IF entry->>'disposition' IS DISTINCT FROM 'accepted' OR business->>'owner' IS DISTINCT FROM 'reviewed-received-structure-v1'
   OR (wire->>'businessCase' IN ('change_with_reading','change_without_reading','meter_exchange')) IS NOT TRUE
   OR gridex_received_sources.review_business_proof_consistent(entry->'party',business,m.id) IS NOT TRUE THEN RAISE EXCEPTION 'structural_apply_original_review_required';END IF;
  SELECT * INTO point FROM public.metering_points WHERE id=(business->>'meteringPointId')::uuid AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND OR point.meter_point_id IS DISTINCT FROM entry#>>'{object,objectId}' OR point.customer_id IS DISTINCT FROM (business->>'customerId')::uuid
   OR point.site_id IS DISTINCT FROM (business->>'siteId')::uuid THEN RAISE EXCEPTION 'structural_apply_point_scope_unqualified'; END IF;
  SELECT * INTO site FROM public.customer_sites WHERE id=point.site_id AND company_id=p_company_id FOR UPDATE;
  IF NOT FOUND OR site.customer_id IS DISTINCT FROM point.customer_id THEN RAISE EXCEPTION 'structural_apply_site_scope_unqualified'; END IF;
  effective_at:=(wire#>>'{effectiveFrom,utc}')::timestamptz;own_tokens:='[]';
  FOR reg IN SELECT r FROM jsonb_array_elements(entry#>'{object,registers}') r LOOP
   line_start:=(reg->>'segmentIndex')::integer;
   SELECT t INTO lin FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::integer=line_start;
   IF lin->>'tag' IS DISTINCT FROM 'LIN' OR lin#>>'{elements,3,0}' IS DISTINCT FROM entry#>>'{object,objectId}'
    OR lin#>>'{elements,3,3}' IS DISTINCT FROM entry#>>'{object,identityAgency}' OR lin#>>'{elements,1,0}' IS DISTINCT FROM reg->>'lineNumber' THEN RAISE EXCEPTION 'structural_apply_physical_scope_incomplete'; END IF;
   SELECT min((t->>'index')::integer) INTO line_end FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::integer>line_start AND t->>'tag' IN ('LIN','UNT','UNZ','UNH');
   own_tokens:=own_tokens||jsonb_build_array(jsonb_build_object('register',reg,'tokens',(SELECT jsonb_agg(t ORDER BY (t->>'index')::integer) FROM jsonb_array_elements(tokens) t WHERE (t->>'index')::integer>=line_start AND (t->>'index')::integer<line_end)));
  END LOOP;
  -- The primary dated source ledger is used by structuralSourceSelection and
  -- the live UTILTS qualification boundary. Do not flatten its future/history
  -- versions into current global masterdata or alter any earlier meter values.
  own_effect:=jsonb_build_object('object',entry->'object','meteringPointId',point.id,'siteId',site.id,
   'effectiveAt',effective_at,'sourceReceivedAt',src.source_received_at,'wire',wire,'sourceRegisters',own_tokens,
   'readingFollowUp',jsonb_build_object('status',CASE WHEN wire->>'businessCase'='change_without_reading' THEN 'not_required_by_this_change' ELSE 'source_process_evidence_required' END,
    'criterion',CASE WHEN wire->>'businessCase'='change_without_reading' THEN 'AT-Z06G-SUPPLIER' WHEN wire->>'businessCase'='meter_exchange' THEN 'AT-Z10M-SUPPLIER' ELSE 'AT-Z06F-SUPPLIER' END,
    'deadline',NULL,'fulfilled',false));
  first_line:=(entry#>>'{object,registers,0,segmentIndex}')::integer;
  INSERT INTO gridex_received_sources.structural_object_apply_receipts(source_message_id,first_line_index,company_id,environment,payload_hash,canonical_assessment_id,object_assessment_id,actor_user_id,source_received_at,object_scope,effect)
  VALUES(m.id,first_line,p_company_id,m.environment,src.payload_hash,canonical.id,assessment.id,p_actor_user_id,src.source_received_at,entry->'object',own_effect);
  objects:=objects||jsonb_build_array(own_effect);manifest:=manifest||jsonb_build_array(jsonb_build_object('object',entry->'object','status','applied'));
  applied_count:=applied_count+jsonb_array_length(entry#>'{object,registers}');
 END LOOP;
 result:=jsonb_build_object('applied',true,'appliedCount',applied_count,'objects',objects,'sourceMessageId',m.id,'objectAssessmentId',assessment.id,'canonicalAssessmentId',canonical.id,'skippedCount',skipped_count,'manifest',manifest);
 INSERT INTO gridex_received_sources.structural_apply_batches(source_message_id,requested_scope_key,company_id,environment,payload_hash,canonical_assessment_id,object_assessment_id,result)
 VALUES(m.id,scope_key,p_company_id,m.environment,src.payload_hash,canonical.id,assessment.id,result);
 INSERT INTO public.ediel_message_events(company_id,ediel_message_id,message_id,event_type,event_status,message,payload,event_payload,created_by)
 VALUES(p_company_id,m.id,m.id,'manual_note','success','Granskad källbunden strukturversion tillämpad.',
  jsonb_build_object('safeApply',true,'safeApplyDecision','applied','appliedCount',applied_count,'sourceAssessmentId',assessment.id,'appliedAutomatically',false),
  jsonb_build_object('safeApply',true,'safeApplyDecision','applied','appliedCount',applied_count,'sourceAssessmentId',assessment.id,'appliedAutomatically',false),p_actor_user_id);
 RETURN result;
END $$;

REVOKE ALL ON FUNCTION gridex_received_reading_expectations.apply_before_live_followup_v1(uuid, uuid, uuid, integer[]) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:895
--
-- Name: capture_source_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_received_reading_expectations; Owner: -
--

CREATE FUNCTION gridex_received_reading_expectations.capture_source_v1(c uuid, env text, msg uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE item jsonb;h text;prior gridex_received_reading_expectations.expectations%rowtype;BEGIN
 PERFORM pg_advisory_xact_lock(hashtextextended('z06f-reading:'||c::text||':'||env,0));
 FOR item IN SELECT value FROM jsonb_array_elements(gridex_received_reading_expectations.source_contracts_v1(c,env,msg)) LOOP
  h:=encode(sha256(convert_to(item::text,'UTF8')),'hex');
  SELECT * INTO prior FROM gridex_received_reading_expectations.expectations WHERE company_id=c AND environment=env AND source_message_id=msg AND first_line_index=(item->>'firstLineIndex')::int;
  IF FOUND THEN IF prior.contract IS DISTINCT FROM item OR prior.contract_hash IS DISTINCT FROM h THEN RAISE EXCEPTION 'z06f_reading_original_conflict';END IF;
  ELSE INSERT INTO gridex_received_reading_expectations.expectations(company_id,environment,source_message_id,first_line_index,contract,contract_hash) VALUES(c,env,msg,(item->>'firstLineIndex')::int,item,h);END IF;
 END LOOP;
END$$;

REVOKE ALL ON FUNCTION gridex_received_reading_expectations.capture_source_v1(uuid, text, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:896
--
-- Name: consider_utilts_source_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_received_reading_expectations; Owner: -
--

CREATE FUNCTION gridex_received_reading_expectations.consider_utilts_source_v1(c uuid, env text, msg uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE m public.ediel_messages%rowtype;prior_source uuid;tokens jsonb;membership jsonb;tx text;stored jsonb;start_at int;stop_at int;first_seq int;zone jsonb;offset_minutes int;
 header jsonb;sender text;receiver text;point text;agency text;reading jsonb;sequence record;own jsonb;register_id text;meter_id text;previous_register text;current_meter text;at timestamptz;dates jsonb;qty jsonb;
 e gridex_received_reading_expectations.expectations%rowtype;candidate_ids uuid[];receipt jsonb;matched bool;
BEGIN

 PERFORM pg_advisory_xact_lock(hashtextextended('z06f-reading:'||c::text||':'||env,0));
 SELECT * INTO m FROM public.ediel_messages WHERE id=msg AND company_id=c AND environment=env FOR SHARE SKIP LOCKED;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'UTILTS' OR(m.message_code IN('E30','E66','S07')) IS NOT TRUE THEN RETURN;END IF;
 SELECT r.membership INTO membership FROM gridex_utilts_binding.receipts r WHERE r.source_message_id=msg AND r.company_id=c AND r.environment=env;
 IF jsonb_typeof(membership) IS DISTINCT FROM 'array' THEN RETURN;END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(m.raw_payload);IF tokens IS NULL THEN RETURN;END IF;
 -- Whole binding is checked independently for EACH actual accepted member;
 -- a legitimate reused immutable origin series remains legitimate.
 FOR tx IN SELECT value FROM jsonb_array_elements_text(membership) LOOP
  BEGIN stored:=gridex_utilts_binding.stored_contract_v1(c,msg,tx);EXCEPTION WHEN SQLSTATE 'P0U01' THEN CONTINUE;END;
  IF stored->>'companyId' IS DISTINCT FROM c::text OR stored->>'environment' IS DISTINCT FROM env OR stored->>'transactionId' IS DISTINCT FROM tx THEN CONTINUE;END IF;
  SELECT(t->>'index')::int INTO STRICT start_at FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='IDE' AND t#>>'{elements,1,0}'='24' AND t#>>'{elements,2,0}'=tx;
  SELECT min((t->>'index')::int) INTO stop_at FROM jsonb_array_elements(tokens)t WHERE(t->>'index')::int>start_at AND t->>'tag' IN('IDE','UNT');
  SELECT coalesce(min((t->>'index')::int),stop_at) INTO first_seq FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='SEQ' AND(t->>'index')::int>start_at AND(t->>'index')::int<stop_at;
  SELECT jsonb_agg(t ORDER BY(t->>'index')::int) INTO header FROM jsonb_array_elements(tokens)t WHERE(t->>'index')::int>start_at AND(t->>'index')::int<first_seq;
  IF(SELECT count(*) FROM jsonb_array_elements(header)t WHERE t->>'tag'='LOC' AND t#>>'{elements,1,0}'='172')<>1 THEN CONTINUE;END IF;
  SELECT t#>>'{elements,2,0}',t#>>'{elements,2,2}' INTO point,agency FROM jsonb_array_elements(header)t WHERE t->>'tag'='LOC' AND t#>>'{elements,1,0}'='172';
  IF(agency IN('9','89')) IS NOT TRUE THEN CONTINUE;END IF;
  SELECT jsonb_agg(t) INTO zone FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='DTM' AND(t->>'index')::int<start_at AND t#>>'{elements,1,0}'='735';
  IF jsonb_array_length(zone) IS DISTINCT FROM 1 OR zone#>>'{0,elements,1,2}' IS DISTINCT FROM '406' OR zone#>>'{0,elements,1,1}'!~'^[+-][0-9]{4}$' THEN CONTINUE;END IF;
  IF substring(zone#>>'{0,elements,1,1}',2,2)::int>14 OR substring(zone#>>'{0,elements,1,1}',4,2)::int>59 THEN CONTINUE;END IF;
  offset_minutes:=(substring(zone#>>'{0,elements,1,1}',2,2)::int*60+substring(zone#>>'{0,elements,1,1}',4,2)::int)*CASE left(zone#>>'{0,elements,1,1}',1) WHEN '-' THEN -1 ELSE 1 END;
  IF abs(offset_minutes)>840 THEN CONTINUE;END IF;
  sender:=NULL;receiver:=NULL;
  IF(SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='MS' AND(t->>'index')::int<start_at)<>1 OR(SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='MR' AND(t->>'index')::int<start_at)<>1 THEN CONTINUE;END IF;
  SELECT t#>>'{elements,2,0}' INTO sender FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='MS' AND(t->>'index')::int<start_at AND t#>>'{elements,2,1}'='SVK' AND t#>>'{elements,2,2}'='260';
  SELECT t#>>'{elements,2,0}' INTO receiver FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'='MR' AND(t->>'index')::int<start_at AND t#>>'{elements,2,1}'='SVK' AND t#>>'{elements,2,2}'='260';
  IF sender IS NULL OR receiver IS NULL THEN CONTINUE;END IF;
  -- Replay actual earlier applied owners through the same constructor. This
  -- derives new follow-up records from authentic retained effects, without
  -- backfilling source approvals, changing old receipts or trusting parsed rows.
  FOR prior_source IN SELECT DISTINCT source_message_id FROM(
   SELECT source_message_id,objects FROM gridex_received_sources.structural_apply_receipts WHERE company_id=c AND environment=env
   UNION ALL SELECT source_message_id,jsonb_build_array(effect) FROM gridex_received_sources.structural_object_apply_receipts WHERE company_id=c AND environment=env
  )r WHERE EXISTS(SELECT FROM jsonb_array_elements(r.objects)o WHERE o#>>'{object,objectId}'=point AND o#>>'{object,identityAgency}'=agency AND o#>>'{wire,businessCase}'='change_with_reading') LOOP
   PERFORM gridex_received_reading_expectations.capture_source_v1(c,env,prior_source);
  END LOOP;
  reading:='[]';previous_register:=NULL;current_meter:=NULL;
  FOR sequence IN SELECT(t->>'index')::int n,coalesce(lead((t->>'index')::int) OVER(ORDER BY(t->>'index')::int),stop_at) next_n FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='SEQ' AND(t->>'index')::int>start_at AND(t->>'index')::int<stop_at LOOP
   SELECT jsonb_agg(t ORDER BY(t->>'index')::int) INTO own FROM jsonb_array_elements(tokens)t WHERE(t->>'index')::int>sequence.n AND(t->>'index')::int<sequence.next_n;
   SELECT jsonb_agg(t) INTO qty FROM jsonb_array_elements(own)t WHERE t->>'tag'='QTY' AND t#>>'{elements,1,0}'='220';
   IF qty IS NULL THEN CONTINUE;END IF;
   IF jsonb_array_length(qty)<>1 THEN reading:=NULL;EXIT;END IF;
   IF qty#>>'{0,elements,1,1}' IS NULL OR qty#>>'{0,elements,1,1}'='NULL' THEN CONTINUE;END IF;
   IF(SELECT count(*) FROM jsonb_array_elements(own)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='AES' AND jsonb_array_length(t->'elements'->1)=2 AND(t->>'index')::int<(qty#>>'{0,index}')::int)<>1 THEN reading:=NULL;EXIT;END IF;
   SELECT t#>>'{elements,1,1}' INTO register_id FROM jsonb_array_elements(own)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='AES' AND(t->>'index')::int<(qty#>>'{0,index}')::int;
   IF previous_register IS DISTINCT FROM register_id THEN current_meter:=NULL;END IF;previous_register:=register_id;
   IF(SELECT count(*) FROM jsonb_array_elements(own)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='MG' AND(t->>'index')::int<(qty#>>'{0,index}')::int)>1 THEN reading:=NULL;EXIT;END IF;
   SELECT t#>>'{elements,1,1}' INTO meter_id FROM jsonb_array_elements(own)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='MG' AND jsonb_array_length(t->'elements'->1)=2 AND(t->>'index')::int<(qty#>>'{0,index}')::int;
   IF meter_id IS NOT NULL THEN current_meter:=meter_id;END IF;meter_id:=current_meter;
   IF meter_id IS NULL THEN reading:=NULL;EXIT;END IF;
   SELECT jsonb_agg(t) INTO dates FROM jsonb_array_elements(own)t WHERE t->>'tag'='DTM' AND t#>>'{elements,1,0}'='597' AND(t->>'index')::int>(qty#>>'{0,index}')::int;
   IF jsonb_array_length(dates) IS DISTINCT FROM 1 THEN reading:=NULL;EXIT;END IF;
   at:=gridex_received_reading_expectations.instant_v1(dates#>>'{0,elements,1,1}',dates#>>'{0,elements,1,2}',offset_minutes);
   IF at IS NULL THEN reading:=NULL;EXIT;END IF;
   reading:=reading||jsonb_build_array(jsonb_build_object('registerId',register_id,'meterNumber',meter_id,'readAt',at,'sourceQuantity',qty#>'{0,elements,1}'));
  END LOOP;
  candidate_ids:='{}';
  FOR e IN SELECT * FROM gridex_received_reading_expectations.expectations x WHERE x.company_id=c AND x.environment=env AND x.contract#>>'{object,objectId}'=point AND x.contract#>>'{object,identityAgency}'=agency AND x.contract#>>'{wire,legalSender}'=sender AND x.contract#>>'{wire,legalReceiver}'=receiver LOOP
   IF e.contract_hash IS DISTINCT FROM encode(sha256(convert_to(e.contract::text,'UTF8')),'hex') OR NOT EXISTS(SELECT FROM jsonb_array_elements(gridex_received_reading_expectations.source_contracts_v1(c,env,e.source_message_id))value WHERE value=e.contract) THEN CONTINUE;END IF;
   IF EXISTS(SELECT FROM gridex_received_reading_expectations.expectations correction WHERE correction.company_id=c AND correction.environment=env AND correction.contract#>>'{replaces,sourceMessageId}'=e.source_message_id::text AND correction.contract#>>'{object,objectId}'=point AND correction.contract#>>'{object,identityAgency}'=agency) THEN CONTINUE;END IF;
   matched:=false;
   IF e.contract->>'mode'='meter_reading' AND reading IS NOT NULL AND jsonb_array_length(reading)>0 THEN
    matched:=(SELECT jsonb_agg(value->'registerId' ORDER BY value->>'registerId') FROM jsonb_array_elements(reading) WHERE(value->>'readAt')::timestamptz=(e.contract->>'effectiveAt')::timestamptz)=(SELECT jsonb_agg(value ORDER BY value#>>'{}') FROM jsonb_array_elements(e.contract->'expectedRegisterIds'))
      AND NOT EXISTS(SELECT FROM jsonb_array_elements(reading)value WHERE(value->>'readAt')::timestamptz=(e.contract->>'effectiveAt')::timestamptz AND value->>'meterNumber' IS DISTINCT FROM e.contract#>>'{wire,meterNumber}');
   ELSIF e.contract->>'mode'='subsequent_values' THEN
    -- Observe initial subsequent values only. No claim about all future periods,
    -- no invented boundary reading where original field259 was absent.
    matched:=stored#>>'{metering,customerId}'=e.contract->>'customerId' AND stored#>>'{metering,meteringPointId}'=e.contract->>'meteringPointId'
     AND EXISTS(SELECT FROM jsonb_array_elements(stored->'observations')v WHERE(v->>'periodStart')::timestamptz>=(e.contract->>'effectiveAt')::timestamptz
      AND(v->>'periodStart')::timestamptz>=(e.contract#>>'{coverage,validFrom}')::timestamptz AND(e.contract#>>'{coverage,validTo}' IS NULL OR(v->>'periodEnd')::timestamptz<=(e.contract#>>'{coverage,validTo}')::timestamptz)
      AND CASE e.contract->>'measurementMethod' WHEN 'Z04' THEN v->>'resolution'='PT15M' WHEN 'Z02' THEN v->>'resolution'='PT1H' WHEN 'Z01' THEN v->>'resolution' IN('P1M','P1Y') ELSE false END
      AND NOT EXISTS(SELECT FROM gridex_received_reading_expectations.expectations later WHERE later.company_id=c AND later.environment=env AND later.contract#>>'{object,objectId}'=point AND later.contract#>>'{object,identityAgency}'=agency AND later.contract#>>'{wire,legalSender}'=sender AND later.contract#>>'{wire,legalReceiver}'=receiver AND(later.contract->>'effectiveAt')::timestamptz>(e.contract->>'effectiveAt')::timestamptz AND(later.contract->>'effectiveAt')::timestamptz<=(v->>'periodStart')::timestamptz));
   END IF;
   IF matched IS TRUE THEN candidate_ids:=array_append(candidate_ids,e.id);END IF;
  END LOOP;
  -- A reading cannot be borrowed by two indistinguishable structural originals.
  IF cardinality(candidate_ids)=1 THEN
   receipt:=jsonb_build_object('version',1,'utiltsSourceId',msg,'transactionId',tx,'sourcePayloadHash',encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),
     'storedContractHash',encode(sha256(convert_to(stored::text,'UTF8')),'hex'),'reading',reading,'observation','actual_accepted_persisted_member');
   INSERT INTO gridex_received_reading_expectations.observations(expectation_id,company_id,environment,utilts_source_message_id,transaction_id,source_payload_hash,receipt,receipt_hash)
    VALUES(candidate_ids[1],c,env,msg,tx,encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),receipt,encode(sha256(convert_to(receipt::text,'UTF8')),'hex')) ON CONFLICT DO NOTHING;
  END IF;
 END LOOP;
END$_$;

REVOKE ALL ON FUNCTION gridex_received_reading_expectations.consider_utilts_source_v1(uuid, text, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:897
--
-- Name: current_status_v1(uuid, text, uuid, integer); Type: FUNCTION; Schema: gridex_received_reading_expectations; Owner: -
--

CREATE FUNCTION gridex_received_reading_expectations.current_status_v1(c uuid, env text, msg uuid, line_index integer) RETURNS jsonb
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT jsonb_build_object('owner','applied-z06f-reading-followup-v1','criterion','AT-Z06F-SUPPLIER','sourceMessageId',msg,'firstLineIndex',line_index,'deadline',NULL,'automaticRequestAllowed',false,
 'status',CASE WHEN count(*)=0 THEN 'source_scope_unavailable' WHEN bool_and(observed) THEN CASE WHEN bool_and(mode='meter_reading') THEN 'reading_observed' ELSE 'initial_values_observed' END ELSE 'pending' END,
 'fulfilled',coalesce(bool_and(observed AND mode='meter_reading'),false),'expectationIds',coalesce(jsonb_agg(id),'[]'))
 FROM(SELECT e.id,e.contract->>'mode' mode,EXISTS(SELECT FROM gridex_received_reading_expectations.observations o WHERE o.expectation_id=e.id) observed FROM gridex_received_reading_expectations.expectations e WHERE e.company_id=c AND e.environment=env AND e.source_message_id=msg AND e.first_line_index=line_index) own;
$$;

REVOKE ALL ON FUNCTION gridex_received_reading_expectations.current_status_v1(uuid, text, uuid, integer) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:898
--
-- Name: instant_v1(text, text, integer); Type: FUNCTION; Schema: gridex_received_reading_expectations; Owner: -
--

CREATE FUNCTION gridex_received_reading_expectations.instant_v1(value text, format text, offset_minutes integer) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$DECLARE v timestamp;BEGIN
 IF (format='102' AND value~'^[0-9]{8}$') THEN v:=make_timestamp(substring(value,1,4)::int,substring(value,5,2)::int,substring(value,7,2)::int,0,0,0);
 ELSIF format IN('203','204') AND value~'^[0-9]{12}([0-9]{2})?$' AND length(value)=(CASE format WHEN '203' THEN 12 ELSE 14 END) THEN
 v:=make_timestamp(substring(value,1,4)::int,substring(value,5,2)::int,substring(value,7,2)::int,substring(value,9,2)::int,substring(value,11,2)::int,CASE format WHEN '204' THEN substring(value,13,2)::int ELSE 0 END);
 ELSE RETURN NULL;END IF;RETURN(v-make_interval(mins=>offset_minutes)) AT TIME ZONE 'UTC';EXCEPTION WHEN datetime_field_overflow OR invalid_datetime_format THEN RETURN NULL;END$_$;

REVOKE ALL ON FUNCTION gridex_received_reading_expectations.instant_v1(text, text, integer) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:899
--
-- Name: source_contracts_v1(uuid, text, uuid); Type: FUNCTION; Schema: gridex_received_reading_expectations; Owner: -
--

CREATE FUNCTION gridex_received_reading_expectations.source_contracts_v1(c uuid, env text, msg uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r record;s gridex_received_sources.sources%rowtype;a gridex_received_sources.object_assessments%rowtype;f gridex_received_sources.prodat_ignored_field_facets%rowtype;
 own jsonb;assessed jsonb;business jsonb;wire jsonb;qualified jsonb;registers jsonb;expected jsonb;mode text;out jsonb:='[]';first_line integer;
BEGIN
 FOR r IN SELECT payload_hash,canonical_assessment_id,object_assessment_id,source_received_at,applied_at,objects FROM gridex_received_sources.structural_apply_receipts WHERE company_id=c AND environment=env AND source_message_id=msg
 UNION ALL SELECT payload_hash,canonical_assessment_id,object_assessment_id,source_received_at,applied_at,jsonb_build_array(effect) FROM gridex_received_sources.structural_object_apply_receipts WHERE company_id=c AND environment=env AND source_message_id=msg LOOP
  SELECT * INTO s FROM gridex_received_sources.sources WHERE company_id=c AND environment=env AND source_message_id=msg;
  SELECT * INTO a FROM gridex_received_sources.object_assessments WHERE id=r.object_assessment_id AND company_id=c AND environment=env AND source_message_id=msg;
  SELECT * INTO f FROM gridex_received_sources.prodat_ignored_field_facets WHERE canonical_assessment_id=r.canonical_assessment_id AND company_id=c AND environment=env AND source_message_id=msg;
  IF s.source_message_id IS NULL OR a.id IS NULL OR f.canonical_assessment_id IS NULL OR s.payload_hash IS DISTINCT FROM r.payload_hash
   OR s.payload_hash IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') OR a.source_payload_hash IS DISTINCT FROM s.payload_hash
   OR a.canonical_assessment_id IS DISTINCT FROM r.canonical_assessment_id OR a.facts_hash IS DISTINCT FROM encode(sha256(convert_to(a.facts_text,'UTF8')),'hex')
   OR NOT EXISTS(SELECT FROM public.ediel_messages original WHERE original.id=msg AND original.company_id=c AND original.environment=env AND original.direction='inbound' AND original.message_family='PRODAT' AND original.message_code='Z06' AND original.raw_payload=s.raw_payload AND original.message_received_at=s.source_received_at)
   OR f.source_payload_hash IS DISTINCT FROM s.payload_hash OR f.fields_hash IS DISTINCT FROM encode(sha256(convert_to(f.fields_text,'UTF8')),'hex') THEN CONTINUE;END IF;
  FOR own IN SELECT value FROM jsonb_array_elements(r.objects) LOOP
   SELECT value INTO assessed FROM jsonb_array_elements(a.facts_text::jsonb->'objects') value WHERE value->'object'=own->'object';
   business:=assessed->'business';wire:=business->'wire';first_line:=(own#>>'{object,registers,0,segmentIndex}')::integer;
   IF assessed->>'disposition' IS DISTINCT FROM 'accepted' OR business->>'owner' IS DISTINCT FROM 'reviewed-received-structure-v1'
    OR wire IS DISTINCT FROM own->'wire' OR wire->>'messageCode' IS DISTINCT FROM 'Z06' OR wire->>'businessCase' IS DISTINCT FROM 'change_with_reading'
    OR business->>'companyId' IS DISTINCT FROM c::text OR business->>'environment' IS DISTINCT FROM env
    OR business->>'meteringPointId' IS DISTINCT FROM own->>'meteringPointId' OR business->>'siteId' IS DISTINCT FROM own->>'siteId'
    OR nullif(business->>'customerId','') IS NULL OR nullif(business->>'supplyPeriodId','') IS NULL OR first_line IS NULL
    OR wire#>>'{effectiveFrom,utc}' IS NULL OR (wire#>>'{effectiveFrom,utc}')::timestamptz IS DISTINCT FROM (own->>'effectiveAt')::timestamptz
    OR gridex_received_sources.structural_effect_matches_v1(c,env,msg,a.id,(business->>'customerId')::uuid,(business->>'siteId')::uuid,(business->>'meteringPointId')::uuid,(business->>'supplyPeriodId')::uuid,own#>>'{object,objectId}',own#>>'{object,identityAgency}',r.applied_at) IS NOT TRUE THEN CONTINUE;END IF;
   SELECT value INTO qualified FROM jsonb_array_elements(gridex_received_sources.applied_structural_method_objects_v1(c,msg)) value
    WHERE value->>'objectId'=own#>>'{object,objectId}' AND value->>'identityAgency'=own#>>'{object,identityAgency}' AND value->>'businessCase'='change_with_reading';
   IF qualified IS NULL OR qualified->>'companyId' IS DISTINCT FROM c::text OR qualified->>'environment' IS DISTINCT FROM env OR qualified->>'sourceMessageId' IS DISTINCT FROM msg::text OR qualified->>'sourcePayloadHash' IS DISTINCT FROM s.payload_hash OR qualified->>'customerId' IS DISTINCT FROM business->>'customerId' OR qualified->>'meteringPointId' IS DISTINCT FROM business->>'meteringPointId'
    OR qualified->>'measurementMethod' IS NULL THEN CONTINUE;END IF;
   -- Original field259 identifies promised meter readings. An ignored physical
   -- value never becomes an expected register. No incoming UTILTS fills gaps.
   registers:=wire->'registers';
   IF EXISTS(SELECT FROM jsonb_array_elements(f.fields_text::jsonb) ignored WHERE ignored->>'fieldNumber' IN('259','224')
    AND ignored#>>'{occurrence,objectId}'=own#>>'{object,objectId}' AND ignored#>>'{occurrence,identityAgency}'=own#>>'{object,identityAgency}') THEN registers:=NULL;END IF;
   SELECT jsonb_agg(value->'registerId' ORDER BY (value->>'position')::int) INTO expected FROM jsonb_array_elements(registers) value;
   mode:=CASE WHEN expected IS NOT NULL AND jsonb_array_length(expected)>0 AND NOT EXISTS(SELECT FROM jsonb_array_elements(expected) value WHERE value='null'::jsonb OR value='""'::jsonb)
      AND (SELECT count(DISTINCT value) FROM jsonb_array_elements(expected))=jsonb_array_length(expected) AND nullif(wire->>'meterNumber','') IS NOT NULL THEN 'meter_reading'
     ELSE 'subsequent_values' END;
   out:=out||jsonb_build_array(jsonb_build_object('version',1,'owner','applied-z06f-reading-followup-v1','companyId',c,'environment',env,'sourceMessageId',msg,
    'sourcePayloadHash',s.payload_hash,'canonicalAssessmentId',r.canonical_assessment_id,'objectAssessmentId',a.id,'objectFactsHash',a.facts_hash,
    'firstLineIndex',first_line,'object',own->'object','wire',wire,'customerId',business->>'customerId','siteId',business->>'siteId','meteringPointId',business->>'meteringPointId',
    'supplyPeriodId',business->>'supplyPeriodId','coverage',business->'coverageWindow','replaces',business->'replaces','measurementMethod',qualified->>'measurementMethod',
    'effectiveAt',own->'effectiveAt','sourceReceivedAt',s.source_received_at,'appliedAt',r.applied_at,'mode',mode,'expectedRegisterIds',expected,
    'deadline',NULL,'automaticRequestAllowed',false));
  END LOOP;
 END LOOP;
 RETURN out;
END$$;

REVOKE ALL ON FUNCTION gridex_received_reading_expectations.source_contracts_v1(uuid, text, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:900
--
-- Name: activate_supply_before_source_guard_v1(uuid, uuid, uuid, date, uuid, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.activate_supply_before_source_guard_v1(p_company_id uuid, p_supplier_switch_request_id uuid, p_source_message_id uuid, p_actual_start_date date DEFAULT NULL::date, p_actor_user_id uuid DEFAULT NULL::uuid, p_idempotency_key text DEFAULT NULL::text) RETURNS TABLE(supplier_switch_request_id uuid, supply_period_id uuid, contract_id uuid, customer_application_id uuid, workflow_id uuid, domain_event_id uuid, notification_job_id uuid)
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
declare
  v_switch public.supplier_switch_requests%rowtype;
  v_period_id uuid;
  v_contract_id uuid;
  v_application_id uuid;
  v_workflow public.customer_application_workflows%rowtype;
  v_event_id uuid;
  v_job_id uuid;
  v_start_date date;
  v_key text;
  v_now timestamptz := now();
  v_tenant_reference text;
begin
  if p_company_id is null then
    raise exception 'supply_activation_company_required' using errcode = '22023';
  end if;
  if p_supplier_switch_request_id is null then
    raise exception 'supply_activation_switch_required' using errcode = '22023';
  end if;
  if p_source_message_id is null then
    raise exception 'supply_activation_source_message_required' using errcode = '22023';
  end if;

  select * into v_switch
  from public.supplier_switch_requests
  where id = p_supplier_switch_request_id
    and company_id = p_company_id
  for update;

  if not found then
    raise exception 'supply_activation_switch_not_found' using errcode = 'P0002';
  end if;
  if v_switch.customer_id is null then
    raise exception 'supply_activation_customer_required' using errcode = '23502';
  end if;
  if v_switch.metering_point_id is null then
    raise exception 'supply_activation_metering_point_required' using errcode = '23502';
  end if;

  v_contract_id := coalesce(v_switch.contract_id, v_switch.customer_contract_id);
  if v_contract_id is null then
    raise exception 'supply_activation_contract_required' using errcode = '23502';
  end if;
  if v_switch.status not in (
    'confirmed',
    'accepted',
    'completed'
  ) then
    raise exception 'supply_activation_switch_not_confirmed' using errcode = '23514';
  end if;

  if not exists(
    select 1
    from public.customer_contracts cc
    join public.metering_points mp
      on mp.id=v_switch.metering_point_id
     and mp.company_id=cc.company_id
     and mp.customer_id=cc.customer_id
    left join public.customer_sites cs
      on cs.id=coalesce(v_switch.customer_site_id,v_switch.site_id)
     and cs.company_id=cc.company_id
     and cs.customer_id=cc.customer_id
    where cc.id=v_contract_id
      and cc.company_id=p_company_id
      and cc.customer_id=v_switch.customer_id
      and (
        coalesce(v_switch.customer_site_id,v_switch.site_id) is null
        or cs.id is not null
      )
  ) then
    raise exception using
      errcode='23514',
      message='supply_activation_customer_contract_site_meter_mismatch';
  end if;

  v_start_date := coalesce(
    p_actual_start_date,
    v_switch.confirmed_start_date,
    v_switch.requested_start_date
  );
  if v_start_date is null then
    raise exception 'supply_activation_start_date_required' using errcode = '23502';
  end if;
  v_key := coalesce(
    nullif(btrim(p_idempotency_key), ''),
    format('activate_customer_supply_v1:%s:%s', p_company_id, p_supplier_switch_request_id)
  );

  insert into public.customer_supply_periods(
    company_id,
    customer_id,
    metering_point_id,
    contract_id,
    start_date,
    actual_start_date,
    source,
    source_process,
    source_message_id,
    source_switch_request_id,
    status,
    metadata,
    updated_at
  ) values (
    p_company_id,
    v_switch.customer_id,
    v_switch.metering_point_id,
    v_contract_id,
    v_start_date,
    v_start_date,
    'activate_customer_supply_v1',
    'supplier_switch_confirmation',
    p_source_message_id,
    v_switch.id,
    'active',
    jsonb_build_object(
      'activation_idempotency_key', v_key,
      'activated_at', v_now
    ),
    v_now
  )
  on conflict (company_id, metering_point_id, start_date)
    where status in ('active', 'confirmed_by_grid_owner')
  do update set
    customer_id = excluded.customer_id,
    contract_id = excluded.contract_id,
    actual_start_date = coalesce(public.customer_supply_periods.actual_start_date, excluded.actual_start_date),
    source_message_id = excluded.source_message_id,
    source_switch_request_id = excluded.source_switch_request_id,
    status = 'active',
    metadata = coalesce(public.customer_supply_periods.metadata, '{}'::jsonb)
      || excluded.metadata,
    updated_at = excluded.updated_at
  returning id into v_period_id;

  update public.supplier_switch_requests
  set status = 'completed',
      confirmed_start_date = coalesce(confirmed_start_date, v_start_date),
      completed_at = coalesce(completed_at, v_now),
      external_reference = coalesce(external_reference, v_key),
      inbound_z04_message_id = coalesce(inbound_z04_message_id, p_source_message_id),
      lifecycle_blocked = false,
      lifecycle_block_source = null,
      updated_at = v_now
  where id = v_switch.id
    and company_id = p_company_id;

  update public.customer_contracts
  set status = 'active',
      lifecycle_stage = 'active',
      actual_start_date = coalesce(actual_start_date, v_start_date),
      confirmed_start_date = coalesce(confirmed_start_date, v_start_date),
      billing_eligible_at = coalesce(billing_eligible_at, v_now),
      billing_eligibility_source = coalesce(
        billing_eligibility_source,
        'activate_customer_supply_v1'
      ),
      metadata = coalesce(metadata, '{}'::jsonb) || jsonb_build_object(
        'supply_period_id', v_period_id,
        'supplier_switch_request_id', v_switch.id,
        'activation_source_message_id', p_source_message_id
      ),
      updated_at = v_now
  where id = v_contract_id
    and company_id = p_company_id
    and customer_id = v_switch.customer_id
    and status in ('signed', 'active');

  if not found then
    raise exception 'supply_activation_contract_not_activatable' using errcode = '23514';
  end if;

  select workflow.* into v_workflow
  from public.customer_application_workflows workflow
  where workflow.company_id = p_company_id
    and workflow.customer_id = v_switch.customer_id
    and workflow.contract_id = v_contract_id
  order by created_at desc
  limit 1
  for update;

  if found then
    v_application_id := v_workflow.customer_application_id;

    insert into public.customer_application_workflow_events(
      company_id,
      workflow_id,
      customer_application_id,
      operation_id,
      from_state,
      to_state,
      event_code,
      actor_user_id,
      metadata,
      idempotency_key
    ) values (
      p_company_id,
      v_workflow.id,
      v_workflow.customer_application_id,
      v_workflow.operation_id,
      v_workflow.state,
      'completed',
      'workflow.supply_activated',
      p_actor_user_id,
      jsonb_build_object(
        'supply_period_id', v_period_id,
        'supplier_switch_request_id', v_switch.id,
        'actual_start_date', v_start_date
      ),
      v_key || ':workflow'
    )
    on conflict (company_id, idempotency_key) do nothing;

    update public.customer_application_workflows
    set state = 'completed',
        next_action = 'none',
        completed_at = coalesce(completed_at, v_now),
        last_transition_at = v_now,
        workflow_version = case
          when state = 'completed' then workflow_version
          else workflow_version + 1
        end,
        snapshot = coalesce(snapshot, '{}'::jsonb) || jsonb_build_object(
          'supply_period_id', v_period_id,
          'supplier_switch_request_id', v_switch.id,
          'actual_start_date', v_start_date,
          'billing_eligible_at', v_now,
          'next_action', 'none'
        ),
        updated_at = v_now
    where id = v_workflow.id;

    update public.website_customer_applications
    set status = 'active',
        actual_start_date = coalesce(actual_start_date, v_start_date),
        next_step = 'none',
        updated_at = v_now
    where id = v_application_id
      and company_id = p_company_id;
  end if;

  insert into public.domain_events(
    company_id,
    event_type,
    aggregate_type,
    aggregate_id,
    subject_customer_id,
    actor_user_id,
    source,
    idempotency_key,
    payload,
    occurred_at
  ) values (
    p_company_id,
    'supply.started',
    'customer_supply_period',
    v_period_id::text,
    v_switch.customer_id,
    p_actor_user_id,
    'activate_customer_supply_v1',
    v_key || ':domain_event',
    jsonb_build_object(
      'customer_id', v_switch.customer_id,
      'contract_id', v_contract_id,
      'customer_site_id', coalesce(v_switch.customer_site_id, v_switch.site_id),
      'metering_point_id', v_switch.metering_point_id,
      'supplier_switch_request_id', v_switch.id,
      'supply_period_id', v_period_id,
      'actual_start_date', v_start_date,
      'billing_eligible_at', v_now
    ),
    v_now
  )
  on conflict (idempotency_key) where idempotency_key is not null
  do nothing
  returning id into v_event_id;

  if v_event_id is null then
    select id into v_event_id
    from public.domain_events
    where idempotency_key = v_key || ':domain_event';
  end if;

  insert into public.customer_operation_jobs(
    company_id,
    customer_id,
    customer_site_id,
    metering_point_id,
    job_type,
    status,
    priority,
    idempotency_key,
    payload,
    request_snapshot,
    run_after,
    created_by,
    updated_at
  ) values (
    p_company_id,
    v_switch.customer_id,
    coalesce(v_switch.customer_site_id, v_switch.site_id),
    v_switch.metering_point_id,
    'dispatch_lifecycle_notification',
    'queued',
    40,
    'lifecycle_notification:' || v_key || ':customer.welcome_active',
    jsonb_build_object(
      'event_type', 'supply_period.activated',
      'source_event_id', v_event_id,
      'contract_id', v_contract_id,
      'payload', jsonb_build_object(
        'start_date', v_start_date,
        'supply_period_id', v_period_id
      )
    ),
    jsonb_build_object(
      'domain_event_id', v_event_id,
      'supplier_switch_request_id', v_switch.id
    ),
    v_now,
    p_actor_user_id,
    v_now
  )
  on conflict do nothing
  returning id into v_job_id;

  if v_job_id is null then
    select id into v_job_id
    from public.customer_operation_jobs
    where company_id = p_company_id
      and job_type = 'dispatch_lifecycle_notification'
      and idempotency_key = 'lifecycle_notification:' || v_key || ':customer.welcome_active'
    order by created_at desc
    limit 1;
  end if;

  select external_tenant_reference into v_tenant_reference
  from public.companies
  where id = p_company_id;

  insert into public.webhook_deliveries(
    company_id,
    webhook_subscription_id,
    domain_event_id,
    event_type,
    max_attempts,
    target_url,
    idempotency_key,
    payload
  )
  select
    p_company_id,
    subscription.id,
    v_event_id,
    'supply.started',
    subscription.max_attempts,
    subscription.endpoint_url,
    format('webhook:%s:%s', subscription.id, v_event_id),
    jsonb_build_object(
      'id', v_event_id,
      'type', 'supply.started',
      'event_id', v_event_id,
      'event_type', 'supply.started',
      'created_at', v_now,
      'tenant_reference', v_tenant_reference,
      'customer_id', v_switch.customer_id,
      'aggregate', jsonb_build_object(
        'type', 'customer_supply_period',
        'id', v_period_id
      ),
      'data', jsonb_build_object(
        'contract_id', v_contract_id,
        'supplier_switch_request_id', v_switch.id,
        'supply_period_id', v_period_id,
        'actual_start_date', v_start_date
      )
    )
  from public.webhook_subscriptions subscription
  where subscription.company_id = p_company_id
    and subscription.status = 'active'
    and (
      '*' = any(coalesce(subscription.event_types, '{}'::text[]))
      or 'supply.started' = any(coalesce(subscription.event_types, '{}'::text[]))
    )
  on conflict (idempotency_key) do nothing;

  return query select
    v_switch.id,
    v_period_id,
    v_contract_id,
    v_application_id,
    v_workflow.id,
    v_event_id,
    v_job_id;
end;
$$;

REVOKE ALL ON FUNCTION gridex_received_sources.activate_supply_before_source_guard_v1(uuid, uuid, uuid, date, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:907
--
-- Name: append_prodat_validation_v2(uuid, text, uuid, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_prodat_validation_v2(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text, p_ignored_fields_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt jsonb;fields jsonb;field jsonb;occ jsonb;s gridex_received_sources.sources%rowtype;a gridex_received_sources.validation_assessments%rowtype;tokens jsonb;line jsonb;digest text;
BEGIN
 -- Canonical source admission/whole register scope remain their prior owner.
 -- This transaction adds only the exclusion list from that same invocation.
 receipt:=gridex_received_sources.append_validation(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text);
 SELECT * INTO STRICT a FROM gridex_received_sources.validation_assessments WHERE id=(receipt->>'assessmentId')::uuid AND company_id=p_company_id AND environment=p_environment;
 SELECT * INTO STRICT s FROM gridex_received_sources.sources WHERE source_message_id=p_source_message_id AND company_id=p_company_id AND environment=p_environment;
 IF s.payload_hash IS DISTINCT FROM p_source_payload_hash OR a.source_message_id IS DISTINCT FROM s.source_message_id
  OR a.facts_text IS DISTINCT FROM p_facts_text OR a.facts_hash IS DISTINCT FROM receipt->>'factsHash' THEN RAISE EXCEPTION 'prodat_ignored_same_original_required';END IF;
 IF p_ignored_fields_text IS NOT NULL THEN
  tokens:=gridex_received_sources.closure_wire_tokens_v2(s.raw_payload);
  IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNH' AND t#>>'{elements,2,0}'='PRODAT')<>1 THEN RAISE EXCEPTION 'prodat_ignored_same_original_required';END IF;
  IF octet_length(p_ignored_fields_text)>262144 THEN RAISE EXCEPTION 'prodat_ignored_field_budget_exceeded';END IF;fields:=p_ignored_fields_text::jsonb;
  IF jsonb_typeof(fields) IS DISTINCT FROM 'array' OR jsonb_array_length(fields)>8192 OR a.facts_text::jsonb->'registerValidation' IS NULL THEN RAISE EXCEPTION 'prodat_ignored_canonical_scope_required';END IF;
  FOR field IN SELECT value FROM jsonb_array_elements(fields) LOOP
   occ:=field->'occurrence';
   IF jsonb_typeof(field) IS DISTINCT FROM 'object' OR field-ARRAY['fieldNumber','sourceRule','occurrence']<>'{}'::jsonb
    OR field->>'sourceRule' IS DISTINCT FROM 'PRODAT26A:P119' OR nullif(field->>'fieldNumber','') IS NULL
    OR jsonb_typeof(occ) IS DISTINCT FROM 'object' OR (occ->>'scope' IN('header','object','register')) IS NOT TRUE
    OR occ->>'messageReference' IS DISTINCT FROM a.facts_text::jsonb->>'messageReference' THEN RAISE EXCEPTION 'prodat_ignored_field_scope_invalid';END IF;
   IF occ->>'scope'<>'header' THEN
    SELECT t INTO line FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LIN' AND (SELECT count(*) FROM jsonb_array_elements(tokens) prior WHERE prior->>'tag'='LIN' AND (prior->>'index')::integer<(t->>'index')::integer)=(occ->>'lineIndex')::integer;
    IF line IS NULL OR line#>>'{elements,1,0}' IS DISTINCT FROM occ->>'lineNumber' OR line#>>'{elements,3,0}' IS DISTINCT FROM occ->>'objectId'
     OR line#>>'{elements,3,3}' IS DISTINCT FROM occ->>'identityAgency' THEN RAISE EXCEPTION 'prodat_ignored_field_physical_scope_invalid';END IF;
   END IF;
  END LOOP;
  digest:=encode(sha256(convert_to(p_ignored_fields_text,'UTF8')),'hex');
  INSERT INTO gridex_received_sources.prodat_ignored_field_facets(canonical_assessment_id,company_id,environment,source_message_id,source_payload_hash,fields_text,fields_hash)
   VALUES(a.id,p_company_id,p_environment,s.source_message_id,s.payload_hash,p_ignored_fields_text,digest);
 END IF;
 RETURN receipt||jsonb_build_object('version',2,'ignoredFieldsHash',digest);
END $$;

REVOKE ALL ON FUNCTION gridex_received_sources.append_prodat_validation_v2(uuid, text, uuid, text, text, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:908
--
-- Name: append_prodat_validation_v3(uuid, text, uuid, text, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_prodat_validation_v3(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text, p_ignored_fields_text text, p_object_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt jsonb;facet_receipt jsonb;assessment_id uuid;
BEGIN
 receipt:=gridex_received_sources.append_prodat_validation_v2(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text,p_ignored_fields_text);
 assessment_id:=(receipt->>'assessmentId')::uuid;
 IF p_object_facts_text IS NOT NULL THEN
  facet_receipt:=public.gridex_record_prodat_object_validation_v1(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,assessment_id,p_object_facts_text);
  IF facet_receipt->>'assessmentId' IS DISTINCT FROM assessment_id::text OR facet_receipt->>'companyId' IS DISTINCT FROM p_company_id::text
   OR facet_receipt->>'environment' IS DISTINCT FROM p_environment OR facet_receipt->>'sourceMessageId' IS DISTINCT FROM p_source_message_id::text
   OR facet_receipt->>'sourcePayloadHash' IS DISTINCT FROM p_source_payload_hash
   OR facet_receipt->>'objectFactsHash' IS DISTINCT FROM encode(sha256(convert_to(p_object_facts_text,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_primary_object_receipt_required';END IF;
 END IF;
 RETURN receipt||jsonb_build_object('version',3,'objectFactsHash',facet_receipt->>'objectFactsHash');
END $$;

REVOKE ALL ON FUNCTION gridex_received_sources.append_prodat_validation_v3(uuid, text, uuid, text, text, text, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:911
--
-- Name: append_prodat_validation_v6(uuid, text, uuid, text, text, text, text, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_prodat_validation_v6(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text, p_ignored_fields_text text, p_object_facts_text text, p_response_facts_text text, p_application_facts_text text, p_source_function_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE receipt jsonb;s gridex_received_sources.sources%rowtype;m public.ediel_messages%rowtype;facts jsonb;response jsonb;application jsonb;functional jsonb;functional_own jsonb;objects jsonb;own jsonb;reg jsonb;app jsonb;planned jsonb;response_hash text;application_hash text;function_hash text;assessment uuid;replay_candidate uuid;replay_rule_pack uuid;replay_rollback boolean:=false;
BEGIN
 -- Current actual authorization graph comes before any ledger/source/market
 -- lock. Writer-compatible facet locks precede the common graph's SHARE ledger
 -- locks, so two primary writers cannot deadlock while upgrading SHARE locks.
 PERFORM gridex_received_sources.lock_prodat_execution_actor_graph_v1();
 LOCK TABLE gridex_received_sources.validation_assessments,gridex_received_sources.prodat_ignored_field_facets,gridex_received_sources.prodat_object_validation_facets,gridex_received_sources.prodat_response_facets,gridex_received_sources.prodat_application_facets,gridex_received_sources.prodat_source_function_facets IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE gridex_customer_life_events.inbound_context_receipts IN SHARE MODE;
 PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id AND environment=p_environment FOR UPDATE;
 SELECT * INTO s FROM gridex_received_sources.sources WHERE source_message_id=p_source_message_id AND company_id=p_company_id AND environment=p_environment FOR UPDATE;
 IF m.id IS NULL OR s.source_message_id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR s.raw_payload IS NULL OR s.raw_payload IS DISTINCT FROM m.raw_payload OR s.payload_hash IS DISTINCT FROM p_source_payload_hash OR s.payload_hash IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_v6_same_original_required';END IF;
 PERFORM public.ediel_require_source_bytes_available_v1(p_company_id,p_source_message_id);
 facts:=p_facts_text::jsonb;
 IF p_response_facts_text IS NOT NULL THEN
  IF octet_length(p_response_facts_text)>524288 THEN RAISE EXCEPTION 'prodat_response_same_owner_required';END IF;
  response:=p_response_facts_text::jsonb;
  IF NOT coalesce(gridex_received_sources.validate_prodat_responses_v1(s.raw_payload,facts,response),false) THEN RAISE EXCEPTION 'prodat_response_same_owner_required';END IF;
  response_hash:=encode(sha256(convert_to(p_response_facts_text,'UTF8')),'hex');
 END IF;
 IF p_source_function_facts_text IS NOT NULL THEN
  IF octet_length(p_source_function_facts_text)>524288 OR p_application_facts_text IS NULL THEN RAISE EXCEPTION 'prodat_source_function_same_owner_required';END IF;
  functional:=p_source_function_facts_text::jsonb;
  IF gridex_received_sources.validate_prodat_source_function_v1(p_company_id,p_source_message_id,s.raw_payload,facts,functional) IS NOT TRUE THEN RAISE EXCEPTION 'prodat_source_function_same_owner_required';END IF;
  function_hash:=encode(sha256(convert_to(p_source_function_facts_text,'UTF8')),'hex');
 END IF;
 IF p_application_facts_text IS NOT NULL THEN
  IF octet_length(p_application_facts_text)>524288 THEN RAISE EXCEPTION 'prodat_application_same_owner_required';END IF;
  application:=p_application_facts_text::jsonb;
  IF NOT coalesce(gridex_received_sources.validate_prodat_application_v2(p_company_id,p_source_message_id,s.raw_payload,facts,application,response,functional),false) THEN RAISE EXCEPTION 'prodat_application_same_owner_required';END IF;
  application_hash:=encode(sha256(convert_to(p_application_facts_text,'UTF8')),'hex');
 END IF;
 IF p_object_facts_text IS NOT NULL THEN
  objects:=p_object_facts_text::jsonb;
  -- The physical register partition is the common join between the full-guide
  -- lineIndex, application register scopes and response segmentIndex. Different
  -- indexes or a negative sibling cannot borrow a positive facet. A separately
  -- authenticated customer source function never promotes full-guide evidence:
  -- its exact own application may stand independently of a global function hold.
  FOR own IN SELECT e FROM jsonb_array_elements(objects->'objects')e LOOP
   SELECT e INTO reg FROM jsonb_array_elements(facts#>'{registerValidation,objects}')e WHERE e->'objectId'=own->'objectId' AND e->'identityAgency'=own->'identityAgency' AND e->'messageReference'=own->'messageReference' AND e#>'{registers,0,lineIndex}'=own->'firstLineIndex';
   IF reg IS NULL THEN RAISE EXCEPTION 'prodat_v6_same_physical_partition_required';END IF;
   functional_own:=NULL;
   IF functional IS NOT NULL THEN
    SELECT e INTO functional_own FROM jsonb_array_elements(functional->'objects')e WHERE e-'functionalDecision'-'reasonCodes'=reg-'disposition'-'reasons';
    IF functional_own IS NULL THEN RAISE EXCEPTION 'prodat_v6_same_function_partition_required';END IF;
   END IF;
   IF application IS NOT NULL THEN
    SELECT e INTO app FROM jsonb_array_elements(application->'objects')e WHERE e-'applicationDecision'-'reasonCodes'=reg-'disposition'-'reasons';
    IF app IS NULL OR own->>'disposition'='accepted' AND app->>'applicationDecision' IS DISTINCT FROM 'accepted'
      OR own->>'disposition'='rejected' AND app->>'applicationDecision' IS DISTINCT FROM 'rejected'
      OR own->>'disposition'='unavailable' AND app->>'applicationDecision'='accepted' AND (functional_own->>'functionalDecision' IS DISTINCT FROM 'accepted' OR own->'reasons' IS DISTINCT FROM '["shared_source_not_qualified"]'::jsonb) THEN RAISE EXCEPTION 'prodat_v6_conflicting_own_application';END IF;
   END IF;
   IF response IS NOT NULL THEN
    SELECT e INTO planned FROM jsonb_array_elements(response->'objects')e WHERE e->'lineIndex'=reg#>'{registers,0,segmentIndex}';
    IF planned IS NULL OR planned->'id' IS DISTINCT FROM own->'objectId' OR nullif(planned->'li','null'::jsonb) IS DISTINCT FROM to_jsonb(nullif(own->>'lineItemReference',''))
     OR planned->>'outcome'='positive' AND ((own->>'disposition' IS DISTINCT FROM 'accepted' AND (functional_own->>'functionalDecision' IS DISTINCT FROM 'accepted' OR app->>'applicationDecision' IS DISTINCT FROM 'accepted' OR own->>'disposition' IS DISTINCT FROM 'unavailable' OR own->'reasons' IS DISTINCT FROM '["shared_source_not_qualified"]'::jsonb)) OR application IS NOT NULL AND app->>'applicationDecision' IS DISTINCT FROM 'accepted') THEN RAISE EXCEPTION 'prodat_v6_conflicting_own_response';END IF;
   END IF;
  END LOOP;
 END IF;
 -- Retain registry authority locks through an equivalent-append rollback.
 -- The inherited validator below still verifies every locked snapshot byte.
 IF facts->>'applicationDecision'='accepted' THEN
  LOCK TABLE public.ediel_rule_pack_sources IN SHARE MODE;
  SELECT id INTO replay_rule_pack FROM public.ediel_rule_packs
   WHERE id::text=facts#>>'{rulePackEvidence,rulePackId}'
    AND source_hash=facts#>>'{rulePackEvidence,sourceHash}' FOR SHARE;
  PERFORM 1 FROM public.ediel_message_profiles
   WHERE id::text=facts#>>'{rulePackEvidence,messageProfileId}'
    AND rule_pack_id=replay_rule_pack
    AND profile_key=facts#>>'{rulePackEvidence,profileKey}' FOR SHARE;
 END IF;
 -- Count every leaf before matching: no ancestor, ambiguous branch or ABA reuse.
 WITH leaves AS (
  SELECT v.id FROM gridex_received_sources.validation_assessments v
   WHERE v.source_message_id=p_source_message_id
    AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)
 ) SELECT id INTO replay_candidate FROM leaves WHERE (SELECT count(*) FROM leaves)=1;
 BEGIN
 -- This is the sole primary append. Existing full-object v3 invokes the prior
 -- canonical/ignored owner and inserts its own facet under this assessment.
 receipt:=gridex_received_sources.append_prodat_validation_v3(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text,p_ignored_fields_text,p_object_facts_text);
 assessment:=(receipt->>'assessmentId')::uuid;
 IF receipt->>'companyId' IS DISTINCT FROM p_company_id::text OR receipt->>'environment' IS DISTINCT FROM p_environment OR receipt->>'sourceMessageId' IS DISTINCT FROM p_source_message_id::text OR receipt->>'sourcePayloadHash' IS DISTINCT FROM p_source_payload_hash OR receipt->>'factsHash' IS DISTINCT FROM encode(sha256(convert_to(p_facts_text,'UTF8')),'hex') OR receipt->>'objectFactsHash' IS DISTINCT FROM (CASE WHEN p_object_facts_text IS NULL THEN NULL ELSE encode(sha256(convert_to(p_object_facts_text,'UTF8')),'hex') END) THEN RAISE EXCEPTION 'prodat_v6_primary_receipt_required';END IF;
 IF response IS NOT NULL THEN
  IF EXISTS(SELECT FROM gridex_received_sources.prodat_response_facets prior WHERE prior.assessment_id=assessment AND(prior.response_facts_hash IS DISTINCT FROM response_hash OR prior.company_id IS DISTINCT FROM p_company_id OR prior.environment IS DISTINCT FROM p_environment OR prior.source_message_id IS DISTINCT FROM p_source_message_id OR prior.source_payload_hash IS DISTINCT FROM p_source_payload_hash)) THEN RAISE EXCEPTION 'prodat_v6_response_replay_conflict';END IF;
  INSERT INTO gridex_received_sources.prodat_response_facets VALUES(assessment,p_source_message_id,p_company_id,p_environment,p_source_payload_hash,p_response_facts_text,response_hash) ON CONFLICT DO NOTHING;
 END IF;
 IF application IS NOT NULL THEN
  IF EXISTS(SELECT FROM gridex_received_sources.prodat_application_facets prior WHERE prior.assessment_id=assessment AND(prior.application_facts_hash IS DISTINCT FROM application_hash OR prior.company_id IS DISTINCT FROM p_company_id OR prior.environment IS DISTINCT FROM p_environment OR prior.source_message_id IS DISTINCT FROM p_source_message_id OR prior.source_payload_hash IS DISTINCT FROM p_source_payload_hash)) THEN RAISE EXCEPTION 'prodat_v6_application_replay_conflict';END IF;
  INSERT INTO gridex_received_sources.prodat_application_facets VALUES(assessment,p_source_message_id,p_company_id,p_environment,p_source_payload_hash,p_application_facts_text,application_hash) ON CONFLICT DO NOTHING;
 END IF;
 IF functional IS NOT NULL THEN
  IF EXISTS(SELECT FROM gridex_received_sources.prodat_source_function_facets prior WHERE prior.assessment_id=assessment AND(prior.function_facts_hash IS DISTINCT FROM function_hash OR prior.company_id IS DISTINCT FROM p_company_id OR prior.environment IS DISTINCT FROM p_environment OR prior.source_message_id IS DISTINCT FROM p_source_message_id OR prior.source_payload_hash IS DISTINCT FROM p_source_payload_hash)) THEN RAISE EXCEPTION 'prodat_v6_source_function_replay_conflict';END IF;
  INSERT INTO gridex_received_sources.prodat_source_function_facets VALUES(assessment,p_source_message_id,p_company_id,p_environment,p_source_payload_hash,p_source_function_facts_text,function_hash) ON CONFLICT DO NOTHING;
 END IF;
 -- Only a fully validated identical positive leaf can retain its identity.
 -- The redundant child and its facets have not committed; rollback does not
 -- delete or rewrite any existing history, receipt, ACK or market effect.
 IF replay_candidate IS NOT NULL AND assessment IS DISTINCT FROM replay_candidate
  AND facts->>'syntaxDecision'='accepted' AND facts->>'applicationDecision'='accepted'
  AND facts->>'functionalDecision'='accepted'
  AND EXISTS(SELECT FROM gridex_received_sources.validation_assessments v
   LEFT JOIN gridex_received_sources.prodat_ignored_field_facets ignored ON ignored.canonical_assessment_id=v.id
   LEFT JOIN gridex_received_sources.prodat_object_validation_facets object ON object.assessment_id=v.id
   LEFT JOIN gridex_received_sources.prodat_response_facets response_facet ON response_facet.assessment_id=v.id
   LEFT JOIN gridex_received_sources.prodat_application_facets application_facet ON application_facet.assessment_id=v.id
   LEFT JOIN gridex_received_sources.prodat_source_function_facets function_facet ON function_facet.assessment_id=v.id
   WHERE v.id=replay_candidate
    AND v.owner='canonical-runtime-with-registry-v1'
    AND v.company_id=p_company_id
    AND v.environment=p_environment
    AND v.source_message_id=p_source_message_id
    AND v.source_payload_hash=p_source_payload_hash
    AND v.facts_text IS NOT DISTINCT FROM p_facts_text
    AND v.facts_hash=encode(sha256(convert_to(p_facts_text,'UTF8')),'hex')
    AND EXISTS(SELECT FROM gridex_received_sources.validation_assessments attempted WHERE attempted.id=assessment AND attempted.previous_assessment_id=v.id AND attempted.source_message_id=v.source_message_id)
    AND ((p_ignored_fields_text IS NULL AND ignored.canonical_assessment_id IS NULL) OR
     (p_ignored_fields_text IS NOT NULL AND ignored.canonical_assessment_id IS NOT NULL
      AND ignored.company_id=p_company_id AND ignored.environment=p_environment
      AND ignored.source_message_id=p_source_message_id AND ignored.source_payload_hash=p_source_payload_hash
      AND ignored.fields_text IS NOT DISTINCT FROM p_ignored_fields_text
      AND ignored.fields_hash=encode(sha256(convert_to(p_ignored_fields_text,'UTF8')),'hex')))
    AND ((p_object_facts_text IS NULL AND object.assessment_id IS NULL) OR
     (p_object_facts_text IS NOT NULL AND object.assessment_id IS NOT NULL
      AND object.company_id=p_company_id AND object.environment=p_environment
      AND object.source_message_id=p_source_message_id AND object.source_payload_hash=p_source_payload_hash
      AND object.facts_text IS NOT DISTINCT FROM p_object_facts_text
      AND object.facts_hash=encode(sha256(convert_to(p_object_facts_text,'UTF8')),'hex')))
    AND ((p_response_facts_text IS NULL AND response_facet.assessment_id IS NULL) OR
     (p_response_facts_text IS NOT NULL AND response_facet.assessment_id IS NOT NULL
      AND response_facet.company_id=p_company_id AND response_facet.environment=p_environment
      AND response_facet.source_message_id=p_source_message_id AND response_facet.source_payload_hash=p_source_payload_hash
      AND response_facet.response_facts_text IS NOT DISTINCT FROM p_response_facts_text
      AND response_facet.response_facts_hash=encode(sha256(convert_to(p_response_facts_text,'UTF8')),'hex')))
    AND ((p_application_facts_text IS NULL AND application_facet.assessment_id IS NULL) OR
     (p_application_facts_text IS NOT NULL AND application_facet.assessment_id IS NOT NULL
      AND application_facet.company_id=p_company_id AND application_facet.environment=p_environment
      AND application_facet.source_message_id=p_source_message_id AND application_facet.source_payload_hash=p_source_payload_hash
      AND application_facet.application_facts_text IS NOT DISTINCT FROM p_application_facts_text
      AND application_facet.application_facts_hash=encode(sha256(convert_to(p_application_facts_text,'UTF8')),'hex')))
    AND ((p_source_function_facts_text IS NULL AND function_facet.assessment_id IS NULL) OR
     (p_source_function_facts_text IS NOT NULL AND function_facet.assessment_id IS NOT NULL
      AND function_facet.company_id=p_company_id AND function_facet.environment=p_environment
      AND function_facet.source_message_id=p_source_message_id AND function_facet.source_payload_hash=p_source_payload_hash
      AND function_facet.function_facts_text IS NOT DISTINCT FROM p_source_function_facts_text
      AND function_facet.function_facts_hash=encode(sha256(convert_to(p_source_function_facts_text,'UTF8')),'hex')))) THEN
  replay_rollback:=true;
  RAISE EXCEPTION 'ediel_equivalent_prodat_canonical_replay_rollback' USING ERRCODE='GX001';
 END IF;
 EXCEPTION WHEN SQLSTATE 'GX001' THEN
  IF replay_rollback IS NOT TRUE OR SQLERRM IS DISTINCT FROM 'ediel_equivalent_prodat_canonical_replay_rollback' THEN RAISE;END IF;
  RETURN jsonb_build_object('version',6,'assessmentId',replay_candidate,'companyId',p_company_id,'environment',p_environment,
   'sourceMessageId',p_source_message_id,'sourcePayloadHash',p_source_payload_hash,
   'factsHash',encode(sha256(convert_to(p_facts_text,'UTF8')),'hex'),'sourceDisposition','not_established',
   'ignoredFieldsHash',CASE WHEN p_ignored_fields_text IS NULL THEN NULL ELSE encode(sha256(convert_to(p_ignored_fields_text,'UTF8')),'hex') END,
   'objectFactsHash',CASE WHEN p_object_facts_text IS NULL THEN NULL ELSE encode(sha256(convert_to(p_object_facts_text,'UTF8')),'hex') END,
   'responseFactsHash',response_hash,'applicationFactsHash',application_hash,'sourceFunctionFactsHash',function_hash);
 END;
 RETURN receipt||jsonb_build_object('version',6,'responseFactsHash',response_hash,'applicationFactsHash',application_hash,'sourceFunctionFactsHash',function_hash);
END$$;

REVOKE ALL ON FUNCTION gridex_received_sources.append_prodat_validation_v6(uuid, text, uuid, text, text, text, text, text, text, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:912
--
-- Name: append_utilts_validation_v1(uuid, text, uuid, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_utilts_validation_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text, p_transaction_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE src gridex_received_sources.sources%rowtype;m public.ediel_messages%rowtype;response jsonb;projection jsonb;projection_hash text;
BEGIN
 SELECT * INTO src FROM gridex_received_sources.sources WHERE source_message_id=p_source_message_id AND company_id=p_company_id AND environment=p_environment FOR UPDATE;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id AND environment=p_environment;
 IF src.source_message_id IS NULL OR m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'UTILTS'
  OR src.payload_hash IS DISTINCT FROM p_source_payload_hash OR m.raw_payload IS DISTINCT FROM src.raw_payload OR src.received_context->>'contextOrigin' IS DISTINCT FROM 'database_insert' THEN RAISE EXCEPTION 'received_utilts_transaction_source_unavailable' USING ERRCODE='23514'; END IF;
 IF p_transaction_facts_text IS NOT NULL THEN
  IF octet_length(p_transaction_facts_text)>524288 THEN RAISE EXCEPTION 'received_utilts_transaction_facts_invalid' USING ERRCODE='23514'; END IF;
  projection:=p_transaction_facts_text::jsonb;
  IF NOT coalesce(gridex_received_sources.validate_utilts_transactions_v1(src.raw_payload,projection),false) THEN RAISE EXCEPTION 'received_utilts_transaction_facts_invalid' USING ERRCODE='23514'; END IF;
  projection_hash:=encode(sha256(convert_to(p_transaction_facts_text,'UTF8')),'hex');
 END IF;
 response:=gridex_received_sources.append_validation(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text);
 IF projection IS NOT NULL THEN
  INSERT INTO gridex_received_sources.utilts_transaction_validations(assessment_id,source_message_id,company_id,environment,source_payload_hash,transaction_facts_text,transaction_facts_hash)
   VALUES((response->>'assessmentId')::uuid,p_source_message_id,p_company_id,p_environment,p_source_payload_hash,p_transaction_facts_text,projection_hash);
 END IF;
 RETURN response||jsonb_build_object('transactionFactsHash',projection_hash);
END $$;

REVOKE ALL ON FUNCTION gridex_received_sources.append_utilts_validation_v1(uuid, text, uuid, text, text, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:913
--
-- Name: append_utilts_validation_v2(uuid, text, uuid, text, text, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
