 projection:=p_functional_facts_text::jsonb;facts:=p_facts_text::jsonb;transactions:=p_transaction_facts_text::jsonb;
 IF facts->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR coalesce(facts->>'functionalDecision','') NOT IN ('rejected','manual_review')
  OR NOT coalesce(gridex_received_sources.validate_utilts_functional_v2(src.raw_payload,projection,transactions),false) THEN RAISE EXCEPTION 'received_utilts_functional_facts_invalid' USING ERRCODE='23514'; END IF;
 projection_hash:=encode(sha256(convert_to(p_functional_facts_text,'UTF8')),'hex');
 response:=gridex_received_sources.append_utilts_validation_v3(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text,p_transaction_facts_text,p_header_facts_text,NULL);
 INSERT INTO gridex_received_sources.utilts_functional_validations_v2(assessment_id,source_message_id,company_id,environment,source_payload_hash,functional_facts_text,functional_facts_hash)
  VALUES((response->>'assessmentId')::uuid,p_source_message_id,p_company_id,p_environment,p_source_payload_hash,p_functional_facts_text,projection_hash);
