-- canonical:917
--
-- Name: append_validation_before_reference_profile_v1(uuid, text, uuid, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_validation_before_reference_profile_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE src gridex_received_sources.sources%rowtype; facts jsonb; pack jsonb; v_previous uuid; v_id uuid; v_hash text; registered public.ediel_rule_packs%rowtype;registered_profile public.ediel_message_profiles%rowtype;registered_sources jsonb;original_ack jsonb;actual_message public.ediel_messages%rowtype;facet jsonb; obj jsonb; reg jsonb; key text; object_keys text[]:=ARRAY[]::text[]; line_ids text[]:=ARRAY[]::text[]; segment_ids int[]:=ARRAY[]::int[]; previous_segment int; position int;
BEGIN
  -- Lock per source before selecting a predecessor. Concurrent assessments
  -- append a single linked sequence; no UPDATE of historic decisions occurs.
  SELECT * INTO src FROM gridex_received_sources.sources WHERE source_message_id=p_source_message_id
    AND company_id=p_company_id AND environment=p_environment FOR UPDATE;
  IF NOT FOUND OR src.payload_hash IS NULL OR src.received_context IS NULL
    OR p_source_payload_hash IS DISTINCT FROM src.payload_hash OR p_facts_text IS NULL OR octet_length(p_facts_text)>65536 THEN
    RAISE EXCEPTION 'received_validation_source_unavailable' USING ERRCODE='23514';
  END IF;
  facts:=p_facts_text::jsonb;
  IF jsonb_typeof(facts) IS DISTINCT FROM 'object'
    OR facts - ARRAY['version','owner','sourceDisposition','objectDisposition','partyDisposition','coverage','originalTenantMatch','syntaxDecision','applicationDecision','functionalDecision','messageReference','reasonCodes','rulePackEvidence','registerValidation'] <> '{}'::jsonb
    OR facts->'version' IS DISTINCT FROM '1'::jsonb OR facts->>'owner' IS DISTINCT FROM 'canonical-runtime-with-registry-v1'
    OR facts->>'sourceDisposition' IS DISTINCT FROM 'not_established' OR facts->>'objectDisposition' IS DISTINCT FROM 'not_checked'
    OR facts->>'partyDisposition' IS DISTINCT FROM 'not_checked' OR facts->>'coverage' IS DISTINCT FROM 'canonical_runtime_only'
    OR facts->>'originalTenantMatch' IS DISTINCT FROM 'matched'
    OR coalesce(facts->>'syntaxDecision','') NOT IN ('accepted','rejected','not_applicable','manual_review')
    OR coalesce(facts->>'applicationDecision','') NOT IN ('accepted','rejected','not_applicable','manual_review')
    OR coalesce(facts->>'functionalDecision','') NOT IN ('accepted','rejected','not_applicable','manual_review')
    OR jsonb_typeof(facts->'reasonCodes') IS DISTINCT FROM 'array' OR jsonb_array_length(facts->'reasonCodes')>128
    OR coalesce(jsonb_typeof(facts->'messageReference'),'missing') NOT IN ('string','null')
    OR length(coalesce(facts->>'messageReference',''))>128 THEN
    RAISE EXCEPTION 'received_validation_not_source_approval' USING ERRCODE='23514';
  END IF;
  IF EXISTS (SELECT FROM jsonb_array_elements(facts->'reasonCodes') AS value WHERE jsonb_typeof(value) IS DISTINCT FROM 'string' OR value#>>'{}' !~ '^[A-Za-z0-9_.:-]{1,128}$') THEN
    RAISE EXCEPTION 'received_validation_reason_unavailable' USING ERRCODE='23514';
  END IF;
  pack:=facts->'rulePackEvidence';
  IF facts->>'applicationDecision'='accepted' AND (pack IS NULL OR pack='null'::jsonb) THEN
    RAISE EXCEPTION 'received_validation_rule_evidence_unavailable' USING ERRCODE='23514';
  END IF;
  IF pack IS DISTINCT FROM 'null'::jsonb THEN
    IF jsonb_typeof(pack) IS DISTINCT FROM 'object' OR NOT pack ?& ARRAY['profileKey','messageProfileId','rulePackId','sourceHash','version','snapshot']
      OR pack - ARRAY['profileKey','messageProfileId','rulePackId','sourceHash','version','snapshot'] <> '{}'::jsonb
      OR jsonb_typeof(pack->'snapshot') IS DISTINCT FROM 'object'
      OR NOT (pack->'snapshot') ?& ARRAY['rulePack','messageProfile','guideSources']
      OR (pack->'snapshot')-ARRAY['rulePack','messageProfile','guideSources'] <> '{}'::jsonb THEN
      RAISE EXCEPTION 'received_validation_rule_evidence_unavailable' USING ERRCODE='23514';
    END IF;
    SELECT * INTO actual_message FROM public.ediel_messages WHERE id=src.source_message_id AND company_id=p_company_id AND environment=p_environment FOR SHARE;
    IF actual_message.message_family IN ('APERAK','CONTRL','UTILTS_ERR') THEN
      -- An ACK inherits the protected original's immutable witness. A later
      -- edit of activation rows never replaces its historic guide authority.
      original_ack:=gridex_ediel_source_rules.read_ack_source_before_basis_v1(p_company_id,p_environment,src.source_message_id);
      IF original_ack IS NOT NULL THEN
        original_ack:=gridex_ediel_source_rules.require_v1(p_company_id,(original_ack#>>'{sourceMessage,id}')::uuid);
      END IF;
      IF original_ack IS NULL OR pack IS DISTINCT FROM jsonb_build_object('profileKey',original_ack->'profileKey',
        'messageProfileId',original_ack->'messageProfileId','rulePackId',original_ack->'rulePackId','sourceHash',original_ack->'sourceHash',
        'version',original_ack->'version','snapshot',jsonb_build_object('rulePack',original_ack#>'{snapshot,rulePack}',
          'messageProfile',original_ack#>'{snapshot,messageProfile}','guideSources',original_ack#>'{snapshot,guideSources}')) THEN
        RAISE EXCEPTION 'received_validation_rule_evidence_unavailable' USING ERRCODE='23514';
      END IF;
    ELSE
      LOCK TABLE public.ediel_rule_pack_sources IN SHARE MODE;
      SELECT * INTO registered FROM public.ediel_rule_packs WHERE id::text=pack->>'rulePackId' AND source_hash=pack->>'sourceHash' FOR SHARE;
      SELECT * INTO registered_profile FROM public.ediel_message_profiles WHERE id::text=pack->>'messageProfileId'
        AND rule_pack_id=registered.id AND profile_key=pack->>'profileKey' FOR SHARE;
      SELECT coalesce(jsonb_agg(to_jsonb(source) ORDER BY source.id),'[]'::jsonb) INTO registered_sources FROM public.ediel_rule_pack_sources source WHERE rule_pack_id=registered.id;
      IF registered.id IS NULL OR registered_profile.id IS NULL
        OR pack->>'version' IS DISTINCT FROM registered.guide_version||':r'||registered.guide_revision
        OR pack#>'{snapshot,rulePack}' IS DISTINCT FROM to_jsonb(registered)
        OR pack#>'{snapshot,messageProfile}' IS DISTINCT FROM to_jsonb(registered_profile)
        OR pack#>'{snapshot,guideSources}' IS DISTINCT FROM registered_sources THEN
        RAISE EXCEPTION 'received_validation_rule_evidence_unavailable' USING ERRCODE='23514';
      END IF;
    END IF;
  END IF;
  -- Optional live-owner register facet. Historical facet-only callers remain
  -- valid. This never grants full source, tenant, legal-party or business approval.
  IF facts ? 'registerValidation' THEN
    facet:=facts->'registerValidation';
    IF pack IS NULL OR pack='null'::jsonb OR jsonb_typeof(facet) IS DISTINCT FROM 'object'
      OR NOT facet ?& ARRAY['version','owner','coverage','objects']
      OR facet-ARRAY['version','owner','coverage','objects'] <> '{}'::jsonb
      OR facet->'version' IS DISTINCT FROM '1'::jsonb
      OR facet->>'owner' IS DISTINCT FROM 'validateProdatRegisterPolicy'
      OR facet->>'coverage' IS DISTINCT FROM 'canonical_register_only'
      OR jsonb_typeof(facet->'objects') IS DISTINCT FROM 'array' THEN
      RAISE EXCEPTION 'received_register_facet_invalid' USING ERRCODE='23514';
    END IF;
    IF jsonb_array_length(facet->'objects')>8192 THEN
      RAISE EXCEPTION 'received_register_facet_budget' USING ERRCODE='23514';
    END IF;
    FOR obj IN SELECT value FROM jsonb_array_elements(facet->'objects') LOOP
      IF jsonb_typeof(obj) IS DISTINCT FROM 'object'
        OR NOT obj ?& ARRAY['messageIndex','messageReference','objectId','identityAgency','disposition','registers','reasons']
        OR obj-ARRAY['messageIndex','messageReference','objectId','identityAgency','disposition','registers','reasons'] <> '{}'::jsonb
        OR jsonb_typeof(obj->'messageIndex') IS DISTINCT FROM 'number'
        OR coalesce(obj->>'messageIndex','') !~ '^(-1|[0-9]{1,4})$'
        OR coalesce(obj->>'disposition','') NOT IN ('accepted','rejected','unavailable')
        OR jsonb_typeof(obj->'registers') IS DISTINCT FROM 'array'
        OR jsonb_typeof(obj->'reasons') IS DISTINCT FROM 'array' THEN
        RAISE EXCEPTION 'received_register_object_invalid' USING ERRCODE='23514';
      END IF;
      IF (obj->>'messageIndex')::int>=8192 OR jsonb_array_length(obj->'registers') NOT BETWEEN 1 AND 8192
        OR jsonb_array_length(obj->'reasons')>128 THEN
        RAISE EXCEPTION 'received_register_object_budget' USING ERRCODE='23514';
      END IF;
      FOREACH key IN ARRAY ARRAY['messageReference','objectId','identityAgency'] LOOP
        IF obj->key IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(obj->key) IS DISTINCT FROM 'string'
          OR length(obj->>key) NOT BETWEEN 1 AND 128 OR obj->>key <> btrim(obj->>key) OR obj->>key ~ '[[:cntrl:]]') THEN
          RAISE EXCEPTION 'received_register_identity_invalid' USING ERRCODE='23514';
        END IF;
      END LOOP;
      IF obj->>'disposition'<>'unavailable' AND ((obj->>'messageIndex')::int<>0 OR jsonb_typeof(obj->'messageReference')<>'string'
        OR ((jsonb_typeof(obj->'objectId')<>'string' OR coalesce(obj->>'identityAgency','') NOT IN ('9','89'))
          AND NOT ((obj->>'disposition'='accepted' AND gridex_received_sources.identity_omission_scope_v1(src.raw_payload,obj)) OR (obj->>'disposition'='rejected' AND (gridex_received_sources.rejected_identity_scope_v1(src.raw_payload,obj) IS TRUE OR gridex_received_sources.rejected_z04h_identity_scope_v1(src.raw_payload,obj) IS TRUE))))) THEN
        RAISE EXCEPTION 'received_register_unvalidated_scope' USING ERRCODE='23514';
      END IF;
      IF (obj->>'disposition'='accepted') IS DISTINCT FROM (jsonb_array_length(obj->'reasons')=0)
        OR EXISTS(SELECT FROM jsonb_array_elements(obj->'reasons') r WHERE jsonb_typeof(r) IS DISTINCT FROM 'string' OR r#>>'{}' !~ '^[A-Za-z0-9_.:-]{1,128}$')
        OR (SELECT count(*)<>count(DISTINCT r) FROM jsonb_array_elements(obj->'reasons') r) THEN
        RAISE EXCEPTION 'received_register_reason_invalid' USING ERRCODE='23514';
      END IF;
      key:=jsonb_build_array(obj->'messageIndex',obj->'objectId',obj->'identityAgency',CASE WHEN obj->'objectId'='null'::jsonb THEN obj#>'{registers,0,lineIndex}' ELSE 'null'::jsonb END)::text;
      IF key=ANY(object_keys) THEN RAISE EXCEPTION 'received_register_duplicate_object' USING ERRCODE='23514'; END IF;
      object_keys:=array_append(object_keys,key);
      previous_segment:=-1; position:=0;
      FOR reg IN SELECT value FROM jsonb_array_elements(obj->'registers') LOOP
        position:=position+1;
        IF jsonb_typeof(reg) IS DISTINCT FROM 'object'
          OR NOT reg ?& ARRAY['lineIndex','lineNumber','registerIndex','registerPosition','segmentIndex']
          OR reg-ARRAY['lineIndex','lineNumber','registerIndex','registerPosition','segmentIndex'] <> '{}'::jsonb THEN
          RAISE EXCEPTION 'received_register_occurrence_invalid' USING ERRCODE='23514';
        END IF;
        FOREACH key IN ARRAY ARRAY['lineIndex','registerPosition','segmentIndex'] LOOP
          IF jsonb_typeof(reg->key) IS DISTINCT FROM 'number' OR coalesce(reg->>key,'') !~ '^[0-9]{1,4}$' THEN
            RAISE EXCEPTION 'received_register_index_invalid' USING ERRCODE='23514';
          END IF;
          IF (reg->>key)::int>=8192 THEN RAISE EXCEPTION 'received_register_index_budget' USING ERRCODE='23514'; END IF;
        END LOOP;
        FOREACH key IN ARRAY ARRAY['lineNumber','registerIndex'] LOOP
          IF reg->key IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(reg->key) IS DISTINCT FROM 'string'
            OR length(reg->>key) NOT BETWEEN 1 AND 128 OR reg->>key<>btrim(reg->>key) OR reg->>key ~ '[[:cntrl:]]') THEN
            RAISE EXCEPTION 'received_register_wire_index_invalid' USING ERRCODE='23514';
          END IF;
        END LOOP;
        IF (reg->>'registerPosition')::int<>position OR (reg->>'segmentIndex')::int<=previous_segment
          OR jsonb_build_array(obj->'messageIndex',reg->'lineIndex')::text=ANY(line_ids) OR (reg->>'segmentIndex')::int=ANY(segment_ids) THEN
          RAISE EXCEPTION 'received_register_occurrence_conflict' USING ERRCODE='23514';
        END IF;
        line_ids:=array_append(line_ids,jsonb_build_array(obj->'messageIndex',reg->'lineIndex')::text);
        segment_ids:=array_append(segment_ids,(reg->>'segmentIndex')::int);
        previous_segment:=(reg->>'segmentIndex')::int;
      END LOOP;
    END LOOP;
  END IF;
  SELECT prior.id INTO v_previous FROM gridex_received_sources.validation_assessments prior WHERE prior.source_message_id=src.source_message_id
    AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=prior.id);
  v_hash:=encode(sha256(convert_to(p_facts_text,'UTF8')),'hex');
  INSERT INTO gridex_received_sources.validation_assessments(source_message_id,company_id,environment,source_payload_hash,previous_assessment_id,facts_text,facts_hash)
    VALUES(src.source_message_id,p_company_id,p_environment,src.payload_hash,v_previous,p_facts_text,v_hash) RETURNING id INTO v_id;
  RETURN jsonb_build_object('version',1,'assessmentId',v_id,'companyId',p_company_id,'environment',p_environment,
    'sourceMessageId',src.source_message_id,'sourcePayloadHash',src.payload_hash,'factsHash',v_hash,'sourceDisposition','not_established');
END $_$;

REVOKE ALL ON FUNCTION gridex_received_sources.append_validation_before_reference_profile_v1(uuid, text, uuid, text, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:918
--
-- Name: append_validation_before_unused_unh_v1(uuid, text, uuid, text, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.append_validation_before_unused_unh_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_source_payload_hash text, p_facts_text text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE m public.ediel_messages%rowtype;result jsonb;BEGIN
 -- Preserve the existing source-ledger -> actual-message lock order. A new
 -- invalid assessment and its delegate writes roll back in this same RPC.
 result:=gridex_received_sources.append_validation_before_reference_profile_v1(p_company_id,p_environment,p_source_message_id,p_source_payload_hash,p_facts_text);
 IF p_facts_text::jsonb->>'syntaxDecision'='accepted' THEN
  -- The protected delegate has already verified the tenant-bound retained
  -- source/hash. A physical technical source may retain company_id NULL;
  -- this check observes those exact same bytes without assigning a tenant.
  SELECT s.raw_payload INTO STRICT m.raw_payload FROM gridex_received_sources.sources s WHERE s.source_message_id=p_source_message_id AND s.company_id=p_company_id AND s.environment=p_environment
   AND s.raw_payload IS NOT NULL AND s.payload_hash=p_source_payload_hash AND encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex')=p_source_payload_hash;
  PERFORM gridex_ediel_ack_guide.require_message_reference_profile_v1(m.raw_payload);END IF;
 RETURN result;END $$;

REVOKE ALL ON FUNCTION gridex_received_sources.append_validation_before_unused_unh_v1(uuid, text, uuid, text, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:919
--
-- Name: applied_structural_method_objects_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.applied_structural_method_objects_v1(c uuid, msg uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r record;s gridex_received_sources.sources%rowtype;a gridex_received_sources.object_assessments%rowtype;f gridex_received_sources.prodat_ignored_field_facets%rowtype;
 own jsonb;assessed jsonb;business jsonb;first_register jsonb;token jsonb;characteristic text;method text;method_count integer;out jsonb:='[]';
BEGIN
 <<receipt_loop>> FOR r IN SELECT company_id,environment,source_message_id,payload_hash,object_assessment_id,canonical_assessment_id,source_received_at,applied_at,objects FROM gridex_received_sources.structural_apply_receipts WHERE company_id=c AND source_message_id=msg
 UNION ALL SELECT company_id,environment,source_message_id,payload_hash,object_assessment_id,canonical_assessment_id,source_received_at,applied_at,jsonb_build_array(effect) FROM gridex_received_sources.structural_object_apply_receipts WHERE company_id=c AND source_message_id=msg LOOP
 SELECT * INTO s FROM gridex_received_sources.sources WHERE company_id=c AND source_message_id=msg AND environment=r.environment;
 SELECT * INTO a FROM gridex_received_sources.object_assessments WHERE id=r.object_assessment_id AND company_id=c AND source_message_id=msg AND environment=r.environment;
 SELECT * INTO f FROM gridex_received_sources.prodat_ignored_field_facets WHERE canonical_assessment_id=r.canonical_assessment_id AND company_id=c AND source_message_id=msg AND environment=r.environment;
 IF s.source_message_id IS NULL OR a.id IS NULL OR f.canonical_assessment_id IS NULL OR s.payload_hash IS DISTINCT FROM r.payload_hash OR s.payload_hash IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') OR a.facts_hash IS DISTINCT FROM encode(sha256(convert_to(a.facts_text,'UTF8')),'hex') OR a.source_payload_hash IS DISTINCT FROM s.payload_hash OR a.canonical_assessment_id IS DISTINCT FROM r.canonical_assessment_id OR f.source_payload_hash IS DISTINCT FROM s.payload_hash OR f.fields_hash IS DISTINCT FROM encode(sha256(convert_to(f.fields_text,'UTF8')),'hex') THEN CONTINUE receipt_loop;END IF;
 FOR own IN SELECT value FROM jsonb_array_elements(r.objects) LOOP
  SELECT value INTO assessed FROM jsonb_array_elements(a.facts_text::jsonb->'objects') value WHERE value->'object'=own->'object';
  business:=assessed->'business';first_register:=own#>'{sourceRegisters,0}';
  IF assessed->>'disposition' IS DISTINCT FROM 'accepted' OR business->>'owner' IS DISTINCT FROM 'reviewed-received-structure-v1' OR business->'wire' IS DISTINCT FROM own->'wire' OR business->>'companyId' IS DISTINCT FROM c::text OR business->>'environment' IS DISTINCT FROM r.environment OR business->>'meteringPointId' IS DISTINCT FROM own->>'meteringPointId' OR business->>'siteId' IS DISTINCT FROM own->>'siteId' OR nullif(business->>'customerId','') IS NULL OR own#>>'{wire,messageCode}' IS DISTINCT FROM 'Z06' OR (own#>>'{wire,businessCase}' IN('change_with_reading','change_without_reading')) IS NOT TRUE THEN CONTINUE;END IF;
  characteristic:=NULL;method:=NULL;method_count:=0;
  FOR token IN SELECT value FROM jsonb_array_elements(first_register->'tokens') LOOP
   IF token->>'tag'='CCI' THEN characteristic:=token#>>'{elements,2,0}';
   ELSIF token->>'tag'='CAV' AND characteristic='Z04' THEN method_count:=method_count+1;method:=token#>>'{elements,1,0}';END IF;
  END LOOP;
  IF method_count<>1 OR EXISTS(SELECT FROM jsonb_array_elements(f.fields_text::jsonb) ignored WHERE ignored->>'fieldNumber'='217' AND ignored#>>'{occurrence,objectId}'=own#>>'{object,objectId}' AND ignored#>>'{occurrence,identityAgency}'=own#>>'{object,identityAgency}' AND ignored#>>'{occurrence,messageReference}'=own#>>'{object,messageReference}' AND ignored#>>'{occurrence,lineIndex}'=first_register#>>'{register,lineIndex}') THEN method:=NULL;END IF;
  out:=out||jsonb_build_array(jsonb_build_object('companyId',c,'environment',r.environment,'sourceMessageId',msg,'sourcePayloadHash',r.payload_hash,'customerId',business->>'customerId','siteId',own->>'siteId','meteringPointId',own->>'meteringPointId','objectId',own#>>'{object,objectId}','identityAgency',own#>>'{object,identityAgency}','businessCase',own#>>'{wire,businessCase}','effectiveAt',own->'effectiveAt','legalNetwork',own#>>'{wire,legalSender}','legalSupplier',own#>>'{wire,legalReceiver}','measurementMethod',nullif(method,''),'sourceReceivedAt',r.source_received_at,'appliedAt',r.applied_at));
 END LOOP;
 END LOOP receipt_loop;
 RETURN CASE WHEN jsonb_array_length(out)=0 THEN NULL ELSE out END;
END$$;

REVOKE ALL ON FUNCTION gridex_received_sources.applied_structural_method_objects_v1(uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:920
--
-- Name: apply_owned_li_repair_v1(uuid, uuid, uuid, uuid, text, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.apply_owned_li_repair_v1(c uuid, op_id uuid, source_id uuid, ack_id uuid, raw text, allowed jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE p gridex_received_sources.prodat_recovery_li_preparations%rowtype;source public.ediel_messages%rowtype;ack public.ediel_messages%rowtype;scopes jsonb;current_objects jsonb;objects jsonb;scope jsonb;obj jsonb;a jsonb;out jsonb:='[]';negative_lines jsonb:='[]';
BEGIN
 SELECT * INTO p FROM gridex_received_sources.prodat_recovery_li_preparations WHERE operation_id=op_id FOR SHARE;IF NOT FOUND THEN
  SELECT * INTO STRICT source FROM public.ediel_messages WHERE id=source_id AND company_id=c;
  IF jsonb_array_length(gridex_received_sources.missing_li_repair_scopes_v1(c,source.environment,ack_id,source_id))>0 THEN RAISE EXCEPTION 'prodat_recovery_owned_li_preparation_required';END IF;
  RETURN allowed;END IF;
 SELECT * INTO STRICT source FROM public.ediel_messages WHERE id=source_id AND company_id=c;
 SELECT * INTO STRICT ack FROM public.ediel_messages WHERE id=ack_id AND company_id=c AND environment=source.environment;
 scopes:=gridex_received_sources.missing_li_repair_scopes_v1(c,source.environment,ack_id,source_id);
 current_objects:=gridex_ack_authority.prodat_correction_objects_v1(c,source.environment,ack_id,source_id);
 IF p.company_id IS DISTINCT FROM c OR p.environment IS DISTINCT FROM source.environment OR p.original_message_id IS DISTINCT FROM source_id OR p.ack_message_id IS DISTINCT FROM ack_id
  OR p.original_payload_hash IS DISTINCT FROM encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex') OR p.ack_payload_hash IS DISTINCT FROM encode(sha256(convert_to(ack.raw_payload,'UTF8')),'hex')
  OR p.missing_scopes IS DISTINCT FROM scopes OR current_objects IS DISTINCT FROM allowed OR p.corrected_payload_hash IS DISTINCT FROM encode(sha256(convert_to(raw,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_recovery_li_preparation_changed';END IF;
 objects:=gridex_ack_authority.prodat_physical_recovery_wire_v1(source.raw_payload)->'objects';
 FOR scope IN SELECT x FROM jsonb_array_elements(gridex_ack_authority.prodat_physical_receipt_v1(c,source.environment,ack_id,source_id)->'physicalOutcomes')x WHERE x->>'outcome'='negative' LOOP
  SELECT x INTO STRICT a FROM jsonb_array_elements(gridex_ack_authority.prodat_physical_source_objects_v1(source.raw_payload))x WHERE x->'lineIndex'=scope#>'{physicalReference,firstLineIndex}';negative_lines:=negative_lines||(a->'registerLineIndices');
 END LOOP;
 FOR obj IN SELECT x FROM jsonb_array_elements(objects)x WHERE negative_lines @> jsonb_build_array(x->'physicalLineIndex') LOOP
  SELECT x INTO a FROM jsonb_array_elements(p.allocations)x WHERE x->'sourceFirstLineIndex'=obj->'physicalLineIndex';
  IF a IS NOT NULL THEN IF obj->>'li' IS NOT NULL THEN RAISE EXCEPTION 'prodat_recovery_existing_li_replacement_forbidden';END IF;obj:=obj||jsonb_build_object('li',a->>'reference');END IF;
  out:=out||jsonb_build_array(obj-'physicalLineIndex');
 END LOOP;
 SELECT coalesce(jsonb_agg(x ORDER BY x::text),'[]') INTO out FROM jsonb_array_elements(out)x;RETURN out;
END$$;

REVOKE ALL ON FUNCTION gridex_received_sources.apply_owned_li_repair_v1(uuid, uuid, uuid, uuid, text, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:921
--
-- Name: apply_permission_before_legal_context_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.apply_permission_before_legal_context_v1(p_company_id uuid, p_source_message_id uuid, p_actor_user_id uuid, p_expected_permission_id uuid DEFAULT NULL::uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE m public.ediel_messages%rowtype; origin public.ediel_messages%rowtype; p public.metering_permissions%rowtype;
 wire jsonb; original jsonb; a jsonb; b jsonb; prior gridex_received_sources.permission_transitions%rowtype;
 ids uuid[]; mode text; reason text; next_status text; negative_status text; count_positive int:=0; count_negative int:=0;
 start_day date; end_day date; end_time timestamptz; before_state jsonb; before_sites jsonb; after_state jsonb; ended_source public.ediel_messages%rowtype; ended_wire jsonb; termination public.ediel_messages%rowtype; termination_wire jsonb; qualified_original uuid; qualified_code text;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR p_actor_user_id IS NULL THEN RETURN jsonb_build_object('applied',false,'reason','permission_source_unavailable'); END IF;
 IF NOT coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,m.company_id,'metering.write'),false)
 OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=m.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
 THEN RETURN jsonb_build_object('applied',false,'reason','permission_execution_actor_unqualified'); END IF;
 SELECT * INTO prior FROM gridex_received_sources.permission_transitions WHERE source_message_id=m.id;
 IF FOUND THEN
  IF prior.company_id<>p_company_id OR prior.payload_hash<>encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR (p_expected_permission_id IS NOT NULL AND prior.permission_id<>p_expected_permission_id) THEN RAISE EXCEPTION 'permission_replay_conflict'; END IF;
  RETURN jsonb_build_object('applied',true,'idempotent',true,'permissionId',prior.permission_id,'status',prior.resulting_state->>'status');
 END IF;
 -- The real canonical runtime must have accepted this exact immutable payload.
 IF NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=m.id AND v.company_id=m.company_id AND v.environment=m.environment
 AND v.source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND (v.facts_text::jsonb)->>'syntaxDecision'='accepted'
 AND (v.facts_text::jsonb)->>'applicationDecision'='accepted' AND (v.facts_text::jsonb)->>'functionalDecision'='accepted'
 AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN jsonb_build_object('applied',false,'reason','canonical_permission_source_not_accepted'); END IF;
 wire:=gridex_received_sources.permission_wire_v1(m.raw_payload);
 IF wire IS NULL OR (wire->>'code' IN ('Z14','Z15')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','permission_wire_unavailable'); END IF;
 -- Correlation is exact: permission owner, outbound original Z13, environment,
 -- opposite legal actors, and original LI. No unrelated unique-row fallback.
 SELECT array_agg(mp.id ORDER BY mp.id) INTO ids FROM public.metering_permissions mp
 JOIN public.ediel_messages z ON z.id=coalesce(mp.source_z13_message_id,mp.outbound_z13_message_id) AND z.company_id=mp.company_id AND z.environment=m.environment
 WHERE mp.company_id=m.company_id AND (p_expected_permission_id IS NULL OR mp.id=p_expected_permission_id)
 AND z.direction='outbound' AND z.status='sent' AND z.message_sent_at IS NOT NULL
 AND EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE nullif(o->>'li','') IS NOT NULL AND o->>'li'=mp.rff_li_reference);
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN jsonb_build_object('applied',false,'reason','no_unique_source_bound_permission'); END IF;
 SELECT * INTO p FROM public.metering_permissions WHERE id=ids[1] AND company_id=m.company_id FOR UPDATE;
 SELECT * INTO origin FROM public.ediel_messages WHERE id=coalesce(p.source_z13_message_id,p.outbound_z13_message_id) AND company_id=m.company_id FOR SHARE;
 IF NOT FOUND OR origin.environment IS DISTINCT FROM m.environment OR origin.direction IS DISTINCT FROM 'outbound' OR origin.status IS DISTINCT FROM 'sent' OR origin.message_sent_at IS NULL
  OR origin.immutable_rendered_at IS NULL OR origin.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(origin.raw_payload,'UTF8')),'hex')
 THEN RETURN jsonb_build_object('applied',false,'reason','permission_original_not_sealed_and_sent'); END IF;
 original:=gridex_received_sources.permission_wire_v1(origin.raw_payload);
 IF original IS NULL OR original->>'code' IS DISTINCT FROM 'Z13' OR wire->>'sender' IS DISTINCT FROM original->>'receiver' OR wire->>'receiver' IS DISTINCT FROM original->>'sender'
 OR p.grid_owner_ediel_id IS DISTINCT FROM wire->>'sender' THEN RETURN jsonb_build_object('applied',false,'reason','permission_legal_actor_mismatch'); END IF;
 IF (SELECT count(*) FROM jsonb_array_elements(original->'objects') o WHERE o->>'li'=p.rff_li_reference)<>1 OR origin.customer_id IS DISTINCT FROM p.customer_id THEN RETURN jsonb_build_object('applied',false,'reason','permission_original_customer_scope_unavailable'); END IF;
 SELECT o INTO b FROM jsonb_array_elements(original->'objects') o WHERE o->>'li'=p.rff_li_reference;
 IF b IS NULL OR nullif(b->>'customerIdentity','') IS NULL OR (b->>'reason' IN ('S17','S18')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','permission_original_mode_unavailable'); END IF;
 mode:=b->>'reason';before_state:=to_jsonb(p);
 PERFORM ps.id FROM public.metering_permission_sites ps WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id ORDER BY ps.id FOR UPDATE;
 SELECT coalesce(jsonb_agg(to_jsonb(ps) ORDER BY ps.id),'[]'::jsonb) INTO before_sites FROM public.metering_permission_sites ps WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id;
 IF wire->>'code'='Z14' THEN
  IF p.source_z13_message_id IS NOT NULL AND p.outbound_z13_message_id IS NOT NULL AND p.source_z13_message_id<>p.outbound_z13_message_id THEN RETURN jsonb_build_object('applied',false,'reason','permission_original_identity_conflict'); END IF;
  IF (p.status IN ('z13_sent','waiting_for_customer_approval','z13_ready')) IS NOT TRUE THEN RETURN jsonb_build_object('applied',false,'reason','permission_business_outcome_already_established'); END IF;
  FOR a IN SELECT o FROM jsonb_array_elements(wire->'objects') o LOOP
   IF a->>'li' IS DISTINCT FROM p.rff_li_reference THEN RETURN jsonb_build_object('applied',false,'reason','permission_object_reference_mismatch'); END IF;
   reason:=a->>'reason';
   IF reason='Z96' AND a->>'status' IN ('A13','A76') THEN
    count_negative:=count_negative+1;
    IF negative_status IS NOT NULL AND negative_status<>a->>'status' THEN RETURN jsonb_build_object('applied',false,'reason','mixed_permission_denial_reasons'); END IF;
    negative_status:=a->>'status';
   ELSIF reason=mode AND a->>'status'='A74' THEN
    count_positive:=count_positive+1;start_day:=gridex_received_sources.permission_date_v1(a->>'reportStart');end_day:=gridex_received_sources.permission_date_v1(a->>'reportEnd');
    IF nullif(a->>'point','') IS NULL OR nullif(a->>'permissionId','') IS NULL OR nullif(a->>'customerIdentity','') IS NULL OR a->>'customerIdentity' IS DISTINCT FROM b->>'customerIdentity'
    OR (b->>'point' IS NOT NULL AND a->>'point' IS DISTINCT FROM b->>'point')
    OR start_day IS NULL OR gridex_received_sources.permission_time_v1(a->>'reportStart') IS NULL OR (a->>'reportEnd' IS NOT NULL AND gridex_received_sources.permission_time_v1(a->>'reportEnd') IS NULL) OR (a->>'reportEnd' IS NOT NULL AND end_day IS NULL) OR (end_day IS NOT NULL AND end_day<start_day) THEN RETURN jsonb_build_object('applied',false,'reason','permission_approved_object_evidence_invalid'); END IF;
   ELSE RETURN jsonb_build_object('applied',false,'reason','permission_business_reason_unqualified'); END IF;
  END LOOP;
  next_status:=CASE WHEN count_positive=0 THEN CASE negative_status WHEN 'A76' THEN 'rejected_passive_timeout' ELSE 'rejected_active' END WHEN count_negative>0 THEN 'partially_approved' ELSE 'active' END;
  -- Parent/site/history writes are one database transaction. Never copy one
  -- linked local site or point to every physical approved object.
  DELETE FROM public.metering_permission_sites WHERE company_id=m.company_id AND metering_permission_id=p.id;
  FOR a IN SELECT o FROM jsonb_array_elements(wire->'objects') o WHERE o->>'status'='A74' LOOP
   INSERT INTO public.metering_permission_sites(company_id,metering_permission_id,customer_id,facility_id,grid_area_code,status,start_date,end_date,start_at,end_at,metadata)
   VALUES(m.company_id,p.id,p.customer_id,a->>'point',a->>'gridArea','approved',gridex_received_sources.permission_date_v1(a->>'reportStart'),gridex_received_sources.permission_date_v1(a->>'reportEnd'),gridex_received_sources.permission_time_v1(a->>'reportStart'),gridex_received_sources.permission_time_v1(a->>'reportEnd'),jsonb_build_object('source','inbound_prodat_z14','edielMessageId',m.id,'permissionId',a->>'permissionId','mode',mode,'product',a->>'product'));
  END LOOP;
  SELECT o INTO a FROM jsonb_array_elements(wire->'objects') o WHERE o->>'status'='A74' LIMIT 1;
  UPDATE public.metering_permissions SET status=next_status,source_z14_message_id=m.id,inbound_z14_message_id=m.id,
   permission_id=CASE WHEN count_positive=1 THEN a->>'permissionId' ELSE permission_id END,
   permission_reference=CASE WHEN count_positive=1 THEN a->>'permissionId' ELSE permission_reference END,
   approved_start_date=CASE WHEN count_positive=1 THEN gridex_received_sources.permission_date_v1(a->>'reportStart') ELSE NULL END,
   approved_end_date=CASE WHEN count_positive=1 THEN gridex_received_sources.permission_date_v1(a->>'reportEnd') ELSE NULL END,
   approved_start_at=CASE WHEN count_positive=1 THEN gridex_received_sources.permission_time_v1(a->>'reportStart') ELSE NULL END,
   approved_end_at=CASE WHEN count_positive=1 THEN gridex_received_sources.permission_time_v1(a->>'reportEnd') ELSE NULL END,
   product_code=CASE WHEN count_positive=1 THEN a->>'product' ELSE NULL END,
   report_frequency=CASE WHEN count_positive=1 THEN a->>'frequency' ELSE NULL END,
   last_blocker=CASE WHEN count_positive=0 THEN 'source_z14_denied_'||negative_status ELSE NULL END,
   metadata=coalesce(metadata,'{}')||jsonb_build_object('marketPermission',jsonb_build_object('mode',mode,'sourceZ14',m.id,'legalActor',wire->>'receiver','dsoActor',wire->>'sender','objects',wire->'objects')),
   market_state_version=market_state_version+1,updated_at=now(),updated_by=p_actor_user_id WHERE id=p.id AND company_id=m.company_id;
 ELSE
  -- Validate every physical object before mutating any of them.
  FOR a IN SELECT o FROM jsonb_array_elements(wire->'objects') o LOOP
   end_time:=gridex_received_sources.permission_time_v1(a->>'permissionEnd');
   IF end_time IS NULL OR a->>'li' IS DISTINCT FROM p.rff_li_reference OR NOT EXISTS(SELECT FROM public.metering_permission_sites ps WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id AND ps.facility_id=a->>'point' AND ps.metadata->>'permissionId'=a->>'permissionId') THEN RETURN jsonb_build_object('applied',false,'reason','z15_permission_object_mismatch'); END IF;
   reason:=a->>'reason';
   IF reason='Z24' THEN
    IF a->>'status' IS DISTINCT FROM 'A74' THEN RETURN jsonb_build_object('applied',false,'reason','z15c_status_unqualified'); END IF;
   ELSIF reason=mode AND a->>'status' IN ('A74','A75') AND a->>'endReason' IN ('B77','B78','B79','B80','E37') THEN NULL;
   ELSE RETURN jsonb_build_object('applied',false,'reason','z15_mode_or_reason_unqualified'); END IF;
  END LOOP;
  IF EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') o WHERE o->>'reason' IS DISTINCT FROM reason) THEN RETURN jsonb_build_object('applied',false,'reason','mixed_z15_modes'); END IF;
  IF reason='Z24' THEN
   SELECT * INTO ended_source FROM public.ediel_messages WHERE id=p.inbound_z15_message_id AND company_id=m.company_id AND environment=m.environment;
   ended_wire:=gridex_received_sources.permission_wire_v1(ended_source.raw_payload);
   IF ended_wire IS NULL OR ended_wire->>'sender' IS DISTINCT FROM wire->>'sender' OR ended_wire->>'receiver' IS DISTINCT FROM wire->>'receiver'
    OR jsonb_array_length(ended_wire->'objects')<>jsonb_array_length(wire->'objects')
    OR EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') own WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(ended_wire->'objects') old WHERE old->>'reason'=mode AND old->>'permissionId'=own->>'permissionId' AND old->>'point'=own->>'point' AND old->>'permissionEnd'=own->>'permissionEnd' AND old->>'li'=own->>'li'))
    THEN RETURN jsonb_build_object('applied',false,'reason','z15c_original_ending_not_bound'); END IF;
   SELECT * INTO prior FROM gridex_received_sources.permission_transitions WHERE source_message_id=ended_source.id AND permission_id=p.id;
   IF NOT FOUND OR p.market_state_version<>(prior.resulting_state->>'market_state_version')::bigint THEN RETURN jsonb_build_object('applied',false,'reason','z15c_original_snapshot_unavailable'); END IF;
   next_status:=prior.previous_state->>'status';
   UPDATE public.metering_permissions SET status=next_status,approved_end_date=(prior.previous_state->>'approved_end_date')::date,approved_end_at=(prior.previous_state->>'approved_end_at')::timestamptz WHERE id=p.id AND company_id=m.company_id;
   -- Restore exactly the previous object period; no customer-contract or
   -- beneficiary/service grant is revived by a market cancellation.
   UPDATE public.metering_permission_sites ps SET status=old->>'status',end_date=(old->>'end_date')::date,end_at=(old->>'end_at')::timestamptz,permission_end_at=(old->>'permission_end_at')::timestamptz,updated_at=now()
   FROM jsonb_array_elements(prior.previous_sites) old
   WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id AND ps.id=(old->>'id')::uuid
    AND EXISTS(SELECT FROM jsonb_array_elements(wire->'objects') own WHERE own->>'point'=ps.facility_id);
  ELSE
   FOR a IN SELECT o FROM jsonb_array_elements(wire->'objects') o LOOP
    end_day:=gridex_received_sources.permission_date_v1(a->>'permissionEnd');end_time:=gridex_received_sources.permission_time_v1(a->>'permissionEnd');
    UPDATE public.metering_permission_sites SET end_date=CASE WHEN end_at IS NULL OR end_time<end_at THEN end_day ELSE end_date END,end_at=least(end_at,end_time),permission_end_at=end_time,status=CASE WHEN end_time>now() THEN status ELSE 'ended' END,updated_at=now()
    WHERE company_id=m.company_id AND metering_permission_id=p.id AND facility_id=a->>'point';
   END LOOP;
   next_status:=CASE WHEN NOT EXISTS(SELECT FROM public.metering_permission_sites ps WHERE ps.company_id=m.company_id AND ps.metering_permission_id=p.id AND (ps.permission_end_at IS NULL OR ps.permission_end_at>now())) THEN 'ended' ELSE p.status END;
   UPDATE public.metering_permissions SET status=next_status,
