-- canonical:963
--
-- Name: missing_li_repair_scopes_v1(uuid, text, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.missing_li_repair_scopes_v1(c uuid, env text, ack_id uuid, source_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE receipt jsonb;ack public.ediel_messages%rowtype;source public.ediel_messages%rowtype;tokens jsonb;erc jsonb;physical jsonb;scope jsonb;next_erc int;point text;count_groups int;result jsonb:='[]';
BEGIN
 receipt:=gridex_ack_authority.prodat_physical_receipt_v1(c,env,ack_id,source_id);IF receipt IS NULL THEN RETURN '[]';END IF;
 SELECT * INTO STRICT ack FROM public.ediel_messages WHERE id=ack_id AND company_id=c AND environment=env;
 SELECT * INTO STRICT source FROM public.ediel_messages WHERE id=source_id AND company_id=c AND environment=env;
 tokens:=gridex_received_sources.closure_wire_tokens_v2(ack.raw_payload);physical:=gridex_ack_authority.prodat_physical_source_objects_v1(source.raw_payload);
 FOR scope IN SELECT x FROM jsonb_array_elements(receipt->'physicalOutcomes')x WHERE x->>'outcome'='negative' AND x#>>'{physicalReference,lineItemReference}' IS NULL LOOP
  count_groups:=0;
  FOR erc IN SELECT x FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='ERC' LOOP
   SELECT min((x->>'index')::int) INTO next_erc FROM jsonb_array_elements(tokens)x WHERE (x->>'index')::int>(erc->>'index')::int AND x->>'tag' IN('ERC','UNT','UNZ');
   IF erc#>>'{elements,1,0}'='41' AND erc#>>'{elements,1,2}'='260'
    AND EXISTS(SELECT FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='FTX' AND x#>>'{elements,1,0}'='AAO' AND x#>>'{elements,3,0}'='226' AND x#>>'{elements,3,2}'='260' AND (x->>'index')::int>(erc->>'index')::int AND (x->>'index')::int<next_erc)
    AND EXISTS(SELECT FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='Z07' AND x#>>'{elements,1,1}'=scope#>>'{physicalReference,objectId}' AND (x->>'index')::int>(erc->>'index')::int AND (x->>'index')::int<next_erc)
    AND NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='RFF' AND x#>>'{elements,1,0}'='LI' AND (x->>'index')::int>(erc->>'index')::int AND (x->>'index')::int<next_erc) THEN count_groups:=count_groups+1;END IF;
  END LOOP;
  IF count_groups<>1 THEN CONTINUE;END IF;
  SELECT x INTO STRICT physical FROM jsonb_array_elements(gridex_ack_authority.prodat_physical_source_objects_v1(source.raw_payload))x WHERE x->'lineIndex'=scope#>'{physicalReference,firstLineIndex}' AND x->>'id'=scope#>>'{physicalReference,objectId}' AND x->>'identityAgency'=scope#>>'{physicalReference,identityAgency}' AND x->>'li' IS NULL;
  result:=result||jsonb_build_array(physical);
 END LOOP;
 SELECT coalesce(jsonb_agg(x ORDER BY(x->>'lineIndex')::int),'[]') INTO result FROM jsonb_array_elements(result)x;RETURN result;
END$$;

REVOKE ALL ON FUNCTION gridex_received_sources.missing_li_repair_scopes_v1(uuid, text, uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:964
--
-- Name: mixed_owned_confirmation_v1(uuid, text, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.mixed_owned_confirmation_v1(c uuid, env text, msg uuid, assessment uuid, scope jsonb, business jsonb) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT FROM gridex_received_sources.prodat_mixed_object_receipts r JOIN gridex_received_sources.prodat_object_validation_facets f ON f.assessment_id=assessment AND f.source_message_id=r.source_message_id AND f.company_id=r.company_id AND f.environment=r.environment AND f.source_payload_hash=r.source_payload_hash AND f.facts_hash=r.object_facts_hash
  JOIN gridex_received_sources.normal_switch_confirmations n ON n.source_message_id=r.source_message_id AND n.company_id=r.company_id AND n.period_id::text=business->>'supplyPeriodId' AND n.switch_id::text=business->>'switchRequestId'
  WHERE r.company_id=c AND r.environment=env AND r.source_message_id=msg AND (SELECT current.facts_hash FROM gridex_received_sources.validation_assessments current WHERE current.id=assessment)=(SELECT initial.facts_hash FROM gridex_received_sources.validation_assessments initial WHERE initial.id=r.assessment_id) AND business->>'owner'='inbound-z04-switch-confirmation-v1' AND n.source_object->>'point'=scope->>'objectId'
   AND EXISTS(SELECT FROM jsonb_array_elements(r.processed_objects) o WHERE o->>'objectId'=scope->>'objectId' AND o->>'identityAgency'=scope->>'identityAgency' AND o->'firstLineIndex'=scope#>'{registers,0,lineIndex}' AND o->>'disposition'='accepted'))
$$;

REVOKE ALL ON FUNCTION gridex_received_sources.mixed_owned_confirmation_v1(uuid, text, uuid, uuid, jsonb, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:965
--
-- Name: mixed_period_canonical_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.mixed_period_canonical_v1(assessment uuid, c uuid, period uuid, msg uuid) RETURNS boolean
    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 SELECT EXISTS(SELECT FROM gridex_received_sources.prodat_mixed_object_receipts r
 JOIN gridex_received_sources.prodat_object_validation_facets f ON f.assessment_id=assessment AND f.source_payload_hash=r.source_payload_hash AND f.facts_hash=r.object_facts_hash
 JOIN gridex_received_sources.normal_switch_confirmations n ON n.source_message_id=r.source_message_id AND n.company_id=r.company_id AND n.period_id=period
 WHERE r.company_id=c AND r.source_message_id=msg AND (SELECT current.facts_hash FROM gridex_received_sources.validation_assessments current WHERE current.id=assessment)=(SELECT initial.facts_hash FROM gridex_received_sources.validation_assessments initial WHERE initial.id=r.assessment_id) AND f.facts_text::jsonb->>'sharedAccepted'='true'
 AND EXISTS(SELECT FROM jsonb_array_elements(r.processed_objects) o WHERE o->>'objectId'=n.source_object->>'point' AND o->>'identityAgency'=n.source_object->>'identityAgency' AND o->>'lineItemReference'=n.source_object->>'li' AND o->>'disposition'='accepted'))
$$;

REVOKE ALL ON FUNCTION gridex_received_sources.mixed_period_canonical_v1(uuid, uuid, uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:968
--
