 value:=substr(p_value,1,4)||'-'||substr(p_value,5,2)||'-'||substr(p_value,7,2)||'T'||substr(p_value,9,2)||':'||substr(p_value,11,2)||':00+01:00';
 result:=value::timestamptz;
 RETURN result;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END $_$;

