  facet:=jsonb_set(facet,'{responses}',original||jsonb_build_array(jsonb_build_object('scope','object','lineIndex',r.first_line_index,'ercCode','100','fieldCode',NULL,'text',positive_text,'id',planned->'id','li',planned->'li')));
 END LOOP;
