-- canonical:1035
--
-- Name: review_business_proof_before_customer_kind_v1(jsonb, jsonb, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.review_business_proof_before_customer_kind_v1(p_party jsonb, p_business jsonb, p_source_id uuid) RETURNS boolean
    LANGUAGE plpgsql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE src gridex_received_sources.sources%rowtype; baseline gridex_received_sources.sources%rowtype;
 root gridex_received_sources.object_assessments%rowtype; current_root gridex_received_sources.object_assessments%rowtype;
 review_snap gridex_received_sources.object_selection_snapshots%rowtype;
 predecessor gridex_received_sources.object_assessments%rowtype;
 cover jsonb:=p_business->'coverageWindow'; wire jsonb:=p_business->'wire'; replacement jsonb:=p_business->'replaces';
 root_entry jsonb; current_entry jsonb; previous_entry jsonb; epoch timestamptz; valid_start timestamptz; valid_end timestamptz;
 change_at timestamptz; minute text; market_time timestamp; owner_ok boolean;
BEGIN
 SELECT * INTO src FROM gridex_received_sources.sources WHERE source_message_id=p_source_id;
 IF NOT FOUND OR src.message_code NOT IN ('Z04','Z06','Z10') OR src.source_received_at IS NULL THEN RETURN false; END IF;
 -- Z06/E34 needs a persisted death assessment or a counterparty-scoped bilateral
 -- agreement. Neither authoritative producer exists in this review owner.
 IF src.message_code='Z06' AND p_business#>>'{wire,businessCase}'='customer_only' THEN RETURN false; END IF;
 IF p_business->>'owner' IS DISTINCT FROM 'reviewed-received-structure-v1'
 OR p_business->>'coverage' IS DISTINCT FROM 'reviewed_post_ledger_supply'
 OR p_business->>'businessDisposition' IS DISTINCT FROM 'reviewed'
 OR p_business->>'reviewStatement' IS DISTINCT FROM 'original_structural_message'
 OR p_business->>'graphNamespace' IS DISTINCT FROM 'legacy_unqualified'
 OR p_business#>>'{object,identityAgency}' IS DISTINCT FROM '9'
 OR p_business-ARRAY['version','owner','coverage','sourceDisposition','businessDisposition','graphNamespace','sourceMessageId','sourcePayloadHash','sourceReceivedAt','companyId','environment','object','assessedAt','wire','reviewerUserId','reviewStatement','customerId','meteringPointId','siteId','switchRequestId','supplyPeriodId','coverageWindow','baselineCurrentAssessmentId','reviewSnapshot','replaces']<>'{}'::jsonb
 OR NOT p_business ?& ARRAY['wire','reviewerUserId','reviewStatement','coverageWindow','baselineCurrentAssessmentId','reviewSnapshot','replaces']
 OR NOT gridex_received_sources.review_party_proof_consistent(p_party,p_business,src.source_received_at)
 OR NOT EXISTS(SELECT FROM public.companies c WHERE c.id=src.company_id AND coalesce(c.status,'active') IN ('active','onboarding'))
 OR NOT (public.gridex_actor_has_company_permission((p_business->>'reviewerUserId')::uuid,src.company_id,'communication.write')
   OR public.gridex_actor_has_company_permission((p_business->>'reviewerUserId')::uuid,src.company_id,'ediel_testing.write')) THEN RETURN false; END IF;
 IF cover->>'kind' IS DISTINCT FROM 'post_ledger_supply' OR cover->>'supplyPeriodId' IS DISTINCT FROM p_business->>'supplyPeriodId'
 OR cover->>'switchRequestId' IS DISTINCT FROM p_business->>'switchRequestId'
 OR cover-ARRAY['kind','baselineSourceMessageId','baselineAssessmentId','baselineFactsHash','supplyPeriodId','switchRequestId','switchCreatedAt','outboundSourceMessageId','outboundCreatedAt','validFrom','validTo']<>'{}'::jsonb
 OR NOT cover ?& ARRAY['kind','baselineSourceMessageId','baselineAssessmentId','baselineFactsHash','supplyPeriodId','switchRequestId','switchCreatedAt','outboundSourceMessageId','outboundCreatedAt','validFrom','validTo']
 OR wire->'object' IS DISTINCT FROM p_business->'object' OR wire->>'messageCode' IS DISTINCT FROM src.message_code
 OR wire->>'legalSender' IS DISTINCT FROM p_party#>>'{parties,legalSender}' OR wire->>'legalReceiver' IS DISTINCT FROM p_party#>>'{parties,legalReceiver}'
 OR wire->>'transportSender' IS DISTINCT FROM p_party#>>'{parties,transportSender}' OR wire->>'transportReceiver' IS DISTINCT FROM p_party#>>'{parties,transportReceiver}'
 OR wire#>>'{effectiveFrom,fieldNumber}' IS DISTINCT FROM (CASE WHEN src.message_code='Z04' THEN '210' ELSE '216' END)
 OR (CASE src.message_code WHEN 'Z04' THEN wire->>'businessCase'='supply_baseline' WHEN 'Z10' THEN wire->>'businessCase'='meter_exchange'
     ELSE wire->>'businessCase' IN ('customer_only','change_with_reading','change_without_reading') END) IS DISTINCT FROM true
 OR jsonb_typeof(wire->'registers') IS DISTINCT FROM 'array' OR jsonb_array_length(wire->'registers')<>jsonb_array_length(p_business#>'{object,registers}')
 OR nullif(wire->>'caseReference','') IS NULL OR nullif(wire->>'documentReference','') IS NULL THEN RETURN false; END IF;
 SELECT * INTO review_snap FROM gridex_received_sources.object_selection_snapshots
 WHERE id=(p_business#>>'{reviewSnapshot,snapshotId}')::uuid AND company_id=src.company_id AND environment=src.environment
 AND readset_hash=p_business#>>'{reviewSnapshot,readsetHash}' AND cutoff_at=(p_business#>>'{reviewSnapshot,cutoffAt}')::timestamptz;
 IF NOT FOUND OR (review_snap.readset_text::jsonb->>'complete') IS DISTINCT FROM 'true'
 OR review_snap.cutoff_at>(p_business->>'assessedAt')::timestamptz
 OR NOT EXISTS(SELECT FROM jsonb_array_elements(review_snap.readset_text::jsonb->'sources') item
   WHERE item->>'sourceMessageId'=src.source_message_id::text AND item->>'payloadHash'=src.payload_hash) THEN RETURN false; END IF;
 SELECT opened_at INTO epoch FROM gridex_received_sources.epoch WHERE singleton;
 valid_start:=(cover->>'validFrom')::timestamptz; valid_end:=(cover->>'validTo')::timestamptz;
 minute:=wire#>>'{effectiveFrom,marketMinute}';
 IF minute IS NULL OR minute !~ '^[0-9]{12}$' OR substring(minute,1,4)::int<1 OR substring(minute,9,2)::int>23 OR substring(minute,11,2)::int>59 THEN RETURN false; END IF;
 market_time:=make_timestamp(substring(minute,1,4)::int,substring(minute,5,2)::int,substring(minute,7,2)::int,substring(minute,9,2)::int,substring(minute,11,2)::int,0);
 change_at:=market_time AT TIME ZONE 'Etc/GMT-1';
 IF (wire#>>'{effectiveFrom,utc}')::timestamptz IS DISTINCT FROM change_at OR valid_start IS NULL OR NOT isfinite(valid_start)
 OR valid_start<epoch OR (valid_end IS NOT NULL AND (NOT isfinite(valid_end) OR valid_end<=valid_start))
 OR change_at<valid_start OR (valid_end IS NOT NULL AND change_at>=valid_end)
 OR (src.message_code='Z04' AND change_at<>valid_start) THEN RETURN false; END IF;
 SELECT * INTO baseline FROM gridex_received_sources.sources WHERE source_message_id=(cover->>'baselineSourceMessageId')::uuid
 AND company_id=src.company_id AND environment=src.environment AND message_code='Z04';
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT a.* INTO root FROM gridex_received_sources.object_assessments a JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=a.id
 WHERE a.id=(cover->>'baselineAssessmentId')::uuid AND a.source_message_id=baseline.source_message_id AND a.company_id=src.company_id
 AND a.environment=src.environment AND a.facts_hash=cover->>'baselineFactsHash' AND w.facts_hash=a.facts_hash AND w.observed_at<=review_snap.cutoff_at;
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT value INTO root_entry FROM jsonb_array_elements(root.facts_text::jsonb->'objects')
 WHERE value#>>'{object,objectId}'=p_business#>>'{object,objectId}' AND value#>>'{object,identityAgency}'='9';
 IF root_entry->>'disposition' IS DISTINCT FROM 'accepted' OR root_entry#>>'{business,owner}' IS DISTINCT FROM 'inbound-z04-switch-confirmation-v1'
 OR root_entry#>>'{business,switchRequestId}' IS DISTINCT FROM p_business->>'switchRequestId'
 OR root_entry#>>'{business,supplyPeriodId}' IS DISTINCT FROM p_business->>'supplyPeriodId'
 OR root_entry#>>'{business,customerId}' IS DISTINCT FROM p_business->>'customerId'
 OR root_entry#>>'{business,meteringPointId}' IS DISTINCT FROM p_business->>'meteringPointId'
 OR root_entry#>>'{business,siteId}' IS DISTINCT FROM p_business->>'siteId'
 OR (root_entry#>>'{business,effectiveFrom,utc}')::timestamptz IS DISTINCT FROM valid_start THEN RETURN false; END IF;
 SELECT a.* INTO current_root FROM gridex_received_sources.object_assessments a JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=a.id
 WHERE a.id=(p_business->>'baselineCurrentAssessmentId')::uuid AND a.source_message_id=baseline.source_message_id
 AND a.company_id=src.company_id AND a.environment=src.environment AND w.facts_hash=a.facts_hash AND w.observed_at<=review_snap.cutoff_at
 AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments next WHERE next.previous_assessment_id=a.id);
 IF NOT FOUND THEN RETURN false; END IF;
 SELECT value INTO current_entry FROM jsonb_array_elements(current_root.facts_text::jsonb->'objects')
 WHERE value#>>'{object,objectId}'=p_business#>>'{object,objectId}' AND value#>>'{object,identityAgency}'='9';
 IF current_entry->>'disposition' IS DISTINCT FROM 'accepted' THEN RETURN false; END IF;
 -- The retained snapshot must actually contain the current baseline assessment,
 -- rather than merely sharing a plausible time and tenant with it.
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(review_snap.readset_text::jsonb->'sources') source,
  LATERAL jsonb_array_elements(source->'assessments') assessment
  WHERE source->>'sourceMessageId'=baseline.source_message_id::text AND assessment->>'id'=current_root.id::text
  AND assessment->>'factsHash'=current_root.facts_hash AND (assessment->>'availableAt')::timestamptz<=review_snap.cutoff_at) THEN RETURN false; END IF;
 SELECT EXISTS(SELECT FROM public.supplier_switch_requests sw
 JOIN public.customer_supply_periods sp ON sp.id=(p_business->>'supplyPeriodId')::uuid
 JOIN public.ediel_messages outbound ON outbound.id=sw.outbound_z03_message_id
 JOIN public.metering_points mp ON mp.id=sw.metering_point_id JOIN public.customer_sites cs ON cs.id=sw.site_id
 WHERE sw.id=(p_business->>'switchRequestId')::uuid AND sw.company_id=src.company_id AND sp.company_id=src.company_id
 AND sw.inbound_z04_message_id=baseline.source_message_id AND sp.source_message_id=baseline.source_message_id
 AND gridex_received_sources.normal_switch_coverage_is_current_v1(src.company_id,sp.id,sw.id,baseline.source_message_id,valid_start,valid_end)
 AND sw.metering_point_id=(p_business->>'meteringPointId')::uuid AND sp.metering_point_id=sw.metering_point_id
 AND sw.customer_id=(p_business->>'customerId')::uuid AND sp.customer_id=sw.customer_id AND sw.site_id=(p_business->>'siteId')::uuid
 AND (sp.source_switch_request_id IS NULL OR sp.source_switch_request_id=sw.id)
 AND mp.company_id=src.company_id AND cs.company_id=src.company_id AND mp.site_id=cs.id AND mp.customer_id=sw.customer_id AND cs.customer_id=sw.customer_id
 AND sw.confirmed_start_date=sp.start_date
 AND sw.created_at=(cover->>'switchCreatedAt')::timestamptz AND sw.created_at>=epoch AND sw.created_at<=valid_start
 AND outbound.id=(cover->>'outboundSourceMessageId')::uuid AND outbound.company_id=src.company_id AND outbound.environment=src.environment
 AND outbound.direction='outbound' AND outbound.message_standard='edifact' AND outbound.message_family='PRODAT' AND outbound.message_code='Z03'
 AND outbound.created_at=(cover->>'outboundCreatedAt')::timestamptz AND outbound.created_at>=sw.created_at AND outbound.created_at<=review_snap.cutoff_at
 AND outbound.customer_id=sw.customer_id AND outbound.metering_point_id=sw.metering_point_id AND outbound.site_id=sw.site_id) INTO owner_ok;
 IF owner_ok IS DISTINCT FROM true THEN RETURN false; END IF;
 IF wire->>'functionCode'='5' THEN
  IF replacement IS NULL OR jsonb_typeof(replacement)<>'object' OR replacement->>'sourceMessageId'=src.source_message_id::text THEN RETURN false; END IF;
  SELECT a.* INTO predecessor FROM gridex_received_sources.object_assessments a JOIN gridex_received_sources.object_availability_witnesses w ON w.assessment_id=a.id
  WHERE a.id=(replacement->>'assessmentId')::uuid AND a.source_message_id=(replacement->>'sourceMessageId')::uuid
  AND a.company_id=src.company_id AND a.environment=src.environment AND a.source_payload_hash=replacement->>'payloadHash'
  AND w.facts_hash=a.facts_hash AND w.observed_at<=review_snap.cutoff_at
  AND NOT EXISTS(SELECT FROM gridex_received_sources.object_assessments next WHERE next.previous_assessment_id=a.id);
  IF NOT FOUND THEN RETURN false; END IF;
  SELECT value INTO previous_entry FROM jsonb_array_elements(predecessor.facts_text::jsonb->'objects')
  WHERE value#>>'{object,objectId}'=p_business#>>'{object,objectId}' AND value#>>'{object,identityAgency}'='9';
  IF previous_entry->>'disposition' IS DISTINCT FROM 'accepted' OR previous_entry#>>'{business,owner}' IS DISTINCT FROM 'reviewed-received-structure-v1'
  OR previous_entry#>>'{business,supplyPeriodId}' IS DISTINCT FROM p_business->>'supplyPeriodId'
  OR previous_entry#>>'{business,wire,messageCode}' IS DISTINCT FROM wire->>'messageCode'
  OR previous_entry#>>'{business,wire,businessCase}' IS DISTINCT FROM wire->>'businessCase'
  OR previous_entry#>>'{business,wire,caseReference}' IS DISTINCT FROM wire->>'caseReference'
  OR previous_entry#>>'{business,wire,documentReference}' IS NOT DISTINCT FROM wire->>'documentReference'
  OR previous_entry#>>'{business,wire,legalSender}' IS DISTINCT FROM wire->>'legalSender'
  OR previous_entry#>>'{business,wire,legalReceiver}' IS DISTINCT FROM wire->>'legalReceiver' THEN RETURN false; END IF;
 ELSE
  IF wire->'functionCode' NOT IN ('"9"'::jsonb,'null'::jsonb) OR replacement IS DISTINCT FROM 'null'::jsonb
   OR (src.message_code='Z04' AND baseline.source_message_id<>src.source_message_id) THEN RETURN false; END IF;
 END IF;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR invalid_datetime_format OR datetime_field_overflow OR numeric_value_out_of_range OR invalid_parameter_value THEN RETURN false;
END $_$;

REVOKE ALL ON FUNCTION gridex_received_sources.review_business_proof_before_customer_kind_v1(jsonb, jsonb, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1039
--
-- Name: seal_utilts_insert_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.seal_utilts_insert_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE observed timestamptz:=clock_timestamp();
BEGIN IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
 IF TG_OP='UPDATE' THEN
  IF OLD.execution_context_snapshot ? 'receivedUtiltsContext' THEN
   IF NEW.execution_context_snapshot->'receivedUtiltsContext' IS DISTINCT FROM OLD.execution_context_snapshot->'receivedUtiltsContext'
    OR NEW.raw_payload IS DISTINCT FROM OLD.raw_payload OR NEW.immutable_payload_hash IS DISTINCT FROM OLD.immutable_payload_hash
    OR ROW(NEW.id,NEW.company_id,NEW.environment,NEW.direction,NEW.message_family,NEW.message_standard,NEW.message_code,NEW.message_received_at)
      IS DISTINCT FROM ROW(OLD.id,OLD.company_id,OLD.environment,OLD.direction,OLD.message_family,OLD.message_standard,OLD.message_code,OLD.message_received_at)
   THEN RAISE EXCEPTION 'immutable_received_utilts_source_cannot_change' USING ERRCODE='23514'; END IF;
  ELSIF NEW.execution_context_snapshot ? 'receivedUtiltsContext' THEN
   RAISE EXCEPTION 'received_utilts_context_cannot_be_backfilled' USING ERRCODE='23514';
  END IF;
 ELSIF TG_OP='INSERT' THEN
  IF jsonb_typeof(NEW.execution_context_snapshot) IN ('object','array') THEN
   NEW.execution_context_snapshot:=NEW.execution_context_snapshot-'receivedUtiltsContext';
  END IF;
  IF NEW.direction='inbound' AND NEW.message_family='UTILTS' AND NEW.message_standard='edifact'
   AND NEW.id IS NOT NULL AND NEW.company_id IS NOT NULL AND NEW.environment IN('test','production')
   AND NEW.message_code IS NOT NULL AND NEW.message_received_at IS NOT NULL AND NEW.raw_payload IS NOT NULL THEN
   NEW.immutable_payload_hash:=encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex');
   NEW.execution_context_snapshot:=(CASE WHEN jsonb_typeof(NEW.execution_context_snapshot)='object' THEN NEW.execution_context_snapshot ELSE '{}'::jsonb END)
    ||jsonb_build_object('receivedUtiltsContext',jsonb_build_object('version',1,'contextOrigin','database_insert','sourceMessageId',NEW.id,
     'companyId',NEW.company_id,'environment',NEW.environment,'messageCode',NEW.message_code,'payloadHash',NEW.immutable_payload_hash,
     'sourceReceivedAt',NEW.message_received_at,'capturedAt',observed));
  END IF;
 END IF;
 RETURN NEW;
END $$;

REVOKE ALL ON FUNCTION gridex_received_sources.seal_utilts_insert_v1() FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1044
--
-- Name: sent_source_is_current_v1(public.ediel_messages); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.sent_source_is_current_v1(m public.ediel_messages) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF m.direction IS DISTINCT FROM 'outbound' OR (m.status IN('sent','acknowledged')) IS NOT TRUE OR m.message_sent_at IS NULL OR m.immutable_rendered_at IS NULL OR m.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RETURN false;END IF;
 -- The shared private provider journal supplies actual acceptance. A positive
 -- ACK projection does not approve a supply or manufacture a sent original.
 RETURN gridex_ediel_transport.accepted_source_basis_v1(m) IS NOT NULL;
END $$;

REVOKE ALL ON FUNCTION gridex_received_sources.sent_source_is_current_v1(public.ediel_messages) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1046
--
-- Name: structural_effect_matches_v1(uuid, text, uuid, uuid, uuid, uuid, uuid, uuid, text, text, timestamp with time zone); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.structural_effect_matches_v1(c uuid, env text, source_id uuid, assessment_id uuid, customer uuid, site uuid, point uuid, period uuid, object_id text, agency text, cutoff timestamp with time zone) RETURNS boolean
    LANGUAGE sql STABLE SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
 WITH receipts AS(SELECT source_message_id,company_id,environment,payload_hash,canonical_assessment_id,object_assessment_id,applied_at,objects FROM gridex_received_sources.structural_apply_receipts
 UNION ALL SELECT source_message_id,company_id,environment,payload_hash,canonical_assessment_id,object_assessment_id,applied_at,jsonb_build_array(effect) FROM gridex_received_sources.structural_object_apply_receipts)
 SELECT count(*)=1 FROM receipts r
 JOIN gridex_received_sources.sources s ON s.source_message_id=r.source_message_id AND s.company_id=r.company_id AND s.environment=r.environment AND s.payload_hash=r.payload_hash
 JOIN gridex_received_sources.object_assessments a ON a.id=r.object_assessment_id AND a.company_id=r.company_id AND a.environment=r.environment AND a.source_message_id=r.source_message_id AND a.source_payload_hash=r.payload_hash AND a.canonical_assessment_id=r.canonical_assessment_id,
 LATERAL jsonb_array_elements(a.facts_text::jsonb->'objects') own,LATERAL jsonb_array_elements(r.objects) applied
 WHERE r.company_id=c AND r.environment=env AND r.source_message_id=source_id AND r.object_assessment_id=assessment_id AND r.applied_at<=cutoff
 AND s.payload_hash=encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex') AND a.facts_hash=encode(sha256(convert_to(a.facts_text,'UTF8')),'hex')
 AND own->>'disposition'='accepted' AND own#>>'{business,owner}'='reviewed-received-structure-v1'
 AND own#>>'{business,companyId}'=c::text AND own#>>'{business,environment}'=env AND own#>>'{business,customerId}'=customer::text AND own#>>'{business,siteId}'=site::text AND own#>>'{business,meteringPointId}'=point::text AND own#>>'{business,supplyPeriodId}'=period::text
 AND own#>>'{object,objectId}'=object_id AND own#>>'{object,identityAgency}'=agency AND applied->'object'=own->'object' AND applied->'wire'=own#>'{business,wire}'
 AND applied->>'meteringPointId'=point::text AND applied->>'siteId'=site::text
$$;

REVOKE ALL ON FUNCTION gridex_received_sources.structural_effect_matches_v1(uuid, text, uuid, uuid, uuid, uuid, uuid, uuid, text, text, timestamp with time zone) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1047
--
-- Name: supply_effect_assessment_owns_period_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.supply_effect_assessment_owns_period_v1(c uuid, source_id uuid, period_id uuid, canonical_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE r gridex_received_sources.supply_object_effect_receipts%rowtype;m public.ediel_messages%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c;
 SELECT stored.* INTO r FROM gridex_received_sources.supply_object_effect_receipts stored WHERE stored.company_id=c AND stored.source_message_id=source_id AND stored.canonical_assessment_id=canonical_id AND stored.environment=m.environment
  AND stored.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296)
  AND stored.payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND stored.effect_hash=encode(sha256(convert_to(stored.effect_text,'UTF8')),'hex')
  AND EXISTS(SELECT FROM jsonb_array_elements(stored.effect_text::jsonb->'resultingStates')state WHERE state->>'id'=period_id::text);
 RETURN r.id IS NOT NULL AND r.effect_text::jsonb->>'owner'='inbound-supply-object-v1' AND r.effect_text::jsonb->'object'=r.object_scope
  AND EXISTS(SELECT FROM gridex_received_sources.supply_source_transitions tr WHERE tr.company_id=c AND tr.source_message_id=source_id AND tr.payload_hash=r.payload_hash AND EXISTS(SELECT FROM jsonb_array_elements(tr.resulting_states)state WHERE state->>'id'=period_id::text AND r.effect_text::jsonb->'resultingStates'@>jsonb_build_array(state)));
END$$;

REVOKE ALL ON FUNCTION gridex_received_sources.supply_effect_assessment_owns_period_v1(uuid, uuid, uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1048
--
-- Name: supply_period_source_at_v1(uuid, uuid, timestamp with time zone); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.supply_period_source_at_v1(p_company_id uuid, p_period_id uuid, p_at timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE basis jsonb;
BEGIN
 IF p_at IS NULL OR NOT isfinite(p_at) THEN RETURN NULL;END IF;
 basis:=gridex_received_sources.supply_period_source_basis_v1(p_company_id,p_period_id,p_at,p_at+interval '1 microsecond');
 IF basis IS NULL OR basis->>'qualified' IS DISTINCT FROM 'true' OR (basis->>'marketStartAt')::timestamptz IS NULL OR (basis->>'marketStartAt')::timestamptz>p_at OR ((basis->>'marketEndAt') IS NOT NULL AND p_at>=(basis->>'marketEndAt')::timestamptz) THEN RETURN NULL;END IF;
 RETURN basis||jsonb_build_object('basisKind','exact_source_point','at',p_at);
EXCEPTION WHEN datetime_field_overflow THEN RETURN NULL;
END $$;

REVOKE ALL ON FUNCTION gridex_received_sources.supply_period_source_at_v1(uuid, uuid, timestamp with time zone) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1049
--
-- Name: supply_period_source_basis_v1(uuid, uuid, timestamp with time zone, timestamp with time zone); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.supply_period_source_basis_v1(p_company_id uuid, p_period_id uuid, p_start timestamp with time zone, p_end timestamp with time zone) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE p public.customer_supply_periods%rowtype;proof gridex_received_sources.normal_switch_confirmations%rowtype;
 tr gridex_received_sources.supply_source_transitions%rowtype;activation gridex_received_sources.normal_supply_activations%rowtype;
 m public.ediel_messages%rowtype;origin public.ediel_messages%rowtype;initial_message public.ediel_messages%rowtype;c public.customer_contracts%rowtype;s public.supplier_switch_requests%rowtype;
 expected jsonb;baseline jsonb;legal jsonb;initial_owned jsonb;source_objects jsonb;initial_wire jsonb;accepted_original jsonb;initial_transition gridex_received_sources.supply_source_transitions%rowtype;ids uuid[];version bigint;source_id uuid;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_supply_v1();
 PERFORM gridex_regulated_supply.lock_graph_v1();
 IF p_company_id IS NULL OR p_period_id IS NULL OR p_start IS NULL OR p_end IS NULL OR NOT isfinite(p_start) OR NOT isfinite(p_end) OR p_end<=p_start THEN RETURN NULL;END IF;
 SELECT * INTO p FROM public.customer_supply_periods WHERE id=p_period_id AND company_id=p_company_id;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF p.source_process IN('assigned_supply','production_receipt_obligation') AND gridex_regulated_supply.ground_current_v1((p.metadata->>'sourceGroundId')::uuid,p_company_id,p.metering_point_id,p.market_start_at) IS NOT TRUE THEN RETURN NULL;END IF;
 SELECT * INTO proof FROM gridex_received_sources.normal_switch_confirmations WHERE period_id=p.id AND company_id=p_company_id;
 IF NOT FOUND THEN
  baseline:=gridex_received_sources.billing_supply_before_normal_switch_v1(p_company_id,p_period_id,p_start,p_end);
  IF baseline IS NULL THEN RETURN NULL;END IF;
  SELECT * INTO p FROM public.customer_supply_periods WHERE id=p_period_id AND company_id=p_company_id;
  IF p.market_state_version IS DISTINCT FROM (baseline->>'marketStateVersion')::bigint THEN RETURN NULL;END IF;
  SELECT own#>'{metadata,sourceObject}' INTO initial_owned FROM gridex_received_sources.supply_source_transitions initial,jsonb_array_elements(initial.resulting_states) own WHERE initial.source_message_id=p.source_message_id AND initial.company_id=p_company_id AND own->>'id'=p.id::text;
  SELECT * INTO origin FROM public.ediel_messages WHERE id=p.source_message_id AND company_id=p_company_id;
  SELECT jsonb_agg(own) INTO source_objects FROM jsonb_array_elements(coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(p_company_id,origin.id,p.id),gridex_received_sources.normal_switch_wire_v1(origin.raw_payload))->'objects') own WHERE own->>'point'=initial_owned->>'point' AND own->>'li'=initial_owned->>'li' AND own->>'start'=initial_owned->>'start';
  IF jsonb_array_length(source_objects) IS DISTINCT FROM 1 OR (source_objects#>>'{0,identityAgency}' IN('9','89')) IS NOT TRUE THEN RETURN NULL;END IF;
  RETURN baseline||jsonb_build_object('initialSourceMessageId',p.source_message_id,'legalActorId',(SELECT g.legal_actor_id FROM gridex_received_sources.regulated_supply_ground_versions g WHERE g.id::text=baseline->>'groundId' AND g.company_id=p_company_id),'sourceObjects',source_objects,'dsoEdielId',coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(p_company_id,origin.id,p.id),gridex_received_sources.normal_switch_wire_v1(origin.raw_payload))->>'sender');
 END IF;
 IF gridex_bilateral_prodat.recorded_supply_current_v1(p_company_id,proof.source_message_id) IS NOT TRUE THEN RETURN NULL;END IF;
 IF p.source_end_message_id IS NOT NULL AND gridex_bilateral_prodat.recorded_supply_current_v1(p_company_id,p.source_end_message_id) IS NOT TRUE THEN RETURN NULL;END IF;
 version:=p.market_state_version;source_id:=p.source_message_id;
 SELECT array_agg(t.source_message_id) INTO ids FROM gridex_received_sources.supply_source_transitions t WHERE t.company_id=p_company_id AND EXISTS(SELECT FROM jsonb_array_elements(t.resulting_states) own WHERE own->>'id'=p.id::text AND (own->>'market_state_version')::bigint=version);
 IF coalesce(cardinality(ids),0)<>1 THEN RETURN NULL;END IF;
 PERFORM z.id FROM public.ediel_messages z WHERE z.company_id=p_company_id AND z.id=ANY(ARRAY[ids[1],source_id,proof.source_message_id,proof.original_message_id]) ORDER BY z.id FOR UPDATE;
 legal:=gridex_ediel_inbound_context.require_v1(p_company_id,proof.source_message_id);
 SELECT * INTO initial_message FROM public.ediel_messages WHERE id=proof.source_message_id AND company_id=p_company_id;
 SELECT * INTO initial_transition FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=proof.source_message_id AND company_id=p_company_id;
 initial_wire:=coalesce(gridex_received_sources.supply_wire_for_period_receipt_v1(p_company_id,initial_message.id,p.id),gridex_received_sources.normal_switch_wire_v1(initial_message.raw_payload));
 IF initial_message.direction IS DISTINCT FROM 'inbound' OR initial_message.message_family IS DISTINCT FROM 'PRODAT' OR initial_message.message_code IS DISTINCT FROM 'Z04'
  OR initial_transition.payload_hash IS DISTINCT FROM encode(sha256(convert_to(initial_message.raw_payload,'UTF8')),'hex')
  OR initial_wire->>'receiver' IS DISTINCT FROM proof.legal_context->>'legalEdielId' OR nullif(initial_wire->>'sender','') IS NULL
  OR (SELECT count(*) FROM jsonb_array_elements(initial_wire->'objects') own WHERE own=proof.source_object)<>1
  OR NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=initial_message.id AND v.company_id=p_company_id AND v.environment=initial_message.environment AND v.source_payload_hash=initial_transition.payload_hash AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND ((v.facts_text::jsonb->>'applicationDecision'='accepted' OR gridex_received_sources.supply_effect_assessment_owns_period_v1(p_company_id,v.source_message_id,p.id,v.id)) OR gridex_received_sources.mixed_period_canonical_v1(v.id,p_company_id,proof.period_id,proof.source_message_id)) AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN NULL;END IF;
 SELECT * INTO s FROM public.supplier_switch_requests WHERE id=proof.switch_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO p FROM public.customer_supply_periods WHERE id=p_period_id AND company_id=p_company_id FOR SHARE;
 IF p.market_state_version IS DISTINCT FROM version OR p.source_message_id IS DISTINCT FROM source_id OR p.source_message_id IS DISTINCT FROM proof.source_message_id OR p.source_switch_request_id IS DISTINCT FROM proof.switch_id
  OR p.customer_id IS DISTINCT FROM (proof.confirmed_period->>'customer_id')::uuid OR p.metering_point_id IS DISTINCT FROM (proof.confirmed_period->>'metering_point_id')::uuid
  OR p.market_start_at IS DISTINCT FROM proof.market_start_at OR p.market_start_at>p_start OR (p.market_end_at IS NOT NULL AND p_end>p.market_end_at)
  OR (p.status IN('confirmed_by_grid_owner','active','ending','ended')) IS NOT TRUE OR s.inbound_z04_message_id IS DISTINCT FROM proof.source_message_id OR s.outbound_z03_message_id IS DISTINCT FROM proof.original_message_id
  OR s.customer_id IS DISTINCT FROM p.customer_id OR s.metering_point_id IS DISTINCT FROM p.metering_point_id OR s.lifecycle_blocked THEN RETURN NULL;END IF;
 SELECT * INTO tr FROM gridex_received_sources.supply_source_transitions WHERE source_message_id=ids[1] AND company_id=p_company_id;
 SELECT * INTO m FROM public.ediel_messages WHERE id=tr.source_message_id AND company_id=p_company_id;
 SELECT own INTO expected FROM jsonb_array_elements(tr.resulting_states) own WHERE own->>'id'=p.id::text;
 SELECT * INTO activation FROM gridex_received_sources.normal_supply_activations WHERE period_id=p.id AND company_id=p_company_id;
 baseline:=CASE WHEN activation.period_id IS NOT NULL AND tr.source_message_id=proof.source_message_id THEN activation.resulting_period ELSE expected END;
 IF expected IS NULL OR baseline IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR tr.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex')
  OR (to_jsonb(p)-ARRAY['updated_at','status']) IS DISTINCT FROM (baseline-ARRAY['updated_at','status'])
  OR (p.status IS DISTINCT FROM baseline->>'status' AND NOT(p.status='ended' AND baseline->>'status'='ending' AND p.market_end_at<=now()))
  OR (s.status IS DISTINCT FROM proof.confirmed_switch->>'status' AND NOT(s.status='completed' AND activation.period_id IS NOT NULL)) THEN RETURN NULL;END IF;
 SELECT * INTO origin FROM public.ediel_messages WHERE id=proof.original_message_id AND company_id=p_company_id AND environment=m.environment;
 SELECT * INTO c FROM public.customer_contracts WHERE id=proof.contract_id AND company_id=p_company_id FOR SHARE;
 IF origin.direction IS DISTINCT FROM 'outbound' OR gridex_received_sources.sent_source_is_current_v1(origin) IS NOT TRUE OR origin.immutable_payload_hash IS DISTINCT FROM proof.original_payload_hash OR origin.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(origin.raw_payload,'UTF8')),'hex')
  OR c.id IS NULL OR c.customer_id IS DISTINCT FROM p.customer_id OR c.metering_point_id IS DISTINCT FROM p.metering_point_id OR (c.status IN('signed','active') OR c.status='terminated' AND c.termination_reason='supply_end' AND p.end_date IS NOT NULL AND c.ended_at IS NOT NULL
   AND ((c.ended_at AT TIME ZONE 'UTC')::date=p.end_date OR (c.ended_at AT TIME ZONE 'Europe/Stockholm')::date=p.end_date)) IS NOT TRUE OR gridex_received_sources.production_contract_hash_v1(c) IS DISTINCT FROM proof.protected_contract_hash
  OR legal->>'legalActorId' IS DISTINCT FROM proof.legal_context->>'legalActorId' OR legal->>'actorRole' IS DISTINCT FROM 'electricity_supplier'
  OR NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments v WHERE v.source_message_id=m.id AND v.company_id=p_company_id AND v.environment=m.environment AND v.source_payload_hash=tr.payload_hash AND v.facts_text::jsonb->>'syntaxDecision'='accepted' AND ((v.facts_text::jsonb->>'applicationDecision'='accepted' OR gridex_received_sources.supply_effect_assessment_owns_period_v1(p_company_id,v.source_message_id,p.id,v.id)) OR gridex_received_sources.mixed_period_canonical_v1(v.id,p_company_id,proof.period_id,proof.source_message_id)) AND v.facts_text::jsonb->>'functionalDecision'='accepted' AND NOT EXISTS(SELECT FROM gridex_received_sources.validation_assessments child WHERE child.previous_assessment_id=v.id)) THEN RETURN NULL;END IF;
 accepted_original:=gridex_ediel_transport.accepted_source_basis_v1(origin);
 IF accepted_original IS NULL THEN RETURN NULL;END IF;
 RETURN jsonb_build_object('qualified',true,'periodId',p.id,'companyId',p.company_id,'customerId',p.customer_id,'meteringPointId',p.metering_point_id,'siteId',coalesce(proof.confirmed_switch->>'site_id',proof.confirmed_switch->>'customer_site_id'),'switchId',proof.switch_id,
  'sourceMessageId',m.id,'initialSourceMessageId',proof.source_message_id,'currentSourceMessageId',m.id,'payloadHash',tr.payload_hash,'marketStateVersion',p.market_state_version,'marketStartAt',p.market_start_at,'marketEndAt',p.market_end_at,
  'legalActorId',proof.legal_context->>'legalActorId','sourceObjects',jsonb_build_array(proof.source_object),'dsoEdielId',initial_wire->>'sender','originalMessageId',origin.id,'originalPayloadHash',origin.immutable_payload_hash,'originalAcceptedAt',accepted_original->>'observedAt','activated',activation.period_id IS NOT NULL);
END $$;

REVOKE ALL ON FUNCTION gridex_received_sources.supply_period_source_basis_v1(uuid, uuid, timestamp with time zone, timestamp with time zone) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1051
--
-- Name: supply_wire_for_period_receipt_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.supply_wire_for_period_receipt_v1(c uuid, source_id uuid, period_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;r gridex_received_sources.supply_object_effect_receipts%rowtype;wire jsonb;BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c;
 SELECT e.* INTO r FROM gridex_received_sources.supply_object_effect_receipts e WHERE e.company_id=c AND e.source_message_id=source_id AND e.environment=m.environment
  AND e.xmin::text::numeric<>mod(pg_current_xact_id()::text::numeric,4294967296)
  AND e.payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') AND e.effect_hash=encode(sha256(convert_to(e.effect_text,'UTF8')),'hex')
  AND EXISTS(SELECT FROM jsonb_array_elements(e.effect_text::jsonb->'resultingStates')state WHERE state->>'id'=period_id::text);
 IF r.id IS NULL OR r.effect_text::jsonb->>'owner' IS DISTINCT FROM 'inbound-supply-object-v1' OR r.effect_text::jsonb->'object' IS DISTINCT FROM r.object_scope THEN RETURN NULL;END IF;
 wire:=gridex_received_sources.supply_wire_for_scope_v1(m.raw_payload,r.object_scope);
 IF wire#>'{objects,0}' IS DISTINCT FROM r.effect_text::jsonb->'wire' THEN RETURN NULL;END IF;RETURN wire;
END$$;

REVOKE ALL ON FUNCTION gridex_received_sources.supply_wire_for_period_receipt_v1(uuid, uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1052
--
-- Name: supply_wire_for_scope_v1(text, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.supply_wire_for_scope_v1(raw text, scope jsonb) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(raw);t jsonb;e jsonb;header jsonb:='{}';own jsonb;first_index integer;last_index integer;key text;value text;characteristic text;
BEGIN
 IF tokens IS NULL OR scope->>'messageIndex' IS DISTINCT FROM '0' OR jsonb_typeof(scope->'registers') IS DISTINCT FROM 'array' OR jsonb_array_length(scope->'registers')<1 THEN RETURN NULL;END IF;
 first_index:=(scope#>>'{registers,0,segmentIndex}')::integer;
 SELECT x INTO t FROM jsonb_array_elements(tokens)x WHERE x->>'index'=first_index::text AND x->>'tag'='LIN';
 IF t IS NULL OR t#>>'{elements,3,0}' IS DISTINCT FROM scope->>'objectId' OR t#>>'{elements,3,3}' IS DISTINCT FROM scope->>'identityAgency' THEN RETURN NULL;END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements(scope->'registers')r WHERE NOT EXISTS(SELECT FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='LIN' AND x->>'index'=r->>'segmentIndex' AND x#>>'{elements,3,0}'=scope->>'objectId' AND x#>>'{elements,3,3}'=scope->>'identityAgency')) THEN RETURN NULL;END IF;
 SELECT min((x->>'index')::integer) INTO last_index FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='LIN' AND (x->>'index')::integer>first_index;
 IF(SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='BGM')<>1 OR(SELECT count(*) FROM jsonb_array_elements(tokens)x WHERE x->>'tag'='UNH')<>1 THEN RETURN NULL;END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::integer<(SELECT min((first_lin->>'index')::integer) FROM jsonb_array_elements(tokens)first_lin WHERE first_lin->>'tag'='LIN') AND x->>'tag' IN('BGM','NAD') ORDER BY(x->>'index')::integer LOOP
  e:=t->'elements';IF t->>'tag'='BGM' THEN header:=header||jsonb_build_object('code',e#>>'{1,0}','bgmId',e#>>'{2,0}');END IF;
  IF t->>'tag'='NAD' AND e#>>'{1,0}' IN('FR','DO') THEN key:=CASE e#>>'{1,0}' WHEN 'FR' THEN 'sender' ELSE 'receiver' END;IF header?key OR e#>>'{2,1}' IS DISTINCT FROM '160' OR e#>>'{2,2}' IS DISTINCT FROM 'SVK' THEN RETURN NULL;END IF;header:=header||jsonb_build_object(key,e#>>'{2,0}');END IF;
 END LOOP;
 -- Only message-header parties precede the FIRST physical LIN. Later objects
 -- must not expose an earlier object's NAD as a second message header.
 IF nullif(header->>'sender','') IS NULL OR nullif(header->>'receiver','') IS NULL OR(header->>'code' IN('Z04','Z05')) IS NOT TRUE THEN RETURN NULL;END IF;
 SELECT x INTO t FROM jsonb_array_elements(tokens)x WHERE x->>'index'=first_index::text;
 own:=jsonb_build_object('point',scope->>'objectId','identityAgency',scope->>'identityAgency','line',t#>>'{elements,1,0}','registerCount',jsonb_array_length(scope->'registers'));
 FOR t IN SELECT x FROM jsonb_array_elements(tokens)x WHERE(x->>'index')::integer>first_index AND(last_index IS NULL OR(x->>'index')::integer<last_index) ORDER BY(x->>'index')::integer LOOP
  e:=t->'elements';key:=NULL;value:=NULL;
  IF t->>'tag'='RFF' AND e#>>'{1,0}' IN('LI','Z05','Z07') THEN key:=CASE e#>>'{1,0}' WHEN 'LI' THEN 'li' WHEN 'Z05' THEN 'gridArea' ELSE 'consumptionPoint' END;value:=e#>>'{1,1}';
  ELSIF t->>'tag'='NAD' AND e#>>'{1,0}'='UD' THEN key:='customerIdentity';value:=e#>>'{2,0}';
  ELSIF t->>'tag'='DTM' AND e#>>'{1,0}' IN('92','93') THEN IF e#>>'{1,2}' IS DISTINCT FROM '203' THEN RETURN NULL;END IF;key:=CASE e#>>'{1,0}' WHEN '92' THEN 'start' ELSE 'end' END;value:=e#>>'{1,1}';
  ELSIF t->>'tag'='CCI' THEN characteristic:=e#>>'{2,0}';
  ELSIF t->>'tag'='CAV' THEN key:=CASE characteristic WHEN 'Z13' THEN 'reason' WHEN 'Z23' THEN 'status' END;value:=e#>>'{1,0}';END IF;
  IF key IS NOT NULL THEN IF own?key THEN RETURN NULL;END IF;own:=own||jsonb_build_object(key,nullif(value,''));END IF;
 END LOOP;
 RETURN header||jsonb_build_object('objects',jsonb_build_array(own));
END$$;

REVOKE ALL ON FUNCTION gridex_received_sources.supply_wire_for_scope_v1(text, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1053
--
-- Name: supply_wire_v1(text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.supply_wire_v1(p_raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(p_raw);t jsonb;e jsonb;out jsonb:='{}';objects jsonb:='[]';obj jsonb;characteristic text;key text;value text;
BEGIN
 IF tokens IS NULL THEN RETURN NULL; END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens) x ORDER BY (x->>'index')::int LOOP
  e:=t->'elements';
  IF t->>'tag'='BGM' THEN out:=out||jsonb_build_object('code',e#>>'{1,0}','bgmId',e#>>'{2,0}'); END IF;
  IF t->>'tag'='NAD' AND obj IS NULL AND e#>>'{1,0}' IN ('FR','DO') THEN
   key:=CASE e#>>'{1,0}' WHEN 'FR' THEN 'sender' ELSE 'receiver' END;
   IF out ? key OR e#>>'{2,1}' IS DISTINCT FROM '160' OR e#>>'{2,2}' IS DISTINCT FROM 'SVK' THEN RETURN NULL; END IF;
   out:=out||jsonb_build_object(key,e#>>'{2,0}');
  END IF;
  IF t->>'tag'='LIN' THEN
   IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj); END IF;
   obj:=jsonb_build_object('point',nullif(e#>>'{3,0}',''),'line',e#>>'{1,0}');characteristic:=NULL;
  ELSIF obj IS NOT NULL THEN
   key:=NULL;value:=NULL;
   IF t->>'tag'='RFF' AND e#>>'{1,0}' IN ('LI','Z05','Z07') THEN key:=CASE e#>>'{1,0}' WHEN 'LI' THEN 'li' WHEN 'Z05' THEN 'gridArea' ELSE 'consumptionPoint' END;value:=e#>>'{1,1}';
   ELSIF t->>'tag'='NAD' AND e#>>'{1,0}'='UD' THEN key:='customerIdentity';value:=e#>>'{2,0}';
   ELSIF t->>'tag'='DTM' AND e#>>'{1,0}' IN ('92','93') THEN
    key:=CASE e#>>'{1,0}' WHEN '92' THEN 'start' ELSE 'end' END;value:=e#>>'{1,1}';
    IF e#>>'{1,2}' IS DISTINCT FROM '203' THEN RETURN NULL; END IF;
   ELSIF t->>'tag'='CCI' THEN characteristic:=e#>>'{2,0}';
   ELSIF t->>'tag'='CAV' THEN key:=CASE characteristic WHEN 'Z13' THEN 'reason' WHEN 'Z23' THEN 'status' END;value:=e#>>'{1,0}';
   END IF;
   IF key IS NOT NULL THEN IF obj ? key THEN RETURN NULL; END IF;obj:=obj||jsonb_build_object(key,nullif(value,''));END IF;
  END IF;
 END LOOP;
 IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj);END IF;
 IF (out->>'code' IN ('Z03','Z04','Z05','Z09')) IS NOT TRUE OR nullif(out->>'sender','') IS NULL OR nullif(out->>'receiver','') IS NULL OR jsonb_array_length(objects)=0 THEN RETURN NULL;END IF;
 RETURN out||jsonb_build_object('objects',objects);
END $$;

REVOKE ALL ON FUNCTION gridex_received_sources.supply_wire_v1(text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1054
--
-- Name: switch_brp_source_basis_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.switch_brp_source_basis_v1(c uuid, message uuid, actor uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;o gridex_received_sources.switch_originals%rowtype;b jsonb;wire jsonb;at timestamptz;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=message AND company_id=c FOR SHARE;
 SELECT * INTO o FROM gridex_received_sources.switch_originals WHERE message_id=m.id AND company_id=c;
 IF m.id IS NULL OR o.message_id IS NULL THEN RAISE EXCEPTION 'switch_brp_original_required';END IF;
 wire:=gridex_received_sources.switch_origin_wire_v1(m.raw_payload);at:=gridex_received_sources.permission_time_v1(o.original_object->>'start');
 b:=gridex_brp_sources.require_source_v1(c,o.contract_id,actor,phase,m.environment,m.customer_id,m.site_id,m.metering_point_id,at,NULL);
 IF b->>'status' IS DISTINCT FROM 'authorized' OR b->>'sourceKind' IS DISTINCT FROM 'signed_contract_brp_declaration' OR wire IS NULL OR at IS NULL
  OR b->>'companyId' IS DISTINCT FROM c::text OR b->>'environment' IS DISTINCT FROM m.environment OR b->>'contractId' IS DISTINCT FROM o.contract_id::text
  OR b->>'customerId' IS DISTINCT FROM m.customer_id::text OR b->>'siteId' IS DISTINCT FROM m.site_id::text OR b->>'meteringPointId' IS DISTINCT FROM m.metering_point_id::text
  OR (b->>'at')::timestamptz IS DISTINCT FROM at OR b->>'legalSenderId' IS DISTINCT FROM wire->>'sender' OR b->>'legalReceiverId' IS DISTINCT FROM wire->>'receiver'
  OR b->>'pointId' IS DISTINCT FROM o.original_object->>'point' OR b->>'identityAgency' IS DISTINCT FROM o.original_object->>'identityAgency' OR b->>'gridArea' IS DISTINCT FROM o.original_object->>'gridArea'
  OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR m.immutable_payload_hash IS DISTINCT FROM o.payload_hash OR m.immutable_rendered_at IS NULL
  OR gridex_received_sources.outbound_single_brp_v1(m.raw_payload) IS DISTINCT FROM b->>'brpEdielId'
 THEN RAISE EXCEPTION 'switch_signed_source_brp_required';END IF;RETURN b;
END$$;

REVOKE ALL ON FUNCTION gridex_received_sources.switch_brp_source_basis_v1(uuid, uuid, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1055
--
-- Name: switch_contract_request_basis_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.switch_contract_request_basis_v1(c uuid, message uuid, actor uuid, phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;o gridex_received_sources.switch_originals%rowtype;basis jsonb;wire jsonb;method text;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=message AND company_id=c FOR SHARE;
 SELECT * INTO o FROM gridex_received_sources.switch_originals WHERE message_id=m.id AND company_id=c;
 IF m.id IS NULL OR o.message_id IS NULL THEN RAISE EXCEPTION 'switch_signed_requested_method_original_required';END IF;
 basis:=gridex_metering_method_changes.contract_request_basis_v1(c,o.contract_id,actor,phase,m.environment);
 wire:=gridex_received_sources.switch_origin_wire_v1(m.raw_payload);
 method:=gridex_received_sources.switch_requested_method_v1(m.raw_payload);
 IF basis->>'status' IS DISTINCT FROM 'authorized' OR wire IS NULL OR method IS NULL OR method IS DISTINCT FROM basis->>'requestedMethod'
  OR basis->>'companyId' IS DISTINCT FROM c::text OR basis->>'environment' IS DISTINCT FROM m.environment OR basis->>'contractId' IS DISTINCT FROM o.contract_id::text OR basis->>'protectedContractHash' IS DISTINCT FROM o.contract_hash
  OR basis->>'customerId' IS DISTINCT FROM m.customer_id::text OR basis->>'siteId' IS DISTINCT FROM m.site_id::text OR basis->>'meteringPointId' IS DISTINCT FROM m.metering_point_id::text
  OR basis->>'legalSenderId' IS DISTINCT FROM wire->>'sender' OR basis->>'legalReceiverId' IS DISTINCT FROM wire->>'receiver'
  OR basis->>'pointId' IS DISTINCT FROM o.original_object->>'point' OR basis->>'identityAgency' IS DISTINCT FROM o.original_object->>'identityAgency' OR basis->>'gridArea' IS DISTINCT FROM o.original_object->>'gridArea'
  OR o.payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') OR m.immutable_payload_hash IS DISTINCT FROM o.payload_hash OR m.immutable_rendered_at IS NULL
 THEN RAISE EXCEPTION 'switch_signed_new_agreement_requested_method_required';END IF;
 RETURN basis;
END$$;

REVOKE ALL ON FUNCTION gridex_received_sources.switch_contract_request_basis_v1(uuid, uuid, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1056
--
-- Name: switch_origin_wire_v1(text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.switch_origin_wire_v1(raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE w jsonb:=gridex_received_sources.normal_switch_wire_v1(raw);tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(raw);t jsonb;installation jsonb;customer jsonb;own jsonb;
BEGIN
 IF w IS NULL OR w->>'code' IS DISTINCT FROM 'Z03' OR jsonb_array_length(w->'objects')<>1 OR (SELECT count(*) FROM jsonb_array_elements(tokens) item WHERE item->>'tag'='LIN')<>1 THEN RETURN NULL;END IF;
 FOR t IN SELECT e FROM jsonb_array_elements(tokens)e LOOP
  IF t->>'tag'='NAD' AND t#>>'{elements,1,0}'='UD' THEN IF customer IS NOT NULL THEN RETURN NULL;END IF;customer:=jsonb_build_object('customerQualifier',t#>>'{elements,2,1}','customerAgency',t#>>'{elements,2,2}');END IF;
  IF t->>'tag'='NAD' AND t#>>'{elements,1,0}'='IT' THEN IF installation IS NOT NULL THEN RETURN NULL;END IF;installation:=jsonb_build_object('installationPoint',t#>>'{elements,2,0}','installationAgency',t#>>'{elements,2,2}');END IF;
 END LOOP;
 own:=w#>'{objects,0}';
 IF nullif(own->>'point','') IS NULL OR (own->>'identityAgency' IN('9','89')) IS NOT TRUE THEN RETURN NULL;END IF;
 IF installation IS NOT NULL AND (installation->>'installationPoint' IS DISTINCT FROM own->>'point' OR installation->>'installationAgency' IS DISTINCT FROM own->>'identityAgency') THEN RETURN NULL;END IF;
 IF customer IS NULL THEN RETURN NULL;END IF;
 own:=own||customer||jsonb_build_object('installationPoint',own->>'point','installationAgency',own->>'identityAgency');
 RETURN w||jsonb_build_object('objects',jsonb_build_array(own));
END $$;

REVOKE ALL ON FUNCTION gridex_received_sources.switch_origin_wire_v1(text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1057
--
-- Name: switch_original_message_immutable_v1(); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.switch_original_message_immutable_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN IF TG_OP='UPDATE' AND OLD.raw_payload IS NOT NULL AND NEW.raw_payload IS NULL AND public.ediel_is_qualified_retention_transition_v1(OLD,NEW) THEN RETURN NEW;END IF;
 IF EXISTS(SELECT FROM gridex_received_sources.switch_originals o WHERE o.message_id=OLD.id) AND
 ROW(NEW.id,NEW.company_id,NEW.environment,NEW.direction,NEW.message_standard,NEW.message_family,NEW.message_code,NEW.intent_id,NEW.outbound_request_id,NEW.source_operation_id,NEW.switch_request_id,NEW.customer_id,NEW.site_id,NEW.metering_point_id,NEW.raw_payload,NEW.immutable_payload_hash,NEW.immutable_rendered_at,NEW.original_message_id)
 IS DISTINCT FROM ROW(OLD.id,OLD.company_id,OLD.environment,OLD.direction,OLD.message_standard,OLD.message_family,OLD.message_code,OLD.intent_id,OLD.outbound_request_id,OLD.source_operation_id,OLD.switch_request_id,OLD.customer_id,OLD.site_id,OLD.metering_point_id,OLD.raw_payload,OLD.immutable_payload_hash,OLD.immutable_rendered_at,OLD.original_message_id)
 THEN RAISE EXCEPTION 'switch_original_bound_message_immutable';END IF;RETURN NEW;
END $$;

REVOKE ALL ON FUNCTION gridex_received_sources.switch_original_message_immutable_v1() FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1058
--
-- Name: switch_requested_method_v1(text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.switch_requested_method_v1(raw text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE token jsonb;active_object boolean:=false;common_open boolean:=true;attribute text;method text;seen_cci boolean:=false;
BEGIN
 FOR token IN SELECT item FROM jsonb_array_elements(gridex_received_sources.closure_wire_tokens_v2(raw)) item LOOP
  IF token->>'tag'='LIN' THEN IF active_object THEN RETURN NULL;END IF;active_object:=true;attribute:=NULL;CONTINUE;END IF;
  IF NOT active_object OR NOT common_open THEN CONTINUE;END IF;
  IF token->>'tag'='DTM' AND NOT seen_cci THEN CONTINUE;END IF;
  IF token->>'tag' IN('RFF','NAD','DTM','UNT') THEN common_open:=false;attribute:=NULL;CONTINUE;END IF;
  IF token->>'tag'='CCI' THEN seen_cci:=true;attribute:=token#>>'{elements,2,0}';CONTINUE;END IF;
  IF token->>'tag'='CAV' AND attribute='Z04' THEN
   IF method IS NOT NULL OR nullif(token#>>'{elements,1,0}','') IS NULL THEN RETURN NULL;END IF;
   method:=token#>>'{elements,1,0}';attribute:=NULL;
  END IF;
 END LOOP;
 RETURN method;
END$$;

REVOKE ALL ON FUNCTION gridex_received_sources.switch_requested_method_v1(text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1059
--
-- Name: validate_prodat_application_v1(text, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.validate_prodat_application_v1(raw text, facts jsonb, facet jsonb, response jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE object jsonb;reg jsonb;scope jsonb;reasons jsonb;seen jsonb:='[]';state text;
BEGIN
 IF jsonb_typeof(facet) IS DISTINCT FROM 'object' OR(SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(facet)k) IS DISTINCT FROM ARRAY['coverage','headerDecision','objects','owner','sourcePayloadHash','version']::text[]
  OR facet->'version' IS DISTINCT FROM '1'::jsonb OR facet->>'owner' IS DISTINCT FROM 'canonical-prodat-application-all-v1' OR facet->>'coverage' IS DISTINCT FROM 'canonical_own_application_only'
  OR facet->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(raw,'UTF8')),'hex') OR(facet->>'headerDecision' IN('accepted','rejected','held')) IS NOT TRUE
  OR facts->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR jsonb_typeof(facts->'rulePackEvidence') IS DISTINCT FROM 'object'
  OR jsonb_typeof(facet->'objects') IS DISTINCT FROM 'array' OR jsonb_array_length(facet->'objects')<>jsonb_array_length(facts#>'{registerValidation,objects}')
  OR facts#>>'{registerValidation,owner}' IS DISTINCT FROM 'validateProdatRegisterPolicy' OR facts#>>'{registerValidation,coverage}' IS DISTINCT FROM 'canonical_register_only' THEN RETURN false;END IF;
 FOR object IN SELECT e FROM jsonb_array_elements(facet->'objects')e LOOP
  IF jsonb_typeof(object) IS DISTINCT FROM 'object' OR(SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(object)k) IS DISTINCT FROM ARRAY['applicationDecision','identityAgency','messageIndex','messageReference','objectId','reasonCodes','registers']::text[] THEN RETURN false;END IF;
  scope:=object-'applicationDecision'-'reasonCodes';reasons:=object->'reasonCodes';state:=object->>'applicationDecision';
  IF(state IN('accepted','rejected','held')) IS NOT TRUE OR jsonb_typeof(reasons) IS DISTINCT FROM 'array' OR jsonb_array_length(reasons)>128
   OR EXISTS(SELECT FROM jsonb_array_elements(reasons)e WHERE jsonb_typeof(e)<>'string' OR e#>>'{}'!~'^[A-Za-z0-9_.:-]{1,128}$')
   OR (SELECT count(*) FROM jsonb_array_elements(reasons)e)<>(SELECT count(DISTINCT e) FROM jsonb_array_elements(reasons)e)
   OR (state='accepted' AND jsonb_array_length(reasons)<>0) OR(state<>'accepted' AND jsonb_array_length(reasons)=0) OR seen@>jsonb_build_array(scope) THEN RETURN false;END IF;
  seen:=seen||jsonb_build_array(scope);
  SELECT e INTO reg FROM jsonb_array_elements(facts#>'{registerValidation,objects}')e WHERE e-'disposition'-'reasons'=scope;
  IF reg IS NULL OR state='accepted' AND(reg->>'disposition' IS DISTINCT FROM 'accepted' OR facet->>'headerDecision' IS DISTINCT FROM 'accepted' OR facts->>'functionalDecision' IS DISTINCT FROM 'accepted')
   OR reg->>'disposition'='rejected' AND state='accepted' OR state='accepted' AND EXISTS(SELECT FROM jsonb_array_elements(coalesce(response->'responses','[]'))e WHERE e->>'ercCode'<>'100'
     AND(e->>'scope'='message' OR e->'lineIndex'=object#>'{registers,0,segmentIndex}')) THEN RETURN false;END IF;
 END LOOP;
 -- The existing actual register binder covers all physical LIN; application
 -- grouping must be exactly that partition, never a caller-selected subset.
 IF EXISTS(SELECT FROM jsonb_array_elements(facts#>'{registerValidation,objects}')e WHERE NOT seen@>jsonb_build_array(e-'disposition'-'reasons')) THEN RETURN false;END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $_$;

REVOKE ALL ON FUNCTION gridex_received_sources.validate_prodat_application_v1(text, jsonb, jsonb, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1060
--
-- Name: validate_prodat_application_v2(uuid, uuid, text, jsonb, jsonb, jsonb, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.validate_prodat_application_v2(c uuid, source_id uuid, raw text, facts jsonb, facet jsonb, response jsonb, source_function jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
BEGIN
 IF source_function IS NULL THEN RETURN gridex_received_sources.validate_prodat_application_v1(raw,facts,facet,response);END IF;
 IF gridex_received_sources.validate_prodat_source_function_v1(c,source_id,raw,facts,source_function) IS NOT TRUE THEN RETURN false;END IF;
 -- V1's physical/full-application checks are retained. Its historical global
 -- functional prerequisite is not an application fact: V5 supplies a distinct
 -- complete genuine source/function partition. The temporary shape input is
 -- neither persisted nor returned, and grants no application-based effect.
 RETURN gridex_received_sources.validate_prodat_application_v1(raw,facts||jsonb_build_object('functionalDecision','accepted'),facet,response);
END $$;

REVOKE ALL ON FUNCTION gridex_received_sources.validate_prodat_application_v2(uuid, uuid, text, jsonb, jsonb, jsonb, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1061
--
-- Name: validate_prodat_responses_v1(text, jsonb, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.validate_prodat_responses_v1(raw text, facts jsonb, facet jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE tokens jsonb:=gridex_utilts_binding.wire_tokens_v1(raw);object jsonb;response jsonb;register_object jsonb;first_line jsonb;line jsonb;indices jsonb;seen integer[]:='{}';idx integer;own_li text;first_end integer;n integer;
BEGIN
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='UNH' AND t#>>'{elements,2,0}'='PRODAT')<>1
  OR jsonb_typeof(facet) IS DISTINCT FROM 'object' OR(SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(facet)k) IS DISTINCT FROM ARRAY['objects','responses','sourcePayloadHash','version']::text[]
  OR facet->'version' IS DISTINCT FROM '1'::jsonb OR facet->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(raw,'UTF8')),'hex')
  OR facts->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR jsonb_typeof(facts->'rulePackEvidence') IS DISTINCT FROM 'object'
  OR facts#>>'{registerValidation,owner}' IS DISTINCT FROM 'validateProdatRegisterPolicy' OR facts#>>'{registerValidation,coverage}' IS DISTINCT FROM 'canonical_register_only'
  OR jsonb_typeof(facet->'objects') IS DISTINCT FROM 'array' OR jsonb_typeof(facet->'responses') IS DISTINCT FROM 'array'
  OR jsonb_array_length(facet->'objects')>8192 OR jsonb_array_length(facet->'responses')>8192 THEN RETURN false;END IF;
 FOR object IN SELECT x FROM jsonb_array_elements(facet->'objects')x LOOP
  IF jsonb_typeof(object) IS DISTINCT FROM 'object' OR(SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(object)k) IS DISTINCT FROM ARRAY['id','li','lineIndex','outcome','registerLineIndices']::text[]
   OR (object->>'outcome' IN('positive','negative','held')) IS NOT TRUE OR jsonb_typeof(object->'lineIndex') IS DISTINCT FROM 'number'
   OR jsonb_typeof(object->'registerLineIndices') IS DISTINCT FROM 'array' OR jsonb_array_length(object->'registerLineIndices')=0 OR object->'lineIndex' IS DISTINCT FROM object#>'{registerLineIndices,0}' THEN RETURN false;END IF;
  idx:=(object->>'lineIndex')::integer;SELECT t INTO first_line FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN' AND(t->>'index')::integer=idx;
  IF first_line IS NULL OR to_jsonb(nullif(first_line#>>'{elements,3,0}','')) IS DISTINCT FROM nullif(object->'id','null'::jsonb) THEN RETURN false;END IF;
  SELECT min((t->>'index')::integer) INTO first_end FROM jsonb_array_elements(tokens)t WHERE(t->>'index')::integer>idx AND t->>'tag' IN('NAD','LIN','UNT');
  SELECT count(*),min(t#>>'{elements,1,1}') INTO n,own_li FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='LI' AND(t->>'index')::integer>idx AND(t->>'index')::integer<first_end;
  IF n>1 OR to_jsonb(nullif(own_li,'')) IS DISTINCT FROM nullif(object->'li','null'::jsonb) THEN RETURN false;END IF;
  SELECT x INTO register_object FROM jsonb_array_elements(facts#>'{registerValidation,objects}')x WHERE x#>'{registers,0,segmentIndex}'=object->'lineIndex';
  SELECT jsonb_agg(x->'segmentIndex' ORDER BY ord) INTO indices FROM jsonb_array_elements(register_object->'registers') WITH ORDINALITY v(x,ord);
  IF register_object IS NULL OR indices IS DISTINCT FROM object->'registerLineIndices' OR register_object->'objectId' IS DISTINCT FROM object->'id' THEN RETURN false;END IF;
  FOR idx IN SELECT value::text::integer FROM jsonb_array_elements(object->'registerLineIndices') LOOP
   IF idx=ANY(seen) THEN RETURN false;END IF;seen:=array_append(seen,idx);
   SELECT t INTO line FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN' AND(t->>'index')::integer=idx;
   IF line IS NULL OR line#>'{elements,3,0}' IS DISTINCT FROM first_line#>'{elements,3,0}' OR line#>'{elements,3,3}' IS DISTINCT FROM first_line#>'{elements,3,3}' THEN RETURN false;END IF;
  END LOOP;
  IF object->>'outcome'='positive' AND(facts->>'applicationDecision' IS DISTINCT FROM 'accepted' OR facts->>'functionalDecision' IS DISTINCT FROM 'accepted' OR register_object->>'disposition' IS DISTINCT FROM 'accepted') THEN RETURN false;END IF;
 END LOOP;
 IF EXISTS(SELECT FROM jsonb_array_elements(tokens)t WHERE t->>'tag'='LIN' AND NOT((t->>'index')::integer=ANY(seen))) THEN RETURN false;END IF;
 FOR response IN SELECT x FROM jsonb_array_elements(facet->'responses')x LOOP
  IF jsonb_typeof(response) IS DISTINCT FROM 'object' OR(SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(response)k) IS DISTINCT FROM ARRAY['ercCode','fieldCode','id','li','lineIndex','scope','text']::text[]
   OR (response->>'scope' IN('message','object')) IS NOT TRUE OR jsonb_typeof(response->'ercCode') IS DISTINCT FROM 'string' OR response->>'ercCode'!~'^[0-9]{1,3}$'
   OR jsonb_typeof(response->'text') IS DISTINCT FROM 'string' OR length(response->>'text') NOT BETWEEN 1 AND 512 OR response->>'text'~'[[:cntrl:]]'
   OR (jsonb_typeof(response->'fieldCode') IN('string','null')) IS NOT TRUE THEN RETURN false;END IF;
  IF response->>'scope'='message' THEN IF response->'lineIndex' IS DISTINCT FROM 'null'::jsonb OR response->>'ercCode'='100' THEN RETURN false;END IF;
  ELSE SELECT x INTO object FROM jsonb_array_elements(facet->'objects')x WHERE x->'lineIndex'=response->'lineIndex';
   IF object IS NULL OR object->>'outcome' IS DISTINCT FROM (CASE WHEN response->>'ercCode'='100' THEN 'positive' ELSE 'negative' END) OR object->'id' IS DISTINCT FROM response->'id' OR object->'li' IS DISTINCT FROM response->'li' THEN RETURN false;END IF;
  END IF;
  IF response->>'ercCode'<>'100' AND(facts->>'applicationDecision' IN('rejected','manual_review')) IS NOT TRUE THEN RETURN false;END IF;
 END LOOP;
 IF EXISTS(SELECT FROM jsonb_array_elements(facet->'objects')o WHERE o->>'outcome'<>'held' AND NOT EXISTS(SELECT FROM jsonb_array_elements(facet->'responses')r WHERE r->>'scope'='object' AND r->'lineIndex'=o->'lineIndex'))
  OR(EXISTS(SELECT FROM jsonb_array_elements(facet->'responses')r WHERE r->>'scope'='message') AND EXISTS(SELECT FROM jsonb_array_elements(facet->'responses')r WHERE r->>'scope'='object')) THEN RETURN false;END IF;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $_$;

REVOKE ALL ON FUNCTION gridex_received_sources.validate_prodat_responses_v1(text, jsonb, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1062
--
-- Name: validate_prodat_source_function_v1(uuid, uuid, text, jsonb, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.validate_prodat_source_function_v1(c uuid, source_id uuid, raw text, facts jsonb, facet jsonb) RETURNS boolean
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE r gridex_customer_life_events.inbound_context_receipts%rowtype;object jsonb;scope jsonb;reg jsonb;seen jsonb:='[]';state text;reasons jsonb;m public.ediel_messages%rowtype;context_xmin numeric;
BEGIN
 IF jsonb_typeof(facet) IS DISTINCT FROM 'object' OR(SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(facet)k) IS DISTINCT FROM ARRAY['coverage','objects','owner','sourceContextFactsHash','sourceContextReceiptId','sourcePayloadHash','version']::text[]
  OR facet->'version' IS DISTINCT FROM '1'::jsonb OR facet->>'owner' IS DISTINCT FROM 'canonical-prodat-source-function-v1' OR facet->>'coverage' IS DISTINCT FROM 'customer_life_event_only'
  OR facet->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(raw,'UTF8')),'hex') OR facet->>'sourceContextFactsHash'!~'^[a-f0-9]{64}$'
  OR facts->>'syntaxDecision' IS DISTINCT FROM 'accepted' OR jsonb_typeof(facts->'rulePackEvidence') IS DISTINCT FROM 'object'
  OR jsonb_typeof(facet->'objects') IS DISTINCT FROM 'array' OR jsonb_array_length(facet->'objects')<>jsonb_array_length(facts#>'{registerValidation,objects}')
  OR facts#>>'{registerValidation,owner}' IS DISTINCT FROM 'validateProdatRegisterPolicy' OR facts#>>'{registerValidation,coverage}' IS DISTINCT FROM 'canonical_register_only' THEN RETURN false;END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=source_id AND company_id=c FOR SHARE;
 SELECT stored.xmin::text::numeric INTO context_xmin FROM gridex_customer_life_events.inbound_context_receipts stored WHERE stored.id=(facet->>'sourceContextReceiptId')::uuid AND stored.company_id=c AND stored.source_message_id=source_id;
 SELECT * INTO r FROM gridex_customer_life_events.inbound_context_receipts WHERE id=(facet->>'sourceContextReceiptId')::uuid AND company_id=c AND source_message_id=source_id FOR SHARE;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'inbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z06' OR m.raw_payload IS DISTINCT FROM raw
  OR r.id IS NULL OR r.environment IS DISTINCT FROM m.environment OR r.payload_hash IS DISTINCT FROM facet->>'sourcePayloadHash' OR r.context_facts_hash IS DISTINCT FROM facet->>'sourceContextFactsHash'
  OR r.context_facts_hash IS DISTINCT FROM encode(sha256(convert_to(r.context_facts::text,'UTF8')),'hex') OR r.context_facts->>'rawPayload' IS DISTINCT FROM raw
  OR r.context_facts->>'status' IS DISTINCT FROM 'authorized' OR context_xmin=mod(pg_current_xact_id()::text::numeric,4294967296) THEN RETURN false;END IF;
 FOR object IN SELECT e FROM jsonb_array_elements(facet->'objects')e LOOP
  IF jsonb_typeof(object) IS DISTINCT FROM 'object' OR(SELECT array_agg(k ORDER BY k) FROM jsonb_object_keys(object)k) IS DISTINCT FROM ARRAY['functionalDecision','identityAgency','messageIndex','messageReference','objectId','reasonCodes','registers']::text[] THEN RETURN false;END IF;
  scope:=object-'functionalDecision'-'reasonCodes';state:=object->>'functionalDecision';reasons:=object->'reasonCodes';
  IF(state IN('accepted','held','not_applicable')) IS NOT TRUE OR jsonb_typeof(reasons) IS DISTINCT FROM 'array' OR jsonb_array_length(reasons)>128
   OR EXISTS(SELECT FROM jsonb_array_elements(reasons)e WHERE jsonb_typeof(e)<>'string' OR e#>>'{}'!~'^[A-Za-z0-9_.:-]{1,128}$')
   OR(SELECT count(*) FROM jsonb_array_elements(reasons)e)<>(SELECT count(DISTINCT e) FROM jsonb_array_elements(reasons)e)
   OR state='accepted' AND jsonb_array_length(reasons)<>0 OR state<>'accepted' AND jsonb_array_length(reasons)=0 OR seen@>jsonb_build_array(scope) THEN RETURN false;END IF;
  seen:=seen||jsonb_build_array(scope);
  SELECT e INTO reg FROM jsonb_array_elements(facts#>'{registerValidation,objects}')e WHERE e-'disposition'-'reasons'=scope;
  IF reg IS NULL OR state='accepted' AND gridex_customer_life_events.inbound_context_object_is_qualified_v1(c,source_id,r.id,scope) IS NOT TRUE THEN RETURN false;END IF;
 END LOOP;
 IF EXISTS(SELECT FROM jsonb_array_elements(facts#>'{registerValidation,objects}')e WHERE NOT seen@>jsonb_build_array(e-'disposition'-'reasons')) THEN RETURN false;END IF;
 RETURN true;
EXCEPTION WHEN invalid_text_representation OR numeric_value_out_of_range OR invalid_parameter_value OR data_exception THEN RETURN false;
END $_$;

REVOKE ALL ON FUNCTION gridex_received_sources.validate_prodat_source_function_v1(uuid, uuid, text, jsonb, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1063
--
-- Name: validate_utilts_functional_v1(text, jsonb, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.validate_utilts_functional_v1(raw text, projection jsonb, transactions jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE selected jsonb;item jsonb;error_item jsonb;eligible jsonb;i integer;
BEGIN
 IF NOT coalesce(gridex_received_sources.validate_utilts_transactions_v1(raw,transactions),false)
  OR jsonb_typeof(projection) IS DISTINCT FROM 'object' OR projection-ARRAY['version','sourcePayloadHash','transactions']<>'{}'::jsonb
  OR projection->'version' IS DISTINCT FROM '1'::jsonb OR projection->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(raw,'UTF8')),'hex')
  OR jsonb_typeof(projection->'transactions') IS DISTINCT FROM 'array' OR jsonb_array_length(projection->'transactions') NOT BETWEEN 1 AND 999 THEN RETURN false; END IF;
 SELECT coalesce(jsonb_agg(value ORDER BY ord),'[]'::jsonb) INTO eligible FROM jsonb_array_elements(transactions->'transactions') WITH ORDINALITY t(value,ord)
  WHERE value->>'disposition'='processability_rejected' AND value->>'responseType'='utilts_err';
 IF jsonb_array_length(eligible)<>jsonb_array_length(projection->'transactions') THEN RETURN false; END IF;
 FOR i IN 0..jsonb_array_length(eligible)-1 LOOP
  selected:=eligible->i;item:=projection->'transactions'->i;
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item-ARRAY['transactionIndex','transactionId','errors']<>'{}'::jsonb
   OR item->'transactionIndex' IS DISTINCT FROM selected->'transactionIndex' OR item->'transactionId' IS DISTINCT FROM selected->'transactionId'
   OR jsonb_typeof(item->'transactionId') IS DISTINCT FROM 'string' OR length(item->>'transactionId') NOT BETWEEN 1 AND 35
   OR jsonb_typeof(item->'errors') IS DISTINCT FROM 'array' OR jsonb_array_length(item->'errors') NOT BETWEEN 1 AND 128 THEN RETURN false; END IF;
  FOR error_item IN SELECT value FROM jsonb_array_elements(item->'errors') LOOP
   -- Shape and actual national projection binding only. The shared ERR guide
   -- owns allowed codes/semantics; no internal diagnostic or local code map.
   IF jsonb_typeof(error_item) IS DISTINCT FROM 'object' OR error_item-ARRAY['code','referenceQualifier','referenceNumber']<>'{}'::jsonb
    OR jsonb_typeof(error_item->'code') IS DISTINCT FROM 'string' OR error_item->>'code' !~ '^E[A-Z0-9]{1,7}$'
    OR jsonb_typeof(error_item->'referenceQualifier') IS DISTINCT FROM 'string' OR error_item->>'referenceQualifier' !~ '^[A-Z0-9]{1,3}$'
    OR error_item->'referenceNumber' IS DISTINCT FROM item->'transactionId' THEN RETURN false; END IF;
  END LOOP;
  IF (SELECT count(*) FROM jsonb_array_elements(item->'errors'))<>(SELECT count(DISTINCT value->>'code') FROM jsonb_array_elements(item->'errors')) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END $_$;

REVOKE ALL ON FUNCTION gridex_received_sources.validate_utilts_functional_v1(text, jsonb, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1064
--
-- Name: validate_utilts_functional_v2(text, jsonb, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.validate_utilts_functional_v2(raw text, projection jsonb, transactions jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE selected jsonb;item jsonb;error_item jsonb;owner_item jsonb;eligible jsonb;i integer;
BEGIN
 IF NOT coalesce(gridex_received_sources.validate_utilts_transactions_v1(raw,transactions),false)
  OR jsonb_typeof(projection) IS DISTINCT FROM 'object' OR projection-ARRAY['version','sourcePayloadHash','transactions']<>'{}'::jsonb
  OR projection->'version' IS DISTINCT FROM '2'::jsonb OR projection->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(raw,'UTF8')),'hex')
  OR jsonb_typeof(projection->'transactions') IS DISTINCT FROM 'array' OR jsonb_array_length(projection->'transactions') NOT BETWEEN 1 AND 999 THEN RETURN false; END IF;
 SELECT coalesce(jsonb_agg(value ORDER BY ord),'[]'::jsonb) INTO eligible FROM jsonb_array_elements(transactions->'transactions') WITH ORDINALITY t(value,ord)
  WHERE value->>'disposition'='processability_rejected' AND value->>'responseType'='utilts_err';
 IF jsonb_array_length(eligible)<>jsonb_array_length(projection->'transactions') THEN RETURN false; END IF;
 FOR i IN 0..jsonb_array_length(eligible)-1 LOOP
  selected:=eligible->i;item:=projection->'transactions'->i;
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item-ARRAY['transactionIndex','transactionId','errors']<>'{}'::jsonb
   OR item->'transactionIndex' IS DISTINCT FROM selected->'transactionIndex' OR item->'transactionId' IS DISTINCT FROM selected->'transactionId'
   OR jsonb_typeof(item->'transactionId') IS DISTINCT FROM 'string' OR length(item->>'transactionId') NOT BETWEEN 1 AND 35
   OR jsonb_typeof(item->'errors') IS DISTINCT FROM 'array' OR jsonb_array_length(item->'errors') NOT BETWEEN 1 AND 128 THEN RETURN false; END IF;
  FOR error_item IN SELECT value FROM jsonb_array_elements(item->'errors') LOOP
   IF jsonb_typeof(error_item) IS DISTINCT FROM 'object' OR error_item-ARRAY['code','ownerIssueCodes','originalScope','referenceQualifier','referenceNumber','responseReference']<>'{}'::jsonb
    OR jsonb_typeof(error_item->'code') IS DISTINCT FROM 'string' OR error_item->>'code' !~ '^E[A-Z0-9]{1,7}$'
    OR jsonb_typeof(error_item->'ownerIssueCodes') IS DISTINCT FROM 'array' OR jsonb_array_length(error_item->'ownerIssueCodes') NOT BETWEEN 1 AND 128
    OR coalesce(error_item->>'originalScope','') NOT IN ('message','transaction')
    OR (error_item->'referenceQualifier' IS DISTINCT FROM 'null'::jsonb AND (jsonb_typeof(error_item->'referenceQualifier') IS DISTINCT FROM 'string' OR error_item->>'referenceQualifier' !~ '^[A-Z0-9]{1,3}$'))
    OR jsonb_typeof(error_item->'responseReference') IS DISTINCT FROM 'object' OR (error_item->'responseReference')-ARRAY['qualifier','number']<>'{}'::jsonb
    OR error_item#>>'{responseReference,qualifier}' IS DISTINCT FROM 'TN' OR error_item#>'{responseReference,number}' IS DISTINCT FROM item->'transactionId'
    OR (error_item->>'originalScope'='message' AND error_item->'referenceNumber' IS DISTINCT FROM 'null'::jsonb)
    OR (error_item->>'originalScope'='transaction' AND (error_item->>'referenceQualifier' IS DISTINCT FROM 'TN' OR error_item->'referenceNumber' IS DISTINCT FROM item->'transactionId')) THEN RETURN false; END IF;
   FOR owner_item IN SELECT value FROM jsonb_array_elements(error_item->'ownerIssueCodes') LOOP
    IF jsonb_typeof(owner_item) IS DISTINCT FROM 'string' OR NOT coalesce(selected->'issueCodes' @> jsonb_build_array(owner_item),false) THEN RETURN false; END IF;
   END LOOP;
   IF (SELECT count(*) FROM jsonb_array_elements(error_item->'ownerIssueCodes'))<>(SELECT count(DISTINCT value) FROM jsonb_array_elements(error_item->'ownerIssueCodes')) THEN RETURN false; END IF;
  END LOOP;
  IF (SELECT count(*) FROM jsonb_array_elements(item->'errors'))<>(SELECT count(DISTINCT value-ARRAY['ownerIssueCodes','responseReference']) FROM jsonb_array_elements(item->'errors')) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END $_$;

REVOKE ALL ON FUNCTION gridex_received_sources.validate_utilts_functional_v2(text, jsonb, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1065
--
-- Name: validate_utilts_header_v1(text, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.validate_utilts_header_v1(raw text, projection jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE tokens jsonb;item jsonb;
BEGIN
 IF jsonb_typeof(projection) IS DISTINCT FROM 'object' OR projection-ARRAY['version','sourcePayloadHash','applicationErrors']<>'{}'::jsonb
  OR projection->'version' IS DISTINCT FROM '1'::jsonb OR projection->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(raw,'UTF8')),'hex')
  OR jsonb_typeof(projection->'applicationErrors') IS DISTINCT FROM 'array' OR jsonb_array_length(projection->'applicationErrors') NOT BETWEEN 1 AND 128 THEN RETURN false; END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(raw);IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNH')<>1
  OR NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='UNH' AND t#>>'{elements,2,0}'='UTILTS') THEN RETURN false; END IF;
 FOR item IN SELECT value FROM jsonb_array_elements(projection->'applicationErrors') LOOP
  -- Only shape/original binding here. The shared national guide's native
  -- checker owns ERC/text semantics; no second field or text/error table.
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item-ARRAY['ercCode','fieldCode','text']<>'{}'::jsonb OR item->>'ercCode' NOT IN ('41','42')
   OR jsonb_typeof(item->'ercCode') IS DISTINCT FROM 'string' OR jsonb_typeof(item->'fieldCode') IS DISTINCT FROM 'string' OR item->>'fieldCode' !~ '^[A-Za-z0-9_./-]{1,17}$'
   OR jsonb_typeof(item->'text') IS DISTINCT FROM 'string' OR length(item->>'text') NOT BETWEEN 1 AND 512 OR item->>'text' ~ '[[:cntrl:]]' THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END $_$;

REVOKE ALL ON FUNCTION gridex_received_sources.validate_utilts_header_v1(text, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1066
--
-- Name: validate_utilts_transactions_v1(text, jsonb); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.validate_utilts_transactions_v1(raw text, projection jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE tokens jsonb;membership jsonb;item jsonb;physical jsonb;ordinal integer;expected_response text;
BEGIN
 IF jsonb_typeof(projection) IS DISTINCT FROM 'object' OR projection-ARRAY['version','sourcePayloadHash','transactions']<>'{}'::jsonb
  OR projection->'version' IS DISTINCT FROM '1'::jsonb OR projection->>'sourcePayloadHash' IS DISTINCT FROM encode(sha256(convert_to(raw,'UTF8')),'hex')
  OR jsonb_typeof(projection->'transactions') IS DISTINCT FROM 'array' OR jsonb_array_length(projection->'transactions')>999 THEN RETURN false; END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(raw);IF tokens IS NULL THEN RETURN false;END IF;
 SELECT coalesce(jsonb_agg(t ORDER BY (t->>'index')::integer),'[]') INTO membership FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='IDE';
 IF jsonb_array_length(membership)<>jsonb_array_length(projection->'transactions') THEN RETURN false; END IF;
 FOR item,ordinal IN SELECT value,(i-1)::integer FROM jsonb_array_elements(projection->'transactions') WITH ORDINALITY x(value,i) LOOP
  physical:=membership->ordinal;
  expected_response:=CASE item->>'disposition' WHEN 'accepted' THEN 'positive_aperak' WHEN 'syntax_rejected' THEN 'negative_contrl' WHEN 'guide_rejected' THEN 'negative_aperak' WHEN 'processability_rejected' THEN 'utilts_err' WHEN 'internal_review' THEN 'none' END;
  IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item-ARRAY['transactionIndex','transactionId','disposition','responseType','issueCodes']<>'{}'::jsonb
   OR item->'transactionIndex' IS DISTINCT FROM to_jsonb(ordinal) OR item->'transactionId' IS DISTINCT FROM coalesce(to_jsonb(nullif(physical#>>'{elements,2,0}','')),'null'::jsonb)
   OR expected_response IS NULL OR item->>'responseType' IS DISTINCT FROM expected_response OR jsonb_typeof(item->'issueCodes') IS DISTINCT FROM 'array' OR jsonb_array_length(item->'issueCodes')>128
   OR EXISTS(SELECT FROM jsonb_array_elements(item->'issueCodes') code WHERE jsonb_typeof(code) IS DISTINCT FROM 'string' OR code#>>'{}' !~ '^[A-Za-z0-9_.:-]{1,128}$') THEN RETURN false; END IF;
  IF item->>'disposition'='accepted' AND (physical#>>'{elements,1,0}' IS DISTINCT FROM '24' OR nullif(item->>'transactionId','') IS NULL OR length(item->>'transactionId')>35 OR jsonb_array_length(item->'issueCodes')<>0) THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN invalid_text_representation THEN RETURN false;
END $_$;

REVOKE ALL ON FUNCTION gridex_received_sources.validate_utilts_transactions_v1(text, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1071
--
-- Name: z02_address_source_basis_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.z02_address_source_basis_v1(p_source_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
 m public.ediel_messages%rowtype;s gridex_received_sources.sources%rowtype;
 original public.ediel_messages%rowtype;candidate public.ediel_messages%rowtype;
 request public.customer_info_requests%rowtype;candidate_request public.customer_info_requests%rowtype;
 site public.customer_sites%rowtype;customer public.customers%rowtype;
 snapshot public.customer_operation_request_snapshots%rowtype;
 dispatch gridex_ediel_transport.attempts%rowtype;
 source_wire jsonb;original_wire jsonb;source_object jsonb;original_object jsonb;
 candidate_wire jsonb;candidate_object jsonb;receipt jsonb;
 source_transport jsonb;candidate_transport jsonb;
 matches integer:=0;object_matches integer;request_id uuid;original_id uuid;
 expected_object text;expected_identity text;expected_qualifier text;address_hash text;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN
  RAISE EXCEPTION 'z02_address_source_service_required' USING ERRCODE='42501';
 END IF;
 SELECT * INTO s FROM gridex_received_sources.sources WHERE source_message_id=p_source_message_id;
 IF NOT FOUND THEN RETURN NULL;END IF;
 -- Service execution is not authority to disclose another company's source.
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active' FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'z02_address_source_actor_required' USING ERRCODE='42501';END IF;
 PERFORM cm.user_id FROM public.company_memberships cm
  WHERE cm.company_id=s.company_id AND cm.user_id=p_actor_user_id
   AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL FOR SHARE;
 IF NOT FOUND OR NOT (
  coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,s.company_id,'ediel.read'),false)
  OR coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,s.company_id,'communication.read'),false)) THEN
  RAISE EXCEPTION 'z02_address_source_actor_read_required' USING ERRCODE='42501';
 END IF;
 PERFORM public.ediel_require_source_bytes_available_v1(s.company_id,s.source_message_id);
 SELECT * INTO m FROM public.ediel_messages WHERE id=s.source_message_id
  AND company_id=s.company_id AND environment=s.environment FOR SHARE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'inbound' OR m.message_standard IS DISTINCT FROM 'edifact'
  OR m.message_family IS DISTINCT FROM 'PRODAT' OR m.message_code IS DISTINCT FROM 'Z02'
  OR s.message_code IS DISTINCT FROM 'Z02' OR s.raw_payload IS NULL
  OR s.raw_payload IS DISTINCT FROM m.raw_payload
  OR s.payload_hash IS DISTINCT FROM m.immutable_payload_hash
  OR s.payload_hash IS DISTINCT FROM encode(sha256(convert_to(s.raw_payload,'UTF8')),'hex')
  OR s.source_received_at IS NULL OR NOT isfinite(s.source_received_at)
  OR s.source_received_at IS DISTINCT FROM m.message_received_at
  OR m.customer_id IS NULL OR m.site_id IS NULL THEN RETURN NULL;END IF;

 SELECT * INTO site FROM public.customer_sites WHERE id=m.site_id
  AND company_id=s.company_id AND customer_id=m.customer_id FOR SHARE;
 IF NOT FOUND THEN RETURN NULL;END IF;
 SELECT * INTO customer FROM public.customers WHERE id=m.customer_id AND company_id=s.company_id FOR SHARE;
 IF NOT FOUND THEN RETURN NULL;END IF;
 expected_object:=coalesce(nullif(btrim(site.normalized_facility_id),''),nullif(btrim(site.facility_id),''));
 expected_identity:=coalesce(nullif(btrim(customer.org_number),''),nullif(btrim(customer.personal_number),''));
 expected_qualifier:=CASE WHEN nullif(btrim(customer.org_number),'') IS NOT NULL THEN 'SE1'
  WHEN nullif(btrim(customer.personal_number),'') IS NOT NULL THEN 'SE2' ELSE NULL END;
 IF expected_object IS NULL OR expected_identity IS NULL THEN RETURN NULL;END IF;
 source_wire:=gridex_received_sources.z02_core_wire_v1(s.raw_payload);
 IF source_wire IS NULL OR source_wire->>'code' IS DISTINCT FROM 'Z02' THEN RETURN NULL;END IF;
 SELECT x->'elements' INTO source_transport FROM jsonb_array_elements(
  gridex_received_sources.closure_wire_tokens_v2(s.raw_payload)) x WHERE x->>'tag'='UNB';
 SELECT count(*) INTO object_matches FROM jsonb_array_elements(source_wire->'objects') x
  WHERE x->>'objectId'=expected_object;
 IF object_matches<>1 THEN RETURN NULL;END IF;
 SELECT x INTO source_object FROM jsonb_array_elements(source_wire->'objects') x WHERE x->>'objectId'=expected_object;
 IF nullif(source_object->>'identityAgency','') IS NULL OR nullif(source_object->>'lineReference','') IS NULL
  OR (source_object->>'reason' IN ('Z22','Z23')) IS NOT TRUE THEN RETURN NULL;END IF;

 -- Select by the physical source correlation, not latest request or mutable
 -- sent_at/parsed_payload. Multiple matching requests are unavailable authority.
 FOR candidate_request IN SELECT r.* FROM public.customer_info_requests r
  WHERE r.company_id=s.company_id AND r.customer_id=m.customer_id AND r.site_id=m.site_id
   AND r.operation_id IS NOT NULL AND r.ediel_message_id IS NOT NULL FOR SHARE
 LOOP
  SELECT * INTO candidate FROM public.ediel_messages o WHERE o.id=candidate_request.ediel_message_id
   AND o.company_id=s.company_id AND o.environment=s.environment AND o.direction='outbound'
   AND o.message_standard='edifact' AND o.message_family='PRODAT' AND o.message_code='Z01'
   AND o.customer_id=m.customer_id AND o.site_id=m.site_id FOR SHARE;
  IF NOT FOUND OR candidate.raw_payload IS NULL OR candidate.immutable_rendered_at IS NULL
   OR NOT isfinite(candidate.immutable_rendered_at)
   OR candidate.immutable_payload_hash IS DISTINCT FROM encode(sha256(convert_to(candidate.raw_payload,'UTF8')),'hex')
   THEN CONTINUE;END IF;
  candidate_wire:=gridex_received_sources.z02_core_wire_v1(candidate.raw_payload);
  SELECT x->'elements' INTO candidate_transport FROM jsonb_array_elements(
   gridex_received_sources.closure_wire_tokens_v2(candidate.raw_payload)) x WHERE x->>'tag'='UNB';
  IF candidate_wire IS NULL OR candidate_wire->>'code' IS DISTINCT FROM 'Z01'
   OR source_wire->>'sender' IS DISTINCT FROM candidate_wire->>'receiver'
   OR source_wire->>'receiver' IS DISTINCT FROM candidate_wire->>'sender'
   OR nullif(source_wire->>'transportSender','') IS NULL OR nullif(source_wire->>'transportReceiver','') IS NULL
   OR source_wire->>'transportSender' IS DISTINCT FROM candidate_wire->>'transportReceiver'
   OR source_wire->>'transportReceiver' IS DISTINCT FROM candidate_wire->>'transportSender'
   OR source_transport->2 IS DISTINCT FROM candidate_transport->3
   OR source_transport->3 IS DISTINCT FROM candidate_transport->2 THEN CONTINUE;END IF;
  SELECT count(*) INTO object_matches FROM jsonb_array_elements(candidate_wire->'objects') x
   WHERE x->>'objectId'=expected_object;
  IF object_matches<>1 THEN CONTINUE;END IF;
  SELECT x INTO candidate_object FROM jsonb_array_elements(candidate_wire->'objects') x WHERE x->>'objectId'=expected_object;
  IF candidate_object->>'identityAgency' IS DISTINCT FROM source_object->>'identityAgency'
   OR candidate_object->>'lineReference' IS DISTINCT FROM source_object->>'lineReference'
   OR candidate_object->>'reason' IS DISTINCT FROM source_object->>'reason'
   OR candidate_object->>'customerId' IS DISTINCT FROM expected_identity
   OR candidate_object->>'customerQualifier' IS DISTINCT FROM expected_qualifier
   OR candidate_object->>'customerAgency' IS DISTINCT FROM '260'
   OR nullif(candidate_object->>'customerName','') IS NULL
   OR NOT EXISTS(SELECT FROM public.ediel_business_references br WHERE br.company_id=s.company_id
    AND br.source_message_id=candidate.id AND br.message_family='PRODAT' AND br.message_code='Z01'
    AND br.reference_type='RFF_LI' AND br.reference_value=source_object->>'lineReference') THEN CONTINUE;END IF;
  matches:=matches+1;request_id:=candidate_request.id;original_id:=candidate.id;
  original_wire:=candidate_wire;original_object:=candidate_object;
 END LOOP;
 IF matches<>1 THEN RETURN NULL;END IF;
 SELECT * INTO request FROM public.customer_info_requests WHERE id=request_id;
 SELECT * INTO original FROM public.ediel_messages WHERE id=original_id;
 PERFORM public.ediel_require_source_bytes_available_v1(s.company_id,original.id);
 IF request.grid_owner_id IS NOT NULL AND (
  request.grid_owner_id IS DISTINCT FROM site.grid_owner_id
  OR m.grid_owner_id IS NOT NULL AND m.grid_owner_id IS DISTINCT FROM request.grid_owner_id
  OR original.grid_owner_id IS NOT NULL AND original.grid_owner_id IS DISTINCT FROM request.grid_owner_id)
  THEN RETURN NULL;END IF;
 SELECT count(*) INTO matches FROM public.customer_operation_request_snapshots x
  WHERE x.company_id=s.company_id AND x.operation_id=request.operation_id AND x.customer_id=m.customer_id
   AND x.customer_site_id=m.site_id AND x.request_kind='customer_data_request'
   AND x.request_reference=request.id::text AND x.superseded_at IS NULL;
 IF matches<>1 THEN RETURN NULL;END IF;
 SELECT * INTO snapshot FROM public.customer_operation_request_snapshots x
  WHERE x.company_id=s.company_id AND x.operation_id=request.operation_id AND x.customer_id=m.customer_id
   AND x.customer_site_id=m.site_id AND x.request_kind='customer_data_request'
   AND x.request_reference=request.id::text AND x.superseded_at IS NULL FOR SHARE;
 address_hash:=coalesce(nullif(btrim(site.address_hash),''),lower(concat_ws('|',nullif(btrim(site.street),''),
  nullif(regexp_replace(coalesce(site.postal_code,''),'[^0-9]','','g'),''),nullif(btrim(site.city),''))));
 IF snapshot.site_address_hash IS DISTINCT FROM address_hash OR snapshot.grid_owner_id IS DISTINCT FROM site.grid_owner_id
  OR nullif(original_object->>'installationAddress','') IS NOT NULL
   AND btrim(original_object->>'installationAddress') IS DISTINCT FROM btrim(site.street) THEN RETURN NULL;END IF;

 -- Reuse the genuine private provider receipt reader after READ authorization.
 -- Its historical sender is not requalified against present-day SEND rights.
 receipt:=gridex_ediel_transport.accepted_source_basis_v1(original);
 IF receipt IS NULL OR receipt->>'status' IS DISTINCT FROM 'accepted_projection'
  OR receipt->>'lane' IS DISTINCT FROM 'generic_journal' THEN RETURN NULL;END IF;
 SELECT * INTO dispatch FROM gridex_ediel_transport.attempts a WHERE a.id=(receipt->>'attemptId')::uuid
  AND a.company_id=s.company_id AND a.environment=s.environment AND a.message_id=original.id
  AND a.classification='accepted' AND a.binding->>'originalHash'=original.immutable_payload_hash
  AND a.entered_at IS NOT NULL AND a.observed_at IS NOT NULL
  AND isfinite(a.entered_at) AND isfinite(a.observed_at)
  AND original.immutable_rendered_at<=a.entered_at AND a.entered_at<=a.observed_at
  AND a.observed_at<=s.source_received_at
  AND a.observed_at=(receipt->>'observedAt')::timestamptz FOR SHARE;
 IF NOT FOUND THEN RETURN NULL;END IF;

 -- Incoming UD fields are intentionally absent from the authority predicate.
 -- The caller parses original C059 bytes and validates reply fields separately.
 RETURN jsonb_build_object('status','z02_address_source_basis','version',1,
  'companyId',s.company_id,'environment',s.environment,'sourceMessageId',m.id,
  'sourcePayloadHash',s.payload_hash,'sourceReceivedAt',s.source_received_at,'sourceRawPayload',s.raw_payload,
  'sourceMessage',to_jsonb(m),'sourceContext',s.received_context,
  'originalMessageId',original.id,'originalPayloadHash',original.immutable_payload_hash,
  'originalRenderedAt',original.immutable_rendered_at,'originalRawPayload',original.raw_payload,
  'originalMessage',to_jsonb(original),'sourceObject',source_object,'originalObject',original_object,
  'request',to_jsonb(request),'requestSnapshot',to_jsonb(snapshot),'customer',to_jsonb(customer),'site',to_jsonb(site),
  'acceptedTransport',to_jsonb(dispatch),'acceptedTransportReceipt',receipt);
END $$;

REVOKE ALL ON FUNCTION gridex_received_sources.z02_address_source_basis_v1(uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1072
--
-- Name: z02_core_wire_v1(text); Type: FUNCTION; Schema: gridex_received_sources; Owner: -
--

CREATE FUNCTION gridex_received_sources.z02_core_wire_v1(p_raw text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE tokens jsonb:=gridex_received_sources.closure_wire_tokens_v2(p_raw);t jsonb;e jsonb;
 result jsonb:='{}';objects jsonb:='[]';obj jsonb;key text;value text;characteristic text;line_index integer:=-1;
BEGIN
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='UNH')<>1
 OR (SELECT count(*) FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='BGM')<>1 THEN RETURN NULL; END IF;
 FOR t IN SELECT x FROM jsonb_array_elements(tokens) x ORDER BY (x->>'index')::integer LOOP
  e:=t->'elements';key:=NULL;value:=NULL;
  IF t->>'tag'='UNB' THEN
   IF result ? 'transportSender' OR jsonb_array_length(e->2)<>2 OR jsonb_array_length(e->3)<>2
    OR (e#>>'{2,1}' IN ('14','ZZ')) IS NOT TRUE OR (e#>>'{3,1}' IN ('14','ZZ')) IS NOT TRUE THEN RETURN NULL; END IF;
   result:=result||jsonb_build_object('transportSender',e#>>'{2,0}','transportReceiver',e#>>'{3,0}');
  ELSIF t->>'tag'='UNH' THEN result:=result||jsonb_build_object('messageReference',e#>>'{1,0}');
  ELSIF t->>'tag'='BGM' THEN result:=result||jsonb_build_object('code',e#>>'{1,0}');
  ELSIF t->>'tag'='NAD' AND obj IS NULL AND e#>>'{1,0}' IN ('FR','DO') THEN
   key:=CASE e#>>'{1,0}' WHEN 'FR' THEN 'sender' ELSE 'receiver' END;
   IF result ? key OR e#>>'{2,1}' IS DISTINCT FROM '160' OR e#>>'{2,2}' IS DISTINCT FROM 'SVK' THEN RETURN NULL; END IF;
   result:=result||jsonb_build_object(key,e#>>'{2,0}');
  END IF;
  IF t->>'tag'='LIN' THEN
   IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj); END IF;
   line_index:=line_index+1;characteristic:=NULL;
   obj:=jsonb_build_object('objectId',e#>>'{3,0}','identityAgency',e#>>'{3,3}','lineIndex',line_index,'lineNumber',e#>>'{1,0}','segmentIndex',(t->>'index')::integer);
  ELSIF obj IS NOT NULL AND t->>'tag' NOT IN ('UNT','UNZ') THEN
   key:=NULL;value:=NULL;
   IF t->>'tag'='RFF' AND e#>>'{1,0}' IN ('LI','Z05') THEN key:=CASE e#>>'{1,0}' WHEN 'LI' THEN 'lineReference' ELSE 'gridArea' END;value:=e#>>'{1,1}';
   ELSIF t->>'tag'='CCI' THEN characteristic:=e#>>'{2,0}';
   ELSIF t->>'tag'='CAV' AND characteristic='Z13' THEN key:='reason';value:=e#>>'{1,0}';characteristic:=NULL;
   ELSIF t->>'tag'='NAD' AND e#>>'{1,0}'='UD' THEN
    IF obj ? 'customerId' THEN RETURN NULL; END IF;
    obj:=obj||jsonb_build_object('customerId',e#>>'{2,0}','customerQualifier',e#>>'{2,1}','customerAgency',e#>>'{2,2}','customerName',e#>>'{4,0}');
   ELSIF t->>'tag'='NAD' AND e#>>'{1,0}'='IT' THEN
    IF obj ? 'installationAddress' THEN RETURN NULL; END IF;
    obj:=obj||jsonb_build_object('installationAddress',e#>>'{5,0}','installationPostcode',e#>>'{8,0}','installationCity',e#>>'{6,0}');
   END IF;
   IF key IS NOT NULL THEN IF obj ? key THEN RETURN NULL; END IF;obj:=obj||jsonb_build_object(key,nullif(value,''));END IF;
  END IF;
 END LOOP;
 IF obj IS NOT NULL THEN objects:=objects||jsonb_build_array(obj); END IF;
 IF (result->>'code' IN ('Z01','Z02')) IS NOT TRUE OR nullif(result->>'sender','') IS NULL OR nullif(result->>'receiver','') IS NULL
 OR jsonb_array_length(objects)=0 THEN RETURN NULL; END IF;
 RETURN result||jsonb_build_object('objects',objects);
END $$;

REVOKE ALL ON FUNCTION gridex_received_sources.z02_core_wire_v1(text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1074
--
-- Name: capture_actor_market_v1(uuid, text, text, jsonb); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.capture_actor_market_v1(a uuid, m text, s text, rec jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$BEGIN
 IF a IS NULL OR(m IN('EL','GAS')) IS NOT TRUE OR rec->>'market' IS DISTINCT FROM m OR nullif(rec->>'edielId','') IS NULL OR nullif(rec->>'countryCode','') IS NULL THEN RAISE EXCEPTION 'ediel_registry_market_source_required';END IF;
 INSERT INTO gridex_registry_import.market_records(actor_id,market,source_sha256,record_sha256,record) VALUES(a,m,s,encode(sha256(convert_to(rec::text,'UTF8')),'hex'),rec);
 INSERT INTO gridex_registry_import.market_current VALUES(a,m,s) ON CONFLICT(actor_id,market) DO UPDATE SET source_sha256=excluded.source_sha256;
END$$;

REVOKE ALL ON FUNCTION gridex_registry_import.capture_actor_market_v1(uuid, text, text, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1075
--
-- Name: capture_route_market_v1(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.capture_route_market_v1(rid uuid, a uuid, m text, s text, rec jsonb) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE r public.platform_actor_routes%rowtype;BEGIN
 SELECT * INTO r FROM public.platform_actor_routes WHERE id=rid FOR SHARE;IF r.id IS NULL OR r.actor_id IS DISTINCT FROM a OR r.registry_market IS DISTINCT FROM m THEN RAISE EXCEPTION 'ediel_registry_route_market_source_required';END IF;
 INSERT INTO gridex_registry_import.route_market_sources VALUES(rid,a,m,s,encode(sha256(convert_to(rec::text,'UTF8')),'hex'),gridex_registry_import.route_tuple_v1(r));
 INSERT INTO gridex_registry_import.route_market_current VALUES(rid,s) ON CONFLICT(route_id) DO UPDATE SET source_sha256=excluded.source_sha256;
END$$;

REVOKE ALL ON FUNCTION gridex_registry_import.capture_route_market_v1(uuid, uuid, text, text, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1076
--
-- Name: capture_route_version_v1(); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.capture_route_version_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE version bigint;snapshot jsonb;
BEGIN
 IF TG_OP='UPDATE' AND (to_jsonb(new)-ARRAY['updated_at','metadata']) IS NOT DISTINCT FROM (to_jsonb(old)-ARRAY['updated_at','metadata']) THEN RETURN new;END IF;
 IF TG_OP='UPDATE' AND (new.id IS DISTINCT FROM old.id OR new.actor_id IS DISTINCT FROM old.actor_id) THEN RAISE EXCEPTION 'ediel_registry_route_identity_immutable';END IF;
 snapshot:=to_jsonb(old);SELECT coalesce(max(revision),0)+1 INTO version FROM gridex_registry_import.route_versions WHERE route_id=old.id;
 INSERT INTO gridex_registry_import.route_versions(route_id,actor_id,revision,snapshot,snapshot_hash) VALUES(old.id,old.actor_id,version,snapshot,encode(sha256(convert_to(snapshot::text,'UTF8')),'hex'));
 IF TG_OP='DELETE' THEN RETURN old;END IF;RETURN new;
END$$;

REVOKE ALL ON FUNCTION gridex_registry_import.capture_route_version_v1() FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1077
--
-- Name: current_el_actor_source_v1(uuid); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.current_el_actor_source_v1(p_actor_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE s text;rec gridex_registry_import.market_records%rowtype;n gridex_registry_import.normalized_batches%rowtype;b gridex_registry_import.batches%rowtype;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.platform_market_actors,public.platform_actor_roles,public.platform_actor_routes,public.platform_actor_certificates,gridex_registry_import.market_current,gridex_registry_import.route_market_current IN SHARE MODE;
 IF p_actor_id IS NULL THEN RAISE EXCEPTION 'ediel_registry_actual_legal_actor_required';END IF;
 SELECT source_sha256 INTO s FROM gridex_registry_import.market_current WHERE actor_id=p_actor_id AND market='EL' FOR SHARE;
 IF NOT FOUND THEN RETURN jsonb_build_object('status','held','actorId',p_actor_id,'reason','current_original_legal_actor_source_required');END IF;
 SELECT * INTO rec FROM gridex_registry_import.market_records WHERE actor_id=p_actor_id AND market='EL' AND source_sha256=s FOR SHARE;
 SELECT * INTO n FROM gridex_registry_import.normalized_batches WHERE source_sha256=s FOR SHARE;
 SELECT * INTO b FROM gridex_registry_import.batches WHERE source_sha256=s FOR SHARE;
 PERFORM 1 FROM public.platform_actor_identifiers i WHERE i.identifier_type='EdielId' AND i.identifier_value=rec.record->>'edielId' ORDER BY i.actor_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.platform_market_actors WHERE id=p_actor_id AND status='active') OR rec.actor_id IS NULL OR n.source_sha256 IS NULL OR b.source_sha256 IS NULL OR rec.record->>'market' IS DISTINCT FROM 'EL'
  OR nullif(rec.record->>'name','') IS NULL OR nullif(rec.record->>'countryCode','') IS NULL OR (rec.record->>'edielId' ~ '^[0-9]{5}$') IS NOT TRUE
  OR rec.record_sha256 IS DISTINCT FROM encode(sha256(convert_to(rec.record::text,'UTF8')),'hex')
  OR b.created_at>clock_timestamp() OR b.source_sha256 IS DISTINCT FROM encode(sha256(b.source_bytes),'hex')
  OR b.normalized_sha256 IS DISTINCT FROM encode(sha256(convert_to(n.records::text,'UTF8')),'hex')
  OR(SELECT count(*) FROM jsonb_array_elements(n.records)item WHERE item=rec.record)<>1
  OR(SELECT count(*) FROM public.platform_actor_identifiers i WHERE i.identifier_type='EdielId' AND i.identifier_value=rec.record->>'edielId' AND i.actor_id=p_actor_id AND(i.valid_from IS NULL OR i.valid_from<=clock_timestamp()::date) AND(i.valid_to IS NULL OR clock_timestamp()::date<=i.valid_to))<>1 THEN
  RETURN jsonb_build_object('status','held','actorId',p_actor_id,'reason','current_original_legal_actor_source_required');END IF;
 RETURN jsonb_build_object('status','source_qualified','actorId',p_actor_id,'market','EL','legalEdielId',rec.record->>'edielId','legalName',rec.record->>'name','countryCode',rec.record->>'countryCode','roles',rec.record->'roles','sourceSha256',s,'sourceRecordSha256',rec.record_sha256);
END$_$;

REVOKE ALL ON FUNCTION gridex_registry_import.current_el_actor_source_v1(uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1078
--
-- Name: current_el_tenant_actor_source_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.current_el_tenant_actor_source_v1(c uuid, legal_actor uuid, env text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE legal_id text;n int;source_actor uuid;q jsonb;identifiers jsonb;roles jsonb;profiles jsonb;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 IF c IS NULL OR legal_actor IS NULL OR(env IN('test','production')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_registry_owned_tenant_supplier_required';END IF;
 PERFORM id FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=env ORDER BY id FOR SHARE;
 PERFORM id FROM public.tenant_actor_roles WHERE company_id=c AND environment=env ORDER BY id FOR SHARE;
 PERFORM id FROM public.tenant_ediel_profiles WHERE company_id=c AND environment=env ORDER BY id FOR SHARE;
 SELECT count(DISTINCT(actor_id,btrim(identifier_value))),min(btrim(identifier_value)),jsonb_agg(to_jsonb(i) ORDER BY id) INTO n,legal_id,identifiers FROM public.tenant_actor_identifiers i WHERE company_id=c AND environment=env AND actor_id=legal_actor AND identifier_type='EdielId' AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR clock_timestamp()<valid_to);
 IF n<>1 OR legal_id!~'^[0-9]{5}$' OR(SELECT count(DISTINCT(actor_id,btrim(identifier_value)))FROM public.tenant_actor_identifiers WHERE company_id=c AND environment=env AND identifier_type='EdielId' AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR clock_timestamp()<valid_to))<>1 THEN RAISE EXCEPTION 'ediel_registry_unique_current_tenant_legal_identifier_required';END IF;
 SELECT jsonb_agg(to_jsonb(r) ORDER BY id) INTO roles FROM public.tenant_actor_roles r WHERE company_id=c AND environment=env AND actor_id=legal_actor AND role_code='electricity_supplier' AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR clock_timestamp()<valid_to);
 SELECT jsonb_agg(to_jsonb(p) ORDER BY id) INTO profiles FROM public.tenant_ediel_profiles p WHERE company_id=c AND environment=env AND market='electricity' AND is_enabled AND valid_from<=clock_timestamp() AND(valid_to IS NULL OR clock_timestamp()<valid_to);
 IF roles IS NULL OR profiles IS NULL THEN RAISE EXCEPTION 'ediel_registry_current_tenant_el_supplier_required';END IF;
 PERFORM id FROM public.platform_actor_identifiers WHERE identifier_type='EdielId' AND identifier_value=legal_id ORDER BY id FOR SHARE;
 SELECT count(DISTINCT actor_id),min(actor_id::text)::uuid INTO n,source_actor FROM public.platform_actor_identifiers WHERE identifier_type='EdielId' AND identifier_value=legal_id AND(valid_from IS NULL OR valid_from<=clock_timestamp()::date) AND(valid_to IS NULL OR clock_timestamp()::date<=valid_to);
 IF n<>1 THEN RETURN jsonb_build_object('status','held','reason','current_original_legal_actor_source_required','companyId',c,'environment',env,'legalActorId',legal_actor);END IF;
 q:=gridex_registry_import.current_el_actor_source_v1(source_actor);
 IF NOT EXISTS(SELECT FROM public.platform_market_actors WHERE id=source_actor AND status='active') OR NOT EXISTS(SELECT FROM public.platform_actor_roles WHERE actor_id=source_actor AND actor_role='electricity_supplier' AND is_active) OR q->>'status' IS DISTINCT FROM 'source_qualified' OR q->>'legalEdielId' IS DISTINCT FROM legal_id OR q->>'market' IS DISTINCT FROM 'EL' OR(q->'roles' @> '["electricity_supplier"]'::jsonb) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','reason','current_original_legal_actor_source_required','companyId',c,'environment',env,'legalActorId',legal_actor,'sourceActorId',source_actor);END IF;
 RETURN q||jsonb_build_object('companyId',c,'environment',env,'legalActorId',legal_actor,'sourceActorId',source_actor,'tenantIdentifierSource',identifiers,'tenantRoleSource',roles,'tenantProfileSource',profiles);
END$_$;

REVOKE ALL ON FUNCTION gridex_registry_import.current_el_tenant_actor_source_v1(uuid, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1079
--
-- Name: dispatch_source_v1(uuid, uuid, uuid, text, text, text); Type: FUNCTION; Schema: gridex_registry_import; Owner: -
--

CREATE FUNCTION gridex_registry_import.dispatch_source_v1(c uuid, communication uuid, profile uuid, env text, family text, application text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE p public.ediel_route_profiles%rowtype;r public.communication_routes%rowtype;profile_id text;communication_id text;registry_id uuid;q jsonb;profile_wire jsonb;subaddress text;source_family text;BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.platform_market_actors,public.platform_actor_roles,public.platform_actor_routes,public.platform_actor_certificates,gridex_registry_import.market_current,gridex_registry_import.route_market_current IN SHARE MODE;
 source_family:=CASE WHEN family='AI_LIST' THEN 'AI' ELSE family END;
 SELECT * INTO p FROM public.ediel_route_profiles WHERE id=profile AND company_id=c FOR SHARE;
 SELECT * INTO r FROM public.communication_routes WHERE id=communication AND company_id=c FOR SHARE;
 IF p.id IS NULL OR r.id IS NULL OR p.communication_route_id IS DISTINCT FROM r.id OR(env IN('test','production')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_registry_owned_route_profile_required';END IF;
 profile_id:=nullif(p.metadata->>'platform_actor_route_id','');communication_id:=nullif(r.auth_config->>'platform_actor_route_id','');
 IF profile_id IS NOT NULL AND communication_id IS NOT NULL AND profile_id IS DISTINCT FROM communication_id THEN RAISE EXCEPTION 'ediel_registry_route_mapping_conflict';END IF;
 IF coalesce(profile_id,communication_id) IS NULL THEN
  IF p.metadata->>'materialized_from'='platform_actor_routes' OR r.auth_config->>'materialized_from'='platform_actor_routes' THEN RAISE EXCEPTION 'ediel_registry_route_mapping_required';END IF;RETURN NULL;
 END IF;
 registry_id:=coalesce(profile_id,communication_id)::uuid;q:=gridex_registry_import.require_el_route_v1(registry_id);profile_wire:=to_jsonb(p);
 IF nullif(profile_wire->>'receiver_subaddress','') IS NOT NULL AND nullif(profile_wire->>'receiver_sub_address','') IS NOT NULL AND profile_wire->>'receiver_subaddress' IS DISTINCT FROM profile_wire->>'receiver_sub_address' THEN RAISE EXCEPTION 'ediel_registry_route_dispatch_source_mismatch';END IF;
 subaddress:=coalesce(nullif(profile_wire->>'receiver_subaddress',''),nullif(profile_wire->>'receiver_sub_address',''));
 -- Registry APP absence remains absent. The SAME canonical policy owns the
 -- protocol APP; actual saved/profile APP is still bound below. A declared
 -- registry APP can never be widened to a different selected application.
 IF q#>>'{wire,environment}' IS DISTINCT FROM env OR q#>>'{wire,family}' IS DISTINCT FROM source_family OR profile_wire->>'environment' IS DISTINCT FROM env
  OR profile_wire->>'message_family' IS DISTINCT FROM family OR lower(q#>>'{wire,transport}') IS DISTINCT FROM 'smtp'
  OR profile_wire->>'transport_type' IS DISTINCT FROM 'smtp' OR to_jsonb(r)->>'route_type' IS DISTINCT FROM 'ediel_partner'
  OR(env='production' AND to_jsonb(r)->>'environment_type' IS DISTINCT FROM 'production') OR(env='test' AND(to_jsonb(r)->>'environment_type' IN('tgt_test','agt_test','bilateral_test')) IS NOT TRUE)
  OR profile_wire->>'receiver_ediel_id' IS DISTINCT FROM q#>>'{wire,interchangePartyId}' OR subaddress IS DISTINCT FROM nullif(q#>>'{wire,subaddress}','')
  OR nullif(profile_wire->>'application_reference','') IS DISTINCT FROM nullif(application,'')
  OR(q#>>'{wire,applicationReference}' IS NOT NULL AND q#>>'{wire,applicationReference}' IS DISTINCT FROM application)
  OR r.target_email IS DISTINCT FROM q#>>'{wire,address}' THEN RAISE EXCEPTION 'ediel_registry_route_dispatch_source_mismatch';END IF;
 IF family='AI_LIST' AND(application IS NOT NULL OR q#>>'{wire,applicationReference}' IS NOT NULL OR nullif(q->>'legalName','') IS NULL
  OR profile_wire->>'is_active' IS DISTINCT FROM 'true' OR profile_wire->>'is_enabled' IS DISTINCT FROM 'true'
  OR to_jsonb(r)->>'is_active' IS DISTINCT FROM 'true' OR profile_wire->>'message_standard' IS DISTINCT FROM 'ai_list'
  OR profile_wire->>'payload_format' IS DISTINCT FROM 'raw') THEN RAISE EXCEPTION 'ediel_registry_ai_list_dispatch_source_required';END IF;
 RETURN q||jsonb_build_object('companyId',c,'communicationRouteId',r.id,'routeProfileId',p.id,'selectedApplicationReference',application)
  ||CASE WHEN family='AI_LIST' THEN jsonb_build_object('canonicalFamily','AI') ELSE '{}'::jsonb END;
END$$;

REVOKE ALL ON FUNCTION gridex_registry_import.dispatch_source_v1(uuid, uuid, uuid, text, text, text) FROM PUBLIC,anon,authenticated,service_role;

