-- canonical:1125
--
-- Name: manual_hold_v1(uuid, uuid, uuid, jsonb, jsonb); Type: FUNCTION; Schema: gridex_service_administration; Owner: -
--

CREATE FUNCTION gridex_service_administration.manual_hold_v1(c uuid, customer uuid, actor uuid, selection jsonb, missing jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE request_id uuid;task uuid;fingerprint text;BEGIN
 fingerprint:=encode(sha256(convert_to(selection::text||':'||missing::text,'UTF8')),'hex');
 PERFORM pg_advisory_xact_lock(hashtextextended('ediel_manual_permission:'||c::text||':'||customer::text||':'||actor::text||':'||fingerprint,0));
 SELECT r.id INTO request_id FROM gridex_service_administration.manual_permission_requests r WHERE r.company_id=c AND r.customer_id=customer AND r.actor_user_id=actor AND r.selection_hash=fingerprint;
 IF request_id IS NULL THEN
  request_id:=gen_random_uuid();
  INSERT INTO public.customer_operation_tasks(company_id,customer_id,task_type,status,priority,title,description,assigned_to,metadata,created_by,updated_by)
   VALUES(c,customer,'ediel_service_permission_source_held','open','high','Mätvärdestillstånd behöver källunderlag','Välj ett entydigt aktuellt tjänsteuppdrag och styrkt behörighetsunderlag innan marknadsbegäran skapas.',actor,jsonb_build_object('serviceCommandRequestId',request_id,'selection',selection,'missing',missing,'marketActivationGranted',false),actor,actor) RETURNING id INTO task;
  INSERT INTO gridex_service_administration.manual_permission_requests(id,company_id,customer_id,actor_user_id,selection,selection_hash,missing,task_id) VALUES(request_id,c,customer,actor,selection,fingerprint,missing,task);
 END IF;
 RETURN jsonb_build_object('status','held','requestId',request_id,'missing',missing);
END $$;

REVOKE ALL ON FUNCTION gridex_service_administration.manual_hold_v1(uuid, uuid, uuid, jsonb, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1127
--
-- Name: permission_matches_assignment_v1(public.ediel_service_assignments, public.metering_permissions); Type: FUNCTION; Schema: gridex_service_administration; Owner: -
--

CREATE FUNCTION gridex_service_administration.permission_matches_assignment_v1(a public.ediel_service_assignments, p public.metering_permissions) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE sender text;receiver text;
BEGIN
 PERFORM i.id FROM public.tenant_actor_identifiers i WHERE i.company_id=a.company_id AND i.environment=a.environment ORDER BY i.id FOR SHARE;
 PERFORM i.id FROM public.platform_actor_identifiers i WHERE i.actor_id=a.dso_actor_id ORDER BY i.id FOR SHARE;
 IF (SELECT count(DISTINCT (i.actor_id,i.identifier_value)) FROM public.tenant_actor_identifiers i WHERE i.company_id=a.company_id AND i.environment=a.environment AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR i.valid_to>now()))<>1 OR (SELECT count(DISTINCT i.identifier_value) FROM public.platform_actor_identifiers i WHERE i.actor_id=a.dso_actor_id AND lower(i.identifier_type) IN ('edielid','ediel_id') AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date))<>1 THEN RETURN false;END IF;
 SELECT i.identifier_value INTO sender FROM public.tenant_actor_identifiers i WHERE i.company_id=a.company_id AND i.environment=a.environment AND i.actor_id=a.provider_actor_id AND i.identifier_type='EdielId' AND i.valid_from<=now() AND (i.valid_to IS NULL OR i.valid_to>now()) LIMIT 1;
 SELECT i.identifier_value INTO receiver FROM public.platform_actor_identifiers i WHERE i.actor_id=a.dso_actor_id AND lower(i.identifier_type) IN ('edielid','ediel_id') AND i.is_verified AND (i.valid_from IS NULL OR i.valid_from<=current_date) AND (i.valid_to IS NULL OR i.valid_to>=current_date) LIMIT 1;
 RETURN p.company_id=a.company_id AND p.customer_id=a.customer_id AND sender IS NOT NULL AND receiver IS NOT NULL AND p.grid_owner_ediel_id=receiver AND p.metadata#>>'{marketPermission,legalActor}'=sender AND p.metadata#>>'{marketPermission,dsoActor}'=receiver AND p.metadata#>>'{marketPermission,mode}'=CASE a.mode WHEN 'V' THEN 'S17' WHEN 'VH' THEN 'S18' END AND public.ediel_permission_source_is_current_v1(a.company_id,p.id,coalesce(p.inbound_z14_message_id,p.source_z14_message_id)) IS TRUE;
END $$;

REVOKE ALL ON FUNCTION gridex_service_administration.permission_matches_assignment_v1(public.ediel_service_assignments, public.metering_permissions) FROM PUBLIC,anon,authenticated,service_role;

