CREATE FUNCTION gridex_supply_rescission.mandate_current_v1(c uuid, mandate uuid, fresh boolean DEFAULT true) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
