-- canonical:1230
--
-- Name: canonical_decimal_v2(text, text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.canonical_decimal_v2(value text, decimal_mark text DEFAULT '.'::text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
BEGIN
 IF value IS NULL OR decimal_mark NOT IN ('.',',') OR
  value !~ (CASE WHEN decimal_mark=',' THEN '^-?[0-9]+(,[0-9]+)?$' ELSE '^-?[0-9]+(\.[0-9]+)?$' END) THEN RETURN NULL; END IF;
 RETURN trim_scale(replace(value,decimal_mark,'.')::numeric)::text;
EXCEPTION WHEN OTHERS THEN RETURN NULL;
END $_$;

REVOKE ALL ON FUNCTION gridex_utilts_binding.canonical_decimal_v2(text, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1233
--
-- Name: decimal_rules_v1(jsonb, text, text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.decimal_rules_v1(tokens jsonb, tx text, decimal_mark text DEFAULT '.'::text) RETURNS jsonb
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE own_start integer;own_end integer;first_seq integer;t jsonb;value text;field text;max_dec integer;decimals integer;unit text;code text;product text;resolution text;format text;guide jsonb:='[]';functional jsonb:='[]';qualifier text;
BEGIN
 SELECT (s->>'index')::integer INTO STRICT own_start FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='IDE' AND s#>>'{elements,2,0}'=tx;
 SELECT min((s->>'index')::integer) INTO own_end FROM jsonb_array_elements(tokens) s WHERE (s->>'index')::integer>own_start AND s->>'tag' IN('IDE','UNT');
 SELECT min((s->>'index')::integer) INTO first_seq FROM jsonb_array_elements(tokens) s WHERE (s->>'index')::integer>own_start AND (s->>'index')::integer<own_end AND s->>'tag'='SEQ';
 SELECT s#>>'{elements,1,0}' INTO STRICT code FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='BGM';
 SELECT s#>>'{elements,3,0}' INTO product FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='LIN' AND (s->>'index')::integer>own_start AND (s->>'index')::integer<first_seq;
 SELECT s#>>'{elements,1,1}',s#>>'{elements,1,2}' INTO resolution,format FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='DTM' AND s#>>'{elements,1,0}'='354' AND (s->>'index')::integer>own_start AND (s->>'index')::integer<first_seq;
 SELECT s#>>'{elements,3,0}' INTO unit FROM jsonb_array_elements(tokens) s WHERE s->>'tag'='MEA' AND (s->>'index')::integer>own_start AND (s->>'index')::integer<first_seq;
 IF code='E30' AND unit IS NULL AND ((resolution='15' AND format='806') OR (resolution='1' AND format IN('801','802'))) THEN unit:='KWH'; END IF;
 FOR t IN SELECT s FROM jsonb_array_elements(tokens) s WHERE (s->>'index')::integer>first_seq AND (s->>'index')::integer<own_end AND s->>'tag' IN('QTY','PRI','MOA') LOOP
  value:=t#>>'{elements,1,1}';qualifier:=t#>>'{elements,1,0}';max_dec:=NULL;
  field:=CASE t->>'tag' WHEN 'MOA' THEN CASE qualifier WHEN '9' THEN '522' END WHEN 'PRI' THEN CASE qualifier WHEN 'CAL' THEN '523' END WHEN 'QTY' THEN CASE qualifier WHEN '135' THEN '515' WHEN '136' THEN '516' WHEN '220' THEN '517' WHEN '42' THEN '521' END END;
  IF field IS NULL THEN CONTINUE; END IF;
  IF value='NULL' AND field IN('516','517') THEN CONTINUE; END IF;
  IF decimal_mark NOT IN('.',',') OR value IS NULL OR value='' OR replace(value,decimal_mark,'.') !~ '^-?[0-9]+([.][0-9]+)?$'
   OR length(value)>(CASE field WHEN '523' THEN 15 ELSE 35 END) THEN guide:=guide||jsonb_build_array(field);CONTINUE; END IF;
  decimals:=CASE WHEN strpos(value,decimal_mark)>0 THEN length(value)-strpos(value,decimal_mark) ELSE 0 END;
  IF field IN('522','523') THEN
   max_dec:=CASE field WHEN '522' THEN 2 ELSE 6 END;
   IF decimals>max_dec THEN guide:=guide||jsonb_build_array(field); END IF;
   CONTINUE;
  END IF;
  IF qualifier IN('135','136') AND product='8716867000030' AND unit IS NOT NULL AND unit<>'KWH' THEN functional:=functional||'"E73"'::jsonb;CONTINUE; END IF;
  max_dec:=CASE WHEN unit='P1' THEN 3 WHEN qualifier='220' AND resolution='1' AND format IN('801','802') THEN 0
   WHEN qualifier IN('135','136') AND unit='KWH' THEN CASE WHEN resolution='1' AND format IN('801','802') THEN 0 WHEN (resolution='15' AND format='806') OR (resolution='1' AND format='805') THEN 3 END END;
  IF max_dec IS NOT NULL AND decimals>max_dec THEN functional:=functional||'"E51"'::jsonb; END IF;
 END LOOP;
 RETURN jsonb_build_object('guide',guide,'functional',functional);
EXCEPTION WHEN no_data_found OR too_many_rows THEN RETURN NULL;
END $_$;

REVOKE ALL ON FUNCTION gridex_utilts_binding.decimal_rules_v1(jsonb, text, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1234
--
-- Name: esco_local_time_v1(text, text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.esco_local_time_v1(value text, offset_value text) RETURNS timestamp with time zone
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $_$
DECLARE local_value timestamp;offset_minutes int;BEGIN
 IF value !~ '^[0-9]{12}$' OR offset_value !~ '^[+-][0-9]{4}$' OR substr(offset_value,4,2)::int>59 OR substr(offset_value,2,2)::int>14 OR (substr(offset_value,2,2)::int=14 AND substr(offset_value,4,2)::int<>0) THEN RETURN NULL;END IF;
 local_value:=make_timestamp(substr(value,1,4)::int,substr(value,5,2)::int,substr(value,7,2)::int,substr(value,9,2)::int,substr(value,11,2)::int,0);
 offset_minutes:=(substr(offset_value,2,2)::int*60+substr(offset_value,4,2)::int)*CASE left(offset_value,1) WHEN '-' THEN -1 ELSE 1 END;
 RETURN (local_value-make_interval(mins=>offset_minutes)) AT TIME ZONE 'UTC';
EXCEPTION WHEN OTHERS THEN RETURN NULL;END $_$;

REVOKE ALL ON FUNCTION gridex_utilts_binding.esco_local_time_v1(text, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1241
--
-- Name: missing_source_quality_v2(jsonb, jsonb); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.missing_source_quality_v2(tokens jsonb, item jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE start_at integer; stop_at integer; quantities jsonb; source_quantity jsonb; supplied jsonb; ordinal integer; next_sequence integer; quality_end integer;
BEGIN
 IF item->>'disposition' IS DISTINCT FROM 'accepted' OR jsonb_typeof(item->'quantities') IS DISTINCT FROM 'array' THEN RETURN false; END IF;
 SELECT (t->>'index')::integer INTO STRICT start_at FROM jsonb_array_elements(tokens) t
  WHERE t->>'tag'='IDE' AND t#>>'{elements,2,0}'=item->>'transactionId';
 SELECT min((t->>'index')::integer) INTO stop_at FROM jsonb_array_elements(tokens) t
  WHERE (t->>'index')::integer>start_at AND t->>'tag' IN ('IDE','UNT');
 SELECT coalesce(jsonb_agg(t ORDER BY (t->>'index')::integer),'[]') INTO quantities FROM jsonb_array_elements(tokens) t
  WHERE t->>'tag'='QTY' AND (t->>'index')::integer>start_at AND (t->>'index')::integer<stop_at;
 FOR ordinal IN 0..least(jsonb_array_length(quantities),jsonb_array_length(item->'quantities'))-1 LOOP
  source_quantity:=quantities->ordinal; supplied:=item->'quantities'->ordinal;
  IF jsonb_typeof(supplied)='object' AND supplied ? 'quality' THEN CONTINUE; END IF;
  SELECT coalesce(min((t->>'index')::integer),stop_at) INTO next_sequence FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='SEQ'
   AND (t->>'index')::integer>(source_quantity->>'index')::integer AND (t->>'index')::integer<stop_at;
  SELECT coalesce(min((t->>'index')::integer),next_sequence) INTO quality_end FROM jsonb_array_elements(tokens) t
   WHERE t->>'tag'='QTY' AND (t->>'index')::integer>(source_quantity->>'index')::integer AND (t->>'index')::integer<next_sequence;
  IF EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='STS' AND t#>>'{elements,1,0}'='8'
   AND (t->>'index')::integer>(source_quantity->>'index')::integer AND (t->>'index')::integer<quality_end) THEN RETURN true; END IF;
 END LOOP;
 RETURN false;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

REVOKE ALL ON FUNCTION gridex_utilts_binding.missing_source_quality_v2(jsonb, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1250
--
-- Name: require_positive_storage_authority_v1(uuid, text, uuid, text, uuid, text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.require_positive_storage_authority_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_transaction_id text, p_ack_message_id uuid DEFAULT NULL::uuid, p_ack_raw_payload text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE
 source public.ediel_messages%rowtype; ack public.ediel_messages%rowtype;
 receipt gridex_utilts_binding.receipts%rowtype; origin gridex_utilts_binding.receipts%rowtype;
 reservation public.ediel_ack_transaction_results%rowtype;
 series public.meter_reading_series%rowtype; stored gridex_utilts_binding.contracts%rowtype;
 tokens jsonb; ack_tokens jsonb; source_hash text; ack_hash text; document_id text;
BEGIN
 IF p_company_id IS NULL OR p_environment NOT IN ('test','production') OR p_source_message_id IS NULL
 OR nullif(p_transaction_id,'') IS NULL OR (p_ack_message_id IS NULL)<>(p_ack_raw_payload IS NULL) THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01';
 END IF;
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT * INTO source FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id AND environment=p_environment FOR SHARE;
 IF NOT FOUND OR source.direction<>'inbound' OR source.message_family<>'UTILTS' OR source.raw_payload IS NULL THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 source_hash:=encode(digest(convert_to(source.raw_payload,'UTF8'),'sha256'),'hex');
 SELECT * INTO receipt FROM gridex_utilts_binding.receipts WHERE source_message_id=source.id;
 IF NOT FOUND OR receipt.company_id IS DISTINCT FROM p_company_id OR receipt.environment IS DISTINCT FROM p_environment
 OR receipt.raw_hash IS DISTINCT FROM source_hash OR receipt.source_context IS DISTINCT FROM gridex_utilts_binding.source_context_v1(source)
 OR NOT receipt.membership ? p_transaction_id THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 tokens:=gridex_utilts_binding.wire_tokens_v1(source.raw_payload);
 IF tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(tokens) t
  WHERE t->>'tag'='IDE' AND t#>>'{elements,1,0}'='24' AND t#>>'{elements,2,0}'=p_transaction_id)<>1 THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 SELECT * INTO reservation FROM public.ediel_ack_transaction_results WHERE company_id=p_company_id AND environment=p_environment
  AND source_message_id=source.id AND source_transaction_id=p_transaction_id FOR SHARE;
 IF NOT FOUND OR reservation.disposition IS DISTINCT FROM 'accepted' OR reservation.planned_response_type IS DISTINCT FROM 'positive_aperak'
 OR reservation.persistence_status IS DISTINCT FROM 'persisted' OR reservation.persisted_series_id IS NULL
 OR (reservation.final_response_type IS NOT NULL AND reservation.final_response_type<>'positive_aperak') THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 SELECT * INTO series FROM public.meter_reading_series WHERE id=reservation.persisted_series_id AND company_id=p_company_id FOR SHARE;
 IF NOT FOUND OR series.message_code IS DISTINCT FROM source.message_code OR series.source_transaction_reference IS DISTINCT FROM p_transaction_id
 OR jsonb_typeof(series.raw_transaction) IS DISTINCT FROM 'object'
 OR series.immutable_hash IS DISTINCT FROM encode(digest(convert_to(series.raw_transaction::text,'UTF8'),'sha256'),'hex') THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 -- Identical old/late accepted data can legitimately reuse an earlier series.
 -- Its genuine source/contract origin stays authoritative; is_current is not an
 -- acceptance criterion and must not silently reject old-late-positive ACKs.
 SELECT * INTO origin FROM gridex_utilts_binding.receipts WHERE source_message_id=series.source_ediel_message_id;
 SELECT * INTO stored FROM gridex_utilts_binding.contracts WHERE series_id=series.id;
 IF origin.source_message_id IS NULL OR stored.series_id IS NULL OR origin.company_id IS DISTINCT FROM p_company_id
 OR origin.environment IS DISTINCT FROM p_environment OR origin.message_code IS DISTINCT FROM source.message_code
 OR stored.company_id IS DISTINCT FROM p_company_id OR stored.environment IS DISTINCT FROM p_environment
 OR stored.source_message_id IS DISTINCT FROM origin.source_message_id OR stored.transaction_id IS DISTINCT FROM p_transaction_id
 OR stored.contract_version NOT IN (1,2) OR stored.contract->>'version' IS DISTINCT FROM stored.contract_version::text
 OR NOT coalesce(gridex_utilts_binding.validate_contract_v1(stored.contract),false)
 OR stored.contract_hash IS DISTINCT FROM encode(digest(convert_to(stored.contract::text,'UTF8'),'sha256'),'hex')
 OR stored.contract IS DISTINCT FROM series.raw_transaction->'consumptionContract' THEN
  RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
 IF p_ack_message_id IS NOT NULL THEN
  SELECT * INTO ack FROM public.ediel_messages WHERE id=p_ack_message_id AND company_id=p_company_id AND environment=p_environment FOR SHARE;
  IF NOT FOUND OR ack.direction<>'outbound' OR ack.message_family<>'APERAK' OR ack.related_message_id IS DISTINCT FROM source.id
  OR ack.raw_payload IS DISTINCT FROM p_ack_raw_payload OR reservation.final_response_type IS DISTINCT FROM 'positive_aperak'
  OR reservation.response_message_id IS DISTINCT FROM ack.id OR reservation.finalized_at IS NULL THEN
   RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
  ack_tokens:=gridex_utilts_binding.wire_tokens_v1(ack.raw_payload);
  SELECT t#>>'{elements,2,0}' INTO document_id FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM';
  IF ack_tokens IS NULL OR (SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='UNH'
    AND t#>>'{elements,2,0}'='APERAK' AND t#>>'{elements,2,2}'='04A' AND t#>>'{elements,2,4}'='E5SE5A')<>1
   OR (SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='BGM' AND t#>>'{elements,1,0}'='312')<>1
   OR (SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='ACW' AND t#>>'{elements,1,1}'=p_transaction_id)<>1
   OR NOT EXISTS(SELECT FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='ACW' AND t#>>'{elements,1,1}'=p_transaction_id)
   OR (SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='DM')
      <>(SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='ACW')
   OR EXISTS(SELECT FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='DM'
       AND (nullif(t#>>'{elements,1,1}','') IS NULL OR length(t#>>'{elements,1,1}')>35 OR btrim(t#>>'{elements,1,1}') IS DISTINCT FROM t#>>'{elements,1,1}'))
   OR EXISTS(SELECT t#>>'{elements,1,1}' FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='RFF' AND t#>>'{elements,1,0}'='DM'
       GROUP BY t#>>'{elements,1,1}' HAVING count(*)>1)
   OR (SELECT count(*) FROM jsonb_array_elements(ack_tokens) t WHERE t->>'tag'='DOC' AND t#>>'{elements,2,0}'=document_id)<>1 THEN
   RAISE EXCEPTION 'utilts_positive_ack_storage_unavailable' USING ERRCODE='P0U01'; END IF;
  ack_hash:=encode(digest(convert_to(ack.raw_payload,'UTF8'),'sha256'),'hex');
 END IF;
 IF p_ack_message_id IS NOT NULL AND EXISTS(SELECT FROM gridex_ediel_inbound_context.receipts x WHERE x.company_id=p_company_id AND x.source_message_id=source.id AND x.environment=p_environment AND x.status='ready' AND x.context->>'actorRole' IN('energy_service_company','esco')) THEN
  PERFORM gridex_ediel_ack_replay.require_positive_service_scope_v1(p_company_id,p_environment,source.id,ack.raw_payload);
 END IF;
 RETURN jsonb_build_object('authorityVersion',1,'companyId',p_company_id,'environment',p_environment,'sourceMessageId',source.id,
  'transactionId',p_transaction_id,'sourceRawHash',source_hash,'ackMessageId',p_ack_message_id,'ackRawHash',ack_hash);
END $$;

REVOKE ALL ON FUNCTION gridex_utilts_binding.require_positive_storage_authority_v1(uuid, text, uuid, text, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1252; confirmed existing body drift; ownership/ACL retained
--
-- Name: stored_contract_v1(uuid, uuid, text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE OR REPLACE FUNCTION gridex_utilts_binding.stored_contract_v1(p_company uuid, p_source uuid, p_transaction text) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog', 'public', 'extensions'
    AS $$
DECLARE v_source public.ediel_messages%rowtype; v_receipt gridex_utilts_binding.receipts%rowtype;
 v_ack public.ediel_ack_transaction_results%rowtype; v_series public.meter_reading_series%rowtype;
 v_contract gridex_utilts_binding.contracts%rowtype; v_point text;
BEGIN
 SELECT s.* INTO v_source FROM public.ediel_messages s WHERE s.id=p_source AND s.company_id=p_company FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'utilts_consumption_source_unavailable' USING ERRCODE='P0U01'; END IF;
 SELECT r.* INTO v_receipt FROM gridex_utilts_binding.receipts r WHERE r.source_message_id=p_source AND r.company_id=p_company;
 IF NOT FOUND OR v_receipt.environment IS DISTINCT FROM v_source.environment OR v_receipt.message_code IS DISTINCT FROM v_source.message_code
 OR v_receipt.source_context IS DISTINCT FROM gridex_utilts_binding.source_context_v1(v_source)
 OR v_receipt.raw_hash IS DISTINCT FROM encode(digest(convert_to(v_source.raw_payload,'UTF8'),'sha256'),'hex') THEN
  RAISE EXCEPTION 'utilts_consumption_source_binding_invalid' USING ERRCODE='P0U01'; END IF;
 IF EXISTS(SELECT FROM jsonb_array_elements_text(v_receipt.membership) m(transaction_id) WHERE NOT EXISTS(
  SELECT FROM public.ediel_ack_transaction_results a WHERE a.company_id=p_company AND a.environment=v_source.environment AND a.source_message_id=p_source AND a.source_transaction_id=m.transaction_id))
 OR (SELECT count(*) FROM public.ediel_ack_transaction_results a WHERE a.source_message_id=p_source)<>jsonb_array_length(v_receipt.membership) THEN
  RAISE EXCEPTION 'utilts_consumption_membership_incomplete' USING ERRCODE='P0U01'; END IF;
 SELECT a.* INTO v_ack FROM public.ediel_ack_transaction_results a WHERE a.company_id=p_company AND a.environment=v_source.environment
 AND a.source_message_id=p_source AND a.source_transaction_id=p_transaction FOR SHARE;
 IF NOT FOUND OR v_ack.disposition IS DISTINCT FROM 'accepted' OR v_ack.persistence_status IS DISTINCT FROM 'persisted'
 OR v_ack.planned_response_type IS DISTINCT FROM 'positive_aperak' THEN RAISE EXCEPTION 'utilts_consumption_not_accepted' USING ERRCODE='P0U01'; END IF;
 SELECT s.* INTO v_series FROM public.meter_reading_series s WHERE s.id=v_ack.persisted_series_id AND s.company_id=p_company FOR SHARE;
 IF NOT FOUND OR v_series.immutable_hash IS DISTINCT FROM encode(digest(convert_to(v_series.raw_transaction::text,'UTF8'),'sha256'),'hex') THEN
  RAISE EXCEPTION 'utilts_consumption_raw_conflict' USING ERRCODE='P0U01'; END IF;
 SELECT c.* INTO v_contract FROM gridex_utilts_binding.contracts c WHERE c.series_id=v_series.id AND c.company_id=p_company;
 IF NOT FOUND OR v_contract.contract_version NOT IN (1,2) OR v_contract.contract_version IS DISTINCT FROM v_receipt.contract_version
 OR v_contract.contract->'version' IS DISTINCT FROM to_jsonb(v_contract.contract_version) OR v_contract.environment IS DISTINCT FROM v_source.environment OR v_contract.transaction_id IS DISTINCT FROM p_transaction
 OR v_contract.contract->>'companyId' IS DISTINCT FROM p_company::text OR v_contract.contract->>'environment' IS DISTINCT FROM v_source.environment
 OR v_contract.contract->>'messageCode' IS DISTINCT FROM v_source.message_code OR v_contract.contract->>'transactionId' IS DISTINCT FROM p_transaction
 OR v_contract.contract_hash IS DISTINCT FROM encode(digest(convert_to(v_contract.contract::text,'UTF8'),'sha256'),'hex')
 OR v_contract.contract IS DISTINCT FROM v_series.raw_transaction->'consumptionContract'
 OR NOT coalesce(gridex_utilts_binding.validate_contract_v1(v_contract.contract),false) THEN
  RAISE EXCEPTION 'utilts_consumption_contract_conflict' USING ERRCODE='P0U01'; END IF;
 -- Pre-forward receipts are not a namespace approval either. All sinks use
 -- this check, including direct calls with an already committed contract.
 v_point:=gridex_utilts_binding.supported_point_v1(gridex_utilts_binding.wire_tokens_v1(v_source.raw_payload),p_transaction);
 IF v_point IS NULL OR EXISTS(SELECT FROM jsonb_array_elements(v_contract.contract->'observations') o WHERE o->>'externalPoint' IS DISTINCT FROM v_point) THEN
  RAISE EXCEPTION 'utilts_consumption_identity_unsupported' USING ERRCODE='P0U01'; END IF;
 IF v_contract.contract_version=2 AND NOT coalesce(gridex_utilts_binding.validate_decimal_source_v2(gridex_utilts_binding.wire_tokens_v1(v_source.raw_payload),v_series.raw_transaction,
  CASE WHEN left(v_source.raw_payload,3)='UNA' THEN substring(v_source.raw_payload,6,1) ELSE '.' END),false) THEN
  RAISE EXCEPTION 'utilts_consumption_decimal_source_conflict' USING ERRCODE='P0U01'; END IF;
 RETURN v_contract.contract;
END $$;

-- canonical:1253; confirmed existing body drift; ownership/ACL retained
--
-- Name: supported_point_v1(jsonb, text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE OR REPLACE FUNCTION gridex_utilts_binding.supported_point_v1(tokens jsonb, transaction_id text) RETURNS text
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE first_ide integer; start_at integer; stop_at integer; end_at integer; point jsonb; party jsonb; role_name text;
BEGIN
 SELECT min((t->>'index')::integer) INTO first_ide FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='IDE';
 FOREACH role_name IN ARRAY ARRAY['MS','MR'] LOOP
  SELECT jsonb_agg(t) INTO party FROM jsonb_array_elements(tokens) t
   WHERE t->>'tag'='NAD' AND t#>>'{elements,1,0}'=role_name AND (t->>'index')::integer<first_ide;
  IF jsonb_array_length(party) IS DISTINCT FROM 1 OR party#>'{0,elements,1}' IS DISTINCT FROM jsonb_build_array(role_name)
   OR jsonb_array_length(party#>'{0,elements,2}') IS DISTINCT FROM 3
   OR nullif(btrim(party#>>'{0,elements,2,0}'),'') IS NULL
   OR party#>>'{0,elements,2,0}' IS DISTINCT FROM btrim(party#>>'{0,elements,2,0}')
   OR party#>>'{0,elements,2,1}' IS DISTINCT FROM 'SVK' OR party#>>'{0,elements,2,2}' IS DISTINCT FROM '260' THEN RETURN NULL; END IF;
 END LOOP;
 SELECT jsonb_agg(t) INTO point FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='IDE' AND t#>>'{elements,2,0}'=transaction_id;
 IF jsonb_array_length(point) IS DISTINCT FROM 1 OR point#>'{0,elements,1}' IS DISTINCT FROM '["24"]'::jsonb
  OR point#>'{0,elements,2}' IS DISTINCT FROM jsonb_build_array(transaction_id) THEN RETURN NULL; END IF;
 start_at:=(point#>>'{0,index}')::integer;
 SELECT min((t->>'index')::integer) INTO end_at FROM jsonb_array_elements(tokens) t
  WHERE (t->>'index')::integer>start_at AND t->>'tag' IN ('IDE','UNT');
 IF end_at IS NULL THEN RETURN NULL; END IF;
 -- Preserve the previously reviewed LOC+175 physical-IDE refusal.
 IF EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LOC'
   AND t#>>'{elements,1,0}'='175' AND (t->>'index')::integer>start_at
   AND (t->>'index')::integer<end_at) THEN RETURN NULL; END IF;
 SELECT min((t->>'index')::integer) INTO stop_at FROM jsonb_array_elements(tokens) t
  WHERE (t->>'index')::integer>start_at AND t->>'tag' IN ('IDE','SEQ','UNT');
 -- A post-SEQ LOC+172 is still inside this IDE, even though it is outside
 -- the SG5 header selected below. Earlier duplicate LOC+172 is caught there.
 IF EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LOC'
   AND t#>>'{elements,1,0}'='172' AND (t->>'index')::integer>=stop_at
   AND (t->>'index')::integer<end_at) THEN RETURN NULL; END IF;
 SELECT jsonb_agg(t) INTO point FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='LOC' AND t#>>'{elements,1,0}'='172'
  AND (t->>'index')::integer>start_at AND (t->>'index')::integer<stop_at;
 IF jsonb_array_length(point) IS DISTINCT FROM 1 OR point#>'{0,elements,1}' IS DISTINCT FROM '["172"]'::jsonb
  OR jsonb_array_length(point#>'{0,elements,2}') IS DISTINCT FROM 3
  OR point#>>'{0,elements,2,1}' IS DISTINCT FROM '' OR point#>>'{0,elements,2,2}' IS DISTINCT FROM '9'
  OR nullif(btrim(point#>>'{0,elements,2,0}'),'') IS NULL
  OR point#>>'{0,elements,2,0}' IS DISTINCT FROM btrim(point#>>'{0,elements,2,0}')
  OR point#>>'{0,elements,2,0}' ~ '[[:cntrl:]]' THEN RETURN NULL; END IF;
 RETURN point#>>'{0,elements,2,0}';
END $$;

-- canonical:1256
--
-- Name: valid_transaction_reference_v2(text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.valid_transaction_reference_v2(value text) RETURNS boolean
    LANGUAGE sql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
 SELECT value IS NOT NULL AND char_length(value) BETWEEN 1 AND 35
  AND value !~ '^ *$' AND right(value,1)<>' '
  AND NOT EXISTS(SELECT FROM generate_series(1,char_length(value)) n
   WHERE ascii(substr(value,n,1))<32 OR ascii(substr(value,n,1)) BETWEEN 127 AND 159 OR ascii(substr(value,n,1))>255)
$_$;

REVOKE ALL ON FUNCTION gridex_utilts_binding.valid_transaction_reference_v2(text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1258; confirmed existing body drift; ownership/ACL retained
--
-- Name: validate_contract_v1(jsonb); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE OR REPLACE FUNCTION gridex_utilts_binding.validate_contract_v1(c jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE o jsonb; observations jsonb:='[]'; projected jsonb;
BEGIN
 IF c->'version'='1'::jsonb THEN RETURN gridex_utilts_binding.validate_legacy_contract_v1(c); END IF;
 IF c->'version' IS DISTINCT FROM '2'::jsonb OR c->>'projectionVersion' IS DISTINCT FROM 'utilts-consumption-v2'
  OR jsonb_typeof(c->'observations') IS DISTINCT FROM 'array'
  OR jsonb_typeof(c->'transactionId') IS DISTINCT FROM 'string'
  OR NOT coalesce(gridex_utilts_binding.valid_transaction_reference_v2(c->>'transactionId'),false) THEN RETURN false; END IF;
 FOR o IN SELECT value FROM jsonb_array_elements(c->'observations') LOOP
  IF jsonb_typeof(o->'quantity') IS DISTINCT FROM 'string'
   OR gridex_utilts_binding.canonical_decimal_v2(o->>'quantity') IS DISTINCT FROM o->>'quantity' THEN RETURN false; END IF;
  -- Reuse the strict frozen V1 shape/time/attribution predicates with an exact
  -- numeric JSON projection. This is validation only, never stored V2 content.
  observations:=observations||jsonb_build_array(o||jsonb_build_object('quantity',(o->>'quantity')::numeric));
 END LOOP;
 projected:=c||jsonb_build_object('version',1,'projectionVersion','utilts-consumption-v1','observations',observations,'transactionId',btrim(c->>'transactionId'));
 -- The frozen validator checks padded text generically. This shape-only copy
 -- uses its nonempty canonical form AFTER exact physical U505 validation.
 -- No stored contract, hash, original or consumer reference is normalized.
 RETURN gridex_utilts_binding.validate_legacy_contract_v1(projected);
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

-- canonical:1259
--
-- Name: validate_decimal_source_v2(jsonb, jsonb, text); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.validate_decimal_source_v2(tokens jsonb, item jsonb, decimal_mark text) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE start_at integer; stop_at integer; first_sequence integer; sequence_at integer; next_sequence integer;
 quantities jsonb; source_quantity jsonb; supplied jsonb; o jsonb; ordinal integer; unit text; own_mea jsonb; scale numeric; code text; energy_unit text; quality_end integer;
BEGIN
 IF item->>'disposition'<>'accepted' THEN RETURN true; END IF;
 SELECT t#>>'{elements,1,0}' INTO STRICT code FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='BGM';
 SELECT (t->>'index')::integer INTO STRICT start_at FROM jsonb_array_elements(tokens) t
  WHERE t->>'tag'='IDE' AND t#>>'{elements,2,0}'=item->>'transactionId';
 SELECT min((t->>'index')::integer) INTO stop_at FROM jsonb_array_elements(tokens) t
  WHERE (t->>'index')::integer>start_at AND t->>'tag' IN ('IDE','UNT');
 SELECT coalesce(min((t->>'index')::integer),stop_at) INTO first_sequence FROM jsonb_array_elements(tokens) t
  WHERE t->>'tag'='SEQ' AND (t->>'index')::integer>start_at AND (t->>'index')::integer<stop_at;
 SELECT jsonb_agg(t) INTO own_mea FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='MEA'
  AND (t->>'index')::integer>start_at AND (t->>'index')::integer<first_sequence;
 IF own_mea IS NOT NULL THEN
  IF jsonb_array_length(own_mea) IS DISTINCT FROM 1 OR own_mea#>>'{0,elements,1,0}' IS DISTINCT FROM 'AAZ' THEN RETURN false; END IF;
  unit:=own_mea#>>'{0,elements,3,0}';
  IF nullif(unit,'') IS NULL THEN RETURN false; END IF;
 END IF;
 -- A source-only request, dated E30 reading or monetary series may have no
 -- field264. Preserve its exact raw values without inventing a kWh consumer.
 IF unit IS DISTINCT FROM item->>'unit' OR (code='E30' AND own_mea IS NOT NULL) THEN RETURN false; END IF;
 energy_unit:=unit;
 -- U p36 requires standard E30 quarter/month/year energy in kWh, while p85
 -- excludes MEA. This explicit source condition never manufactures a raw MEA.
 IF code='E30' AND unit IS NULL AND (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='DTM'
  AND (t->>'index')::integer>start_at AND (t->>'index')::integer<first_sequence AND t#>>'{elements,1,0}'='354')=1
  AND EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='DTM'
  AND (t->>'index')::integer>start_at AND (t->>'index')::integer<first_sequence AND t#>>'{elements,1,0}'='354'
  AND ((t#>>'{elements,1,1}'='15' AND t#>>'{elements,1,2}'='806') OR (t#>>'{elements,1,1}'='1' AND t#>>'{elements,1,2}' IN ('801','802'))))
 THEN energy_unit:='KWH'; END IF;
 IF code IN ('E31','E66','S07','S02','S03','S04') AND unit IS NULL THEN RETURN false; END IF;
 SELECT coalesce(jsonb_agg(t ORDER BY (t->>'index')::integer),'[]') INTO quantities FROM jsonb_array_elements(tokens) t
  WHERE t->>'tag'='QTY' AND (t->>'index')::integer>start_at AND (t->>'index')::integer<stop_at;
 IF code IN ('S01','S05') AND jsonb_array_length(quantities)>0 AND unit IS NULL THEN RETURN false; END IF;
 IF jsonb_typeof(item->'quantities') IS DISTINCT FROM 'array' OR jsonb_array_length(item->'quantities')<>jsonb_array_length(quantities) THEN RETURN false; END IF;
 FOR ordinal IN 0..jsonb_array_length(quantities)-1 LOOP
  source_quantity:=quantities->ordinal; supplied:=item->'quantities'->ordinal;
  IF supplied->>'qualifier' IS DISTINCT FROM source_quantity#>>'{elements,1,0}'
   OR nullif(source_quantity#>>'{elements,1,2}','') IS NOT NULL THEN RETURN false; END IF;
  SELECT max((t->>'index')::integer) INTO sequence_at FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='SEQ'
   AND (t->>'index')::integer>start_at AND (t->>'index')::integer<(source_quantity->>'index')::integer;
  SELECT coalesce(min((t->>'index')::integer),stop_at) INTO next_sequence FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='SEQ'
   AND (t->>'index')::integer>sequence_at AND (t->>'index')::integer<stop_at;
  IF sequence_at IS NULL OR EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='MEA'
   AND (t->>'index')::integer>sequence_at AND (t->>'index')::integer<next_sequence
   AND (t#>>'{elements,1,0}' IS DISTINCT FROM 'AAZ' OR t#>>'{elements,3,0}' IS DISTINCT FROM unit)) THEN RETURN false; END IF;
  IF source_quantity#>>'{elements,1,0}' IN ('136','220') AND source_quantity#>>'{elements,1,1}'='NULL' THEN
   IF source_quantity#>>'{elements,1,0}'='136' OR code='E30' THEN
    SELECT coalesce(min((t->>'index')::integer),next_sequence) INTO quality_end FROM jsonb_array_elements(tokens) t
     WHERE t->>'tag'='QTY' AND (t->>'index')::integer>(source_quantity->>'index')::integer AND (t->>'index')::integer<next_sequence;
    IF NOT EXISTS(SELECT FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='STS'
     AND (t->>'index')::integer>(source_quantity->>'index')::integer AND (t->>'index')::integer<quality_end
     AND t#>>'{elements,1,0}'='8' AND t#>>'{elements,2,0}'='46') THEN RETURN false; END IF;
   END IF;
   IF supplied->'value' IS DISTINCT FROM 'null'::jsonb THEN RETURN false; END IF;
  ELSIF jsonb_typeof(supplied->'value') IS DISTINCT FROM 'string'
   OR gridex_utilts_binding.canonical_decimal_v2(source_quantity#>>'{elements,1,1}',decimal_mark) IS DISTINCT FROM supplied->>'value'
   OR gridex_utilts_binding.canonical_decimal_v2(supplied->>'value') IS DISTINCT FROM supplied->>'value' THEN RETURN false; END IF;
  -- SC-053: a supplied stored quality must be this QTY's own STS+8 code
  -- (until the next QTY of the same SEQ), or JSON null when it has none.
  IF supplied ? 'quality' THEN
   SELECT coalesce(min((t->>'index')::integer),next_sequence) INTO quality_end FROM jsonb_array_elements(tokens) t
    WHERE t->>'tag'='QTY' AND (t->>'index')::integer>(source_quantity->>'index')::integer AND (t->>'index')::integer<next_sequence;
   IF (SELECT count(*) FROM jsonb_array_elements(tokens) t WHERE t->>'tag'='STS' AND t#>>'{elements,1,0}'='8'
     AND (t->>'index')::integer>(source_quantity->>'index')::integer AND (t->>'index')::integer<quality_end)>1
    OR supplied->'quality' IS DISTINCT FROM coalesce((SELECT to_jsonb(t#>>'{elements,2,0}') FROM jsonb_array_elements(tokens) t
     WHERE t->>'tag'='STS' AND t#>>'{elements,1,0}'='8'
      AND (t->>'index')::integer>(source_quantity->>'index')::integer AND (t->>'index')::integer<quality_end),'null'::jsonb)
   THEN RETURN false; END IF;
  END IF;
 END LOOP;
 -- SC-053: once an item carries stored qualities (the SC-053 shape), every
 -- quantity with a source STS+8 must carry its own; a committed pre-SC-053
 -- item has none and keeps its original validation.
 IF EXISTS(SELECT FROM jsonb_array_elements(item->'quantities') q WHERE jsonb_typeof(q)='object' AND q ? 'quality')
  AND gridex_utilts_binding.missing_source_quality_v2(tokens,item) THEN RETURN false; END IF;
 FOR o IN SELECT value FROM jsonb_array_elements(item#>'{consumptionContract,observations}') LOOP
  source_quantity:=quantities->((o->>'sourceOrdinal')::integer);
  scale:=CASE energy_unit WHEN 'KWH' THEN 1 WHEN 'MWH' THEN 1000 WHEN 'GWH' THEN 1000000 END;
  IF source_quantity IS NULL OR source_quantity#>>'{elements,1,0}' IS DISTINCT FROM '136'
   OR scale IS NULL OR trim_scale(gridex_utilts_binding.canonical_decimal_v2(source_quantity#>>'{elements,1,1}',decimal_mark)::numeric*scale)::text IS DISTINCT FROM o->>'quantity'
   THEN RETURN false; END IF;
 END LOOP;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $$;

REVOKE ALL ON FUNCTION gridex_utilts_binding.validate_decimal_source_v2(jsonb, jsonb, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1260
--
-- Name: validate_legacy_contract_v1(jsonb); Type: FUNCTION; Schema: gridex_utilts_binding; Owner: -
--

CREATE FUNCTION gridex_utilts_binding.validate_legacy_contract_v1(c jsonb) RETURNS boolean
    LANGUAGE plpgsql IMMUTABLE
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE p_contract ALIAS FOR $1; v_billing jsonb:=p_contract->'billing'; v_value jsonb; v_key text; v_observation jsonb;
BEGIN
 IF NOT coalesce(gridex_utilts_binding.validate_contract_base_v1(p_contract),false) THEN RETURN false; END IF;
 IF jsonb_typeof(v_billing->'requestScope') NOT IN ('string','null')
 OR (v_billing->>'capability'='write' AND v_billing->>'requestScope' IS DISTINCT FROM 'billing_underlay') THEN RETURN false; END IF;
 FOREACH v_key IN ARRAY ARRAY['month','year'] LOOP
  v_value:=v_billing->v_key;
  IF v_value<>'null'::jsonb AND (jsonb_typeof(v_value)<>'number' OR (v_value#>>'{}')::numeric<>trunc((v_value#>>'{}')::numeric)) THEN RETURN false; END IF;
 END LOOP;
 IF (v_billing->>'month')::numeric NOT BETWEEN 1 AND 12 OR (v_billing->>'year')::numeric NOT BETWEEN 1900 AND 9999 THEN RETURN false; END IF;
 -- TypeScript rejects empty/padded strings in all nullable text fields too.
 FOR v_value IN SELECT value FROM jsonb_each(p_contract) UNION ALL SELECT value FROM jsonb_each(p_contract->'interpretation')
  UNION ALL SELECT value FROM jsonb_each(p_contract->'metering') UNION ALL SELECT value FROM jsonb_each(v_billing) LOOP
  IF jsonb_typeof(v_value)='string' AND (nullif(btrim(v_value#>>'{}'),'') IS NULL OR btrim(v_value#>>'{}')<>v_value#>>'{}') THEN RETURN false; END IF;
 END LOOP;
 FOR v_observation IN SELECT value FROM jsonb_array_elements(p_contract->'observations') LOOP
  PERFORM (v_observation->>'quantity')::double precision;
  FOR v_value IN SELECT value FROM jsonb_each(v_observation) LOOP
   IF jsonb_typeof(v_value)='string' AND (nullif(btrim(v_value#>>'{}'),'') IS NULL OR btrim(v_value#>>'{}')<>v_value#>>'{}') THEN RETURN false; END IF;
  END LOOP;
 END LOOP;
 RETURN true;
EXCEPTION WHEN OTHERS THEN RETURN false;
END $_$;

REVOKE ALL ON FUNCTION gridex_utilts_binding.validate_legacy_contract_v1(jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1263
--
-- Name: capture_insert_v1(); Type: FUNCTION; Schema: gridex_utilts_issuer; Owner: -
--

CREATE FUNCTION gridex_utilts_issuer.capture_insert_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE src gridex_received_sources.sources%rowtype;wire jsonb;tokens jsonb;token jsonb;legal jsonb;sender jsonb;first_detail integer;v gridex_utilts_issuer.issuer_versions%rowtype;mandate gridex_utilts_issuer.transport_mandate_versions%rowtype;
 matches integer;epoch bigint;txs jsonb:='[]';collisions jsonb:='[]';ref text;duplicate_message boolean:=false;ordinal integer:=0;reason text:='ediel_utilts_foreign_issuer_basis_unavailable';
BEGIN
 IF NEW.direction IS DISTINCT FROM 'inbound' OR NEW.message_standard IS DISTINCT FROM 'edifact' OR NEW.message_family IS DISTINCT FROM 'UTILTS' THEN RETURN NEW;END IF;
 SELECT * INTO src FROM gridex_received_sources.sources WHERE source_message_id=NEW.id AND company_id=NEW.company_id AND environment=NEW.environment AND origin='database_insert';
 IF src.source_message_id IS NULL OR src.received_context->>'contextOrigin' IS DISTINCT FROM 'database_insert' OR src.raw_payload IS DISTINCT FROM NEW.raw_payload
  OR src.payload_hash IS DISTINCT FROM encode(sha256(convert_to(NEW.raw_payload,'UTF8')),'hex') THEN RETURN NEW;END IF;
 wire:=gridex_ack_authority.wire_v1(NEW.raw_payload);tokens:=gridex_utilts_binding.wire_tokens_v1(NEW.raw_payload);
 IF wire IS NOT NULL AND tokens IS NOT NULL AND wire->>'family'='UTILTS' AND wire->>'code' IS DISTINCT FROM 'ERR' THEN
  SELECT min((x->>'index')::integer) INTO first_detail FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='IDE';
  SELECT count(*) INTO matches FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='MS' AND (first_detail IS NULL OR (x->>'index')::integer<first_detail);
  IF matches=1 THEN SELECT x#>'{elements,2}' INTO legal FROM jsonb_array_elements(tokens) x WHERE x->>'tag'='NAD' AND x#>>'{elements,1,0}'='MS' AND (first_detail IS NULL OR (x->>'index')::integer<first_detail);END IF;
  sender:=wire->'sender';ref:=wire->>'document';
  FOR token IN SELECT value FROM jsonb_array_elements(tokens) x(value) WHERE value->>'tag'='IDE' ORDER BY (value->>'index')::integer LOOP
   txs:=txs||jsonb_build_array(jsonb_build_object('transactionIndex',ordinal,'transactionId',token#>>'{elements,2,0}'));ordinal:=ordinal+1;
  END LOOP;
  IF legal IS NOT NULL THEN PERFORM gridex_utilts_issuer.lock_legal_identity_v1(NEW.environment,legal);END IF;
  SELECT count(*) INTO matches FROM gridex_utilts_issuer.issuer_versions i JOIN gridex_utilts_issuer.namespaces n ON n.id=i.namespace_id JOIN gridex_utilts_issuer.transport_mandate_versions m ON m.issuer_version_id=i.id
   WHERE n.environment=NEW.environment AND i.legal_identity=legal AND m.transport_sender=sender
    AND i.approved_at<=src.captured_at AND m.approved_at<=src.captured_at AND i.valid_from<=src.captured_at AND (i.valid_until IS NULL OR src.captured_at<i.valid_until)
    AND m.valid_from<=src.captured_at AND (m.valid_until IS NULL OR src.captured_at<m.valid_until)
    AND NOT EXISTS(SELECT FROM gridex_utilts_issuer.revocations r WHERE r.namespace_id=n.id AND (r.issuer_version_id=i.id OR r.mandate_version_id=m.id) AND r.approved_at<=src.captured_at AND r.effective_at<=src.captured_at);
  IF matches=1 THEN
   SELECT i.* INTO v FROM gridex_utilts_issuer.issuer_versions i JOIN gridex_utilts_issuer.namespaces n ON n.id=i.namespace_id JOIN gridex_utilts_issuer.transport_mandate_versions m ON m.issuer_version_id=i.id
    WHERE n.environment=NEW.environment AND i.legal_identity=legal AND m.transport_sender=sender
     AND i.approved_at<=src.captured_at AND m.approved_at<=src.captured_at AND i.valid_from<=src.captured_at AND (i.valid_until IS NULL OR src.captured_at<i.valid_until)
     AND m.valid_from<=src.captured_at AND (m.valid_until IS NULL OR src.captured_at<m.valid_until)
     AND NOT EXISTS(SELECT FROM gridex_utilts_issuer.revocations r WHERE r.namespace_id=n.id AND (r.issuer_version_id=i.id OR r.mandate_version_id=m.id) AND r.approved_at<=src.captured_at AND r.effective_at<=src.captured_at);
   SELECT * INTO mandate FROM gridex_utilts_issuer.transport_mandate_versions m WHERE m.issuer_version_id=v.id AND m.transport_sender=sender AND m.approved_at<=src.captured_at AND m.valid_from<=src.captured_at AND (m.valid_until IS NULL OR src.captured_at<m.valid_until)
    AND NOT EXISTS(SELECT FROM gridex_utilts_issuer.revocations r WHERE r.mandate_version_id=m.id AND r.approved_at<=src.captured_at AND r.effective_at<=src.captured_at);
   PERFORM gridex_utilts_issuer.lock_namespace_v1(v.namespace_id);
   -- Fence newly committed revocation/version observations after acquiring the
   -- same namespace lock as approval/revocation and first-effect consumers.
   IF EXISTS(SELECT FROM gridex_utilts_issuer.revocations r WHERE r.namespace_id=v.namespace_id AND (r.issuer_version_id=v.id OR r.mandate_version_id=mandate.id) AND r.approved_at<=src.captured_at AND r.effective_at<=src.captured_at) THEN v.id:=NULL;mandate.id:=NULL;v.namespace_id:=NULL;
   ELSE
    SELECT coalesce(max(a.namespace_epoch),0)+1 INTO epoch FROM gridex_utilts_issuer.source_admissions a WHERE a.namespace_id=v.namespace_id;
    duplicate_message:=ref IS NOT NULL AND EXISTS(SELECT FROM gridex_utilts_issuer.observed_identifiers o WHERE o.namespace_id=v.namespace_id AND o.field_number='203' AND o.physical_reference=ref);
    SELECT coalesce(jsonb_agg(own ORDER BY (own->>'transactionIndex')::integer),'[]') INTO collisions FROM jsonb_array_elements(txs) own WHERE EXISTS(SELECT FROM gridex_utilts_issuer.observed_identifiers o WHERE o.namespace_id=v.namespace_id AND o.field_number='505' AND o.physical_reference=own->>'transactionId');
    reason:='ediel_utilts_identity_history_coverage_unavailable';
   END IF;
  ELSIF matches>1 THEN reason:='ediel_utilts_foreign_issuer_binding_ambiguous';END IF;
 END IF;
 INSERT INTO gridex_utilts_issuer.source_admissions(source_message_id,company_id,environment,source_payload_hash,observed_at,namespace_id,issuer_version_id,mandate_version_id,namespace_epoch,message_reference,transactions,message_reference_collision,transaction_reference_collisions,hold_reason)
  VALUES(NEW.id,NEW.company_id,NEW.environment,src.payload_hash,src.captured_at,v.namespace_id,v.id,mandate.id,epoch,ref,txs,duplicate_message,collisions,reason);
 IF v.id IS NOT NULL THEN
  IF nullif(ref,'') IS NOT NULL THEN INSERT INTO gridex_utilts_issuer.observed_identifiers VALUES(NEW.id,v.namespace_id,'203',ref,-1);END IF;
  INSERT INTO gridex_utilts_issuer.observed_identifiers SELECT NEW.id,v.namespace_id,'505',own->>'transactionId',(own->>'transactionIndex')::integer FROM jsonb_array_elements(txs) own WHERE nullif(own->>'transactionId','') IS NOT NULL;
 END IF;
 RETURN NEW;
END $$;

REVOKE ALL ON FUNCTION gridex_utilts_issuer.capture_insert_v1() FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1264
--
-- Name: fence_ground_insert_v1(); Type: FUNCTION; Schema: gridex_utilts_issuer; Owner: -
--

CREATE FUNCTION gridex_utilts_issuer.fence_ground_insert_v1() RETURNS trigger
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $_$
DECLARE ns uuid;issuer gridex_utilts_issuer.issuer_versions%rowtype;env text;identity jsonb;admission gridex_utilts_issuer.source_admissions%rowtype;item jsonb;
BEGIN
 IF TG_TABLE_NAME='transport_mandate_versions' THEN SELECT * INTO issuer FROM gridex_utilts_issuer.issuer_versions WHERE id=NEW.issuer_version_id;ns:=issuer.namespace_id;identity:=issuer.legal_identity;
 ELSE ns:=NEW.namespace_id;IF TG_TABLE_NAME='issuer_versions' THEN identity:=NEW.legal_identity;END IF;END IF;
 IF identity IS NOT NULL THEN SELECT environment INTO env FROM gridex_utilts_issuer.namespaces WHERE id=ns;PERFORM gridex_utilts_issuer.lock_legal_identity_v1(env,identity);END IF;
 PERFORM gridex_utilts_issuer.lock_namespace_v1(ns);
 IF TG_TABLE_NAME='revocations' THEN
  IF NOT EXISTS(SELECT FROM gridex_utilts_issuer.issuer_versions v WHERE v.namespace_id=ns AND (v.id=NEW.issuer_version_id OR EXISTS(SELECT FROM gridex_utilts_issuer.transport_mandate_versions m WHERE m.id=NEW.mandate_version_id AND m.issuer_version_id=v.id))) THEN RAISE EXCEPTION 'utilts_issuer_revocation_scope_invalid' USING ERRCODE='23514'; END IF;
 END IF;
 IF TG_TABLE_NAME='source_absence_grounds' THEN
  SELECT * INTO admission FROM gridex_utilts_issuer.source_admissions WHERE source_message_id=NEW.source_message_id;
  IF admission.namespace_id IS NULL OR ROW(NEW.namespace_id,NEW.issuer_version_id,NEW.mandate_version_id,NEW.namespace_epoch,NEW.source_payload_hash)
   IS DISTINCT FROM ROW(admission.namespace_id,admission.issuer_version_id,admission.mandate_version_id,admission.namespace_epoch,admission.source_payload_hash) THEN RAISE EXCEPTION 'utilts_issuer_absence_scope_invalid' USING ERRCODE='23514'; END IF;
  FOR item IN SELECT value FROM jsonb_array_elements(NEW.normalized_issued_identifiers) LOOP
   IF jsonb_typeof(item) IS DISTINCT FROM 'object' OR item-ARRAY['field','reference','originalIssuanceReference','originalSourceSha256','originEvidenceSha256']<>'{}'::jsonb
    OR jsonb_typeof(item->'field') IS DISTINCT FROM 'string' OR coalesce(item->>'field','') NOT IN('203','505') OR jsonb_typeof(item->'reference') IS DISTINCT FROM 'string' OR length(item->>'reference')=0
    OR jsonb_typeof(item->'originalIssuanceReference') IS DISTINCT FROM 'string' OR length(item->>'originalIssuanceReference')=0
    OR jsonb_typeof(item->'originalSourceSha256') IS DISTINCT FROM 'string' OR coalesce(item->>'originalSourceSha256','') !~ '^[a-f0-9]{64}$'
    OR jsonb_typeof(item->'originEvidenceSha256') IS DISTINCT FROM 'string' OR coalesce(item->>'originEvidenceSha256','') !~ '^[a-f0-9]{64}$'
   THEN RAISE EXCEPTION 'utilts_issuer_history_projection_invalid' USING ERRCODE='23514';END IF;
  END LOOP;
 END IF;
 RETURN NEW;
END $_$;

REVOKE ALL ON FUNCTION gridex_utilts_issuer.fence_ground_insert_v1() FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1265
