-- canonical:1267
--
-- Name: read_v1(uuid, uuid); Type: FUNCTION; Schema: gridex_utilts_issuer; Owner: -
--

CREATE FUNCTION gridex_utilts_issuer.read_v1(p_company uuid, p_source uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;a gridex_utilts_issuer.source_admissions%rowtype;grounds gridex_utilts_issuer.source_absence_grounds%rowtype;known boolean;collisions jsonb;reason text;qualified boolean:=false;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_source AND company_id=p_company AND direction='inbound' AND message_family='UTILTS' AND message_standard='edifact';
 IF m.id IS NULL THEN RAISE EXCEPTION 'utilts_issuer_source_scope_required' USING ERRCODE='23514';END IF;
 SELECT * INTO a FROM gridex_utilts_issuer.source_admissions WHERE source_message_id=m.id AND company_id=p_company AND environment=m.environment AND source_payload_hash=encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex');
 reason:=coalesce(a.hold_reason,'ediel_utilts_historical_issuer_basis_unavailable');known:=coalesce(a.message_reference_collision,false);collisions:=coalesce(a.transaction_reference_collisions,'[]');
 IF a.namespace_id IS NOT NULL THEN
  SELECT * INTO grounds FROM gridex_utilts_issuer.source_absence_grounds WHERE source_message_id=a.source_message_id AND source_payload_hash=a.source_payload_hash AND namespace_id=a.namespace_id AND issuer_version_id=a.issuer_version_id AND mandate_version_id=a.mandate_version_id AND namespace_epoch=a.namespace_epoch AND approved_at<=statement_timestamp();
  IF EXISTS(SELECT FROM gridex_utilts_issuer.revocations r WHERE r.namespace_id=a.namespace_id AND (r.issuer_version_id=a.issuer_version_id OR r.mandate_version_id=a.mandate_version_id) AND r.approved_at<=statement_timestamp() AND r.effective_at<=statement_timestamp()) THEN
   -- A revocation holds new positive effects; it cannot rewrite an
   -- authenticated collision observed under the original issuer admission.
   reason:='ediel_utilts_foreign_issuer_basis_revoked';
  ELSE
   IF grounds.source_message_id IS NOT NULL THEN
    known:=known OR EXISTS(SELECT FROM jsonb_array_elements(grounds.normalized_issued_identifiers) x WHERE x->>'field'='203' AND x->>'reference'=a.message_reference);
    SELECT coalesce(jsonb_agg(own ORDER BY (own->>'transactionIndex')::integer),'[]') INTO collisions FROM jsonb_array_elements(a.transactions) own WHERE a.transaction_reference_collisions @>jsonb_build_array(own) OR EXISTS(SELECT FROM jsonb_array_elements(grounds.normalized_issued_identifiers) x WHERE x->>'field'='505' AND x->>'reference'=own->>'transactionId');
    qualified:=true;reason:=NULL;
   END IF;
  END IF;
 END IF;
 RETURN jsonb_build_object('version',1,'companyId',p_company,'environment',m.environment,'sourceMessageId',m.id,'sourcePayloadHash',encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex'),
  'status',CASE WHEN qualified THEN 'qualified' ELSE 'held' END,'authorityVersionId',a.issuer_version_id,'namespaceEpoch',a.namespace_epoch::text,
  'messageReferenceCollision',known,'transactionReferenceCollisions',collisions,'holdReason',reason);
END $$;

REVOKE ALL ON FUNCTION gridex_utilts_issuer.read_v1(uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1268
--
-- Name: require_first_effect_v1(uuid, uuid, text, text, jsonb); Type: FUNCTION; Schema: gridex_utilts_issuer; Owner: -
--

CREATE FUNCTION gridex_utilts_issuer.require_first_effect_v1(p_company uuid, p_source uuid, p_transaction text, p_disposition text, p_issue_codes jsonb) RETURNS void
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_utilts_issuer.source_admissions%rowtype;facts jsonb;
BEGIN
 SELECT * INTO a FROM gridex_utilts_issuer.source_admissions WHERE source_message_id=p_source AND company_id=p_company;
 IF a.namespace_id IS NOT NULL THEN PERFORM gridex_utilts_issuer.lock_namespace_v1(a.namespace_id);END IF;
 facts:=gridex_utilts_issuer.read_v1(p_company,p_source);
 IF p_disposition='accepted' AND (facts->>'status' IS DISTINCT FROM 'qualified' OR facts->'messageReferenceCollision' IS DISTINCT FROM 'false'::jsonb
  OR EXISTS(SELECT FROM jsonb_array_elements(facts->'transactionReferenceCollisions') x WHERE x->>'transactionId'=p_transaction)) THEN RAISE EXCEPTION 'utilts_issuer_identity_first_effect_held' USING ERRCODE='P0U01';END IF;
 IF p_issue_codes ? 'UTILTS_ISSUER_MESSAGE_REFERENCE_DUPLICATE' AND facts->'messageReferenceCollision' IS DISTINCT FROM 'true'::jsonb THEN RAISE EXCEPTION 'utilts_issuer_duplicate_source_proof_required' USING ERRCODE='P0U01';END IF;
 IF p_issue_codes ? 'UTILTS_ISSUER_TRANSACTION_REFERENCE_DUPLICATE' AND NOT EXISTS(SELECT FROM jsonb_array_elements(facts->'transactionReferenceCollisions') x WHERE x->>'transactionId'=p_transaction) THEN RAISE EXCEPTION 'utilts_issuer_duplicate_source_proof_required' USING ERRCODE='P0U01';END IF;
END $$;

REVOKE ALL ON FUNCTION gridex_utilts_issuer.require_first_effect_v1(uuid, uuid, text, text, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1363
--
-- Name: ediel_admit_unattributed_technical_source_v1(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_admit_unattributed_technical_source_v1(p_inbound_email_message_id uuid, p_parse_result_id uuid, p_actor_user_id uuid, p_expected_payload_hash text, p_expected_environment text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.inbound_email_messages%rowtype;p public.inbound_ediel_parse_results%rowtype;
 old_source uuid;source_id uuid;env jsonb;born public.ediel_messages%rowtype;result jsonb;
BEGIN
 PERFORM gridex_unattributed_intake.require_service_v1();
 -- The current production/PostgREST birth path is READ COMMITTED. A lock
 -- cannot refresh an older RR snapshot of ordinary originals; hold instead.
 IF current_setting('transaction_isolation') IS DISTINCT FROM 'read committed' THEN
  RAISE EXCEPTION 'ediel_technical_intake_read_committed_required' USING ERRCODE='25000';END IF;
 -- Serialize the actual physical-original universe, including ordinary writers,
 -- not just this RPC. Use existing authority locks for endpoint/actor changes.
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 LOCK TABLE public.inbound_email_attachments IN SHARE MODE;
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT * INTO m FROM public.inbound_email_messages WHERE id=p_inbound_email_message_id FOR UPDATE;
 SELECT source_message_id INTO old_source FROM gridex_unattributed_intake.technical_births WHERE inbound_email_message_id=m.id;
 IF old_source IS NOT NULL THEN
  result:=gridex_unattributed_intake.receipt_v1(old_source,p_actor_user_id);
  IF result->>'sourcePayloadHash' IS DISTINCT FROM p_expected_payload_hash OR result->>'environment' IS DISTINCT FROM p_expected_environment THEN
   RAISE EXCEPTION 'ediel_technical_intake_replay_scope_conflict' USING ERRCODE='23514';END IF;
  RETURN result;
 END IF;
 SELECT * INTO p FROM public.inbound_ediel_parse_results WHERE id=p_parse_result_id AND inbound_email_message_id=m.id FOR UPDATE;
 PERFORM gridex_unattributed_intake.require_custody_v1(m.id,p.id);
 env:=gridex_ediel_technical_ack.envelope(p.raw_payload);
 IF p_actor_user_id IS NULL OR p.company_id IS NOT NULL OR m.environment IS DISTINCT FROM p_expected_environment
  OR gridex_unattributed_intake.sha_v1(p.raw_payload) IS DISTINCT FROM p_expected_payload_hash THEN
  RAISE EXCEPTION 'ediel_technical_intake_scope_required' USING ERRCODE='23514';END IF;
 IF EXISTS(SELECT FROM public.ediel_messages o CROSS JOIN LATERAL(
  SELECT gridex_ediel_technical_ack.envelope(o.raw_payload)e)x WHERE o.direction='inbound'
  AND x.e->>'environment'=env->>'environment' AND x.e->'sender'=env->'sender' AND x.e->'receiver'=env->'receiver'
  AND x.e->>'applicationReference'=env->>'applicationReference' AND x.e->>'uciReference'=env->>'uciReference') THEN
  RAISE EXCEPTION 'ediel_technical_intake_physical_original_exists' USING ERRCODE='23505';END IF;
 source_id:=gen_random_uuid();
 INSERT INTO gridex_unattributed_intake.technical_births VALUES(source_id,m.id,p.id,p_expected_payload_hash,m.environment,
  m.received_at,env,p.message_family,p.message_code,p_actor_user_id,txid_current());
 INSERT INTO gridex_unattributed_intake.physical_claims VALUES(
  gridex_unattributed_intake.physical_key_v1(env),source_id,txid_current());
 -- NULL here is unresolved legal staging, not the mailbox's technical owner.
 UPDATE public.inbound_email_messages SET company_id=NULL WHERE id=m.id;
 INSERT INTO public.ediel_messages(id,company_id,resolved_company_id,direction,message_standard,message_family,message_code,
  environment,test_flag,status,transport_type,inbound_email_message_id,mailbox_message_id,message_received_at,raw_payload,
  immutable_payload_hash,sender_ediel_id,sender_sub_address,receiver_ediel_id,receiver_sub_address,
  parsed_unb_sender_ediel_id,parsed_unb_receiver_ediel_id,interchange_reference,transaction_reference,application_reference,
  parsed_payload,validation_report,tenant_resolution_status,business_match_status,processing_status,created_by)
 VALUES(source_id,NULL,NULL,'inbound','edifact',p.message_family,p.message_code,m.environment,
  CASE WHEN m.environment='test' THEN 1 ELSE 0 END,'received','imap',m.id,m.id::text,m.received_at,p.raw_payload,
  p_expected_payload_hash,p.sender_ediel_id,p.sender_sub_address,p.receiver_ediel_id,p.receiver_sub_address,
  p.sender_ediel_id,p.receiver_ediel_id,p.interchange_reference,p.transaction_reference,p.application_reference,
  p.parsed_payload,jsonb_build_object('status','routing_unresolved_manual_review','authorizesBusinessEffect',false),
  'tenant_unresolved','blocked','tenant_unresolved',p_actor_user_id) RETURNING * INTO born;
 result:=gridex_unattributed_intake.receipt_v1(born.id,p_actor_user_id);
 IF result IS NULL THEN RAISE EXCEPTION 'ediel_technical_intake_birth_required';END IF;
 RETURN result;
END $$;

REVOKE ALL ON FUNCTION public.ediel_admit_unattributed_technical_source_v1(uuid, uuid, uuid, text, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1364
--
-- Name: ediel_advance_permission_deadlines_v1(uuid, uuid, integer); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_advance_permission_deadlines_v1(p_actor_user_id uuid, p_company_id uuid DEFAULT NULL::uuid, p_limit integer DEFAULT 100) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE pid uuid;p public.metering_permissions%rowtype;tr gridex_received_sources.permission_effect_transitions_v1%rowtype;changed integer:=0;rows_changed integer;source_ids uuid[];
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'permission_source_service_required' USING ERRCODE='42501';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') THEN RAISE EXCEPTION 'permission_execution_actor_unqualified' USING ERRCODE='42501';END IF;
 FOR pid IN SELECT x.id FROM public.metering_permissions x WHERE(p_company_id IS NULL OR x.company_id=p_company_id) AND x.inbound_z15_message_id IS NOT NULL AND x.status IN('active','approved','partially_approved','z14_received') AND EXISTS(SELECT FROM public.metering_permission_sites s WHERE s.company_id=x.company_id AND s.metering_permission_id=x.id AND s.status IN('approved','active') AND s.permission_end_at<=now()) ORDER BY x.id LIMIT least(greatest(coalesce(p_limit,100),1),200) LOOP
  SELECT array_agg(DISTINCT x.source_message_id ORDER BY x.source_message_id) INTO source_ids FROM gridex_received_sources.permission_effect_transitions_v1 x WHERE x.permission_id=pid;
  PERFORM m.id FROM public.ediel_messages m WHERE m.id=ANY(source_ids) ORDER BY m.id FOR UPDATE;
  SELECT * INTO p FROM public.metering_permissions WHERE id=pid FOR UPDATE SKIP LOCKED;
  IF p.id IS NULL THEN CONTINUE;END IF;
  PERFORM cm.id FROM public.company_memberships cm WHERE cm.company_id=p.company_id AND cm.user_id=p_actor_user_id FOR SHARE;
  IF public.gridex_actor_has_company_permission(p_actor_user_id,p.company_id,'metering.write') IS NOT TRUE OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p.company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL) THEN CONTINUE;END IF;
  PERFORM s.id FROM public.metering_permission_sites s WHERE s.company_id=p.company_id AND s.metering_permission_id=p.id ORDER BY s.id FOR UPDATE;
  IF public.ediel_permission_source_is_current_v1(p.company_id,p.id,coalesce(p.inbound_z14_message_id,p.source_z14_message_id)) IS NOT TRUE THEN CONTINUE;END IF;
  SELECT * INTO tr FROM gridex_received_sources.permission_effect_transitions_v1 x WHERE x.company_id=p.company_id AND x.permission_id=p.id AND(x.resulting_state->>'market_state_version')::bigint=p.market_state_version;
  UPDATE public.metering_permission_sites s SET status='ended',updated_at=now() FROM jsonb_array_elements(tr.resulting_sites)own WHERE s.company_id=p.company_id AND s.metering_permission_id=p.id AND own->>'id'=s.id::text AND s.status IN('approved','active') AND own->>'status' IN('approved','active') AND s.permission_end_at IS NOT NULL AND s.permission_end_at=(own->>'permission_end_at')::timestamptz AND s.permission_end_at<=now();
  GET DIAGNOSTICS rows_changed=ROW_COUNT;changed:=changed+rows_changed;
  IF NOT EXISTS(SELECT FROM public.metering_permission_sites s WHERE s.company_id=p.company_id AND s.metering_permission_id=p.id AND s.status IN('approved','active')) THEN UPDATE public.metering_permissions SET status='ended',updated_at=now(),updated_by=p_actor_user_id WHERE id=p.id AND company_id=p.company_id AND market_state_version=p.market_state_version;END IF;
 END LOOP;
 RETURN jsonb_build_object('updated',changed);
END$$;

REVOKE ALL ON FUNCTION public.ediel_advance_permission_deadlines_v1(uuid, uuid, integer) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1366
--
-- Name: ediel_ai_bi_processing_decision_v2(uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
