-- canonical:1400
--
-- Name: ediel_bind_switch_original_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_bind_switch_original_v1(p_company_id uuid, p_switch_id uuid, p_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;result jsonb;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_outbound_v1();SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF m.message_family='PRODAT' AND m.message_code='Z03' AND gridex_bilateral_prodat.outbound_required_v1(m.raw_payload) IS TRUE THEN
  result:=gridex_bilateral_prodat.bind_switch_h_v1(p_company_id,p_switch_id,p_message_id,p_actor_user_id);
  -- Same first-effect bindings as the national original: the signed requested
  -- method and the BRP source are bound with the H original, so the transport
  -- guards requalify them before every send.
  IF result->>'status'='bound' AND result->>'idempotent' IS DISTINCT FROM 'true' THEN
   PERFORM gridex_received_sources.bind_switch_contract_request_v1(p_company_id,p_message_id,p_actor_user_id);
   PERFORM gridex_received_sources.bind_switch_brp_source_v1(p_company_id,p_message_id,p_actor_user_id);
  END IF;
  RETURN result;
 END IF;
 RETURN gridex_bilateral_prodat.bind_switch_before_bilateral_v1(p_company_id,p_switch_id,p_message_id,p_actor_user_id);
END$$;

REVOKE ALL ON FUNCTION public.ediel_bind_switch_original_v1(uuid, uuid, uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1401
--
-- Name: ediel_brp_change_message_basis_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_brp_change_message_basis_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE o gridex_brp_changes.origins%rowtype;
b jsonb;

BEGIN PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
PERFORM m.user_id FROM public.company_memberships m WHERE m.company_id=p_company_id
  AND m.user_id=p_actor_user_id FOR SHARE;
IF p_company_id IS NULL
  OR p_actor_user_id IS NULL
  OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id
  AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=p_company_id
  AND m.user_id=p_actor_user_id
  AND m.status='active'
  AND m.is_active
  AND m.accepted_at IS NOT NULL)
  OR (public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel.send') OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.send')) IS NOT TRUE THEN RAISE EXCEPTION 'brp_message_actor_forbidden' USING ERRCODE='42501';
END IF;
SELECT * INTO o FROM gridex_brp_changes.origins WHERE company_id=p_company_id
  AND message_id=p_message_id;
IF NOT FOUND THEN RETURN NULL;
END IF;
b:=gridex_brp_changes.context_v1(o.company_id,o.event_id,o.actor_user_id);
IF b IS DISTINCT FROM o.basis THEN RETURN jsonb_build_object('status','held','missing',ARRAY['brp_change_current_source_changed']);
END IF;
PERFORM public.ediel_require_brp_change_source_current_v1(p_company_id,p_message_id);
RETURN jsonb_build_object('basis',b,'intentId',o.intent_id,'actorUserId',o.actor_user_id);
END$$;

REVOKE ALL ON FUNCTION public.ediel_brp_change_message_basis_v1(uuid, uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

