--
-- Name: ediel_brp_change_source_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_brp_change_source_v1(p_company_id uuid, p_event_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$BEGIN RETURN gridex_brp_changes.context_v1(p_company_id,p_event_id,p_actor_user_id);
END$$;

