-- canonical:1475
--
-- Name: ediel_prepare_customer_masterdata_v1(uuid, uuid, uuid, timestamp with time zone, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_prepare_customer_masterdata_v1(p_company_id uuid, p_customer_id uuid, p_actor_user_id uuid, p_as_of timestamp with time zone, p_environment text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE b jsonb;prep gridex_customer_masterdata.preparations%rowtype;BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'customer_masterdata_service_required' USING ERRCODE='42501';END IF;
 b:=gridex_customer_masterdata.basis_v1(p_company_id,p_customer_id,p_actor_user_id,p_as_of,p_environment,'prepare');IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 INSERT INTO gridex_customer_masterdata.preparations(company_id,customer_id,environment,as_of,observed_at,actor_user_id,basis,basis_hash) VALUES(p_company_id,p_customer_id,p_environment,p_as_of,statement_timestamp(),p_actor_user_id,b,encode(sha256(convert_to(b::text,'UTF8')),'hex')) ON CONFLICT DO NOTHING RETURNING * INTO prep;
 IF prep.id IS NULL THEN SELECT * INTO STRICT prep FROM gridex_customer_masterdata.preparations WHERE company_id=p_company_id AND customer_id=p_customer_id AND environment IS NOT DISTINCT FROM p_environment AND as_of=p_as_of AND actor_user_id=p_actor_user_id AND basis=b AND recovery_operation_id IS NULL AND cancellation_origin_id IS NULL;END IF;
 RETURN (b-'sourceProof')||jsonb_build_object('sourceContextId',prep.id);
END$$;

REVOKE ALL ON FUNCTION public.ediel_prepare_customer_masterdata_v1(uuid, uuid, uuid, timestamp with time zone, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1476
--
-- Name: ediel_prepare_duplicate_103_response_v1(uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_prepare_duplicate_103_response_v1(p_company_id uuid, p_source_message_id uuid, p_inbound_email_message_id uuid, p_actor_user_id uuid, p_smtp jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source jsonb;i gridex_ediel_duplicate_responses.intents%rowtype;existing jsonb;route jsonb;BEGIN
 PERFORM gridex_prodat_object_batch.require_service_v1();source:=gridex_ediel_duplicate_responses.source_v1(p_company_id,p_source_message_id,p_inbound_email_message_id,p_actor_user_id);
 SELECT * INTO i FROM gridex_ediel_duplicate_responses.intents WHERE reception_id=(source->>'receptionId')::uuid;
 existing:=gridex_ediel_duplicate_responses.read_result_v1(i);IF existing IS NOT NULL THEN
  PERFORM gridex_ediel_duplicate_responses.source_v1(p_company_id,p_source_message_id,p_inbound_email_message_id,p_actor_user_id);
  RETURN existing||jsonb_build_object('replayed',true);END IF;
 PERFORM public.ediel_require_source_bytes_available_v1(p_company_id,p_source_message_id);
 IF p_smtp IS NULL THEN
  IF gridex_ediel_duplicate_responses.source_v1(p_company_id,p_source_message_id,p_inbound_email_message_id,p_actor_user_id) IS DISTINCT FROM source THEN RAISE EXCEPTION 'ediel_duplicate_current_source_changed';END IF;
  RETURN source||jsonb_build_object('status','qualified','route',NULL,'serverDate203',to_char(clock_timestamp() AT TIME ZONE 'Etc/GMT-1','YYYYMMDDHH24MI'));END IF;
 route:=gridex_ediel_technical_ack.select_configured_reply_route_v2(p_company_id,source->'technicalBasis','APERAK',p_smtp->>'from',p_smtp->>'host',(p_smtp->>'port')::int);
 IF gridex_ediel_duplicate_responses.source_v1(p_company_id,p_source_message_id,p_inbound_email_message_id,p_actor_user_id) IS DISTINCT FROM source THEN RAISE EXCEPTION 'ediel_duplicate_current_source_changed';END IF;
 RETURN source||jsonb_build_object('status','qualified','route',route,'serverDate203',to_char(clock_timestamp() AT TIME ZONE 'Etc/GMT-1','YYYYMMDDHH24MI'));
END $$;

REVOKE ALL ON FUNCTION public.ediel_prepare_duplicate_103_response_v1(uuid, uuid, uuid, uuid, jsonb) FROM PUBLIC,anon,authenticated,service_role;

