    LANGUAGE sql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$ SELECT EXISTS(SELECT FROM gridex_ediel_retention.process_tombstones WHERE company_id=p_company_id AND retention_class=p_retention_class AND target_id=p_target_id AND source_hash=p_source_hash) $$;

