-- canonical:1507
--
-- Name: ediel_queue_prodat_retry_v1(uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_queue_prodat_retry_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid, p_operation_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;op gridex_received_sources.prodat_recovery_operations%rowtype;b gridex_received_sources.prodat_recovery_outboxes%rowtype;o public.ediel_outbox%rowtype;assessment jsonb;queued_id uuid;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.ediel_messages IN SHARE ROW EXCLUSIVE MODE;
 PERFORM 1 FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR UPDATE;
 PERFORM gridex_received_sources.require_recovery_execution_actor_v1(p_company_id,p_actor_user_id,'send');
 SELECT * INTO STRICT m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR UPDATE;
 SELECT * INTO STRICT op FROM gridex_received_sources.prodat_recovery_operations WHERE id=p_operation_id AND company_id=p_company_id AND original_message_id=m.id AND kind='verified_transfer_loss';
 IF m.environment IS DISTINCT FROM op.environment OR m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' OR op.original_payload_hash IS DISTINCT FROM m.immutable_payload_hash OR op.original_payload_hash IS DISTINCT FROM encode(sha256(convert_to(m.raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'prodat_retry_queue_source_changed';END IF;
 SELECT * INTO b FROM gridex_received_sources.prodat_recovery_outboxes WHERE operation_id=op.id;
 IF FOUND THEN
  SELECT * INTO STRICT o FROM public.ediel_outbox WHERE id=b.outbox_id AND company_id=p_company_id AND ediel_message_id=m.id AND environment=m.environment;
  RETURN jsonb_build_object('status','existing','outboxId',o.id,'operationId',op.id,'previousAttemptId',op.previous_attempt_id);
 END IF;
 assessment:=gridex_received_sources.require_established_recovery_source_v1(p_company_id,op.id);
 IF assessment->>'status' IS DISTINCT FROM 'authorized' OR NOT EXISTS(SELECT FROM gridex_ediel_transport.reservations r WHERE r.message_id=m.id AND r.attempt_id=op.previous_attempt_id AND r.state='observed') THEN RAISE EXCEPTION 'prodat_retry_queue_actual_negative_required';END IF;
 INSERT INTO public.ediel_outbox(company_id,ediel_message_id,status,priority,lock_key,message_family,message_code,environment,route_profile_id,payload,queued_at,created_by,updated_by)
 VALUES(m.company_id,m.id,'queued',50,'prodat-loss-retry:'||op.id,'PRODAT',m.message_code,m.environment,m.route_profile_id,jsonb_build_object('recoveryOperationId',op.id,'previousAttemptId',op.previous_attempt_id),now(),p_actor_user_id,p_actor_user_id) ON CONFLICT(lock_key) DO NOTHING RETURNING id INTO queued_id;
 IF queued_id IS NULL THEN RAISE EXCEPTION 'prodat_retry_queue_unbound_collision';END IF;
 INSERT INTO gridex_received_sources.prodat_recovery_outboxes(operation_id,outbox_id,actor_user_id) VALUES(op.id,queued_id,p_actor_user_id);
 RETURN jsonb_build_object('status','queued','outboxId',queued_id,'operationId',op.id,'previousAttemptId',op.previous_attempt_id);
END $$;

REVOKE ALL ON FUNCTION public.ediel_queue_prodat_retry_v1(uuid, uuid, uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1508
--
-- Name: ediel_read_actor_registry_batch_v1(uuid, text, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_actor_registry_batch_v1(p_actor_user_id uuid, p_source_base64 text, p_source_sha256 text, p_source_kind text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE prior gridex_registry_import.batches%rowtype;source_bytes bytea;source_hash text;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 LOCK TABLE public.platform_market_actors,public.platform_actor_roles,public.platform_actor_routes,public.platform_actor_certificates,gridex_registry_import.market_current,gridex_registry_import.route_market_current IN SHARE MODE;
 IF p_actor_user_id IS NULL OR public.canonical_actor_is_platform_admin(p_actor_user_id) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_registry_platform_actor_required' USING ERRCODE='42501';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM u.id FROM auth.users u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM au.user_id FROM public.admin_users au WHERE au.user_id=p_actor_user_id FOR SHARE;
 PERFORM ur.id FROM public.user_roles ur WHERE ur.user_id=p_actor_user_id FOR SHARE;
 IF public.canonical_actor_is_platform_admin(p_actor_user_id) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_registry_platform_actor_revoked' USING ERRCODE='42501';END IF;
 source_bytes:=decode(p_source_base64,'base64');
 IF p_source_base64 IS NULL OR octet_length(source_bytes) NOT BETWEEN 1 AND 16777216 OR (p_source_kind IN('companies_xml','companies_txt','csv')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_registry_source_shape_required';END IF;
 source_hash:=encode(sha256(source_bytes),'hex');
 IF p_source_sha256 IS DISTINCT FROM source_hash THEN RAISE EXCEPTION 'ediel_registry_exact_source_hash_required';END IF;
 SELECT * INTO prior FROM gridex_registry_import.batches WHERE source_sha256=source_hash FOR SHARE;
 IF NOT FOUND THEN RETURN NULL;END IF;
 IF prior.source_bytes IS DISTINCT FROM source_bytes OR prior.source_kind IS DISTINCT FROM p_source_kind THEN RAISE EXCEPTION 'ediel_registry_exact_original_source_required';END IF;
 RETURN prior.result||jsonb_build_object('reusedExistingRun',true);
END $$;

REVOKE ALL ON FUNCTION public.ediel_read_actor_registry_batch_v1(uuid, text, text, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1509
--
-- Name: ediel_read_ai_purpose_source_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_ai_purpose_source_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_include_bytes boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_ai_purpose_sources.artifacts%rowtype;r gridex_ai_purpose_sources.reviews%rowtype;result jsonb;basis jsonb;state text;missing jsonb;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'ai_purpose_service_required' USING ERRCODE='42501';END IF;
 IF gridex_ai_purpose_sources.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'ai_purpose_read_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO a FROM gridex_ai_purpose_sources.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR SHARE;IF NOT FOUND THEN RAISE EXCEPTION 'ai_purpose_artifact_unavailable';END IF;
 SELECT * INTO r FROM gridex_ai_purpose_sources.reviews WHERE artifact_id=a.id ORDER BY reviewed_at DESC,id DESC LIMIT 1 FOR SHARE;basis:=gridex_ai_purpose_sources.current_v1(a);
 state:=CASE WHEN basis IS NOT NULL THEN 'authorized' WHEN r.decision='rejected' THEN 'rejected' WHEN r.id IS NOT NULL THEN 'held' ELSE 'archived' END;missing:=CASE WHEN basis IS NOT NULL THEN '[]'::jsonb WHEN r.id IS NOT NULL AND r.decision<>'approved' THEN r.missing ELSE '["current_purpose_authority_missing_or_revoked"]'::jsonb END;
 result:=a.claims-ARRAY['companyId','legalActorId','legalSupplierEdielId','legalCompany','sourceProfile','retentionClass'];result:=result||jsonb_build_object('artifactId',a.id,'sourceReference',a.source_reference,'sourceVersion',a.source_version,'sourceHash',a.source_hash,'claimsHash',a.claims_hash,'mimeType','application/pdf','byteLength',octet_length(a.source_bytes),'status',state,'missing',missing);
 IF p_include_bytes THEN result:=result||jsonb_build_object('bytesBase64',replace(encode(a.source_bytes,'base64'),E'\n',''));END IF;RETURN result;
END$$;

REVOKE ALL ON FUNCTION public.ediel_read_ai_purpose_source_v1(uuid, uuid, uuid, boolean) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1510
--
-- Name: ediel_read_beneficiary_export_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_beneficiary_export_v1(p_beneficiary_company_id uuid, p_actor_user_id uuid, p_job_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE j gridex_ediel_exports.jobs%rowtype; current_page jsonb; retained jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 SELECT * INTO j FROM gridex_ediel_exports.jobs WHERE id=p_job_id AND beneficiary_company_id=p_beneficiary_company_id AND actor_user_id=p_actor_user_id FOR SHARE;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_export_not_found' USING ERRCODE='42501'; END IF;
 -- Complete current authority and immutable source proof again; no earlier
 -- job completion, receipt or payload authorizes this read.
 current_page:=public.ediel_beneficiary_series_page_v1(j.beneficiary_company_id,j.actor_user_id,j.grant_id,j.expected_grant_version,j.purpose,j.series_id,j.fields,j.start_at,j.end_at,j.page_limit,j.after_at,j.after_id);
 IF j.status='completed' THEN
  IF j.result_expires_at<=clock_timestamp() THEN RAISE EXCEPTION 'ediel_export_expired'; END IF;
  SELECT page INTO STRICT retained FROM gridex_ediel_exports.results WHERE job_id=j.id AND beneficiary_company_id=j.beneficiary_company_id AND actor_user_id=j.actor_user_id AND expires_at>clock_timestamp() FOR SHARE;
  IF retained IS DISTINCT FROM current_page THEN RAISE EXCEPTION 'ediel_export_result_basis_changed'; END IF;
 END IF;
 RETURN jsonb_build_object('jobId',j.id,'status',j.status,'page',retained);
END $$;

REVOKE ALL ON FUNCTION public.ediel_read_beneficiary_export_v1(uuid, uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1511
--
-- Name: ediel_read_bilateral_customer_source_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_bilateral_customer_source_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_include_bytes boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_bilateral_customer_sources.artifacts%rowtype;r gridex_bilateral_customer_sources.reviews%rowtype;status text;missing jsonb;result jsonb;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM id FROM public.ediel_messages WHERE company_id=p_company_id AND id=(SELECT source_message_id FROM gridex_bilateral_customer_sources.artifacts WHERE id=p_artifact_id AND company_id=p_company_id) FOR SHARE;

 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'bilateral_customer_source_service_required' USING ERRCODE='42501';END IF;
 IF gridex_bilateral_customer_sources.classified_actor_wallclock_v1(p_company_id,p_actor_user_id,'read','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_customer_source_read_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT a FROM gridex_bilateral_customer_sources.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR SHARE;SELECT * INTO r FROM gridex_bilateral_customer_sources.reviews WHERE artifact_id=a.id ORDER BY reviewed_at DESC,id DESC LIMIT 1 FOR SHARE;
 IF gridex_bilateral_customer_sources.classified_independent_wallclock_v1(a) IS NOT NULL THEN status:='authorized';missing:='[]';ELSIF r.decision='rejected' THEN status:='rejected';missing:=r.missing;ELSIF r.id IS NOT NULL THEN status:='held';missing:=CASE WHEN r.decision='approved' THEN '["current_bilateral_source_authority_unavailable"]'::jsonb ELSE r.missing END;ELSE status:='archived';missing:='["separate_bilateral_source_review_required"]';END IF;
 result:=jsonb_build_object('artifactId',a.id,'sourceMessageId',a.source_message_id,'agreementId',a.agreement_id,'supplyPeriodId',a.supply_period_id,'contractId',a.contract_id,'effectiveAt',a.claims->'effectiveAt','sourceReference',a.source_reference,'sourceVersion',a.source_version,'sourceHash',a.source_hash,'claimsHash',a.claims_hash,'mimeType','application/pdf','byteLength',octet_length(a.source_bytes),'status',status,'missing',missing);
 IF p_include_bytes THEN result:=result||jsonb_build_object('bytesBase64',replace(encode(a.source_bytes,'base64'),E'\n',''));END IF; IF gridex_bilateral_customer_sources.classified_actor_wallclock_v1(p_company_id,p_actor_user_id,'read','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_customer_post_wait_actor_forbidden' USING ERRCODE='42501';END IF; RETURN result;
END$$;

