-- canonical:1513
--
-- Name: ediel_read_bilateral_prodat_ground_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_bilateral_prodat_ground_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_include_bytes boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE a gridex_bilateral_prodat.artifacts%rowtype;r gridex_bilateral_prodat.reviews%rowtype;o gridex_bilateral_prodat.origins%rowtype;out jsonb;current boolean:=false;
BEGIN
 IF gridex_bilateral_prodat.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_prodat_artifact_read_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT a FROM gridex_bilateral_prodat.artifacts WHERE id=p_artifact_id AND company_id=p_company_id;
 SELECT * INTO r FROM gridex_bilateral_prodat.reviews WHERE company_id=p_company_id AND artifact_id=a.id ORDER BY reviewed_at DESC,id DESC LIMIT 1;SELECT * INTO o FROM gridex_bilateral_prodat.origins WHERE company_id=p_company_id AND artifact_id=a.id;
 IF o.ground_id IS NOT NULL THEN current:=gridex_bilateral_prodat.ground_current_v1(o.ground_id,p_company_id,greatest(now(),(a.scope->>'validFrom')::timestamptz));END IF;
 out:=jsonb_build_object('status',CASE WHEN current THEN 'authorized' WHEN o.ground_id IS NOT NULL THEN 'held' WHEN r.id IS NOT NULL THEN r.decision ELSE 'archived' END,'companyId',p_company_id,'artifactId',a.id,'profileVersionId',o.ground_id,'sourceHash',a.source_hash,'scopeHash',a.scope_hash,'scope',a.scope,'sourceReference',a.source_reference,'sourceVersion',a.source_version,'mimeType',a.mime_type,'byteLength',octet_length(a.source_bytes),'missing',CASE WHEN current THEN '[]'::jsonb WHEN o.ground_id IS NOT NULL THEN '["actual_current_qualified_ground"]'::jsonb ELSE coalesce(r.missing,'["separate_qualified_source_review_required"]') END);
 IF p_include_bytes THEN out:=out||jsonb_build_object('bytesBase64',encode(a.source_bytes,'base64'));END IF;RETURN out;
END$$;

REVOKE ALL ON FUNCTION public.ediel_read_bilateral_prodat_ground_v1(uuid, uuid, uuid, boolean) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1514
--
-- Name: ediel_read_bilateral_prodat_outbound_original_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_bilateral_prodat_outbound_original_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE m public.ediel_messages%rowtype;cap jsonb;
BEGIN
 PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF m.id IS NULL OR gridex_bilateral_prodat.outbound_required_v1(m.raw_payload) IS NOT TRUE THEN RETURN NULL;END IF;
 PERFORM public.ediel_require_source_bytes_available_v1(p_company_id,p_message_id);PERFORM gridex_bilateral_prodat.require_outbound_original_v1(m,false);
 SELECT capability INTO cap FROM gridex_bilateral_prodat.outbound_operations WHERE message_id=m.id AND company_id=m.company_id;RETURN cap;
END$$;

REVOKE ALL ON FUNCTION public.ediel_read_bilateral_prodat_outbound_original_v1(uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1515
--
-- Name: ediel_read_bilateral_prodat_outbound_original_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_bilateral_prodat_outbound_original_v1(p_company_id uuid, p_actor_user_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE m public.ediel_messages%rowtype;cap jsonb;BEGIN
 IF gridex_bilateral_prodat.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_prodat_outbound_current_reader_required' USING ERRCODE='42501';END IF;
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR SHARE;
 IF m.id IS NULL OR gridex_bilateral_prodat.outbound_required_v1(m.raw_payload) IS NOT TRUE THEN IF gridex_bilateral_prodat.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_prodat_outbound_terminal_reader_required' USING ERRCODE='42501';END IF;RETURN NULL;END IF;
 PERFORM public.ediel_require_source_bytes_available_v1(m.company_id,m.id);PERFORM gridex_bilateral_prodat.require_recorded_outbound_source_current_v1(m);
 SELECT capability INTO cap FROM gridex_bilateral_prodat.outbound_operations WHERE message_id=m.id AND company_id=m.company_id;
 IF gridex_bilateral_prodat.actor_v1(p_company_id,p_actor_user_id,'read') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_prodat_outbound_terminal_reader_required' USING ERRCODE='42501';END IF;
 RETURN cap||jsonb_build_object('originalActorUserId',cap->>'actorUserId','actorUserId',p_actor_user_id);
END$$;

REVOKE ALL ON FUNCTION public.ediel_read_bilateral_prodat_outbound_original_v1(uuid, uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1516
--
-- Name: ediel_read_blob_retention_decision_v1(uuid, uuid, uuid, boolean); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_blob_retention_decision_v1(p_company_id uuid, p_actor_user_id uuid, p_decision_id uuid, p_include_document boolean DEFAULT false) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE d gridex_ediel_retention.blob_decisions%rowtype;t gridex_ediel_retention.blob_tombstones%rowtype;permission text;reviews jsonb;current_review uuid;basis jsonb;physical boolean:=false;
BEGIN
 -- actor_v1 takes the authorization registry locks. Never trust a browser's
 -- selected class, actor, reviewer outcome or prior HTTP authorization check.
 IF NOT p_include_document AND gridex_ediel_retention.record_permission_v1(p_company_id,p_actor_user_id,'__read_scope__') IS TRUE THEN permission:='ediel.retention.read';
 ELSIF gridex_ediel_retention.permission_v1(p_company_id,p_actor_user_id,'ediel.retention.review') IS TRUE THEN permission:='ediel.retention.review';
 ELSIF NOT p_include_document AND gridex_ediel_retention.permission_v1(p_company_id,p_actor_user_id,'ediel.retention.submit') IS TRUE THEN permission:='ediel.retention.submit';
 ELSIF NOT p_include_document AND gridex_ediel_retention.permission_v1(p_company_id,p_actor_user_id,'ediel.retention.purge') IS TRUE THEN permission:='ediel.retention.purge';
 ELSE RAISE EXCEPTION 'retention_current_read_grant_required' USING ERRCODE='42501';END IF;
 IF permission='ediel.retention.read' THEN PERFORM gridex_ediel_retention.record_read_actor_v1(p_company_id,p_actor_user_id);ELSE PERFORM gridex_ediel_retention.actor_v1(p_company_id,p_actor_user_id,permission);END IF;
 SELECT * INTO STRICT d FROM gridex_ediel_retention.blob_decisions WHERE company_id=p_company_id AND id=p_decision_id FOR SHARE;
 IF gridex_ediel_retention.class_permission_v1(p_company_id,p_actor_user_id,d.retention_class) IS NOT TRUE THEN RAISE EXCEPTION 'retention_current_class_grant_required' USING ERRCODE='42501';END IF;
 IF encode(sha256(d.document_bytes),'hex') IS DISTINCT FROM d.document_hash THEN RAISE EXCEPTION 'retention_actual_document_hash_required';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('reviewId',r.id,'actorUserId',r.actor_user_id,'outcome',r.outcome,'reason',r.reason,'createdAt',r.created_at) ORDER BY r.created_at,r.id),'[]') INTO reviews FROM gridex_ediel_retention.blob_reviews r WHERE r.decision_id=d.id;
 SELECT * INTO t FROM gridex_ediel_retention.blob_tombstones WHERE company_id=p_company_id AND decision_id=d.id AND retention_class=d.retention_class AND target_id=d.target_id FOR SHARE;
 current_review:=gridex_ediel_retention.blob_current_v1(d);
 IF t.target_id IS NULL AND current_review IS NOT NULL THEN
  BEGIN
   basis:=gridex_ediel_retention.blob_basis_v1(p_company_id,d.retention_class,d.target_id);
   IF basis->>'targetHash' IS DISTINCT FROM d.target_hash OR basis->>'sourceHash' IS DISTINCT FROM d.source_hash THEN current_review:=NULL;END IF;
  EXCEPTION WHEN no_data_found OR raise_exception THEN current_review:=NULL;END;
 ELSIF t.target_id IS NOT NULL THEN current_review:=NULL;END IF;
 IF t.target_id IS NOT NULL THEN
  IF d.retention_class='transport_raw_mime_bytes' THEN
   physical:=EXISTS(SELECT FROM gridex_ediel_retention.blob_events WHERE retention_class=d.retention_class AND target_id=d.target_id AND kind='physical_bytes_removed');
  ELSE
   physical:=EXISTS(SELECT FROM gridex_received_sources.sources s JOIN public.ediel_messages m ON m.company_id=s.company_id AND m.id=s.source_message_id WHERE s.company_id=p_company_id AND s.source_message_id=d.message_id AND s.raw_payload IS NULL AND s.retention_purged_at IS NOT NULL AND m.raw_payload IS NULL AND m.parsed_payload='{}'::jsonb AND m.validation_report='{}'::jsonb AND m.metadata='{}'::jsonb)
    AND NOT EXISTS(SELECT FROM public.ediel_message_payloads p WHERE p.company_id=p_company_id AND p.ediel_message_id=d.message_id AND (p.raw_payload IS NOT NULL OR p.encrypted_payload IS NOT NULL));
  END IF;
 END IF;
 RETURN jsonb_build_object('companyId',d.company_id,'decisionId',d.id,'retentionClass',d.retention_class,'targetId',d.target_id,'messageId',d.message_id,'sourceHash',d.source_hash,'targetHash',d.target_hash,'documentHash',d.document_hash,'documentByteLength',octet_length(d.document_bytes),'submittedBy',d.submitted_by,'createdAt',d.created_at,
 'issuerQualified',gridex_ediel_retention.blob_receipt_v1(d) IS NOT NULL,'currentQualified',current_review IS NOT NULL,'revoked',EXISTS(SELECT FROM gridex_ediel_retention.blob_revocations WHERE decision_id=d.id),'reviews',reviews,
 'purge',CASE WHEN t.target_id IS NULL THEN NULL ELSE jsonb_build_object('createdAt',t.created_at,'byteLength',t.byte_length,'physicalBytesRemoved',physical) END,
 'documentBase64',CASE WHEN p_include_document THEN replace(encode(d.document_bytes,'base64'),E'\n','') ELSE NULL END);
END$$;

REVOKE ALL ON FUNCTION public.ediel_read_blob_retention_decision_v1(uuid, uuid, uuid, boolean) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1517
--
-- Name: ediel_read_business_ack_status_v1(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_read_business_ack_status_v1(p_source_message_id uuid, p_actor_user_id uuid, p_company_id uuid DEFAULT NULL::uuid, p_ack_family text DEFAULT NULL::text, p_environment text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;company uuid;basis jsonb;entry jsonb;
 family text;items jsonb:='[]';held uuid[]:='{}';correlation record;snapshot jsonb;receipt jsonb;qualified jsonb;
 latest_capture timestamptz;latest_ack uuid;ambiguous_summary boolean:=false;BEGIN
 PERFORM gridex_prodat_object_batch.require_service_v1();
 IF p_source_message_id IS NULL OR p_actor_user_id IS NULL
  OR (p_ack_family IS NOT NULL AND p_ack_family NOT IN('CONTRL','APERAK','UTILTS_ERR'))
  THEN RAISE EXCEPTION 'ediel_business_ack_status_scope_required' USING ERRCODE='22023';END IF;
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 SELECT * INTO source FROM public.ediel_messages WHERE id=p_source_message_id AND direction IN('inbound','outbound') FOR SHARE;
 IF source.id IS NULL OR(p_environment IS NOT NULL AND source.environment IS DISTINCT FROM p_environment)
  THEN RAISE EXCEPTION 'ediel_business_ack_status_source_required';END IF;
 -- A null public company is resolved only by the actual native source owner.
 IF source.direction='inbound' THEN
  basis:=gridex_ack_authority.read_outbound_originals_v1(source.id,coalesce(p_ack_family,'APERAK'));
 END IF;
 company:=coalesce(source.company_id,(basis->>'companyId')::uuid);
 IF company IS NULL OR(p_company_id IS NOT NULL AND p_company_id IS DISTINCT FROM company)
  THEN RAISE EXCEPTION 'ediel_business_ack_status_tenant_required' USING ERRCODE='42501';END IF;
 IF NOT EXISTS(SELECT FROM public.user_profiles WHERE id=p_actor_user_id AND user_status='active')
  OR NOT EXISTS(SELECT FROM public.companies WHERE id=company AND is_active AND status='active')
  OR public.gridex_actor_has_company_permission(p_actor_user_id,company,'communication.read') IS NOT TRUE
  THEN RAISE EXCEPTION 'ediel_business_ack_status_reader_required' USING ERRCODE='42501';END IF;
 IF source.direction='inbound' THEN
 FOREACH family IN ARRAY CASE WHEN p_ack_family IS NULL THEN ARRAY['CONTRL','APERAK','UTILTS_ERR'] ELSE ARRAY[p_ack_family] END LOOP
  PERFORM gridex_ediel_duplicate_responses.read_business_original_v1(company,source.environment,source.id,p_actor_user_id,family,NULL,'read');
  basis:=gridex_ack_authority.read_outbound_originals_v1(source.id,family);
  IF basis->>'sourceMessageId' IS DISTINCT FROM source.id::text OR basis->>'environment' IS DISTINCT FROM source.environment
   OR (basis->>'companyId' IS NOT NULL AND basis->>'companyId' IS DISTINCT FROM company::text)
   THEN RAISE EXCEPTION 'ediel_business_ack_status_native_scope_mismatch';END IF;
  FOR entry IN SELECT value FROM jsonb_array_elements(basis->'originals') LOOP
   IF gridex_ediel_duplicate_responses.is_duplicate_ack_v1((entry#>>'{message,id}')::uuid) THEN CONTINUE;END IF;
   -- A native consumption/witness may qualify an original whose mutable
   -- public relation is absent. Project the private binding; never repair it.
   IF entry->>'status'='qualified' THEN
    qualified:=gridex_ediel_duplicate_responses.read_business_original_v1(company,source.environment,source.id,p_actor_user_id,family,(entry#>>'{message,id}')::uuid,'read');
    IF qualified#>>'{ackMessage,id}' IS DISTINCT FROM entry#>>'{message,id}' THEN RAISE EXCEPTION 'ediel_business_ack_status_native_scope_mismatch';END IF;
    items:=items||jsonb_build_array(qualified->'ackMessage');
   ELSE held:=array_append(held,(entry#>>'{message,id}')::uuid);END IF;
  END LOOP;
 END LOOP;
 ELSE
  -- Incoming ACK status is disclosed only through its immutable correlation
  -- and the existing exact-receipt owner. Mutable aggregate caches are unused.
  FOR correlation IN SELECT c.*,r.captured_at FROM gridex_ack_authority.source_correlations c
   LEFT JOIN gridex_ack_authority.applied_receipts r USING(ack_message_id)
   WHERE c.source_message_id=source.id AND c.company_id=company AND c.environment=source.environment
   ORDER BY r.captured_at ASC NULLS FIRST,c.ack_message_id LOOP
   basis:=gridex_ack_authority.read_committed_v1(company,source.environment,correlation.ack_message_id,p_actor_user_id);
   IF basis->>'kind' IS DISTINCT FROM 'exact_receipt' THEN held:=array_append(held,correlation.ack_message_id);CONTINUE;END IF;
   IF basis->>'sourceMessageId' IS DISTINCT FROM source.id::text OR basis->>'companyId' IS DISTINCT FROM company::text
    OR basis->>'environment' IS DISTINCT FROM source.environment OR basis->>'ackFamily' IS DISTINCT FROM correlation.ack_family
    THEN RAISE EXCEPTION 'ediel_business_ack_status_native_scope_mismatch';END IF;
   SELECT to_jsonb(m)||jsonb_build_object('related_message_id',source.id,'ack_outcome',correlation.ack_outcome)
    INTO entry FROM public.ediel_messages m WHERE m.id=correlation.ack_message_id;
   IF p_ack_family IS NULL OR correlation.ack_family=p_ack_family THEN items:=items||jsonb_build_array(entry);END IF;
   IF correlation.captured_at IS NULL THEN held:=array_append(held,correlation.ack_message_id);CONTINUE;END IF;
   IF latest_capture IS NOT DISTINCT FROM correlation.captured_at THEN
    IF snapshot IS DISTINCT FROM basis#>'{result,sourceMessage}' THEN ambiguous_summary:=true;END IF;
   ELSE ambiguous_summary:=false;END IF;
   snapshot:=basis#>'{result,sourceMessage}';receipt:=((basis->'result')-'sourceMessage')||
    jsonb_build_object('ackMessageId',correlation.ack_message_id,'capturedAt',correlation.captured_at);
   latest_capture:=correlation.captured_at;latest_ack:=correlation.ack_message_id;
  END LOOP;
  IF ambiguous_summary THEN held:=array_append(held,latest_ack);snapshot:=NULL;receipt:=NULL;END IF;
 END IF;
 -- Inner original qualification can wait. Recheck before disclosing its result.
 IF public.gridex_actor_has_company_permission(p_actor_user_id,company,'communication.read') IS NOT TRUE
  THEN RAISE EXCEPTION 'ediel_business_ack_status_reader_required' USING ERRCODE='42501';END IF;
 RETURN jsonb_build_object('version',1,'companyId',company,'sourceMessageId',source.id,
  'environment',source.environment,'sourceDirection',source.direction,'sourceSnapshot',snapshot,'sourceReceipt',receipt,
  'ackFamily',p_ack_family,'messages',items,'heldOriginalIds',held);
END $$;

REVOKE ALL ON FUNCTION public.ediel_read_business_ack_status_v1(uuid, uuid, uuid, text, text) FROM PUBLIC,anon,authenticated,service_role;

