-- canonical:1614
--
-- Name: ediel_reserve_switch_cancellation_v1(uuid, uuid, uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_reserve_switch_cancellation_v1(p_company_id uuid, p_switch_id uuid, p_actor_user_id uuid, p_intent_id uuid, p_outbound_request_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE b jsonb;i public.ediel_message_intents%rowtype;r public.outbound_requests%rowtype;o gridex_switch_cancellations.origins%rowtype;binding jsonb;
BEGIN
 b:=gridex_switch_cancellations.context_v1(p_company_id,p_switch_id,p_actor_user_id);IF b->>'status' IS DISTINCT FROM 'authorized' THEN RETURN b;END IF;
 SELECT * INTO i FROM public.ediel_message_intents WHERE id=p_intent_id AND company_id=p_company_id FOR SHARE;
 SELECT * INTO r FROM public.outbound_requests WHERE id=p_outbound_request_id AND company_id=p_company_id FOR SHARE;
 IF i.id IS NULL OR r.id IS NULL OR i.environment IS DISTINCT FROM b->>'environment' OR i.direction IS DISTINCT FROM 'outbound' OR i.message_family IS DISTINCT FROM 'PRODAT' OR i.message_code IS DISTINCT FROM 'Z03'
  OR i.business_process IS DISTINCT FROM 'supplier_switch' OR i.customer_id::text IS DISTINCT FROM b->>'customerId' OR i.metering_point_id IS DISTINCT FROM b->>'pointId' OR i.grid_area_code IS DISTINCT FROM b->>'gridArea'
  OR i.operation_id IS NULL OR i.validation_status IS DISTINCT FROM 'validated' OR i.transaction_reference IS DISTINCT FROM b->>'li'
  OR r.payload->>'environment' IS DISTINCT FROM b->>'environment' OR r.source_type IS DISTINCT FROM 'manual' OR r.source_id::text IS DISTINCT FROM i.id::text OR r.request_type IS DISTINCT FROM 'supplier_switch'
  OR r.operation_id IS DISTINCT FROM i.operation_id OR r.customer_id::text IS DISTINCT FROM b->>'customerId' OR r.metering_point_id::text IS DISTINCT FROM b->>'meteringPointId' OR r.site_id::text IS DISTINCT FROM b->>'siteId'
 THEN RAISE EXCEPTION 'switch_cancellation_validated_intent_request_required';END IF;
 binding:=to_jsonb(i)-ARRAY['created_at','updated_at','validation_status','validation_report','render_status','outbox_status','ack_status','ediel_message_id','outbound_request_id'];
 SELECT * INTO o FROM gridex_switch_cancellations.origins WHERE company_id=p_company_id AND switch_id=p_switch_id AND original_message_id=(b->>'originalMessageId')::uuid FOR UPDATE;
 IF FOUND THEN IF o.intent_id IS DISTINCT FROM i.id OR o.outbound_request_id IS DISTINCT FROM r.id OR o.intent_binding IS DISTINCT FROM binding OR o.original_hash IS DISTINCT FROM b->>'originalHash' THEN RAISE EXCEPTION 'switch_cancellation_reservation_conflict';END IF;
 ELSE INSERT INTO gridex_switch_cancellations.origins(id,company_id,switch_id,original_message_id,original_hash,intent_id,outbound_request_id,actor_user_id,basis,intent_binding)
 VALUES(i.operation_id::uuid,p_company_id,p_switch_id,(b->>'originalMessageId')::uuid,b->>'originalHash',i.id,r.id,p_actor_user_id,b-ARRAY['operationId','intentId','outboundRequestId','messageId'],binding) RETURNING * INTO o;END IF;
 RETURN jsonb_build_object('status','reserved','operationId',o.id,'intentId',o.intent_id,'outboundRequestId',o.outbound_request_id,'messageId',o.message_id);
END $$;

REVOKE ALL ON FUNCTION public.ediel_reserve_switch_cancellation_v1(uuid, uuid, uuid, uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1615
--
-- Name: ediel_reserve_wire_reference_namespace_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_reserve_wire_reference_namespace_v1(p_company_id uuid, p_message_id uuid) RETURNS void
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
DECLARE m public.ediel_messages%rowtype;
BEGIN
 SELECT * INTO m FROM public.ediel_messages WHERE id=p_message_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR m.direction IS DISTINCT FROM 'outbound' OR nullif(m.raw_payload,'') IS NULL THEN RAISE EXCEPTION 'ediel_wire_reference_source_invalid'; END IF;
 PERFORM gridex_ediel_wire_namespace.reserve(m);
END $$;

REVOKE ALL ON FUNCTION public.ediel_reserve_wire_reference_namespace_v1(uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1616
--
-- Name: ediel_resolve_service_permission_command_v1(uuid, uuid, uuid, bigint, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_resolve_service_permission_command_v1(p_company_id uuid, p_assignment_id uuid, p_actor_user_id uuid, p_expected_version bigint, p_permission_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$DECLARE timing jsonb;BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'ediel_service_manual_service_required' USING ERRCODE='42501';END IF;
 IF p_assignment_id IS NULL OR p_permission_id IS NULL OR p_expected_version IS NULL OR p_expected_version<1 THEN RAISE EXCEPTION 'ediel_service_permission_command_scope_required';END IF;
 PERFORM gridex_service_permission.lock_request_writer_v1();
 timing:=gridex_service_permission.current_request_timing_v1(p_company_id,p_assignment_id,p_actor_user_id,p_expected_version,false);
 IF timing->>'status' IS DISTINCT FROM 'authorized' THEN RETURN jsonb_build_object('status','held','permissionId',NULL,'missing',timing->'missing');END IF;
 -- A recorded immutable request binds this assignment scope to one permission.
 IF timing->>'permissionId' IS NOT NULL AND timing->>'permissionId' IS DISTINCT FROM p_permission_id::text THEN
  RETURN jsonb_build_object('status','held','permissionId',NULL,'missing',ARRAY['immutable_service_request_permission_mismatch']);
 END IF;
 RETURN gridex_service_permission.resolve_before_request_timing_v1(p_company_id,p_assignment_id,p_actor_user_id,p_expected_version,p_permission_id);
END $$;

REVOKE ALL ON FUNCTION public.ediel_resolve_service_permission_command_v1(uuid, uuid, uuid, bigint, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1617
--
-- Name: ediel_retention_lock_auth_actor_v1(uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_retention_lock_auth_actor_v1(p_actor_user_id uuid) RETURNS boolean
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE active boolean;
BEGIN
 -- The same FOR SHARE lock as the installed actor/reviewer owners prevents a
 -- concurrent deletion/ban from passing a prior unlocked authorization check.
 SELECT deleted_at IS NULL AND (banned_until IS NULL OR banned_until<=clock_timestamp())
 INTO active FROM auth.users WHERE id=p_actor_user_id FOR SHARE;
 IF active IS DISTINCT FROM true THEN RETURN false;END IF;
 PERFORM id FROM public.user_profiles WHERE id=p_actor_user_id FOR SHARE;
 RETURN EXISTS(SELECT FROM public.user_profiles p WHERE p.id=p_actor_user_id
               AND p.user_status='active' AND to_jsonb(p)->>'disabled_at' IS NULL);
END$$;

REVOKE ALL ON FUNCTION public.ediel_retention_lock_auth_actor_v1(uuid) FROM PUBLIC,anon,authenticated,service_role;

