-- canonical:1619
--
-- Name: ediel_review_ai_purpose_source_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_review_ai_purpose_source_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_review jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_ai_purpose_sources.artifacts%rowtype;r gridex_ai_purpose_sources.reviews%rowtype;o gridex_ai_purpose_sources.origins%rowtype;prior gridex_ai_processing.decisions%rowtype;actual jsonb;receipt jsonb;missing jsonb:='[]';result text;decision uuid;n int;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'ai_purpose_service_required' USING ERRCODE='42501';END IF;
 IF gridex_ai_purpose_sources.actor_v1(p_company_id,p_actor_user_id,'review') IS NOT TRUE THEN RAISE EXCEPTION 'ai_purpose_review_actor_forbidden' USING ERRCODE='42501';END IF;
 -- Same central authorization prefix, then stable decision/journal table fence.
 LOCK TABLE gridex_ai_processing.decisions,gridex_ai_purpose_sources.origins,gridex_ai_purpose_sources.reviews IN SHARE ROW EXCLUSIVE MODE;
 SELECT * INTO a FROM gridex_ai_purpose_sources.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR jsonb_typeof(p_review) IS DISTINCT FROM 'object' OR NOT(p_review ?& ARRAY['sourceHash','claimsHash','decision','reason']) OR EXISTS(SELECT FROM jsonb_object_keys(p_review) x WHERE x NOT IN('sourceHash','claimsHash','decision','reason','clause')) OR p_review->>'sourceHash' IS DISTINCT FROM a.source_hash OR p_review->>'claimsHash' IS DISTINCT FROM a.claims_hash OR (p_review->>'decision' IN('approve','hold','reject')) IS NOT TRUE OR length(coalesce(p_review->>'reason','')) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'ai_purpose_actual_archived_candidate_required';END IF;
 IF a.submitted_by=p_actor_user_id THEN RAISE EXCEPTION 'ai_purpose_separate_reviewer_required' USING ERRCODE='42501';END IF;
 actual:=gridex_ai_purpose_sources.claims_v1(a.company_id,a.claims);receipt:=gridex_ai_purpose_sources.receipt_current_v1(a);
 IF actual IS DISTINCT FROM a.claims OR encode(sha256(a.source_bytes),'hex') IS DISTINCT FROM a.source_hash THEN missing:=missing||'"current_exact_archived_claims_required"'::jsonb;END IF;
 IF receipt IS NULL THEN missing:=missing||'"authentic_current_purpose_issuer_and_representation"'::jsonb;END IF;
 IF p_review->>'decision'='approve' AND (jsonb_typeof(p_review->'clause') IS DISTINCT FROM 'object' OR p_review->'clause' IS DISTINCT FROM receipt->'clause') THEN missing:=missing||'"exact_signed_original_legal_clause_required"'::jsonb;END IF;
 SELECT * INTO o FROM gridex_ai_purpose_sources.origins WHERE artifact_id=a.id;
 IF FOUND THEN IF gridex_ai_purpose_sources.current_v1(a) IS NULL THEN RETURN jsonb_build_object('status','held','artifactId',a.id,'missing','["current_purpose_authority_revoked_or_superseded"]'::jsonb);END IF;RETURN jsonb_build_object('status','authorized','artifactId',a.id,'decisionId',o.decision_id);END IF;
 result:=CASE WHEN p_review->>'decision'='reject' THEN 'rejected' WHEN p_review->>'decision'='hold' OR jsonb_array_length(missing)>0 THEN 'held' ELSE 'approved' END;
 INSERT INTO gridex_ai_purpose_sources.reviews(artifact_id,company_id,reviewer_user_id,decision,reason,clause,missing) VALUES(a.id,a.company_id,p_actor_user_id,result,p_review->>'reason',p_review->'clause',missing) RETURNING * INTO r;
 IF result<>'approved' THEN RETURN jsonb_build_object('status',result,'artifactId',a.id,'missing',missing);END IF;
 SELECT count(*) INTO n FROM gridex_ai_processing.decisions d WHERE company_id=a.company_id AND list_type=a.claims->>'listType' AND purpose=a.claims->>'purpose' AND EXISTS(SELECT FROM gridex_ai_purpose_sources.origins origin_candidate JOIN gridex_ai_purpose_sources.artifacts candidate ON candidate.id=origin_candidate.artifact_id WHERE origin_candidate.decision_id=d.id AND candidate.environment=a.environment) AND NOT EXISTS(SELECT FROM gridex_ai_processing.decisions next WHERE next.previous_decision_id=d.id);
 IF n>1 THEN RAISE EXCEPTION 'ai_purpose_previous_decision_ambiguous';END IF;
 SELECT * INTO prior FROM gridex_ai_processing.decisions d WHERE company_id=a.company_id AND list_type=a.claims->>'listType' AND purpose=a.claims->>'purpose' AND EXISTS(SELECT FROM gridex_ai_purpose_sources.origins origin_candidate JOIN gridex_ai_purpose_sources.artifacts candidate ON candidate.id=origin_candidate.artifact_id WHERE origin_candidate.decision_id=d.id AND candidate.environment=a.environment) AND NOT EXISTS(SELECT FROM gridex_ai_processing.decisions next WHERE next.previous_decision_id=d.id) ORDER BY id LIMIT 1 FOR SHARE;
 INSERT INTO gridex_ai_processing.decisions(company_id,list_type,purpose,revision,previous_decision_id,gdpr_basis,retention_days,valid_from,valid_until,source_reference,source_sha256,decision_owner_registry_id,decision_owner_registry_version)
 VALUES(a.company_id,a.claims->>'listType',a.claims->>'purpose',(SELECT coalesce(max(d.revision),0)+1 FROM gridex_ai_processing.decisions d WHERE d.company_id=a.company_id AND d.list_type=a.claims->>'listType' AND d.purpose=a.claims->>'purpose'),prior.id,a.claims->>'gdprBasis',(a.claims->>'retentionDays')::integer,(a.claims->>'validFrom')::timestamptz,(a.claims->>'validUntil')::timestamptz,a.source_reference,a.source_hash,(receipt->>'ownerRegistryId')::uuid,receipt->>'ownerRegistryVersion') RETURNING id INTO decision;
 INSERT INTO gridex_ai_purpose_sources.origins(artifact_id,review_id,decision_id,company_id) VALUES(a.id,r.id,decision,a.company_id);
 RETURN jsonb_build_object('status','authorized','artifactId',a.id,'decisionId',decision);
END$$;

REVOKE ALL ON FUNCTION public.ediel_review_ai_purpose_source_v1(uuid, uuid, uuid, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1620
--
-- Name: ediel_review_artifact_retention_v1(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_review_artifact_retention_v1(p_company_id uuid, p_actor_user_id uuid, p_decision_id uuid, p_outcome text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE d gridex_ediel_retention.decisions%rowtype;r uuid;outcome text;claims jsonb;
BEGIN PERFORM gridex_ediel_retention.actor_v1(p_company_id,p_actor_user_id,'ediel.retention.review');
 IF gridex_ediel_retention.class_permission_v1(p_company_id,p_actor_user_id,'requested_change_source_artifact_bytes') IS NOT TRUE THEN RAISE EXCEPTION 'retention_current_class_grant_required';END IF;SELECT * INTO STRICT d FROM gridex_ediel_retention.decisions WHERE id=p_decision_id AND company_id=p_company_id FOR UPDATE;
 IF p_outcome NOT IN('approve','hold','reject') OR nullif(p_reason,'') IS NULL OR length(p_reason)>4000 THEN RAISE EXCEPTION 'ediel_retention_review_shape_required';END IF;
 IF p_outcome='approve' AND d.submitted_by=p_actor_user_id THEN RAISE EXCEPTION 'ediel_retention_separate_reviewer_required';END IF;
 claims:=gridex_ediel_retention.receipt_v1(d);outcome:=CASE WHEN p_outcome='reject' THEN 'rejected' WHEN p_outcome='approve' AND claims IS NOT NULL THEN 'approved' ELSE 'held' END;
 INSERT INTO gridex_ediel_retention.reviews(decision_id,actor_user_id,outcome,reason) VALUES(d.id,p_actor_user_id,outcome,p_reason) RETURNING id INTO r;
 INSERT INTO public.audit_logs(actor_user_id,company_id,entity_type,entity_id,action,metadata) VALUES(p_actor_user_id,p_company_id,'ediel_retention_decision',d.id,'ediel.retention.reviewed',jsonb_build_object('reviewId',r,'outcome',outcome));
 RETURN jsonb_build_object('status',outcome,'decisionId',d.id,'reviewId',r);
END$$;

REVOKE ALL ON FUNCTION public.ediel_review_artifact_retention_v1(uuid, uuid, uuid, text, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1621
--
-- Name: ediel_review_bilateral_customer_source_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_review_bilateral_customer_source_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_review jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_bilateral_customer_sources.artifacts%rowtype;o gridex_bilateral_customer_sources.origins%rowtype;receipt jsonb;actual jsonb;missing jsonb:='[]';decision text;review_id uuid;
BEGIN
 PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();
 PERFORM id FROM public.ediel_messages WHERE company_id=p_company_id AND id=(SELECT source_message_id FROM gridex_bilateral_customer_sources.artifacts WHERE id=p_artifact_id AND company_id=p_company_id) FOR UPDATE;

 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'bilateral_customer_source_service_required' USING ERRCODE='42501';END IF;
 IF gridex_bilateral_customer_sources.classified_actor_wallclock_v1(p_company_id,p_actor_user_id,'review','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_customer_source_review_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT a FROM gridex_bilateral_customer_sources.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR UPDATE;decision:=p_review->>'decision';
 IF jsonb_typeof(p_review) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_review) k WHERE k NOT IN('sourceHash','claimsHash','decision','reason','clause')) OR (decision IN('approve','hold','reject')) IS NOT TRUE OR p_review->>'sourceHash' IS DISTINCT FROM a.source_hash OR p_review->>'claimsHash' IS DISTINCT FROM a.claims_hash OR nullif(p_review->>'reason','') IS NULL OR length(p_review->>'reason')>4000 THEN RAISE EXCEPTION 'bilateral_customer_source_actual_archived_review_required';END IF;
 IF decision='approve' AND a.submitted_by=p_actor_user_id THEN RAISE EXCEPTION 'bilateral_customer_source_separate_reviewer_required';END IF;
 SELECT * INTO o FROM gridex_bilateral_customer_sources.origins WHERE artifact_id=a.id FOR SHARE;IF FOUND THEN IF decision<>'approve' THEN RAISE EXCEPTION 'bilateral_customer_source_authorized_origin_requires_revocation';END IF;IF gridex_bilateral_customer_sources.classified_independent_wallclock_v1(a) IS NULL THEN  IF gridex_bilateral_customer_sources.classified_actor_wallclock_v1(p_company_id,p_actor_user_id,'review','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_customer_post_wait_actor_forbidden' USING ERRCODE='42501';END IF; RETURN jsonb_build_object('status','held','artifactId',a.id,'missing',ARRAY['current_bilateral_source_authority_unavailable']);END IF;PERFORM gridex_bilateral_customer_sources.publish_life_event_classification_v1(p_company_id,a.id); IF gridex_bilateral_customer_sources.classified_actor_wallclock_v1(p_company_id,p_actor_user_id,'review','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_customer_post_wait_actor_forbidden' USING ERRCODE='42501';END IF; RETURN jsonb_build_object('status','authorized','artifactId',a.id,'sourceMessageId',a.source_message_id);END IF;
 IF decision='hold' THEN missing:='["explicit_bilateral_source_review_hold"]';ELSIF decision='reject' THEN missing:='["explicit_bilateral_source_review_rejection"]';
 ELSE
  actual:=gridex_bilateral_customer_sources.classified_source_claims_wallclock_v1(a.company_id,a.source_message_id,a.agreement_id,a.supply_period_id,a.contract_id);receipt:=gridex_bilateral_customer_sources.classified_receipt_wallclock_v1(a);
  IF actual IS DISTINCT FROM a.claims OR receipt IS NULL THEN missing:='["authentic_current_bilateral_dso_receipt_and_representation"]';
  ELSIF jsonb_typeof(p_review->'clause') IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_review->'clause') k WHERE k NOT IN('locator','quote')) OR nullif(p_review#>>'{clause,locator}','') IS NULL OR length(p_review#>>'{clause,locator}')>1000 OR nullif(p_review#>>'{clause,quote}','') IS NULL OR length(p_review#>>'{clause,quote}')>10000 OR receipt->'clause' IS DISTINCT FROM p_review->'clause' OR position(convert_to(p_review#>>'{clause,quote}','UTF8') IN a.source_bytes)=0 THEN missing:='["actual_signed_bilateral_pdf_and_verbatim_customer_clause"]';END IF;
 END IF;
 INSERT INTO gridex_bilateral_customer_sources.reviews(artifact_id,company_id,reviewer_user_id,decision,reason,clause,missing) VALUES(a.id,a.company_id,p_actor_user_id,CASE WHEN missing='[]'::jsonb THEN 'approved' WHEN decision='reject' THEN 'rejected' ELSE 'held' END,p_review->>'reason',p_review->'clause',missing) RETURNING id INTO review_id;
 IF missing<>'[]'::jsonb THEN  IF gridex_bilateral_customer_sources.classified_actor_wallclock_v1(p_company_id,p_actor_user_id,'review','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_customer_post_wait_actor_forbidden' USING ERRCODE='42501';END IF; RETURN jsonb_build_object('status',CASE decision WHEN 'reject' THEN 'rejected' ELSE 'held' END,'artifactId',a.id,'missing',missing);END IF;
 INSERT INTO gridex_bilateral_customer_sources.origins(artifact_id,review_id,company_id,source_message_id) VALUES(a.id,review_id,a.company_id,a.source_message_id);
 PERFORM gridex_bilateral_customer_sources.publish_life_event_classification_v1(p_company_id,a.id); IF gridex_bilateral_customer_sources.classified_actor_wallclock_v1(p_company_id,p_actor_user_id,'review','method_contract') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_customer_post_wait_actor_forbidden' USING ERRCODE='42501';END IF; RETURN jsonb_build_object('status','authorized','artifactId',a.id,'sourceMessageId',a.source_message_id);
END$$;

REVOKE ALL ON FUNCTION public.ediel_review_bilateral_customer_source_v1(uuid, uuid, uuid, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1622
--
-- Name: ediel_review_bilateral_prodat_ground_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_review_bilateral_prodat_ground_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_review jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE a gridex_bilateral_prodat.artifacts%rowtype;o gridex_bilateral_prodat.origins%rowtype;g gridex_bilateral_prodat.profile_versions%rowtype;scope jsonb;decision text;missing jsonb:='[]';rid uuid;receipt jsonb;
BEGIN
 IF gridex_bilateral_prodat.actor_v1(p_company_id,p_actor_user_id,'review') IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_prodat_review_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO STRICT a FROM gridex_bilateral_prodat.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR UPDATE;
 decision:=p_review->>'decision';IF jsonb_typeof(p_review) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_review) k WHERE k NOT IN('sourceHash','scopeHash','decision','reason')) OR (decision IN('approve','hold','reject')) IS NOT TRUE OR p_review->>'sourceHash' IS DISTINCT FROM a.source_hash OR p_review->>'scopeHash' IS DISTINCT FROM a.scope_hash OR nullif(p_review->>'reason','') IS NULL OR length(p_review->>'reason')>4000 THEN RAISE EXCEPTION 'bilateral_prodat_review_exact_archived_candidate_required';END IF;
 IF decision='approve' AND a.submitted_by=p_actor_user_id THEN RAISE EXCEPTION 'bilateral_prodat_separate_reviewer_required';END IF;
 SELECT * INTO o FROM gridex_bilateral_prodat.origins WHERE artifact_id=a.id AND company_id=a.company_id;
 IF FOUND THEN IF decision<>'approve' THEN RAISE EXCEPTION 'bilateral_prodat_authorized_ground_requires_revocation';END IF;
 IF gridex_bilateral_prodat.ground_current_v1(o.ground_id,a.company_id,greatest(now(),(a.scope->>'validFrom')::timestamptz)) IS NOT TRUE THEN RETURN jsonb_build_object('status','held','companyId',p_company_id,'artifactId',a.id,'missing',ARRAY['actual_current_qualified_ground']);END IF;
 RETURN jsonb_build_object('status','authorized','companyId',p_company_id,'artifactId',a.id,'profileVersionId',o.ground_id,'missing','[]'::jsonb);END IF;
 IF decision='hold' THEN missing:='["explicit_source_review_hold"]';ELSIF decision='reject' THEN missing:='["explicit_source_review_rejection"]';
 ELSE scope:=gridex_bilateral_prodat.scope_v1(p_company_id,a.selector);
 IF scope IS NULL OR scope IS DISTINCT FROM a.scope THEN missing:='["actual_current_immutable_contract_point_legal_registry_scope"]';
 ELSIF gridex_bilateral_prodat.receipt_current_v1(a) IS NOT TRUE THEN missing:='["authentic_current_issuer_representation_and_legal_ground_receipt"]';END IF;END IF;
 IF missing<>'[]'::jsonb THEN INSERT INTO gridex_bilateral_prodat.reviews(company_id,artifact_id,reviewer_user_id,decision,reason,missing) VALUES(p_company_id,a.id,p_actor_user_id,CASE decision WHEN 'reject' THEN 'rejected' ELSE 'held' END,p_review->>'reason',missing);
 RETURN jsonb_build_object('status',CASE decision WHEN 'reject' THEN 'rejected' ELSE 'held' END,'companyId',p_company_id,'artifactId',a.id,'missing',missing);END IF;
 receipt:=convert_from(decode(a.issuer_receipt->>'payloadBase64','base64'),'UTF8')::jsonb;
 INSERT INTO gridex_bilateral_prodat.reviews(company_id,artifact_id,reviewer_user_id,decision,reason,missing) VALUES(p_company_id,a.id,p_actor_user_id,'approved',p_review->>'reason','[]') RETURNING id INTO rid;
 INSERT INTO gridex_bilateral_prodat.profile_versions(company_id,environment,legal_actor_id,dso_actor_id,grid_area_code,process,bilateral_agreement_id,consumption_supply_period_id,source_reference,source_sha256,legal_decision_reference,registry_version,approved_by,approved_at,valid_from,valid_to)
 VALUES(p_company_id,a.environment,(a.scope->>'legalActorId')::uuid,(a.scope->>'dsoActorId')::uuid,a.scope->>'gridArea',a.scope->>'kind',(a.scope->>'bilateralAgreementId')::uuid,NULL,a.source_reference,a.source_hash,receipt->>'legalDecisionReference',a.source_version||':'||a.scope_hash,p_actor_user_id,(SELECT reviewed_at FROM gridex_bilateral_prodat.reviews WHERE id=rid),(a.scope->>'validFrom')::timestamptz,(a.scope->>'validTo')::timestamptz) RETURNING * INTO g;
 INSERT INTO gridex_bilateral_prodat.origins(ground_id,company_id,artifact_id,review_id,ground_binding) VALUES(g.id,p_company_id,a.id,rid,to_jsonb(g)-'revoked_at');
 IF gridex_bilateral_prodat.ground_current_v1(g.id,p_company_id,greatest(now(),(a.scope->>'validFrom')::timestamptz)) IS NOT TRUE THEN RAISE EXCEPTION 'bilateral_prodat_postwrite_actual_ground_unqualified';END IF;
 RETURN jsonb_build_object('status','authorized','companyId',p_company_id,'artifactId',a.id,'profileVersionId',g.id,'missing','[]'::jsonb);
END$$;

REVOKE ALL ON FUNCTION public.ediel_review_bilateral_prodat_ground_v1(uuid, uuid, uuid, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1623
--
-- Name: ediel_review_blob_retention_v1(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_review_blob_retention_v1(p_company_id uuid, p_actor_user_id uuid, p_decision_id uuid, p_outcome text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
