-- canonical:1630
--
-- Name: ediel_review_network_registry_source_v1(uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_review_network_registry_source_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_review jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE a gridex_network_registry_sources.artifacts%rowtype;r gridex_network_registry_sources.reviews%rowtype;o gridex_network_registry_sources.origins%rowtype;prior gridex_network_registry_sources.origins%rowtype;actual jsonb;receipt jsonb;missing jsonb:='[]';result text;version_id uuid;n int;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'network_registry_service_required' USING ERRCODE='42501';END IF;
 IF gridex_network_registry_sources.actor_v1(p_company_id,p_actor_user_id,'review') IS NOT TRUE THEN RAISE EXCEPTION 'network_registry_review_actor_forbidden' USING ERRCODE='42501';END IF;
 -- Same central authorization prefix, then stable decision/journal table fence.
 LOCK TABLE gridex_network_registry_sources.origins,gridex_network_registry_sources.reviews IN SHARE ROW EXCLUSIVE MODE;
 SELECT * INTO a FROM gridex_network_registry_sources.artifacts WHERE id=p_artifact_id AND company_id=p_company_id FOR UPDATE;
 IF NOT FOUND OR jsonb_typeof(p_review) IS DISTINCT FROM 'object' OR NOT(p_review ?& ARRAY['sourceHash','claimsHash','decision','reason']) OR EXISTS(SELECT FROM jsonb_object_keys(p_review) x WHERE x NOT IN('sourceHash','claimsHash','decision','reason','clause')) OR p_review->>'sourceHash' IS DISTINCT FROM a.source_hash OR p_review->>'claimsHash' IS DISTINCT FROM a.claims_hash OR (p_review->>'decision' IN('approve','hold','reject')) IS NOT TRUE OR length(coalesce(p_review->>'reason','')) NOT BETWEEN 1 AND 4000 THEN RAISE EXCEPTION 'network_registry_actual_archived_candidate_required';END IF;
 IF a.submitted_by=p_actor_user_id THEN RAISE EXCEPTION 'network_registry_separate_reviewer_required' USING ERRCODE='42501';END IF;
 actual:=gridex_network_registry_sources.claims_v1(a.company_id,a.claims);receipt:=gridex_network_registry_sources.receipt_current_v1(a);
 IF actual IS DISTINCT FROM a.claims OR encode(sha256(a.source_bytes),'hex') IS DISTINCT FROM a.source_hash THEN missing:=missing||'"current_exact_archived_claims_required"'::jsonb;END IF;
 IF receipt IS NULL THEN missing:=missing||'"authentic_current_network_registry_issuer_and_representation"'::jsonb;END IF;
 IF p_review->>'decision'='approve' AND (jsonb_typeof(p_review->'clause') IS DISTINCT FROM 'object' OR p_review->'clause' IS DISTINCT FROM receipt->'clause') THEN missing:=missing||'"exact_signed_original_legal_clause_required"'::jsonb;END IF;
 SELECT * INTO o FROM gridex_network_registry_sources.origins WHERE artifact_id=a.id;
 IF FOUND THEN IF gridex_network_registry_sources.current_v1(a) IS NULL THEN RETURN jsonb_build_object('status','held','artifactId',a.id,'missing','["current_network_registry_authority_revoked_or_superseded"]'::jsonb);END IF;RETURN jsonb_build_object('status','authorized','artifactId',a.id,'registryVersionId',o.id);END IF;
 result:=CASE WHEN p_review->>'decision'='reject' THEN 'rejected' WHEN p_review->>'decision'='hold' OR jsonb_array_length(missing)>0 THEN 'held' ELSE 'approved' END;
 INSERT INTO gridex_network_registry_sources.reviews(artifact_id,company_id,reviewer_user_id,decision,reason,clause,missing) VALUES(a.id,a.company_id,p_actor_user_id,result,p_review->>'reason',p_review->'clause',missing) RETURNING * INTO r;
 IF result<>'approved' THEN RETURN jsonb_build_object('status',result,'artifactId',a.id,'missing',missing);END IF;
 SELECT count(*) INTO n FROM gridex_network_registry_sources.origins version WHERE company_id=a.company_id AND environment=a.environment AND network_actor_id=a.network_actor_id AND NOT EXISTS(SELECT FROM gridex_network_registry_sources.origins child WHERE child.previous_version_id=version.id);
 IF n>1 THEN RAISE EXCEPTION 'network_registry_previous_version_ambiguous';END IF;
 SELECT * INTO prior FROM gridex_network_registry_sources.origins version WHERE company_id=a.company_id AND environment=a.environment AND network_actor_id=a.network_actor_id AND NOT EXISTS(SELECT FROM gridex_network_registry_sources.origins child WHERE child.previous_version_id=version.id) FOR SHARE;
 INSERT INTO gridex_network_registry_sources.origins(artifact_id,review_id,company_id,environment,network_actor_id,registry_version,previous_version_id) VALUES(a.id,r.id,a.company_id,a.environment,a.network_actor_id,a.source_version,prior.id) RETURNING id INTO version_id;
 RETURN jsonb_build_object('status','authorized','artifactId',a.id,'registryVersionId',version_id);
END$$;

REVOKE ALL ON FUNCTION public.ediel_review_network_registry_source_v1(uuid, uuid, uuid, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1631
--
-- Name: ediel_review_periodic_e66_reason_v1(uuid, uuid, uuid, uuid, jsonb); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_review_periodic_e66_reason_v1(p_company_id uuid, p_actor_user_id uuid, p_artifact_id uuid, p_evidence_id uuid, p_review jsonb) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    SET "TimeZone" TO 'UTC'
    AS $$
DECLARE artifact gridex_ediel_services.artifacts%rowtype;e public.ediel_service_evidence%rowtype;generic gridex_ediel_services.reviews%rowtype;
 claims jsonb;v gridex_ediel_services.periodic_reason_reviews%rowtype;seq bigint;decision text;
BEGIN
 PERFORM gridex_ediel_services.lock_periodic_reason_graph_v1(true);
 IF gridex_ediel_services.actor_current_v1(p_company_id,p_actor_user_id,true) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_periodic_reason_reviewer_forbidden' USING ERRCODE='42501';END IF;
 IF jsonb_typeof(p_review) IS DISTINCT FROM 'object' OR EXISTS(SELECT FROM jsonb_object_keys(p_review) k WHERE k NOT IN('decision','reason','sourceHash','scopeHash'))
 OR (p_review->>'decision' IN('approve','hold','reject')) IS NOT TRUE OR nullif(btrim(p_review->>'reason'),'') IS NULL OR length(p_review->>'reason')>2000 THEN RAISE EXCEPTION 'ediel_periodic_reason_review_shape_invalid';END IF;
 SELECT * INTO artifact FROM gridex_ediel_services.artifacts WHERE company_id=p_company_id AND id=p_artifact_id;
 SELECT * INTO e FROM public.ediel_service_evidence WHERE company_id=p_company_id AND id=p_evidence_id FOR SHARE;
 SELECT * INTO generic FROM gridex_ediel_services.reviews WHERE company_id=p_company_id AND artifact_id=p_artifact_id AND evidence_id=p_evidence_id ORDER BY review_sequence DESC LIMIT 1;
 IF artifact.id IS NULL OR e.id IS NULL OR generic.id IS NULL OR artifact.submitted_by=p_actor_user_id OR generic.decision<>'approved' OR generic.id IS DISTINCT FROM (SELECT r.id FROM gridex_ediel_services.reviews r WHERE r.company_id=p_company_id AND r.evidence_id=p_evidence_id ORDER BY r.review_sequence DESC LIMIT 1)
 OR generic.artifact_id IS DISTINCT FROM artifact.id OR generic.scope_basis_version IS DISTINCT FROM artifact.scope_basis_version
 OR gridex_ediel_services.review_current_v1(e) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_periodic_reason_separate_current_review_required';END IF;
 IF artifact.source_hash IS DISTINCT FROM p_review->>'sourceHash' OR artifact.scope_hash IS DISTINCT FROM p_review->>'scopeHash' THEN RAISE EXCEPTION 'ediel_periodic_reason_review_original_hash_required';END IF;
 claims:=gridex_ediel_services.signed_periodic_reason_claims_v1(artifact);
 IF claims IS NULL THEN RAISE EXCEPTION 'ediel_periodic_reason_signed_bilateral_claim_required';END IF;
 SELECT coalesce(max(review_sequence),0)+1 INTO seq FROM gridex_ediel_services.periodic_reason_reviews WHERE company_id=p_company_id AND evidence_id=p_evidence_id;
 decision:=CASE p_review->>'decision' WHEN 'approve' THEN 'approved' WHEN 'reject' THEN 'rejected' ELSE 'held' END;
 INSERT INTO gridex_ediel_services.periodic_reason_reviews(company_id,artifact_id,evidence_id,generic_review_id,scope_basis_version,claims,claims_hash,reviewer_user_id,review_sequence,decision,reason)
 VALUES(p_company_id,artifact.id,e.id,generic.id,artifact.scope_basis_version,claims,encode(sha256(convert_to(claims::text,'UTF8')),'hex'),p_actor_user_id,seq,decision,p_review->>'reason') RETURNING * INTO v;
 RETURN jsonb_build_object('version',1,'reviewId',v.id,'companyId',v.company_id,'artifactId',v.artifact_id,'evidenceId',v.evidence_id,'reviewSequence',v.review_sequence,'status',v.decision,'claimsHash',v.claims_hash,'reasonCode',claims->>'reasonCode','marketActivationGranted',false);
END $$;

REVOKE ALL ON FUNCTION public.ediel_review_periodic_e66_reason_v1(uuid, uuid, uuid, uuid, jsonb) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1632
--
-- Name: ediel_review_process_journal_retention_v1(uuid, uuid, uuid, text, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_review_process_journal_retention_v1(p_company_id uuid, p_actor_user_id uuid, p_decision_id uuid, p_outcome text, p_reason text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE d gridex_ediel_retention.process_decisions%rowtype;basis jsonb;outcome text;r uuid;BEGIN
 PERFORM gridex_ediel_retention.record_actor_v1(p_company_id,p_actor_user_id,'legal_acceptance_personal_snapshot','ediel.retention.review');SELECT * INTO STRICT d FROM gridex_ediel_retention.process_decisions WHERE id=p_decision_id AND company_id=p_company_id FOR UPDATE;
 IF p_outcome NOT IN('approve','hold','reject') OR nullif(btrim(p_reason),'') IS NULL OR length(p_reason)>4000 THEN RAISE EXCEPTION 'process_retention_review_shape_required';END IF;IF p_outcome='approve' AND d.submitted_by=p_actor_user_id THEN RAISE EXCEPTION 'process_retention_separate_reviewer_required';END IF;
 basis:=gridex_ediel_retention.process_basis_v1(p_company_id,d.retention_class,d.target_id);outcome:=CASE WHEN p_outcome='reject' THEN 'rejected' WHEN p_outcome='approve' AND gridex_ediel_retention.process_receipt_v1(d) IS NOT NULL AND basis->>'sourceHash'=d.source_hash AND basis->>'targetHash'=d.target_hash AND basis->>'scopeHash'=d.scope_hash AND basis->>'allIncludedScopesClosed'='true' THEN 'approved' ELSE 'held' END;
 INSERT INTO gridex_ediel_retention.process_reviews(decision_id,actor_user_id,outcome,reason) VALUES(d.id,p_actor_user_id,outcome,p_reason) RETURNING id INTO r;INSERT INTO public.audit_logs(actor_user_id,company_id,entity_type,entity_id,action,metadata) VALUES(p_actor_user_id,p_company_id,'process_journal_retention',d.id,'ediel.retention.process_reviewed',jsonb_build_object('reviewId',r,'outcome',outcome));RETURN jsonb_build_object('status',outcome,'decisionId',d.id,'reviewId',r);END$$;

