-- canonical:1660
--
-- Name: ediel_service_permission_manual_options_v1(uuid, uuid, uuid[]); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_service_permission_manual_options_v1(p_company_id uuid, p_actor_user_id uuid, p_permission_ids uuid[]) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$DECLARE options jsonb;BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'ediel_service_manual_service_required' USING ERRCODE='42501';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM m.user_id FROM public.company_memberships m WHERE m.company_id=p_company_id AND m.user_id=p_actor_user_id FOR SHARE;
 IF p_company_id IS NULL OR p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=p_company_id AND m.user_id=p_actor_user_id AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL) OR (public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'metering.read') OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'metering.write')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_service_manual_read_forbidden' USING ERRCODE='42501';END IF;
 IF p_permission_ids IS NULL OR cardinality(p_permission_ids)>100 OR array_position(p_permission_ids,NULL) IS NOT NULL OR cardinality(p_permission_ids)<>(SELECT count(DISTINCT id) FROM unnest(p_permission_ids) id) THEN RAISE EXCEPTION 'ediel_service_manual_option_selection_invalid';END IF;
 IF (SELECT count(*) FROM public.metering_permissions p WHERE p.company_id=p_company_id AND p.id=ANY(p_permission_ids))<>cardinality(p_permission_ids) THEN RAISE EXCEPTION 'ediel_service_manual_permission_not_owned';END IF;
 PERFORM a.id FROM public.ediel_service_assignments a JOIN public.ediel_assignment_permission_links l ON l.company_id=a.company_id AND l.assignment_id=a.id JOIN public.metering_permissions p ON p.company_id=l.company_id AND p.id=l.permission_id WHERE l.company_id=p_company_id AND l.permission_id=ANY(p_permission_ids) AND a.customer_id=p.customer_id ORDER BY a.id FOR SHARE OF a;
 PERFORM p.id FROM public.metering_permissions p WHERE p.company_id=p_company_id AND p.id=ANY(p_permission_ids) ORDER BY p.id FOR SHARE;
 SELECT coalesce(jsonb_agg(jsonb_build_object('permissionId',p.id,'assignmentId',a.id,'assignmentVersion',a.version,'beneficiaryCompanyId',a.beneficiary_company_id,'beneficiaryLabel',beneficiary.name,'purpose',a.purpose,'mode',a.mode,'status',a.status) ORDER BY p.id,a.id),'[]') INTO options FROM public.ediel_assignment_permission_links l JOIN public.ediel_service_assignments a ON a.company_id=l.company_id AND a.id=l.assignment_id JOIN public.metering_permissions p ON p.company_id=l.company_id AND p.id=l.permission_id JOIN public.companies beneficiary ON beneficiary.id=a.beneficiary_company_id WHERE l.company_id=p_company_id AND l.permission_id=ANY(p_permission_ids) AND a.customer_id=p.customer_id;
 RETURN jsonb_build_object('companyId',p_company_id,'options',options);
END $$;

REVOKE ALL ON FUNCTION public.ediel_service_permission_manual_options_v1(uuid, uuid, uuid[]) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1661
--
-- Name: ediel_service_permission_message_basis_v1(uuid, uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_service_permission_message_basis_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO ''
    AS $$
DECLARE s gridex_service_permission.origins%rowtype;
BEGIN
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM m.user_id FROM public.company_memberships m WHERE m.company_id=p_company_id AND m.user_id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.company_memberships m WHERE m.company_id=p_company_id AND m.user_id=p_actor_user_id AND m.status='active' AND m.is_active AND m.accepted_at IS NOT NULL) OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active') OR (public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel.send') OR public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.send')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_permission_origin_message_forbidden' USING ERRCODE='42501'; END IF;
 SELECT * INTO s FROM gridex_service_permission.origins WHERE company_id=p_company_id AND message_id=p_message_id;
 IF NOT FOUND THEN RAISE EXCEPTION 'ediel_permission_origin_message_unbound'; END IF;
 PERFORM public.ediel_require_service_permission_origin_current_v1(p_company_id,p_message_id);
 RETURN jsonb_build_object('basis',s.basis,'actorUserId',s.actor_user_id,'intentId',s.intent_id);
END $$;

REVOKE ALL ON FUNCTION public.ediel_service_permission_message_basis_v1(uuid, uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:1662
--
-- Name: ediel_service_permission_message_basis_v1(uuid, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.ediel_service_permission_message_basis_v1(p_company_id uuid, p_message_id uuid, p_actor_user_id uuid, p_phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s gridex_service_permission.origins%rowtype;current_source gridex_service_permission.origins%rowtype;m public.ediel_messages%rowtype;
BEGIN
 IF p_company_id IS NULL OR p_message_id IS NULL OR p_actor_user_id IS NULL OR (p_phase IN('prepare','send')) IS NOT TRUE THEN RAISE EXCEPTION 'ediel_permission_origin_message_phase_required';END IF;
 -- Recovery qualification prelocks its complete source/ACK cohort first. The
 -- selected terminal source is already held there; ordinary originals use the
 -- same source-before-current-actor order here.
 SELECT * INTO m FROM public.ediel_messages WHERE company_id=p_company_id AND id=p_message_id FOR UPDATE;
 PERFORM 1 FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM 1 FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR (CASE p_phase WHEN 'prepare' THEN coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.write'),false)
   WHEN 'send' THEN coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel.send'),false) OR coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.send'),false) END) IS NOT TRUE
 THEN RAISE EXCEPTION 'ediel_permission_origin_message_forbidden' USING ERRCODE='42501';END IF;
 IF m.id IS NULL OR m.direction IS DISTINCT FROM 'outbound' OR m.message_family IS DISTINCT FROM 'PRODAT' THEN RAISE EXCEPTION 'ediel_permission_origin_message_not_owned';END IF;
 SELECT * INTO s FROM gridex_service_permission.origins WHERE company_id=p_company_id AND message_id=p_message_id;
 IF s.message_id IS NULL THEN RETURN NULL;END IF;
 IF s.intent_id IS DISTINCT FROM m.intent_id OR s.basis->>'companyId' IS DISTINCT FROM p_company_id::text OR s.basis->>'code' IS DISTINCT FROM m.message_code OR s.basis->>'environment' IS DISTINCT FROM m.environment THEN RAISE EXCEPTION 'ediel_permission_origin_message_basis_changed';END IF;
 -- Full current service source, legal tuple, immutable wire/evidence and bounds
 -- remain mandatory. The historic source actor is provenance, not this caller.
 PERFORM gridex_service_permission.require_original_source_current_v1(p_company_id,p_message_id);
 -- The sole source owner locks permission/evidence before its immutable origin.
 -- Do not invert that order by locking this origin before current qualification.
 SELECT * INTO current_source FROM gridex_service_permission.origins WHERE company_id=p_company_id AND message_id=p_message_id FOR SHARE;
 IF current_source IS DISTINCT FROM s THEN RAISE EXCEPTION 'ediel_permission_origin_message_basis_changed' USING ERRCODE='40001';END IF;
 RETURN jsonb_build_object('basis',s.basis,'actorUserId',s.actor_user_id,'intentId',s.intent_id);
END$$;

REVOKE ALL ON FUNCTION public.ediel_service_permission_message_basis_v1(uuid, uuid, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

