    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE owner uuid;
BEGIN
 SELECT m.company_id INTO owner FROM public.ediel_messages m WHERE m.id=NEW.source_ediel_message_id;
