-- canonical:2271
--
-- Name: gridex_read_inbound_ack_source_v1(uuid, text, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_read_inbound_ack_source_v1(p_company_id uuid, p_environment text, p_ack_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE result jsonb; evidence jsonb;
BEGIN
 IF current_user<>'service_role' THEN RAISE EXCEPTION 'service_role_required' USING ERRCODE='42501'; END IF;
 result:=gridex_ediel_source_rules.read_ack_source_before_basis_v1(p_company_id,p_environment,p_ack_message_id);
 IF result IS NULL THEN RETURN NULL; END IF;
 evidence:=gridex_ediel_source_rules.require_v1(p_company_id,(result#>>'{sourceMessage,id}')::uuid);
 RETURN result||jsonb_build_object('sourceRulePackEvidence',evidence);
END $$;

REVOKE ALL ON FUNCTION public.gridex_read_inbound_ack_source_v1(uuid, text, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:2273
--
-- Name: gridex_read_outbound_acks_for_source_v2(uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_read_outbound_acks_for_source_v2(p_source_message_id uuid, p_ack_family text, p_actor_user_id uuid, p_phase text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE s public.ediel_messages%rowtype;basis jsonb;entry jsonb;owned jsonb;items jsonb:='[]';c uuid;BEGIN
 PERFORM gridex_prodat_object_batch.require_service_v1();PERFORM gridex_ediel_ack_replay.lock_current_graph_v2();PERFORM gridex_bilateral_prodat.lock_source_receipts_v1();
 SELECT * INTO s FROM public.ediel_messages WHERE id=p_source_message_id AND direction='inbound' FOR SHARE;
 IF s.id IS NULL THEN RAISE EXCEPTION 'ack_original_inbound_source_required';END IF;
 basis:=gridex_ack_authority.read_outbound_originals_v1(s.id,p_ack_family);c:=(basis->>'companyId')::uuid;
 PERFORM gridex_ediel_duplicate_responses.read_business_original_v1(c,s.environment,s.id,p_actor_user_id,p_ack_family,NULL,p_phase);
 FOR entry IN SELECT x FROM jsonb_array_elements(basis->'originals')x LOOP
  IF entry->>'status' IS DISTINCT FROM 'qualified' THEN RAISE EXCEPTION 'ediel_historical_ack_scope_basis_unavailable';END IF;
  owned:=gridex_ediel_duplicate_responses.read_business_original_v1(c,s.environment,s.id,p_actor_user_id,p_ack_family,(entry#>>'{message,id}')::uuid,p_phase);
  IF owned IS NULL THEN RAISE EXCEPTION 'ediel_historical_ack_scope_basis_unavailable';END IF;
  items:=items||jsonb_build_array(entry||jsonb_build_object('message',owned->'ackMessage'));
 END LOOP;
 -- Recheck every returned own original after the last possible inner wait.
 FOR entry IN SELECT x FROM jsonb_array_elements(items)x LOOP
  PERFORM gridex_ediel_duplicate_responses.read_business_original_v1(c,s.environment,s.id,p_actor_user_id,p_ack_family,(entry#>>'{message,id}')::uuid,p_phase);
 END LOOP;
 PERFORM gridex_ediel_duplicate_responses.read_business_original_v1(c,s.environment,s.id,p_actor_user_id,p_ack_family,NULL,p_phase);
 RETURN basis||jsonb_build_object('version',2,'executionActorUserId',p_actor_user_id,'executionPhase',p_phase,'originals',items);
END$$;

REVOKE ALL ON FUNCTION public.gridex_read_outbound_acks_for_source_v2(uuid, text, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:2274
--
-- Name: gridex_read_periodic_dgi_e66_reason_v1(uuid, uuid); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_read_periodic_dgi_e66_reason_v1(p_company_id uuid, p_message_id uuid) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;result jsonb;
BEGIN
 PERFORM gridex_ediel_services.lock_periodic_reason_graph_v1();
 SELECT * INTO STRICT source FROM public.ediel_messages WHERE company_id=p_company_id AND id=p_message_id FOR SHARE;
 BEGIN result:=gridex_ediel_services.periodic_reason_projection_v1(p_company_id,source.environment,p_message_id);
 EXCEPTION WHEN raise_exception OR insufficient_privilege OR no_data_found OR too_many_rows OR invalid_text_representation THEN
  result:=jsonb_build_object('version',1,'companyId',p_company_id,'environment',source.environment,'sourceMessageId',p_message_id,'sourcePayloadHash',encode(sha256(convert_to(source.raw_payload,'UTF8')),'hex'),'status','held','expectedReasons','[]'::jsonb,'holdReason',SQLERRM);
 END;
 RETURN result;
END $$;

REVOKE ALL ON FUNCTION public.gridex_read_periodic_dgi_e66_reason_v1(uuid, uuid) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:2275
--
-- Name: gridex_read_prodat_ignored_fields_v1(uuid, text, uuid, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_read_prodat_ignored_fields_v1(p_company_id uuid, p_environment text, p_actor_user_id uuid, p_snapshot_id uuid, p_readset_hash text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE snap gridex_received_sources.object_selection_snapshots%rowtype;result jsonb;
BEGIN
 IF current_setting('role',true) IS DISTINCT FROM 'service_role' AND session_user<>'service_role' THEN RAISE EXCEPTION 'prodat_ignored_service_required' USING ERRCODE='42501';END IF;
 PERFORM u.id FROM public.user_profiles u WHERE u.id=p_actor_user_id FOR SHARE;
 PERFORM cm.user_id FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id FOR SHARE;
 IF p_actor_user_id IS NULL OR NOT EXISTS(SELECT FROM public.user_profiles u WHERE u.id=p_actor_user_id AND u.user_status='active')
  OR NOT EXISTS(SELECT FROM public.company_memberships cm WHERE cm.company_id=p_company_id AND cm.user_id=p_actor_user_id AND cm.status='active' AND cm.is_active AND cm.accepted_at IS NOT NULL)
  OR NOT(coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'communication.write'),false) OR coalesce(public.gridex_actor_has_company_permission(p_actor_user_id,p_company_id,'ediel_testing.write'),false)) THEN RAISE EXCEPTION 'ediel_tenant_actor_forbidden' USING ERRCODE='42501';END IF;
 SELECT * INTO snap FROM gridex_received_sources.object_selection_snapshots WHERE id=p_snapshot_id AND company_id=p_company_id AND environment=p_environment AND readset_hash=p_readset_hash;
 IF NOT FOUND OR snap.readset_hash IS DISTINCT FROM encode(sha256(convert_to(snap.readset_text,'UTF8')),'hex') OR snap.readset_text::jsonb->>'complete' IS DISTINCT FROM 'true' THEN RAISE EXCEPTION 'prodat_ignored_owned_snapshot_required';END IF;
 SELECT coalesce(jsonb_agg(jsonb_build_object('sourceMessageId',source->>'sourceMessageId','canonicalAssessmentId',assessment->>'canonicalAssessmentId','fieldsText',f.fields_text,'fieldsHash',f.fields_hash) ORDER BY source->>'sourceMessageId',assessment->>'canonicalAssessmentId'),'[]') INTO result
 FROM jsonb_array_elements(snap.readset_text::jsonb->'sources') source CROSS JOIN LATERAL jsonb_array_elements(source->'assessments') assessment
 LEFT JOIN gridex_received_sources.prodat_ignored_field_facets f ON f.canonical_assessment_id=(assessment->>'canonicalAssessmentId')::uuid AND f.company_id=p_company_id AND f.environment=p_environment AND f.source_message_id::text=source->>'sourceMessageId' AND f.source_payload_hash=source->>'payloadHash'
 WHERE (assessment->>'assessedAt')::timestamptz<=snap.cutoff_at AND NOT EXISTS(SELECT FROM jsonb_array_elements(source->'assessments') child WHERE child->>'previousAssessmentId'=assessment->>'id' AND (child->>'assessedAt')::timestamptz<=snap.cutoff_at);
 RETURN jsonb_build_object('version',1,'companyId',p_company_id,'environment',p_environment,'snapshotId',snap.id,'readsetHash',snap.readset_hash,'facets',result);
END $$;

REVOKE ALL ON FUNCTION public.gridex_read_prodat_ignored_fields_v1(uuid, text, uuid, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

