-- canonical:2349
--
-- Name: gridex_require_utilts_positive_ack_authority_v1(uuid, text, uuid, text, uuid, text); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_require_utilts_positive_ack_authority_v1(p_company_id uuid, p_environment text, p_source_message_id uuid, p_transaction_id text, p_ack_message_id uuid DEFAULT NULL::uuid, p_ack_raw_payload text DEFAULT NULL::text) RETURNS jsonb
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog'
    AS $$
DECLARE source public.ediel_messages%rowtype;basis jsonb;f gridex_received_err_response.final_responses%rowtype;ack public.ediel_messages%rowtype;
BEGIN
 SELECT * INTO source FROM public.ediel_messages WHERE id=p_source_message_id AND company_id=p_company_id AND environment=p_environment FOR SHARE;
 IF source.message_family IS DISTINCT FROM 'UTILTS_ERR' THEN RETURN gridex_utilts_binding.require_positive_storage_authority_v1(p_company_id,p_environment,p_source_message_id,p_transaction_id,p_ack_message_id,p_ack_raw_payload);END IF;
 basis:=gridex_received_err_response.require_v1(p_company_id,p_environment,p_source_message_id);
 IF NOT EXISTS(SELECT FROM jsonb_array_elements(basis->'transactions')t WHERE t->>'transactionId'=p_transaction_id) THEN RAISE EXCEPTION 'utilts_err_application_response_authority_unavailable';END IF;
 IF p_ack_message_id IS NOT NULL OR p_ack_raw_payload IS NOT NULL THEN
  SELECT * INTO f FROM gridex_received_err_response.final_responses WHERE source_message_id=p_source_message_id AND transaction_id=p_transaction_id;
  SELECT * INTO ack FROM public.ediel_messages WHERE id=p_ack_message_id AND company_id=p_company_id AND environment=p_environment AND direction='outbound';
  IF ack.id IS NULL OR f.ack_message_id IS DISTINCT FROM p_ack_message_id OR ack.related_message_id IS DISTINCT FROM p_source_message_id OR ack.raw_payload IS DISTINCT FROM p_ack_raw_payload
   OR f.company_id IS DISTINCT FROM p_company_id OR f.environment IS DISTINCT FROM p_environment OR f.ack_payload_hash IS DISTINCT FROM encode(sha256(convert_to(p_ack_raw_payload,'UTF8')),'hex') THEN RAISE EXCEPTION 'utilts_err_application_response_authority_unavailable';END IF;
 END IF;
 RETURN jsonb_build_object('authorityVersion',1,'companyId',p_company_id,'environment',p_environment,'sourceMessageId',p_source_message_id,'transactionId',p_transaction_id,'ackMessageId',p_ack_message_id,
  'sourceRawHash',basis->'sourceHash','ackRawHash',CASE WHEN p_ack_message_id IS NULL THEN NULL ELSE encode(sha256(convert_to(p_ack_raw_payload,'UTF8')),'hex') END);
END $$;

REVOKE ALL ON FUNCTION public.gridex_require_utilts_positive_ack_authority_v1(uuid, text, uuid, text, uuid, text) FROM PUBLIC,anon,authenticated,service_role;

-- canonical:2418
--
-- Name: gridex_supply_end_followup_v1(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_supply_end_followup_v1() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'public', 'pg_catalog', 'pg_temp'
    AS $$
DECLARE
  v_end date := coalesce(NEW.actual_end_date, NEW.end_date);
  v_key text := 'source-end:' || NEW.id::text || ':' || coalesce(NEW.actual_end_date, NEW.end_date)::text;
  v_contract public.customer_contracts%rowtype;
  v_contract_id uuid := coalesce(NEW.customer_contract_id, NEW.contract_id);
  v_binding_end date;
BEGIN
  IF v_end IS NULL OR NEW.company_id IS NULL OR NEW.customer_id IS NULL
   OR coalesce(NEW.metadata->>'end_key','') <> ''
   OR NEW.status NOT IN ('ending','ended')
   OR (OLD.end_date IS NOT DISTINCT FROM NEW.end_date AND OLD.actual_end_date IS NOT DISTINCT FROM NEW.actual_end_date AND OLD.status IN ('ending','ended')) THEN
    RETURN NEW;
  END IF;
  IF EXISTS (SELECT 1 FROM public.customer_operation_tasks t WHERE t.company_id = NEW.company_id AND t.customer_id = NEW.customer_id
     AND t.task_type = 'final_invoice_pending' AND t.metadata->>'end_key' = v_key) THEN
    RETURN NEW;
  END IF;

  IF v_contract_id IS NOT NULL THEN
    SELECT * INTO v_contract FROM public.customer_contracts
     WHERE id = v_contract_id AND company_id = NEW.company_id AND customer_id = NEW.customer_id FOR UPDATE;
    IF FOUND AND v_contract.status IN ('signed','active') AND NOT EXISTS (
      SELECT 1 FROM public.customer_supply_periods other
       WHERE other.company_id = NEW.company_id AND coalesce(other.customer_contract_id, other.contract_id) = v_contract_id
         AND other.id <> NEW.id AND other.status IN ('active','confirmed_by_grid_owner')
         AND (coalesce(other.actual_end_date, other.end_date) IS NULL OR coalesce(other.actual_end_date, other.end_date) > v_end)) THEN
      BEGIN
        PERFORM public.gridex_record_customer_contract_event_v1(NEW.company_id, v_contract_id, NEW.customer_id, 'terminated', now(),
          'Avtalet upphörde eftersom leveransen till anläggningen upphörde.',
          jsonb_build_object('ends_at', v_end, 'termination_notice_date', now(), 'termination_reason', 'supply_end',
            'reason_code', 'supply_end', 'source_message_id', NEW.source_message_id),
          NULL, NULL, 'supply-end:' || v_contract_id::text || ':' || v_key);
      EXCEPTION WHEN OTHERS THEN
        -- The received supply end stands; a person ends the contract.
        INSERT INTO public.customer_operation_tasks(company_id, customer_id, metering_point_id, task_type, status, priority, title, description, metadata)
        VALUES (NEW.company_id, NEW.customer_id, NEW.metering_point_id, 'contract_end_review', 'open', 'high',
          'Avsluta avtal efter leveransslut',
          'Leveransen har upphört men avtalet kunde inte avslutas automatiskt. Kontrollera och avsluta avtalet.',
          jsonb_build_object('contract_id', v_contract_id, 'supply_end_date', v_end, 'end_key', v_key, 'reason', SQLERRM));
      END;
      IF coalesce(v_contract.binding_months, 0) > 0 AND v_contract.starts_at IS NOT NULL THEN
        v_binding_end := (v_contract.starts_at + make_interval(months => v_contract.binding_months))::date;
        IF v_binding_end > v_end THEN
          INSERT INTO public.customer_operation_tasks(company_id, customer_id, metering_point_id, task_type, status, priority, title, description, metadata)
          VALUES (NEW.company_id, NEW.customer_id, NEW.metering_point_id, 'break_fee_review', 'open', 'normal',
            'Bedöm brytavgift vid leveransslut',
            'Leveransen upphörde före bindningstidens slut. Bedöm om avtalet medger en brytavgift; inget debiteras automatiskt.',
            jsonb_build_object('contract_id', v_contract_id, 'binding_months', v_contract.binding_months,
              'binding_ends_at', v_binding_end, 'supply_end_date', v_end, 'end_key', v_key));
        END IF;
      END IF;
    END IF;
  END IF;

  INSERT INTO public.customer_operation_tasks(company_id, customer_id, metering_point_id, task_type, status, priority, title, description, metadata)
  VALUES (NEW.company_id, NEW.customer_id, NEW.metering_point_id, 'final_invoice_pending', 'open', 'high', 'Slutfaktura',
    'Leveransen upphör ' || to_char(v_end, 'YYYY-MM-DD') || '. Invänta slutavläsningen och fakturera perioden till och med slutdatumet.',
    jsonb_build_object('supply_end_date', v_end, 'end_reason', 'supply_end', 'end_key', v_key, 'supply_period_id', NEW.id));
  RETURN NEW;
END $$;

REVOKE ALL ON FUNCTION public.gridex_supply_end_followup_v1() FROM PUBLIC,anon,authenticated,service_role;

-- canonical:2495
--
-- Name: gridex_version_ediel_route_profile_v2(); Type: FUNCTION; Schema: public; Owner: -
--

CREATE FUNCTION public.gridex_version_ediel_route_profile_v2() RETURNS trigger
    LANGUAGE plpgsql SECURITY DEFINER
    SET search_path TO 'pg_catalog', 'public'
    AS $$
BEGIN
 IF NEW.company_id IS DISTINCT FROM OLD.company_id THEN RAISE EXCEPTION 'ediel_route_history_tenant_immutable'; END IF;
 IF (to_jsonb(NEW)-ARRAY['route_version','updated_at','updated_by']) IS DISTINCT FROM (to_jsonb(OLD)-ARRAY['route_version','updated_at','updated_by']) THEN
  INSERT INTO public.ediel_route_history(route_profile_id,company_id,route_version,snapshot,change_reason,created_by)
   VALUES(OLD.id,OLD.company_id,coalesce(OLD.route_version,1),to_jsonb(OLD),'observed_before_update',coalesce(OLD.updated_by,OLD.created_by)) ON CONFLICT(route_profile_id,route_version) DO NOTHING;
  NEW.route_version:=coalesce(OLD.route_version,1)+1;
 ELSE NEW.route_version:=OLD.route_version;
 END IF;
 RETURN NEW;
END $$;

REVOKE ALL ON FUNCTION public.gridex_version_ediel_route_profile_v2() FROM PUBLIC,anon,authenticated,service_role;

