IF (SELECT md5(prosrc) FROM pg_proc WHERE oid=to_regprocedure('public.ediel_create_national_supply_rescission_original_v1(uuid, uuid, jsonb)')) IS DISTINCT FROM '779eb2075b18fecc4823c3af1b9c46f2' THEN RAISE EXCEPTION 'legacy_latest_retired_creator_body_required'; END IF;
END $latest_creators$;

